let aiMarkingSettings = { instructions: '', strictness: 3, perQuestion: true };

async function loadMarkingSettings() {
  if (!currentUser) return;
  // Students read the teacher's (admin's) rubric so marking is consistent.
  const ownerUid = adminUid || currentUser.uid;
  try {
    const snap = await getDoc(doc(db, 'users', ownerUid, SETTINGS_COL, 'marking'));
    if (snap.exists()) {
      const d = snap.data();
      aiMarkingSettings = {
        instructions: d.instructions || '',
        strictness: d.strictness || 3,
        perQuestion: d.perQuestion !== false
      };
    }
  } catch (e) { console.warn('Could not load marking settings:', e); }
}

function openAiEngineSettings() {
  const eng = getAiEngine();
  document.querySelectorAll('input[name="aiEngineChoice"]').forEach(r => { r.checked = r.value === eng; });
  const modelSel = document.getElementById('aiEngineModel');
  modelSel.value = getOpenAiModel();
  if (!modelSel.value) modelSel.value = OPENAI_DEFAULT_MODEL;   // stored model no longer offered
  const imgSel = document.getElementById('aiEngineImageModel');
  if (imgSel) { imgSel.value = getOpenAiImageModel(); if (!imgSel.value) imgSel.value = OPENAI_IMAGE_DEFAULT_MODEL; }
  document.getElementById('aiEngineKey').value = getOpenAiKey();
  document.getElementById('aiEngineOverlay').classList.add('active');
}

function closeAiEngineSettings() {
  document.getElementById('aiEngineOverlay').classList.remove('active');
}

function saveAiEngineSettings() {
  const picked = document.querySelector('input[name="aiEngineChoice"]:checked');
  const eng = picked ? picked.value : 'gemini';
  const key = (document.getElementById('aiEngineKey').value || '').trim();
  const model = document.getElementById('aiEngineModel').value || OPENAI_DEFAULT_MODEL;
  if (eng === 'openai' && !key) { showToast('Paste your OpenAI API key to use ChatGPT', 'error'); return; }
  const imgSelEl = document.getElementById('aiEngineImageModel');
  const imageModel = (imgSelEl && imgSelEl.value) || OPENAI_IMAGE_DEFAULT_MODEL;
  try {
    localStorage.setItem(AI_ENGINE_STORE.engine, eng);
    localStorage.setItem(AI_ENGINE_STORE.model, model);
    localStorage.setItem(AI_ENGINE_STORE.imageModel, imageModel);
    if (key) localStorage.setItem(AI_ENGINE_STORE.key, key);
    else localStorage.removeItem(AI_ENGINE_STORE.key);
  } catch (e) { showToast('Could not save: ' + (e && e.message ? e.message : e), 'error'); return; }
  closeAiEngineSettings();
  showToast(eng === 'openai' ? 'AI engine set to ChatGPT (' + model + ') — saved on this device' : 'AI engine set to Gemini', 'success');
}

function openMarkingSettings() {
  document.getElementById('mkInstructions').value = aiMarkingSettings.instructions || '';
  const sEl = document.getElementById('mkStrictness');
  sEl.value = aiMarkingSettings.strictness || 3;
  document.getElementById('mkStrictnessLabel').textContent =
    ['', 'Very lenient', 'Lenient', 'Balanced', 'Strict', 'Very strict'][sEl.value];
  document.getElementById('mkPerQuestion').checked = aiMarkingSettings.perQuestion !== false;
  document.getElementById('markingSettingsOverlay').classList.add('active');
}

function closeMarkingSettings() {
  document.getElementById('markingSettingsOverlay').classList.remove('active');
}

async function saveMarkingSettings() {
  aiMarkingSettings = {
    instructions: (document.getElementById('mkInstructions').value || '').trim(),
    strictness: parseInt(document.getElementById('mkStrictness').value) || 3,
    perQuestion: document.getElementById('mkPerQuestion').checked
  };
  try {
    await setDoc(doc(db, 'users', currentUser.uid, SETTINGS_COL, 'marking'), aiMarkingSettings, { merge: true });
    showToast('Marking guide saved', 'success');
    closeMarkingSettings();
  } catch (e) {
    showToast('Could not save: ' + (e && e.message ? e.message : e), 'error');
  }
}

// Builds the instruction block injected before every grading prompt.
// `topic` (the question's topic) pulls in the teacher's uploaded Teaching
// Notes for that topic — preferred keywords and marking standards.
function _markingPreamble(questionGuide, topic) {
  const sMap = {
    1: 'Mark VERY leniently: accept any answer showing partial understanding or that is close in meaning.',
    2: 'Mark leniently: accept answers that capture the main idea even if imprecise or with minor errors.',
    3: 'Use balanced, fair judgement, like a typical classroom teacher.',
    4: 'Mark strictly: require accurate, reasonably complete answers containing the correct key idea.',
    5: 'Mark VERY strictly: require precise, complete answers; do not accept vague or partial ones as fully correct.'
  };
  const parts = [sMap[aiMarkingSettings.strictness] || sMap[3]];
  if (aiMarkingSettings.instructions) {
    parts.push(`Follow these teacher marking instructions: ${aiMarkingSettings.instructions}`);
  }
  if (aiMarkingSettings.perQuestion && questionGuide) {
    parts.push(`Marking guide specific to THIS question: ${questionGuide}`);
  }
  try {
    const notes = _notesMarkingBlock(topic);
    if (notes) parts.push(notes);
  } catch (e) {}
  return parts.join(' ');
}

