function updateQpProgress() {
  const total = qpQueue.length;
  const current = Math.min(qpIndex + 1, total);
  const textEl = document.getElementById('qpProgressText');
  const fillEl = document.getElementById('qpProgressFill');
  if (textEl) textEl.textContent = `${qpAnswered} / ${total} answered`;
  if (fillEl) fillEl.style.width = total > 0 ? `${Math.round((qpAnswered / total) * 100)}%` : '0%';
}

function renderQpQuestion(q) {
  const qLevel = getTopicLevel(q.topic || '');
  let html = `
    <div class="practice-card">
      <div class="practice-card-header">
        <h3>${escapeHtml(q.title)}</h3>
        <div style="display:flex;gap:6px;align-items:center;">
          <span class="qp-level-badge">${escapeHtml(qLevel)}</span>
          <span class="qb-tag category">${escapeHtml(normalizeCategoryValue(q.category))}</span>
          <span class="qb-tag topic">${escapeHtml(q.topic)}</span>
          ${qSecondaryTagsHtml(q)}
        </div>
      </div>
      <div class="practice-card-body">`;

  html += buildOpenBody(q, '#qpContainer', {
    scoreElId: 'qpScoreDisplay', scorePrefix: 'AI Score', mode: 'quickpractice-open', onAllMarked: _qpAllPartsMarked
  });

  html += `</div>
      <div class="practice-actions">
        <div style="display:flex;align-items:center;gap:10px;">
          <div class="practice-score" id="qpScoreDisplay"></div>
          <button class="flag-question-btn" onclick="openFlagDialog('${q.id}','${escapeHtml(q.title).replace(/'/g,"\\'")}')">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg>
            Flag
          </button>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;">
          <button class="btn btn-outline" onclick="resetQpOpenAnswers()">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:14px;height:14px;"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>
            Reset
          </button>
          <button class="btn btn-primary" id="qpNextBtn" onclick="loadNextQpQuestion()" style="display:none;">
            Next &rarr;
          </button>
        </div>
      </div>
    </div>`;

  qpSubmitted = false;
  document.getElementById('qpContainer').innerHTML = html;
  // Nothing for the AI to mark — let the student move on straight away.
  if (!questionHasMarkableAnswer(q)) {
    const nextBtn = document.getElementById('qpNextBtn');
    if (nextBtn) nextBtn.style.display = '';
  }
}

function resetQpOpenAnswers() {
  if (qpSubmitted) return;
  resetOpenAnswersIn('#qpContainer', 'qpScoreDisplay');
}
// Every part of the current Quick Practice question has been AI-marked.
function _qpAllPartsMarked(res) {
  if (qpSubmitted) return;
  qpSubmitted = true;
  document.querySelectorAll('#qpContainer .open-answer').forEach(a => a.disabled = true);
  document.querySelectorAll('#qpContainer .part-ai-btn').forEach(b => b.disabled = true);
  _recordQpResult(res.score, res.total, res.mistakes);
  qpAnswered = Math.max(qpAnswered, qpIndex + 1);
  updateQpProgress();
  const nextBtn = document.getElementById('qpNextBtn');
  if (nextBtn) nextBtn.style.display = '';
}

