// =====================================================================
// PERFORMANCE TRACKING + AI REPORT (students) + explanation reveal
// =====================================================================
let cerPerf = null; // in-memory performance profile for the signed-in student
function _emptyPerf() { return { attempts: 0, totalScore: 0, totalPossible: 0, topics: {}, categories: {}, recent: [], score100: 0 }; }
function _computeScore100(p) {
  const rec = (p.recent || []).slice(-30);
  if (rec.length) return Math.round(rec.reduce((s, r) => s + (r.pct || 0), 0) / rec.length);
  return p.totalPossible ? Math.round(100 * p.totalScore / p.totalPossible) : 0;
}
async function loadCerPerf() {
  if (!currentUser) { cerPerf = _emptyPerf(); return; }
  try {
    const s = await getDoc(doc(db, 'users', currentUser.uid, STATS_COL, 'performance'));
    cerPerf = s.exists() ? Object.assign(_emptyPerf(), s.data()) : _emptyPerf();
  } catch (e) { console.warn('perf load', e); cerPerf = _emptyPerf(); }
}
// Called after EVERY marking so the report always reflects the latest work.
function recordCerPerformance(q, score, total, mode, answerText) {
  try { progressOnMarked(q, score, total, { mode, answerText }); } catch (e) { console.warn('progress record', e); }
  if (!currentUser || currentUser.role !== 'student' || !q || !total) return;
  if (!cerPerf) cerPerf = _emptyPerf();
  const p = cerPerf;
  const topic = q.topic || 'General';
  const category = normalizeCategoryValue(q.category) || 'CER';
  const pct = Math.max(0, Math.min(100, Math.round((score / total) * 100)));
  p.attempts = (p.attempts || 0) + 1;
  p.totalScore = (p.totalScore || 0) + score;
  p.totalPossible = (p.totalPossible || 0) + total;
  p.topics = p.topics || {}; p.categories = p.categories || {};
  (p.topics[topic] = p.topics[topic] || { score: 0, possible: 0, attempts: 0 });
  p.topics[topic].score += score; p.topics[topic].possible += total; p.topics[topic].attempts++;
  (p.categories[category] = p.categories[category] || { score: 0, possible: 0, attempts: 0 });
  p.categories[category].score += score; p.categories[category].possible += total; p.categories[category].attempts++;
  // Track strength by question type too (mcq vs open) — part of the weakness profile.
  const qType = qpHasMcq(q) ? 'mcq' : 'open';
  p.types = p.types || {};
  (p.types[qType] = p.types[qType] || { score: 0, possible: 0, attempts: 0 });
  p.types[qType].score += score; p.types[qType].possible += total; p.types[qType].attempts++;
  p.recent = p.recent || [];
  p.recent.push({ pct, topic, category, type: qType, title: q.title || '', mode: mode || '', at: new Date().toISOString() });
  if (p.recent.length > 50) p.recent = p.recent.slice(-50);
  // Full marks on a question filed under a gap is a step towards closing it.
  // The threshold matches progressOnMarked's, so "right" means the same thing
  // to the gap list as it does to the progress counters.
  if (total && (score / total) >= 0.95) { try { lgNoteWin(q); } catch (e) { console.warn('gap win', e); } }
  p.score100 = _computeScore100(p);
  p.updatedAt = new Date().toISOString();
  setDoc(doc(db, 'users', currentUser.uid, STATS_COL, 'performance'), p, { merge: true }).catch(e => console.warn('perf save', e));
  setDoc(doc(db, PROGRESS_COL, currentUser.uid), {
    name: currentUser.name || '', email: currentUser.email || '',
    score100: p.score100, attempts: p.attempts, updatedAt: p.updatedAt
  }, { merge: true }).catch(e => console.warn('leaderboard save', e));
}
function _scoreColor(s) { return s >= 80 ? 'var(--primary)' : s >= 55 ? 'var(--accent-orange)' : 'var(--accent-red)'; }
function _topicAccuracy(p) {
  return Object.entries(p.topics || {})
    .map(([t, d]) => ({ topic: t, acc: d.possible ? Math.round(100 * d.score / d.possible) : 0, n: d.attempts || 0 }))
    .filter(x => x.n > 0);
}
// =====================================================================
// STUDENT HOME — one simple screen: continue today's practice, questions
// due for review, weakest topic, recent progress, and one Games button.
// =====================================================================
let _homeWeakestTopic = '';

// Questions this student has attempted but never fully cracked (best < 100%),
// weakest and least-recently-tried first. In-syllabus, within level, markable.
function _homeReviewPool() {
  const stats = _qAttemptStats || {};
  const pool = (questionBank || []).filter(q => {
    if (!q || q.id == null) return false;
    if (!questionHasMarkableAnswer(q) || !qInSyllabus(q) || !qWithinStudentLevel(q)) return false;
    const r = stats[String(q.id)];
    return !!(r && r.n > 0 && (r.best || 0) < 1);
  });
  const best = q => (stats[String(q.id)] && stats[String(q.id)].best) || 0;
  const last = q => (stats[String(q.id)] && stats[String(q.id)].last) || 0;
  return pool.sort((a, b) => (best(a) - best(b)) || (last(a) - last(b)));
}

async function renderHomePage() {
  const c = document.getElementById('homeContainer');
  if (!c) return;
  const first = ((currentUser && currentUser.name) || '').trim().split(/\s+/)[0] || '';
  const g = document.getElementById('homeGreeting');
  if (g) g.textContent = first ? `👋 Hi, ${first}!` : '🏠 Home';
  c.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text-muted);">Loading your day…</div>';
  try { await loadAttemptStats(); } catch (_) {}
  try { if (!cerPerf) await loadCerPerf(); } catch (_) {}
  const p = cerPerf || _emptyPerf();

  // Today's practice (the 10-a-day goal).
  const s = (progress && progress.streak) || {};
  const todayQ = (s.dayKey === progressToday()) ? (s.dayMarks || 0) : 0;
  const goal = 10;
  const streakDays = s.count || 0;

  // Due for review + weakest topic (needs 2+ attempts to be meaningful).
  const review = _homeReviewPool();
  const topics = _topicAccuracy(p).sort((a, b) => (a.acc - b.acc) || (b.n - a.n));
  const weakest = topics.find(t => t.n >= 2) || topics[0] || null;
  _homeWeakestTopic = weakest ? weakest.topic : '';

  // Recent progress: last five marked questions, newest first.
  const recent = (p.recent || []).slice(-5).reverse();
  const recentRows = recent.map(r => {
    const col = r.pct >= 80 ? 'var(--primary)' : r.pct >= 50 ? 'var(--accent-orange)' : 'var(--accent-red)';
    return `<div class="home-recent-row">
      <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(r.title || r.topic || 'Question')}</span>
      <span style="color:var(--text-muted);font-size:0.76rem;flex:0 0 auto;">${escapeHtml(r.topic || '')}</span>
      <b style="color:${col};flex:0 0 auto;">${Number(r.pct) || 0}%</b>
    </div>`;
  }).join('');

  const pctToday = Math.min(100, Math.round((todayQ / goal) * 100));
  // Revision cards, but only when there is something to do with them — a card
  // that always says "nothing waiting" is a card nobody reads.
  let fcDue = 0, fcTopGap = null;
  try { fcDue = fcDecks.reduce((s, d) => s + fcDueCards(d).length, 0); } catch (_) {}
  try { if (!fcDue) fcTopGap = fcGaps(1)[0] || null; } catch (_) {}
  const fcCardHtml = (fcDue || fcTopGap) ? `
      <div class="home-card">
        <h3>🃏 Revision cards</h3>
        ${fcDue ? `
        <div class="home-big">${fcDue}<span style="font-size:1.05rem;color:var(--text-muted);font-weight:600;"> card${fcDue === 1 ? '' : 's'} due</span></div>
        <div class="home-sub">Written from your own mistakes. Five minutes here beats half an hour of reading.</div>
        <button class="btn btn-blue" onclick="navigateTo('flashcards')">Revise now</button>` : `
        <div class="home-big" style="font-size:1.35rem;">${escapeHtml(fcTopGap.label)}</div>
        <div class="home-sub">This is what's costing you the most marks. I can turn it into flashcards in one tap.</div>
        <button class="btn btn-blue" onclick="navigateTo('flashcards')">Make my cards</button>`}
      </div>` : '';
  // The gap list, on the same terms as the revision card above: shown only when
  // there is actually something on it.
  let lgTop = null, lgN = 0;
  try { const act = lgActiveGaps(); lgN = act.length; lgTop = act[0] || null; } catch (_) {}
  const lgCardHtml = lgTop ? `
      <div class="home-card">
        <h3>🎯 My gaps</h3>
        <div class="home-big" style="font-size:1.35rem;">${lgKindIcon(lgTop.kind)} ${escapeHtml(lgTop.label)}</div>
        <div class="home-sub">${lgN === 1 ? 'The one thing' : 'The first of ' + lgN + ' things'} you keep getting wrong.
          I'll pick questions on it — or write you a brand-new one.</div>
        <button class="btn btn-blue" onclick="navigateTo('gaps')">Work on my gaps</button>
      </div>` : '';
  c.innerHTML = `
    <div class="home-grid">
      <div class="home-card wide">
        <h3>📘 Today's practice</h3>
        <div class="home-big">${Math.min(todayQ, goal)}<span style="font-size:1.05rem;color:var(--text-muted);font-weight:600;"> / ${goal} questions</span></div>
        <div class="home-bar"><div class="home-bar-fill" style="width:${pctToday}%;"></div></div>
        <div class="home-sub">${todayQ >= goal ? '🎉 Daily goal done — anything more is bonus!' : streakDays ? `🔥 ${streakDays}-day streak — answer ${goal - todayQ} more to keep today counting.` : 'Answer questions every day to build a practice streak.'}</div>
        <button class="btn btn-primary btn-lg" onclick="homeContinuePractice()">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:16px;height:16px;"><polygon points="5 3 19 12 5 21 5 3"/></svg>
          ${todayQ > 0 ? "Continue today's practice" : "Start today's practice"}
        </button>
      </div>
      <div class="home-card">
        <h3>🔁 Due for review</h3>
        <div class="home-big">${review.length}<span style="font-size:1.05rem;color:var(--text-muted);font-weight:600;"> question${review.length === 1 ? '' : 's'}</span></div>
        <div class="home-sub">${review.length ? "Ones you haven't fully cracked yet — beat your best score." : "Nothing waiting — everything you've tried is mastered!"}</div>
        ${review.length ? `<button class="btn btn-blue" onclick="homeStartReview()">Review ${Math.min(review.length, 10)} now</button>` : ''}
      </div>
      <div class="home-card">
        <h3>🎯 Weakest topic</h3>
        ${weakest ? `
        <div class="home-big" style="font-size:1.35rem;">${escapeHtml(weakest.topic)}</div>
        <div class="home-sub">${weakest.acc}% correct over ${weakest.n} attempt${weakest.n === 1 ? '' : 's'} — a little focus goes a long way.</div>
        <button class="btn btn-blue" onclick="homePractiseWeakest()">Practise this topic</button>` : `
        <div class="home-sub">Answer a few questions and your weakest topic will show up here with a one-tap practice button.</div>`}
      </div>
      ${lgCardHtml}
      ${fcCardHtml}
      <div class="home-card wide">
        <h3>🧭 Not sure what to do?</h3>
        <div class="home-sub">The menu is long and you only need a few of it. Ask Ai-nstein and he'll lay out the next step as buttons — nothing to hunt for, and these three cost you nothing.</div>
        <div class="home-guide-row">
          <button class="btn btn-outline" onclick="ainsteinGuideLocal('tour')">🧭 How do I use this?</button>
          <button class="btn btn-outline" onclick="ainsteinGuideLocal('lost')">🤷 I'm lost — what now?</button>
          <button class="btn btn-outline" onclick="ainsteinGuideLocal('psle')">📄 Suggest a PSLE paper</button>
        </div>
      </div>
      <div class="home-card wide">
        <h3>📈 Recent progress</h3>
        ${recent.length ? `
        <div class="home-sub">Performance score <b style="color:${_scoreColor(p.score100 || 0)};">${p.score100 || 0}/100</b> · ${p.attempts || 0} question${(p.attempts || 0) === 1 ? '' : 's'} marked so far.</div>
        <div>${recentRows}</div>
        <button class="btn btn-outline" onclick="navigateTo('myreport')">View full report</button>` : `
        <div class="home-sub">Your last few marked questions will appear here once you start practising.</div>`}
      </div>
    </div>`;
}

// Home actions — each hands over to an existing practice surface.
function homeContinuePractice() {
  navigateTo('quickpractice');
  startQuickPractice();
}
function homeStartReview() {
  const pool = _homeReviewPool();
  if (!pool.length) { showToast('Nothing to review — great work!', 'success'); return; }
  _questRun = null;
  qpQueue = pool.slice(0, 10);
  qpIndex = -1;
  qpAnswered = 0;
  qpSessionResults = [];
  navigateTo('quickpractice');
  showToast('🔁 Review session — beat your old scores!', 'info');
  preloadQueueImages(qpQueue).then(() => loadNextQpQuestion()).catch(() => loadNextQpQuestion());
}
function homePractiseWeakest() {
  navigateTo('topicalpractice');
  if (_homeWeakestTopic) tpStartTopic(_homeWeakestTopic);
}

// =====================================================================
// LEARNING GAPS — the grammar and vocabulary this student does not yet
// understand, kept as a list and used to choose what they see next
//
// The mistake log below records WHAT went wrong on a particular question. This
// is the layer above it: the same evidence read as a list of NAMED WEAKNESSES —
// "subject-verb agreement with collective nouns", "the word 'reluctant'" — that
// outlives the question it was learnt from.
//
// That list does three jobs, and it is the same list for all three:
//   1. it is shown to the student (and their teacher) as plain English,
//   2. it PICKS the bank questions they are served next (lgBankQuestionsFor),
//   3. it BRIEFS the AI when there is nothing left in the bank to serve, so a
//      brand-new question can be written for the exact gap (lgBuildQuestion).
//
// A gap is closed by the student, not by the clock: LG_CLEAR_WINS answers in a
// row on questions filed under it and it moves to Cleared. One wrong answer
// re-opens it, because a gap that closes on a lucky guess teaches nobody.
//
// Storage: users/{uid}/{SETTINGS_COL}/learningGaps — the student's own tree, so
// it is covered by the same rules as their settings. Nothing is mirrored to the
// class collection: a list of what a child cannot do is not a class statistic.
// =====================================================================
const GAPS_DOC = 'learningGaps';    // users/{uid}/{SETTINGS_COL}/learningGaps
const LG_MAX = 60;                  // gaps kept — the oldest, weakest-evidence go first
const LG_CLEAR_WINS = 3;            // right answers in a row that close a gap
const LG_EVIDENCE_KEEP = 4;         // "you wrote X" examples kept per gap
const LG_TEXT_MAX = 200;
const LG_NEW_PER_ATTEMPT = 2;       // gaps one wrong question may open

// The kinds a gap can have. Grammar and vocabulary are the two the brief names,
// and they lead; the rest exist so a mistake that is plainly neither is not
// filed as one of them.
const LG_KINDS = {
  grammar:       { label: 'Grammar',       icon: '🔤', topics: ['Grammar', 'Grammar Cloze', 'Synthesis and Transformation'] },
  vocabulary:    { label: 'Vocabulary',    icon: '📖', topics: ['Vocabulary', 'Vocabulary Cloze', 'Comprehension: Vocabulary in Context'] },
  spelling:      { label: 'Spelling',      icon: '✍️', topics: ['Punctuation and Spelling', 'Editing for Spelling and Grammar'] },
  punctuation:   { label: 'Punctuation',   icon: '❞',  topics: ['Punctuation and Spelling'] },
  comprehension: { label: 'Comprehension', icon: '🔍', topics: ['Comprehension (Open-ended)', 'Comprehension Cloze', 'Comprehension: Inference', 'Visual Text Comprehension'] },
  writing:       { label: 'Writing',       icon: '📝', topics: ['Continuous Writing', 'Situational Writing', 'Picture Composition'] },
};
function lgKindLabel(k) { return (LG_KINDS[k] || {}).label || 'Skill'; }
function lgKindIcon(k) { return (LG_KINDS[k] || {}).icon || '🎯'; }
function lgKindOf(raw) { const k = String(raw || '').toLowerCase().trim(); return LG_KINDS[k] ? k : 'grammar'; }

// ---- the store ---------------------------------------------------------
let lgState = null;                 // null until hydrated, and again after sign-out
let _lgSaveTimer = null;
// Walking a question's blocks to read its text is the expensive part of
// matching, and the gaps page asks for a count per gap — so without this the
// page costs O(gaps × bank) block walks. Keyed by question id and cleared at the
// top of each render, so one render is one walk per question however long the
// list gets. Declared here, above lgOnSignOut, because that clears it.
let _lgTextCache = new Map();

function lgDefaults() {
  return { gaps: {}, credits: { dayKey: null, used: 0 }, updatedAt: null };
}
function _lgClip(s, n) {
  return stripHtmlToText(String(s == null ? '' : s)).replace(/\s+/g, ' ').trim().slice(0, n || LG_TEXT_MAX);
}
function _lgNorm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim(); }
function lgGapKey(kind, label) { return lgKindOf(kind) + ':' + _lgNorm(label); }

// Anything read back from Firestore goes through this, so a half-written or
// hand-edited document can never take the page down.
function lgHydrate(saved) {
  const out = lgDefaults();
  const gaps = (saved && saved.gaps && typeof saved.gaps === 'object') ? saved.gaps : {};
  Object.keys(gaps).forEach(k => {
    const g = gaps[k];
    if (!g || typeof g !== 'object') return;
    const label = _lgClip(g.label, 90);
    if (!label) return;
    const kind = lgKindOf(g.kind);
    const key = String(g.key || lgGapKey(kind, label));
    out.gaps[key] = {
      key, kind, label,
      note: _lgClip(g.note, LG_TEXT_MAX),
      misses: Math.max(1, parseInt(g.misses, 10) || 1),
      wins: Math.max(0, parseInt(g.wins, 10) || 0),
      streak: Math.max(0, parseInt(g.streak, 10) || 0),
      firstAt: String(g.firstAt || g.lastAt || ''),
      lastAt: String(g.lastAt || ''),
      qIds: (Array.isArray(g.qIds) ? g.qIds : []).map(String).filter(Boolean).slice(0, 12),
      evidence: (Array.isArray(g.evidence) ? g.evidence : []).slice(0, LG_EVIDENCE_KEEP).map(e => ({
        wrote: _lgClip(e && e.wrote, LG_TEXT_MAX),
        should: _lgClip(e && e.should, LG_TEXT_MAX),
        onQuestion: _lgClip(e && e.onQuestion, 120),
        at: String((e && e.at) || ''),
      })),
      cleared: !!g.cleared,
      clearedAt: String(g.clearedAt || ''),
    };
  });
  const c = (saved && saved.credits) || {};
  out.credits = { dayKey: c.dayKey ? String(c.dayKey) : null, used: Math.max(0, parseInt(c.used, 10) || 0) };
  out.updatedAt = (saved && saved.updatedAt) || null;
  return out;
}

async function lgInit() {
  if (!currentUser || !db) { lgState = null; return; }
  try {
    const s = await getDoc(doc(db, 'users', currentUser.uid, SETTINGS_COL, GAPS_DOC));
    lgState = lgHydrate(s.exists() ? s.data() : null);
  } catch (e) {
    console.warn('learning gaps load', e);
    lgState = lgHydrate(null);
  }
  _lgRollCredits();
}
function lgOnSignOut() {
  lgState = null;
  _lgTextCache.clear();
  if (_lgSaveTimer) { clearTimeout(_lgSaveTimer); _lgSaveTimer = null; }
}

// Writes coalesce: one photo answer marks every part at once and would
// otherwise be one document write per part.
function lgSave() {
  if (!lgState || !currentUser || !db) return;
  lgState.updatedAt = new Date().toISOString();
  if (_lgSaveTimer) clearTimeout(_lgSaveTimer);
  _lgSaveTimer = setTimeout(() => {
    _lgSaveTimer = null;
    setDoc(doc(db, 'users', currentUser.uid, SETTINGS_COL, GAPS_DOC), lgState)
      .catch(e => console.warn('learning gaps save', e));
  }, 800);
}

// ---- the daily credits -------------------------------------------------
// Thirty a day, reset by the calendar day rather than by a rolling 24 hours:
// a child who practises after school every day gets the same allowance every
// day, instead of one that drifts later and later.
const REGEN_DAILY_CREDITS = 30;

function _lgRollCredits() {
  if (!lgState) return;
  const today = progressToday();
  if (lgState.credits.dayKey !== today) {
    lgState.credits = { dayKey: today, used: 0 };
  }
}
function lgCreditsLeft() {
  if (!lgState) return 0;
  _lgRollCredits();
  return Math.max(0, REGEN_DAILY_CREDITS - (lgState.credits.used | 0));
}
// Spends one and reports whether it was there to spend. The caller must not
// start the AI call unless this returned true.
function lgSpendCredit() {
  if (!lgState) return false;
  if (lgCreditsLeft() <= 0) return false;
  lgState.credits.used = (lgState.credits.used | 0) + 1;
  lgSave();
  try { lgPaintCredits(); } catch (_) {}
  return true;
}
// A credit spent on a call that then FAILED is a credit the student never got
// anything for, so it goes back.
function lgRefundCredit() {
  if (!lgState) return;
  lgState.credits.used = Math.max(0, (lgState.credits.used | 0) - 1);
  lgSave();
  try { lgPaintCredits(); } catch (_) {}
}

// ---- recording a gap ---------------------------------------------------
// `items` are { kind, label, note }. Everything else on the record is derived
// here so no caller can file a half-built gap.
function lgRecord(items, q, evidence) {
  if (!lgState || !Array.isArray(items) || !items.length) return [];
  const at = new Date().toISOString();
  const qid = String((q && q.id) || '');
  const touched = [];
  items.slice(0, LG_NEW_PER_ATTEMPT).forEach(it => {
    const label = _lgClip(it && it.label, 90);
    if (!label) return;
    const kind = lgKindOf(it && it.kind);
    const key = lgGapKey(kind, label);
    const g = lgState.gaps[key] || {
      key, kind, label, note: '', misses: 0, wins: 0, streak: 0,
      firstAt: at, lastAt: at, qIds: [], evidence: [], cleared: false, clearedAt: '',
    };
    g.misses++;
    g.streak = 0;                     // a fresh miss resets the run towards Cleared
    g.cleared = false;                // …and re-opens a gap that had been closed
    g.clearedAt = '';
    g.lastAt = at;
    if (!g.note && it && it.note) g.note = _lgClip(it.note, LG_TEXT_MAX);
    if (qid && g.qIds.indexOf(qid) < 0) g.qIds = [qid].concat(g.qIds).slice(0, 12);
    const ev = (evidence || []).find(e => e && (e.wrote || e.should));
    if (ev) {
      g.evidence = [{
        wrote: _lgClip(ev.wrote, LG_TEXT_MAX) || '(left blank)',
        should: _lgClip(ev.should, LG_TEXT_MAX),
        onQuestion: _lgClip((q && q.title) || '', 120),
        at,
      }].concat(g.evidence).slice(0, LG_EVIDENCE_KEEP);
    }
    lgState.gaps[key] = g;
    touched.push(g);
  });
  _lgPrune();
  lgSave();
  return touched;
}

// Bounded, like the mistake log. What goes first is what the list is least
// likely to need: cleared gaps, then the ones missed least and longest ago.
function _lgPrune() {
  const keys = Object.keys(lgState.gaps);
  if (keys.length <= LG_MAX) return;
  const ranked = keys.map(k => lgState.gaps[k]).sort((a, b) => {
    if (!!a.cleared !== !!b.cleared) return a.cleared ? 1 : -1;
    return (b.misses - a.misses) || String(b.lastAt || '').localeCompare(String(a.lastAt || ''));
  });
  ranked.slice(LG_MAX).forEach(g => { delete lgState.gaps[g.key]; });
}

// A right answer on a question filed under a gap. LG_CLEAR_WINS in a row and
// the gap is Cleared — it stays on the list, in its own section, because
// "you used to get this wrong and now you don't" is worth showing a child.
function lgNoteWin(q) {
  if (!lgState || !q || q.id == null) return;
  const qid = String(q.id);
  const tags = (typeof qTagList === 'function' ? qTagList(q) : []).map(t => _lgNorm(t));
  let changed = false;
  Object.values(lgState.gaps).forEach(g => {
    if (g.cleared) return;
    const linked = g.qIds.indexOf(qid) >= 0 || tags.indexOf(_lgNorm(g.label)) >= 0;
    if (!linked) return;
    g.wins++;
    g.streak++;
    if (g.streak >= LG_CLEAR_WINS) { g.cleared = true; g.clearedAt = new Date().toISOString(); }
    changed = true;
  });
  if (changed) lgSave();
}

// ---- naming the gap ----------------------------------------------------
// The model reads the question, the mark and what the student actually wrote,
// and names the gap in the words a teacher would use. It is given the gaps
// already on this student's list and told to REUSE an existing name where it
// fits, or the same weakness accumulates under three spellings and none of
// them ever gathers enough evidence to matter.
function _lgClassifyPrompt(q, parts) {
  const p = (typeof _docQParts === 'function') ? _docQParts(q) : { text: '' };
  const known = lgActiveGaps().slice(0, 24).map(g => `${g.kind}: ${g.label}`);
  const wrong = parts.slice(0, 4).map((x, i) =>
    `${i + 1}. The mark is for: "${_lgClip(x.expected, 200) || '(not recorded)'}" — the student wrote: "${_lgClip(x.student, 200) || '(left blank)'}"`).join('\n');
  return [
    'You are a Singapore primary-school English teacher (P3-P6) keeping a running list of what ONE pupil does not yet understand.',
    '',
    'They have just got this question wrong.',
    'Question topic: ' + ((q && q.topic) || 'English'),
    'Question: "' + _lgClip(p.text || (q && q.title) || '', 600) + '"',
    'What went wrong:',
    wrong,
    '',
    known.length ? 'Already on this pupil\'s list — REUSE one of these names EXACTLY if this mistake is the same weakness:\n' + known.join('\n') : 'Their list is empty so far.',
    '',
    'Name at most ' + LG_NEW_PER_ATTEMPT + ' weaknesses this mistake actually shows. Reply with ONLY this JSON:',
    '{"items":[{"kind":"grammar","label":"...","note":"..."}]}',
    '',
    'RULES:',
    '- "kind" is exactly one of: ' + Object.keys(LG_KINDS).join(', ') + '.',
    '- "label" is the TEACHABLE THING, in a teacher\'s words, at most 8 words and lowercase: "subject-verb agreement with collective nouns", "past perfect tense", "the word \'reluctant\'". For vocabulary, the label is the WORD or phrase itself.',
    '- Never use the topic as the label. "Grammar" is not a weakness; "using \'fewer\' with countable nouns" is.',
    '- Only name what THIS mistake shows. A careless slip is not a weakness — if the answer shows no misunderstanding at all, return {"items":[]}.',
    '- "note" is one short sentence, addressed to "you", saying what to remember. No more than 25 words.',
    '- Prefer a name already on their list, copied EXACTLY, over a new one that means the same thing.',
    '- Plain text only. No markdown.',
  ].join('\n');
}

// The list must still fill when the AI is off or the call fails, so a mistake
// falls back to the question's own labelling: its tags name the idea a teacher
// already wrote down, and failing that its topic does. Coarser than the model's
// answer, never nothing.
function _lgFallbackItems(q) {
  const tags = (typeof qTagList === 'function' ? qTagList(q) : []).filter(Boolean);
  const topic = String((q && q.topic) || '').trim();
  const kind = lgKindFromTopic(topic);
  const names = tags.length ? tags.slice(0, LG_NEW_PER_ATTEMPT) : (topic ? [topic] : []);
  return names.map(n => ({ kind, label: n, note: '' }));
}
function lgKindFromTopic(topic) {
  const t = String(topic || '');
  const hit = Object.keys(LG_KINDS).find(k => (LG_KINDS[k].topics || []).indexOf(t) >= 0);
  if (hit) return hit;
  const lower = t.toLowerCase();
  if (lower.indexOf('vocab') >= 0) return 'vocabulary';
  if (lower.indexOf('spell') >= 0) return 'spelling';
  if (lower.indexOf('punctuation') >= 0) return 'punctuation';
  if (lower.indexOf('comprehension') >= 0) return 'comprehension';
  if (lower.indexOf('writing') >= 0 || lower.indexOf('composition') >= 0) return 'writing';
  return 'grammar';
}

// THE ONE ENTRY POINT. Called from fcNoteMistakes — the single function every
// marking path already funnels its wrong answers through — so there is no
// second hook to keep in step, and a surface added later is covered for free.
// Fire-and-forget: a failed classification costs a line on a list, never the
// marking the student is looking at.
function lgNoteFromParts(q, parts, mode) {
  try {
    if (!lgState || !currentUser || currentUser.role !== 'student' || !q) return;
    const wrong = (Array.isArray(parts) ? parts : []).filter(p => p && (p.expected || p.student));
    if (!wrong.length) return;
    const evidence = wrong.map(p => ({ wrote: p.student, should: p.expected }));
    const record = items => { if (items && items.length) lgRecord(items, q, evidence); };
    if (!window.__aiReady || !window.__aiReady()) { record(_lgFallbackItems(q)); return; }
    askGemini(_lgClassifyPrompt(q, wrong), { maxOutputTokens: 260, temperature: 0.2, json: true })
      .then(raw => {
        const parsed = _parseAIJson(raw) || {};
        const items = (Array.isArray(parsed.items) ? parsed.items : [])
          .filter(x => x && _lgClip(x.label, 90));
        // An empty list is a real answer here — the model was told to return one
        // when the slip shows no misunderstanding — so it is NOT overridden.
        if (items.length) record(items);
        else if (!Array.isArray(parsed.items)) record(_lgFallbackItems(q));
      })
      .catch(e => { console.warn('gap classify', e); record(_lgFallbackItems(q)); });
  } catch (e) { console.warn('lgNoteFromParts', e); }
}

// ---- reading the list --------------------------------------------------
// Worst first: how often it has been missed, weighted by how recently, the same
// shape the flashcard gaps use so the two lists never disagree about what
// matters most.
// FC_HALFLIFE_DAYS is declared in the flashcards section BELOW this one, so it
// is in its temporal dead zone here — read at call time only, never at module
// eval. Nothing in this section runs before the first render, so that holds.
function _lgScore(g) {
  const ms = Date.parse(g.lastAt || '') || 0;
  const rec = ms ? Math.pow(0.5, Math.max(0, (Date.now() - ms) / 86400000) / FC_HALFLIFE_DAYS) : 0.35;
  return (g.misses || 1) * rec;
}
function lgAllGaps() { return lgState ? Object.values(lgState.gaps) : []; }
function lgActiveGaps() {
  return lgAllGaps().filter(g => !g.cleared).sort((a, b) => _lgScore(b) - _lgScore(a));
}
function lgClearedGaps() {
  return lgAllGaps().filter(g => g.cleared)
    .sort((a, b) => String(b.clearedAt || '').localeCompare(String(a.clearedAt || '')));
}
function lgGap(key) { return (lgState && lgState.gaps[key]) || null; }

// ---- job 2: feeding the student the RIGHT questions ---------------------
// The bank is searched for what actually bears on this gap, best first. The
// questions they got the gap FROM lead — a question you could not do is the
// most relevant question there is — then anything tagged with the gap's name,
// then the topics that teach this kind, and for a vocabulary gap, any question
// whose text uses the word.
//
// Everything is filtered to what this student may be served at all: markable,
// in syllabus, within their level. A gap can outlive the questions that made it
// (they get retagged, they get deleted), so an empty result is normal and the
// caller must handle it rather than treat it as an error.
function _lgQText(q) {
  const k = String(q.id);
  let v = _lgTextCache.get(k);
  if (v === undefined) {
    v = ((q.title || '') + ' ' + ((_docQParts(q) || {}).text || ''));
    _lgTextCache.set(k, v);
  }
  return v;
}

function lgBankQuestionsFor(gap, limit) {
  if (!gap) return [];
  const bank = Array.isArray(questionBank) ? questionBank : [];
  const label = _lgNorm(gap.label);
  const kindTopics = (LG_KINDS[gap.kind] || {}).topics || [];
  const fromGap = new Set(gap.qIds.map(String));
  // A vocabulary gap is a WORD, so a question that uses it is on point. Two
  // letters or fewer would match half the bank, so those score on tags alone.
  const word = (gap.kind === 'vocabulary' && label.length > 2) ? label : '';
  const wordRe = word ? new RegExp('\\b' + word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i') : null;

  const scored = [];
  bank.forEach(q => {
    if (!q || q.id == null) return;
    if (!questionHasMarkableAnswer(q) || !qInSyllabus(q) || !qWithinStudentLevel(q)) return;
    let score = 0;
    if (fromGap.has(String(q.id))) score += 100;
    const tags = (typeof qTagList === 'function' ? qTagList(q) : []).map(t => _lgNorm(t));
    if (tags.indexOf(label) >= 0) score += 60;
    else if (tags.some(t => t && (t.indexOf(label) >= 0 || label.indexOf(t) >= 0))) score += 30;
    const topics = (typeof qTopicList === 'function') ? qTopicList(q) : [q.topic];
    if (topics.some(t => kindTopics.indexOf(t) >= 0)) score += 12;
    if (wordRe && wordRe.test(_lgQText(q))) score += 45;
    if (score > 0) scored.push({ q, score });
  });
  scored.sort((a, b) => (b.score - a.score) || (String(a.q.title || '')).localeCompare(String(b.q.title || '')));
  return scored.slice(0, Math.max(1, limit || 12)).map(x => x.q);
}

// Practise a gap out of the bank. It runs on the Topical Practice surface —
// the same queue, the same renderer, the same marking — because a gap session
// is a topical session whose topic happens to be one weakness.
async function lgPractiseGap(key) {
  const gap = lgGap(key);
  if (!gap) return;
  const queue = lgBankQuestionsFor(gap, 12);
  if (!queue.length) {
    showToast('Nothing in the bank for this one yet — try “New question” instead', 'info');
    return;
  }
  tpActiveTopics = [gap.label];
  navigateTo('topicalpractice');
  await tpRunQueue(queue, {
    title: gap.label,
    subtitle: lgKindLabel(gap.kind) + ' — ' + queue.length + ' question' + (queue.length === 1 ? '' : 's') + ' on this gap',
    labelHtml: `<span class="tp-level-badge" style="background:var(--accent-orange-light);color:var(--accent-orange);">${lgKindIcon(gap.kind)} ${escapeHtml(gap.label)}</span>`,
    emptyMsg: 'Nothing in the bank for this one yet',
    restart: () => lgPractiseGap(key),
  });
}

// ---- job 3: writing a NEW question for the gap --------------------------
// When the bank has nothing left — or the student has just spent a credit for
// another go at something they got wrong — the question is written to order.
//
// It goes through buildBlocksFromAi like every other AI authoring path, so a
// generated question is the same shape as a bank one and every student surface
// renders it unchanged. It is NOT saved: the bank is the teacher's, and a
// question nobody has vetted does not belong in it.
let _lgGenN = 0;

function _lgGenPrompt(gap, sourceQ, evidence) {
  const src = sourceQ ? _docQParts(sourceQ) : null;
  const lines = [
    'You are a Singapore primary-school English teacher (P3-P6) writing ONE new practice question for a single pupil.',
    '',
    'The weakness it must test: ' + lgKindLabel(gap.kind).toLowerCase() + ' — "' + gap.label + '".',
  ];
  if (gap.note) lines.push('What they need to remember: ' + gap.note);
  if (evidence && (evidence.wrote || evidence.should)) {
    lines.push('Last time, the mark was for "' + _lgClip(evidence.should, 200) + '" and they wrote "' + _lgClip(evidence.wrote, 200) + '".');
  }
  if (src && src.text) {
    lines.push('', 'The question they got wrong (write a DIFFERENT one testing the SAME thing — new situation, new words, never a reworded copy):',
      '"' + _lgClip(src.text, 500) + '"');
  }
  lines.push(
    '',
    'Reply with ONLY this JSON:',
    '{"title":"a short title, at most 8 words","blocks":[{"type":"text","text":"the question as the pupil reads it"},{"type":"mcq","options":["...","...","...","..."],"correctIndex":0},{"type":"explanation","text":"..."}]}',
    '',
    'RULES:',
    '- Use an "mcq" block with EXACTLY 4 options for a question with one right answer, and "correctIndex" as its 0-based position. Otherwise use {"type":"plainanswer","text":"the full model answer"} instead of the mcq block.',
    '- Exactly ONE "text" block, then ONE answer block (mcq or plainanswer), then ONE "explanation" block. Nothing else — this pupil sees it on a phone.',
    '- The question must aim STRAIGHT at the weakness named above. If it could be answered without understanding that, it is the wrong question.',
    '- Never mention a picture, diagram, table or passage: there is none, and a question that refers to one cannot be answered.',
    '- No sub-parts, no (a)/(b): one question, one answer.',
    '- The "explanation" is 2-4 sentences addressed to "you", saying why the answer is right and what rule to remember.',
    '- Singapore primary-school English, plain text only. No markdown, no [[brackets]].');
  return lines.join('\n');
}

// Build one generated question object for a gap. Throws with a message worth
// showing — every caller is a button the student just pressed.
async function lgBuildQuestion(gap, sourceQ) {
  if (!gap) throw new Error('that gap is no longer on your list');
  if (!window.__aiReady || !window.__aiReady()) throw new Error('the AI is not ready — try again in a moment');
  const evidence = (gap.evidence || [])[0] || null;
  const raw = await askGemini(_lgGenPrompt(gap, sourceQ, evidence), {
    maxOutputTokens: 900, temperature: 0.7, json: true,
  });
  const data = _parseAIJson(raw);
  if (!data || typeof data !== 'object') throw new Error('the AI did not return a usable question');
  const built = buildBlocksFromAi(data);
  const blocks = (built && built.blocks) || [];
  const q = {
    // `gen_` keeps a generated id from ever colliding with a bank one, and makes
    // it obvious in an attempts row where the question came from.
    id: 'gen_' + Date.now().toString(36) + '_' + (++_lgGenN),
    title: _lgClip(data.title, 90) || ('Practice: ' + gap.label),
    topic: (sourceQ && sourceQ.topic) || (LG_KINDS[gap.kind] || {}).topics[0] || 'Grammar',
    category: (sourceQ && sourceQ.category) || 'Key Concepts',
    tags: [gap.label],
    blocks,
    generated: true,
    fromGap: gap.key,
  };
  if (!questionHasMarkableAnswer(q)) throw new Error('the AI did not return a question that can be marked');
  return q;
}

// ---- rendering a generated question ------------------------------------
// Each one gets its OWN container id. buildOpenBody keys its answer stores by
// container selector, so two cards sharing a selector would clobber each
// other's answers — the same trap the whole-paper worksheet editor has.
function lgRenderGenerated(hostEl, q, opts) {
  if (!hostEl || !q) return '';
  const cfg = opts || {};
  const id = 'lgGen_' + String(q.id).replace(/[^a-zA-Z0-9_]/g, '');
  const sel = '#' + id;
  const scoreId = id + '_score';
  const body = buildOpenBody(q, sel, {
    scoreElId: scoreId,
    scorePrefix: 'AI Score',
    mode: cfg.mode || 'gap-generated',
    onAllMarked: cfg.onAllMarked || null,
  });
  hostEl.insertAdjacentHTML('beforeend', `
    <div class="practice-card lg-gen-card" id="${id}">
      <div class="practice-card-header">
        <h3>${escapeHtml(q.title)}</h3>
        <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
          <span class="qb-tag" style="background:var(--accent-orange-light);color:var(--accent-orange);">✨ Written for you</span>
          ${cfg.gapLabel ? `<span class="qb-tag topic">${escapeHtml(cfg.gapLabel)}</span>` : ''}
        </div>
      </div>
      <div class="practice-card-body">${body}</div>
      <div class="practice-actions">
        <div class="practice-score" id="${scoreId}"></div>
        <div style="font-size:0.76rem;color:var(--text-muted);">Not from the question bank — written just now for this gap</div>
      </div>
    </div>`);
  const el = document.getElementById(id);
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  return sel;
}

// ---- another go at a question you got wrong ----------------------------
// Thirty credits a day. One credit buys a NEW question on the same idea — not
// the same question again, which only tests whether they read the answer we
// just showed them.
//
// The offer is made from _checkAllPartsMarked, the one place every surface
// finishes marking, so it appears wherever a student answers: quick practice,
// topical practice, a gap session, and on a generated question too — getting the
// retry wrong is exactly when another one is worth having.
let _lgRetryStore = {};        // token → the question and what went wrong on it
let _lgRetryN = 0;

// The gap this retry should aim at. The list is asked first — by the time a
// student has read their feedback the classifier has usually landed — and where
// it has nothing yet, the question's own labelling stands in, so a retry is
// never blocked waiting for an AI call.
function _lgRetryGap(rec) {
  const qid = String((rec.q && rec.q.id) || '');
  const onList = lgActiveGaps().find(g => g.qIds.indexOf(qid) >= 0);
  if (onList) return onList;
  const fallback = _lgFallbackItems(rec.q)[0] || { kind: lgKindFromTopic(rec.q && rec.q.topic), label: (rec.q && rec.q.topic) || 'English' };
  const w = rec.wrong[0] || {};
  return {
    key: '', kind: lgKindOf(fallback.kind), label: fallback.label, note: '',
    qIds: qid ? [qid] : [], evidence: [{ wrote: w.student, should: w.expected }],
  };
}

function lgOfferRetry(containerSel, q, results) {
  if (!lgState || !currentUser || currentUser.role !== 'student' || !q) return;
  const wrong = Object.values(results || {}).filter(r => r && r.verdict !== 'correct');
  if (!wrong.length) return;                       // full marks needs no second go
  const c = document.querySelector(containerSel);
  if (!c) return;
  // Scoped to THIS container, so the offer under a generated question does not
  // read as the outer question's and block it.
  if (c.querySelector('.lg-retry-offer')) return;
  const token = 'rt' + (++_lgRetryN);
  _lgRetryStore[token] = { q, wrong: wrong.map(r => ({ expected: r.expected, student: r.student })) };
  const left = lgCreditsLeft();
  const html = `
    <div class="lg-retry-offer" id="lgRetryWrap_${token}">
      <div class="lg-retry-head">
        <div>
          <div class="lg-retry-title">🔄 Try another one like it</div>
          <div class="lg-retry-sub">A brand-new question on the same idea — that is how you find out whether it has stuck.</div>
        </div>
        <span class="lg-credit-chip" data-lg-credits>${left} / ${REGEN_DAILY_CREDITS} left today</span>
      </div>
      <div class="lg-retry-actions">
        <button class="btn btn-primary" id="lgRetryBtn_${token}" onclick="lgRetry('${token}')"${left <= 0 ? ' disabled' : ''}>
          ${left > 0 ? '✨ New question (1 credit)' : 'No credits left today'}
        </button>
      </div>
      <div id="lgRetryHost_${token}"></div>
    </div>`;
  // Always LAST in the container. The explanation cards insert themselves after
  // the action bar, and they arrive whenever their AI call returns — anchoring
  // the offer to the same place would put it above the explanation on an MCQ
  // (no AI call, so it lands synchronously) and below it on a written answer.
  // Appending at the end is the only placement that reads the same every time:
  // score, then why, then what to do about it.
  c.insertAdjacentHTML('beforeend', html);
}

async function lgRetry(token) {
  const rec = _lgRetryStore[token];
  if (!rec) return;
  const btn = document.getElementById('lgRetryBtn_' + token);
  const host = document.getElementById('lgRetryHost_' + token);
  if (!host) return;
  if (!window.__aiReady || !window.__aiReady()) {
    showToast('The AI is not ready yet — try again in a moment', 'info');
    return;
  }
  // Spend BEFORE the call, so two quick taps cannot buy two questions for one
  // credit; a call that then fails refunds it.
  if (!lgSpendCredit()) {
    showToast(`That is all ${REGEN_DAILY_CREDITS} of today's credits — you get ${REGEN_DAILY_CREDITS} more tomorrow`, 'info');
    if (btn) { btn.disabled = true; btn.textContent = 'No credits left today'; }
    return;
  }
  const orig = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = '✨ Writing your question…'; }
  try {
    const gap = _lgRetryGap(rec);
    const gq = await lgBuildQuestion(gap, rec.q);
    lgRenderGenerated(host, gq, { mode: 'retry-generated', gapLabel: gap.label });
    // One credit, one question: the button is done. Getting the NEW question
    // wrong offers its own retry, so the chain continues from there.
    if (btn) {
      btn.remove();
      const wrap = document.getElementById('lgRetryWrap_' + token);
      const sub = wrap && wrap.querySelector('.lg-retry-sub');
      if (sub) sub.textContent = 'Here is a new question on the same idea. Answer it the way you would in an exam.';
    }
  } catch (e) {
    lgRefundCredit();
    console.warn('retry generate', e);
    showToast('Could not write a new question — ' + ((e && e.message) || 'try again') + ' (your credit was not used)', 'error');
    if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  }
}

// Every place the number of credits is shown, refreshed from the one store.
function lgPaintCredits() {
  const left = lgCreditsLeft();
  document.querySelectorAll('[data-lg-credits]').forEach(el => {
    el.textContent = left + ' / ' + REGEN_DAILY_CREDITS + ' left today';
  });
  const badge = document.getElementById('lgGapBadge');
  if (badge) {
    const n = lgState ? lgActiveGaps().length : 0;
    badge.textContent = n;
    badge.style.display = n > 0 ? '' : 'none';
  }
}

// ---- the page ----------------------------------------------------------
// A gap key is `kind:normalised label`, so it is always [a-z0-9 :] — mapping
// ':' and ' ' onto distinct underscore runs keeps this injective, which a bare
// strip of non-alphanumerics would not (two different gaps could then share one
// host element and the second one's button would silently do nothing). Both the
// card and the generate button MUST derive the id from here.
function _lgHostId(key) {
  return 'lgGapHost_' + String(key).replace(/:/g, '__').replace(/ /g, '_').replace(/[^a-zA-Z0-9_]/g, '');
}

function _lgGapCardHtml(g, cleared) {
  const bankN = lgBankQuestionsFor(g, 12).length;
  const ev = (g.evidence || [])[0];
  const safe = String(g.key).replace(/'/g, "\\'");
  const when = _fcWhenLabel(Date.parse(g.lastAt || '') || 0);
  return `
    <div class="lg-gap-card${cleared ? ' cleared' : ''}">
      <div class="lg-gap-top">
        <span class="lg-gap-icon">${lgKindIcon(g.kind)}</span>
        <div class="lg-gap-name">
          <div class="lg-gap-label">${escapeHtml(g.label)}</div>
          <div class="lg-gap-meta">
            <span class="lg-kind-chip">${escapeHtml(lgKindLabel(g.kind))}</span>
            <span>Missed ${g.misses} time${g.misses === 1 ? '' : 's'}</span>
            <span>·</span>
            <span>Last ${escapeHtml(when)}</span>
            ${cleared ? '<span>·</span><span class="lg-cleared-chip">✓ Cleared</span>'
              : (g.streak ? `<span>·</span><span class="lg-streak-chip">${g.streak}/${LG_CLEAR_WINS} right in a row</span>` : '')}
          </div>
        </div>
      </div>
      ${g.note ? `<div class="lg-gap-note">${escapeHtml(g.note)}</div>` : ''}
      ${ev && (ev.wrote || ev.should) ? `
        <div class="lg-gap-evidence">
          <div><span class="lg-ev-key">You wrote</span> “${escapeHtml(ev.wrote || '(left blank)')}”</div>
          ${ev.should ? `<div><span class="lg-ev-key">The mark is for</span> “${escapeHtml(ev.should)}”</div>` : ''}
        </div>` : ''}
      <div class="lg-gap-actions">
        <button class="btn btn-outline" onclick="lgPractiseGap('${safe}')"${bankN ? '' : ' disabled'}>
          📚 Practise${bankN ? ` (${bankN})` : ' — none in the bank'}
        </button>
        <button class="btn btn-primary" onclick="lgGenerateForGap('${safe}')">✨ New question (1 credit)</button>
        ${cleared ? '' : `<button class="btn btn-outline lg-got-it" onclick="lgMarkGotIt('${safe}')">I've got this</button>`}
      </div>
      <div id="${_lgHostId(g.key)}" class="lg-gap-host"></div>
    </div>`;
}

function renderGapsPage() {
  const c = document.getElementById('gapsContainer');
  if (!c) return;
  if (!lgState) {
    c.innerHTML = '<div class="lg-empty">Loading your list…</div>';
    lgInit().then(() => renderGapsPage()).catch(() => {
      c.innerHTML = '<div class="lg-empty">Could not load your list — check your connection.</div>';
    });
    return;
  }
  // One walk per question for this whole render, however many gaps are listed.
  _lgTextCache.clear();
  const active = lgActiveGaps();
  const cleared = lgClearedGaps();
  const left = lgCreditsLeft();

  let html = `
    <div class="lg-credit-bar">
      <div>
        <div class="lg-credit-title">✨ ${left} of ${REGEN_DAILY_CREDITS} credits left today</div>
        <div class="lg-credit-sub">Each credit writes you a brand-new question on something you got wrong. They refill every day.</div>
      </div>
      <span class="lg-credit-chip" data-lg-credits>${left} / ${REGEN_DAILY_CREDITS} left today</span>
    </div>`;

  if (!active.length && !cleared.length) {
    html += `
      <div class="lg-empty">
        <div class="lg-empty-icon">🎯</div>
        <div class="lg-empty-title">Nothing on your list yet</div>
        <div class="lg-empty-sub">Answer some questions and anything you get wrong turns up here — the exact grammar
          point or word, not just the topic — so you can practise that instead of everything.</div>
        <button class="btn btn-primary" onclick="navigateTo('${practicePageFor()}')">Start practising</button>
      </div>`;
  } else {
    html += active.length ? `
      <div class="lg-section-head">
        <h3>Working on</h3>
        <span class="lg-section-sub">${active.length} thing${active.length === 1 ? '' : 's'} to crack — hardest first</span>
      </div>
      ${active.map(g => _lgGapCardHtml(g, false)).join('')}` : `
      <div class="lg-empty">
        <div class="lg-empty-icon">🎉</div>
        <div class="lg-empty-title">Nothing outstanding</div>
        <div class="lg-empty-sub">Everything you have got wrong, you have since got right. Keep practising and this list
          will fill itself back up.</div>
      </div>`;
    if (cleared.length) {
      html += `
        <div class="lg-section-head">
          <h3>Cleared</h3>
          <span class="lg-section-sub">${cleared.length} you used to get wrong and now don't</span>
        </div>
        ${cleared.map(g => _lgGapCardHtml(g, true)).join('')}`;
    }
  }
  c.innerHTML = html;
  lgPaintCredits();
}

// Write one new question for a gap, straight onto the card. Costs a credit —
// the same credit the retry button spends, because it buys the same thing.
async function lgGenerateForGap(key) {
  const gap = lgGap(key);
  if (!gap) return;
  const host = document.getElementById(_lgHostId(key));
  if (!host) return;
  if (!window.__aiReady || !window.__aiReady()) {
    showToast('The AI is not ready yet — try again in a moment', 'info');
    return;
  }
  if (!lgSpendCredit()) {
    showToast(`That is all ${REGEN_DAILY_CREDITS} of today's credits — you get ${REGEN_DAILY_CREDITS} more tomorrow`, 'info');
    return;
  }
  host.innerHTML = '<div class="lg-gen-wait">✨ Writing a question for this…</div>';
  try {
    const sourceQ = (gap.qIds || []).map(id => (questionBank || []).find(q => String(q.id) === String(id))).find(Boolean) || null;
    const q = await lgBuildQuestion(gap, sourceQ);
    host.innerHTML = '';
    lgRenderGenerated(host, q, { mode: 'gap-generated', gapLabel: gap.label });
  } catch (e) {
    lgRefundCredit();
    console.warn('gap generate', e);
    host.innerHTML = '';
    showToast('Could not write a question — ' + ((e && e.message) || 'try again') + ' (your credit was not used)', 'error');
  }
}

// The student's own call that a gap is closed. It stays on the list under
// Cleared, and one wrong answer re-opens it (lgRecord clears the flag), so this
// is a shortcut rather than a way to delete the evidence.
function lgMarkGotIt(key) {
  const g = lgGap(key);
  if (!g) return;
  g.cleared = true;
  g.clearedAt = new Date().toISOString();
  g.streak = Math.max(g.streak, LG_CLEAR_WINS);
  lgSave();
  renderGapsPage();
  showToast(`Moved “${g.label}” to Cleared — it comes back if you slip on it again`, 'success');
}

// =====================================================================
// REVISION FLASHCARDS — built from the mistakes this student actually made
//
// The point of a flashcard here is NOT to cover the syllabus. It is to cover the
// gap: the ideas this student has got wrong, weighted so that a mistake made
// yesterday matters more than the same mistake a month ago, and one made four
// times matters more than one made once.
//
// A "gap" is named by the question's TAGS where it has them — a teacher writing
// down the exact idea a question tests is the best label we will ever get — and by
// its topic where it has none. So a student who keeps losing marks on questions
// tagged "elastic spring force" gets a deck about elastic spring force, not a deck
// about Forces.
// =====================================================================
const FC_HALFLIFE_DAYS = 14;    // a mistake this old counts half as much
const FC_MAX_GAPS = 8;          // gaps offered on the page
const FC_Q_PER_GAP = 4;         // wrong questions shown to the model per gap
const FC_CARDS_PER_GAP = 4;     // cards asked for per gap

// ---- the durable mistake log ------------------------------------------------
// Until now nothing about WHY an answer was wrong outlived the page. The model
// answer for the part they failed, what they actually wrote, which option they
// picked — all of it was computed at marking time, shown once and dropped on the
// floor. Scores persisted; reasons did not.
//
// That is the difference between a card that says "revise Forces" and one that
// says "you wrote 'it gets heavier' — the mark is for 'the spring stretches
// more'". The second one is the gap. So one small document per wrong part now
// survives, in users/{uid}/mistakes.
//
// Text is clipped and the log is pruned to the newest FC_LOG_KEEP, so it stays
// bounded no matter how much a student practises. Writes are fire-and-forget: a
// failed write costs a future flashcard, never the marking in front of them.
const FC_LOG_KEEP = 300;
const FC_TEXT_MAX = 320;
const FC_PARTS_PER_ATTEMPT = 6;
let mistakeLog = [];            // newest first
let _mistakeLogAt = 0;

function _mkCol() { return collection(db, 'users', currentUser.uid, MISTAKES_COL); }
function _mkRef(id) { return doc(db, 'users', currentUser.uid, MISTAKES_COL, id); }
function _fcClip(s) {
  return stripHtmlToText(String(s == null ? '' : s)).replace(/\s+/g, ' ').trim().slice(0, FC_TEXT_MAX);
}

// Record the parts of one just-marked question the student did NOT get right.
// `parts` elements are { kind:'open'|'mcq', verdict, expected, student }.
function fcNoteMistakes(q, parts, mode) {
  try {
    if (!currentUser || currentUser.role !== 'student' || !q || !db) return;
    const list = (Array.isArray(parts) ? parts : [])
      .filter(p => p && (_fcClip(p.expected) || _fcClip(p.student)));
    if (!list.length) return;
    const at = new Date().toISOString();
    const tags = qTagList(q);
    list.slice(0, FC_PARTS_PER_ATTEMPT).forEach((p, i) => {
      const rec = {
        id: 'mk_' + Date.now().toString(36) + i + Math.random().toString(36).slice(2, 6),
        qId: String(q.id || ''),
        qTitle: String(q.title || '').slice(0, 120),
        topic: String(q.topic || ''),
        tags,
        kind: p.kind === 'mcq' ? 'mcq' : 'open',
        verdict: p.verdict === 'partial' ? 'partial' : 'incorrect',
        expected: _fcClip(p.expected),
        student: _fcClip(p.student) || '(left blank)',
        mode: String(mode || ''),
        at,
      };
      mistakeLog.unshift(rec);
      setDoc(_mkRef(rec.id), rec).catch(e => console.warn('mistake log write', e));
    });
    if (mistakeLog.length > FC_LOG_KEEP) _fcPruneLog();
    // The same evidence, read as a list of named weaknesses. This is the ONE
    // place the gap list is fed, because this is the one place every marking
    // path already brings its wrong answers.
    lgNoteFromParts(q, list, mode);
  } catch (e) { console.warn('fcNoteMistakes', e); }
}

// Local list first so the app is immediately correct; the deletes are best-effort.
function _fcPruneLog() {
  const drop = mistakeLog.slice(FC_LOG_KEEP);
  mistakeLog = mistakeLog.slice(0, FC_LOG_KEEP);
  drop.forEach(r => { if (r && r.id) deleteDoc(_mkRef(r.id)).catch(() => {}); });
}

async function loadMistakeLog(force) {
  if (!currentUser || !db) return mistakeLog;
  if (mistakeLog.length && !force && (Date.now() - _mistakeLogAt) < 5 * 60 * 1000) return mistakeLog;
  try {
    const snap = await getDocs(_mkCol());
    const out = [];
    snap.forEach(d => { const r = d.data(); if (r && r.qId != null) out.push(Object.assign({}, r, { id: d.id })); });
    out.sort((a, b) => String(b.at || '').localeCompare(String(a.at || '')));
    mistakeLog = out;
    _mistakeLogAt = Date.now();
  } catch (e) { console.warn('mistake log load', e); }
  return mistakeLog;
}

// How much a mistake still counts, by how long ago it was. Exponential decay, so
// "recently" is a slope rather than a cut-off — nothing drops off a cliff the
// moment it turns fifteen days old.
function _fcRecencyWeight(ms) {
  if (!ms) return 0.35;         // undated (pre-timestamp attempt): counts, but least
  const days = Math.max(0, (Date.now() - ms) / 86400000);
  return Math.pow(0.5, days / FC_HALFLIFE_DAYS);
}

// Every question this student has attempted and not fully cracked, with how badly
// and how recently. This is the raw material for every gap below.
function _fcWrongPool() {
  const stats = _qAttemptStats || {};
  const out = [];
  (Array.isArray(questionBank) ? questionBank : []).forEach(q => {
    if (!q || q.id == null) return;
    if (!qInSyllabus(q) || !qWithinStudentLevel(q)) return;
    const r = stats[String(q.id)];
    if (!r || !r.n) return;
    const wrong = Math.max(0, (r.n || 0) - (r.correct || 0));   // attempts that were not full marks
    const best = r.best || 0;
    if (!wrong && best >= 1) return;                            // got it, every time — not a gap
    out.push({ q, n: r.n || 0, wrong: wrong || 1, best, last: r.last || 0 });
  });
  return out;
}

// Group the wrong questions into named gaps and rank them. Both halves of the
// brief are in the score: `wrong` is how COMMON the mistake is, the recency weight
// is how RECENT. A near-miss counts for less than a blank, because half marks on a
// question is a different kind of gap from no marks at all.
function fcGaps(limit) {
  const byKey = new Map();
  _fcWrongPool().forEach(x => {
    const tags = qTagList(x.q);
    const names = tags.length ? tags : [x.q.topic || 'General'];
    const w = _fcRecencyWeight(x.last);
    names.forEach(name => {
      const key = name.toLowerCase();
      const g = byKey.get(key) || {
        label: name, key, tagged: !!tags.length,
        score: 0, wrong: 0, attempts: 0, worst: 1, last: 0, questions: [],
      };
      g.score += x.wrong * w * (1 - x.best * 0.5);
      g.wrong += x.wrong;
      g.attempts += x.n;
      g.worst = Math.min(g.worst, x.best);
      g.last = Math.max(g.last, x.last);
      g.questions.push(x);
      byKey.set(key, g);
    });
  });
  const gaps = Array.from(byKey.values());
  // Within a gap, the question they did worst on leads — that is the one a card
  // most needs to be built from.
  gaps.forEach(g => g.questions.sort((a, b) => (a.best - b.best) || (b.last - a.last)));
  gaps.sort((a, b) => (b.score - a.score) || (b.wrong - a.wrong) || (b.last - a.last));
  return gaps.slice(0, Math.max(1, limit || FC_MAX_GAPS));
}

// A phrase for how fresh a gap is, for the card meta line.
function _fcWhenLabel(ms) {
  if (!ms) return 'a while ago';
  const days = Math.floor((Date.now() - ms) / 86400000);
  if (days <= 0) return 'today';
  if (days === 1) return 'yesterday';
  if (days < 7) return days + ' days ago';
  if (days < 14) return 'last week';
  if (days < 60) return Math.round(days / 7) + ' weeks ago';
  return Math.round(days / 30) + ' months ago';
}

// ---- turning a gap into cards ----------------------------------------------
// The model writes the cards, but it is not asked to remember any English: every
// fact it needs is handed to it — the model answer and the teacher's explanation
// from the questions this student failed, plus, where the log has them, the exact
// words the student wrote instead. Its job is to turn that into recall questions.
//
// This is the difference between a revision card and a fact card. "What is a
// force?" tests nothing about this child. "A spring is loaded with a heavier mass.
// What happens to its extension, and why?" — written because they answered that
// wrong on Tuesday — tests the gap.

// Everything about one failed question that a card could be built from.
function _fcQuestionBrief(x) {
  const q = x.q;
  const p = _docQParts(q);
  const brief = {
    title: _fcClip(q.title || ''),
    topic: q.topic || '',
    tags: qTagList(q),
    question: _fcClip(p.text || ''),
    theirBestScore: Math.round((x.best || 0) * 100) + '%',
    timesWrong: x.wrong,
    lastTried: _fcWhenLabel(x.last),
  };
  const model = _deriveModelAnswer(q);
  if (model) brief.modelAnswer = _fcClip(model);
  if (p.mcq) {
    const opts = (p.mcq.options || []).map(o => stripHtml(o.text || '')).filter(Boolean);
    if (opts.length) brief.options = opts.map(o => _fcClip(o));
    const correct = (p.mcq.options || []).find(o => o.id === p.mcq.correctId);
    if (correct) brief.correctOption = _fcClip(stripHtml(correct.text || ''));
  }
  const expl = ((q.blocks || []).find(b => b && b.type === 'explanation' && stripHtml(b.content || '').trim()));
  if (expl) brief.teacherExplanation = _fcClip(expl.content);
  const cm = ((q.blocks || []).find(b => b && b.type === 'commonMistake' && stripHtml(b.text || '').trim()));
  if (cm) brief.commonMistakeNote = _fcClip(cm.text);
  return brief;
}

// The student's own wrong answers on this gap's questions, newest first.
function _fcGapEvidence(gap, limit) {
  const ids = new Set(gap.questions.map(x => String(x.q.id)));
  return mistakeLog
    .filter(r => r && ids.has(String(r.qId)))
    .slice(0, limit || 6)
    .map(r => ({
      onQuestion: _fcClip(r.qTitle),
      theyWrote: _fcClip(r.student),
      markIsFor: _fcClip(r.expected),
      kind: r.kind === 'mcq' ? 'multiple-choice' : 'written',
      when: _fcWhenLabel(Date.parse(r.at) || 0),
    }));
}

function _fcDeckPrompt(gaps) {
  const payload = gaps.map(g => ({
    gap: g.label,
    howOften: g.wrong + ' wrong attempt' + (g.wrong === 1 ? '' : 's') + ' out of ' + g.attempts,
    mostRecently: _fcWhenLabel(g.last),
    bestScoreSoFar: Math.round((g.worst || 0) * 100) + '%',
    questionsTheyGotWrong: g.questions.slice(0, FC_Q_PER_GAP).map(_fcQuestionBrief),
    whatTheyActuallyWrote: _fcGapEvidence(g, 5),
  }));
  return [
    'You are making revision flashcards for one Singapore primary-school English student (P3-P6).',
    '',
    'These are the gaps in THEIR knowledge, worked out from the questions they have actually got wrong — how often, and how recently. For each gap you are given the questions they failed, the model answer, the teacher\'s explanation, and where we have it, the exact words the student wrote instead.',
    '',
    JSON.stringify(payload, null, 1),
    '',
    'Write ' + FC_CARDS_PER_GAP + ' flashcards for EACH gap. Reply with ONLY this JSON:',
    '{"title":"a short name for the whole deck","cards":[{"gap":"the exact gap string this card is for","front":"the question on the front","back":"the answer on the back","hint":"one short nudge, or \\"\\""}]}',
    '',
    'THE RULES THAT MAKE THESE REVISION CARDS RATHER THAN FACT CARDS:',
    '- Every card must target the specific thing THIS student got wrong. Where you are told what they wrote, aim the card straight at that error — if they said a heavier mass makes a spring "heavier" instead of "stretch more", the card asks what happens to the extension and why.',
    '- Use ONLY the English in the data above: the model answers, the correct options and the teacher explanations are your source of truth. Do not add facts from your own knowledge, and never contradict a model answer even if you would have phrased it differently.',
    '- "front" is a question, never a topic heading. "What happens to the spring\'s extension when the mass is doubled?" — not "Elastic spring force".',
    '- "back" is the full mark-worthy answer in one or two short sentences, in the plain wording a P3-P6 child would be expected to write. Include the BECAUSE — the reasoning is where the marks are.',
    '- Never write a card whose answer is just "yes" or "no". Ask for the reason instead.',
    '- Do not copy a question from the data word for word. Change the numbers, the object or the situation so they have to think rather than remember the page.',
    '- Vary what you ask for across a gap\'s cards: a definition, a cause-and-effect, a "why is the wrong answer wrong", a real-life example.',
    '- "hint" is a nudge that does NOT give the answer away, or an empty string. Never put the answer in the hint.',
    '- Plain text only. No markdown, no bullet symbols, no headings, no bold.',
    '- "gap" must be copied EXACTLY as it appears above, so the app can file the card.',
  ].join('\n');
}

// Build a deck for the given gaps, save it, and return it.
async function fcBuildDeck(gaps) {
  if (!Array.isArray(gaps) || !gaps.length) throw new Error('there are no gaps to build from yet');
  if (!window.__aiReady || !window.__aiReady()) throw new Error('the AI is not ready — try again in a moment');
  const raw = await askGemini(_fcDeckPrompt(gaps), {
    maxOutputTokens: 300 + gaps.length * FC_CARDS_PER_GAP * 130, temperature: 0.5, json: true,
  });
  const parsed = _parseAIJson(raw) || {};
  const labels = new Map(gaps.map(g => [g.label.toLowerCase(), g.label]));
  const qIdsByGap = new Map(gaps.map(g => [g.label.toLowerCase(), g.questions.slice(0, FC_Q_PER_GAP).map(x => String(x.q.id))]));
  const seen = new Set();
  const cards = (Array.isArray(parsed.cards) ? parsed.cards : []).map((c, i) => {
    const front = _fcClip(c && c.front), back = _fcClip(c && c.back);
    if (!front || !back) return null;
    const key = front.toLowerCase();
    if (seen.has(key)) return null;                 // the model does sometimes repeat itself
    seen.add(key);
    // An unrecognised gap string is filed under the strongest gap rather than
    // dropped — the card is still about this student's work.
    const gk = String((c && c.gap) || '').trim().toLowerCase();
    const gap = labels.get(gk) || gaps[0].label;
    return {
      id: 'fc' + i + '_' + Math.random().toString(36).slice(2, 7),
      front, back, hint: _fcClip(c && c.hint), gap,
      qIds: qIdsByGap.get(gap.toLowerCase()) || [],
      box: 0, due: 0, seen: 0, right: 0, wrong: 0,
    };
  }).filter(Boolean);
  if (!cards.length) throw new Error('the AI did not return any usable cards');
  const deck = {
    id: 'fd_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 6),
    title: _fcClip(parsed.title) || (gaps.length === 1 ? gaps[0].label : 'My weak spots') ,
    gaps: gaps.map(g => g.label),
    source: 'mistakes',
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    cards,
  };
  deck.title = deck.title.slice(0, 90);
  fcDecks.unshift(deck);
  await fcSaveDeck(deck);
  return deck;
}

// ---- decks: storage + when each card comes back -----------------------------
// Leitner boxes. "Still shaky" always sends a card back to box 0, so a card they
// keep missing keeps coming back today; "Got it" moves it up one and the gap
// between sightings widens. Five boxes is enough for revision measured in weeks,
// and a child can see the whole ladder.
const FC_INTERVAL_DAYS = [0, 1, 3, 7, 16];
let fcDecks = [];
let fcRun = null;      // { deckId, queue:[cardId], i, flipped, right, wrong } while reviewing

function _fcCol() { return collection(db, 'users', currentUser.uid, FLASHCARDS_COL); }
function _fcRef(id) { return doc(db, 'users', currentUser.uid, FLASHCARDS_COL, id); }

// Anything loaded from Firestore is put through this, so a half-written or
// hand-edited document can never break the review screen.
function _fcNormalise(raw, id) {
  if (!raw || typeof raw !== 'object') return null;
  const cards = (Array.isArray(raw.cards) ? raw.cards : []).map((c, i) => {
    if (!c || typeof c !== 'object') return null;
    const front = String(c.front || '').trim();
    const back = String(c.back || '').trim();
    if (!front || !back) return null;
    return {
      id: String(c.id || ('c' + i)),
      front, back,
      hint: String(c.hint || '').trim(),
      gap: String(c.gap || '').trim(),
      qIds: (Array.isArray(c.qIds) ? c.qIds : []).map(String).slice(0, 6),
      box: Math.max(0, Math.min(FC_INTERVAL_DAYS.length - 1, parseInt(c.box, 10) || 0)),
      due: Number(c.due) || 0,
      seen: Math.max(0, parseInt(c.seen, 10) || 0),
      right: Math.max(0, parseInt(c.right, 10) || 0),
      wrong: Math.max(0, parseInt(c.wrong, 10) || 0),
    };
  }).filter(Boolean);
  if (!cards.length) return null;
  return {
    id: String(raw.id || id || ''),
    title: String(raw.title || 'Revision deck').slice(0, 90),
    gaps: (Array.isArray(raw.gaps) ? raw.gaps : []).map(g => String(g)).slice(0, 12),
    source: String(raw.source || 'mistakes'),
    createdAt: String(raw.createdAt || ''),
    updatedAt: String(raw.updatedAt || ''),
    cards,
  };
}

async function loadFlashcardDecks() {
  if (!currentUser || !db) return;
  try {
    const snap = await getDocs(_fcCol());
    const out = [];
    snap.forEach(d => { const deck = _fcNormalise(d.data(), d.id); if (deck && deck.id) out.push(deck); });
    out.sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
    fcDecks = out;
  } catch (e) { console.warn('flashcard decks load', e); }
}

async function fcSaveDeck(deck) {
  if (!currentUser || !db || !deck || !deck.id) return false;
  deck.updatedAt = new Date().toISOString();
  fcPaintDueBadge();
  try { await setDoc(_fcRef(deck.id), deck); return true; }
  catch (e) { console.warn('flashcard deck save', e); return false; }
}

// Cards waiting, on the sidebar item. Silent when there is nothing to do — a
// badge that is always lit stops being information.
function fcPaintDueBadge() {
  const el = document.getElementById('fcDueBadge');
  if (!el) return;
  const n = fcDecks.reduce((s, d) => s + fcDueCards(d).length, 0);
  el.textContent = String(n);
  el.style.display = n ? '' : 'none';
}

function fcCardDue(card, now) {
  return (Number(card && card.due) || 0) <= (now || Date.now());
}
function fcDueCards(deck, now) {
  return ((deck && deck.cards) || []).filter(c => fcCardDue(c, now));
}
// How much of a deck is "learned": cards that have climbed past the first two
// boxes. A percentage of cards SEEN would flatter a student who pressed "Got it"
// on everything once; this only moves when a card survives being asked again.
function fcDeckMastery(deck) {
  const cards = (deck && deck.cards) || [];
  if (!cards.length) return 0;
  return Math.round(100 * cards.filter(c => (c.box || 0) >= 2).length / cards.length);
}
// Grade one card. `ok` false always resets to box 0 — the whole point of the deck
// is that a gap keeps coming back until it closes.
function fcGrade(card, ok) {
  if (!card) return;
  card.seen = (card.seen || 0) + 1;
  if (ok) {
    card.right = (card.right || 0) + 1;
    card.box = Math.min(FC_INTERVAL_DAYS.length - 1, (card.box || 0) + 1);
  } else {
    card.wrong = (card.wrong || 0) + 1;
    card.box = 0;
  }
  const days = FC_INTERVAL_DAYS[card.box] || 0;
  // Box 0 is due immediately, so a missed card can be re-tried in this same sitting.
  card.due = days ? Date.now() + days * 86400000 : Date.now();
}

// ---- the page ---------------------------------------------------------------
let _fcBusy = false;
let _fcGapSel = new Set();      // gap keys ticked for the next build

async function renderFlashcardsPage() {
  const c = document.getElementById('flashcardsContainer');
  if (!c) return;
  if (fcRun) { _fcRenderRun(); return; }
  c.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text-muted);">Looking at what you\'ve been getting wrong…</div>';
  try { await loadAttemptStats(); } catch (_) {}
  try { if (!fcDecks.length) await loadFlashcardDecks(); } catch (_) {}
  try { await loadMistakeLog(); } catch (_) {}
  _fcRenderHome();
}

function _fcRenderHome() {
  const c = document.getElementById('flashcardsContainer');
  if (!c) return;
  const gaps = fcGaps();
  // Drop ticks for gaps that have since closed, so a stale selection can't build
  // a deck about something they have now got right.
  Array.from(_fcGapSel).forEach(k => { if (!gaps.some(g => g.key === k)) _fcGapSel.delete(k); });
  const now = Date.now();

  // Severity is shown as a word, relative to their own worst gap. The raw score is
  // a made-up number on a made-up scale — "2.9" tells a child nothing, and printing
  // it would only invite them to try to make it go down.
  const topScore = gaps.length ? gaps[0].score : 0;
  const severity = g => {
    const r = topScore ? g.score / topScore : 0;
    if (r >= 0.75) return { label: 'biggest gap', cls: 'hot' };
    if (r >= 0.35) return { label: 'needs work', cls: 'warm' };
    return { label: 'minor', cls: 'cool' };
  };
  const gapRows = gaps.map(g => {
    const on = _fcGapSel.has(g.key);
    const sev = severity(g);
    const detail = g.wrong + '× wrong of ' + g.attempts + ' ' + (g.attempts === 1 ? 'try' : 'tries') +
      ' · last slipped ' + _fcWhenLabel(g.last) +
      (g.worst < 1 ? ' · best so far ' + Math.round(g.worst * 100) + '%' : '');
    return `<button type="button" class="fc-gap${on ? ' on' : ''}" onclick="fcToggleGap(${JSON.stringify(g.key).replace(/"/g, '&quot;')})">
      <span class="fc-gap-tick" aria-hidden="true">${on ? '✓' : ''}</span>
      <span class="fc-gap-txt">
        <b>${escapeHtml(g.label)}</b>
        <span>${escapeHtml(detail)}</span>
      </span>
      <span class="fc-gap-n ${sev.cls}" title="How much this is costing you compared with your other gaps">${sev.label}</span>
    </button>`;
  }).join('');

  const nSel = _fcGapSel.size;
  const buildCard = gaps.length ? `
    <div class="card card-pad fc-build">
      <h3 style="margin:0;">🎯 Your gaps right now</h3>
      <p class="fc-lede">Worked out from the questions you've actually got wrong — the ones you miss <b>often</b> and <b>recently</b> come first. Pick the ones to revise, or just press the button and I'll take the top three.</p>
      <div class="fc-gaps">${gapRows}</div>
      <div class="fc-build-row">
        <button class="btn btn-primary btn-lg" onclick="fcBuildFromGaps()" ${_fcBusy ? 'disabled' : ''}>
          ${_fcBusy ? '⏳ Writing your cards…' : '✨ Make my revision cards' + (nSel ? ' (' + nSel + ' gap' + (nSel === 1 ? '' : 's') + ')' : '')}
        </button>
        ${nSel ? `<button class="btn btn-outline" onclick="fcClearGaps()" ${_fcBusy ? 'disabled' : ''}>Clear</button>` : ''}
      </div>
      <div class="fc-note">${mistakeLog.length
        ? 'Your cards are written from the marks you lost — the model answer you needed, and what you wrote instead.'
        : 'Cards are written from the questions you got wrong. Keep practising and they get sharper, because I start remembering exactly which part you lost the mark on.'}</div>
    </div>` : `
    <div class="card card-pad fc-build">
      <h3 style="margin:0;">🎯 Nothing to revise yet</h3>
      <p class="fc-lede">Flashcards here are built from your own mistakes, so there's nothing to make until you've got a few questions wrong. Do some practice first and come back — this fills itself in.</p>
      <div class="fc-build-row">
        <button class="btn btn-primary btn-lg" onclick="navigateTo('quickpractice');startQuickPractice();">Start practising</button>
      </div>
    </div>`;

  const deckRows = fcDecks.map(d => {
    const due = fcDueCards(d, now).length;
    const mastery = fcDeckMastery(d);
    return `<div class="fc-deck">
      <div class="fc-deck-head">
        <div class="fc-deck-what">
          <b>${escapeHtml(d.title)}</b>
          <span>${d.cards.length} card${d.cards.length === 1 ? '' : 's'} · ${escapeHtml((d.gaps || []).slice(0, 3).join(', ') || 'mixed')}${(d.gaps || []).length > 3 ? ' +' + ((d.gaps || []).length - 3) : ''}</span>
        </div>
        <span class="fc-deck-due${due ? ' on' : ''}">${due ? due + ' due' : 'all caught up'}</span>
      </div>
      <div class="fc-bar" title="${mastery}% of the cards have survived being asked more than once"><div class="fc-bar-fill" style="width:${mastery}%;"></div></div>
      <div class="fc-deck-row">
        <button class="btn btn-primary" onclick="fcStartReview('${d.id}')">${due ? '▶ Revise ' + due : '🔁 Revise all ' + d.cards.length}</button>
        <button class="btn btn-outline" onclick="fcDeleteDeck('${d.id}')" style="color:var(--accent-red);">Delete</button>
      </div>
    </div>`;
  }).join('');

  c.innerHTML = buildCard + (fcDecks.length ? `
    <div class="card card-pad" style="margin-top:18px;">
      <h3 style="margin:0 0 4px;">🗂 My decks</h3>
      <p class="fc-lede">A card you get right comes back later; one you miss comes straight back. The bar is how many have stuck.</p>
      <div class="fc-decks">${deckRows}</div>
    </div>` : '');
}

function fcToggleGap(key) {
  if (_fcGapSel.has(key)) _fcGapSel.delete(key); else _fcGapSel.add(key);
  _fcRenderHome();
}
function fcClearGaps() { _fcGapSel.clear(); _fcRenderHome(); }

// No selection means "you decide" — the top three gaps, which is what a student
// who just wants to revise actually wants.
async function fcBuildFromGaps() {
  if (_fcBusy) return;
  const all = fcGaps();
  const chosen = _fcGapSel.size ? all.filter(g => _fcGapSel.has(g.key)) : all.slice(0, 3);
  if (!chosen.length) { showToast('Nothing to build from yet — do some practice first', 'info'); return; }
  _fcBusy = true;
  _fcRenderHome();
  try {
    const deck = await fcBuildDeck(chosen);
    _fcGapSel.clear();
    _fcBusy = false;
    _fcRenderHome();
    showToast('✨ ' + deck.cards.length + ' cards ready — on your weakest spots', 'success');
  } catch (e) {
    console.warn('flashcard build', e);
    _fcBusy = false;
    _fcRenderHome();
    showToast('Couldn\'t make the cards — ' + ((e && e.message) || 'try again in a moment'), 'error');
  }
}

async function fcDeleteDeck(id) {
  const deck = fcDecks.find(d => d.id === id);
  if (!deck) return;
  if (!confirm('Delete “' + deck.title + '”?\n\nThe ' + deck.cards.length + ' cards in it go too. Your gaps stay, so you can always make a fresh deck.')) return;
  fcDecks = fcDecks.filter(d => d.id !== id);
  if (fcRun && fcRun.deckId === id) fcRun = null;
  _fcRenderHome();
  try { await deleteDoc(_fcRef(id)); } catch (e) { console.warn('deck delete', e); }
  showToast('Deck deleted', 'info');
}

// ---- reviewing --------------------------------------------------------------
// Due cards first; if nothing is due the whole deck is offered, because a student
// who came here to revise should never be told to come back tomorrow.
function fcStartReview(deckId) {
  const deck = fcDecks.find(d => d.id === deckId);
  if (!deck || !deck.cards.length) return;
  const now = Date.now();
  let pool = fcDueCards(deck, now);
  if (!pool.length) pool = deck.cards.slice();
  // Weakest first: most-missed, then least-seen.
  pool.sort((a, b) => ((b.wrong || 0) - (a.wrong || 0)) || ((a.seen || 0) - (b.seen || 0)));
  fcRun = { deckId, queue: pool.map(c => c.id), i: 0, flipped: false, right: 0, wrong: 0, done: 0 };
  _fcRenderRun();
}

function _fcRunDeck() { return fcRun ? fcDecks.find(d => d.id === fcRun.deckId) : null; }
function _fcRunCard() {
  const deck = _fcRunDeck();
  if (!deck || !fcRun) return null;
  const id = fcRun.queue[fcRun.i];
  return deck.cards.find(c => c.id === id) || null;
}

function _fcRenderRun() {
  const c = document.getElementById('flashcardsContainer');
  const deck = _fcRunDeck();
  if (!c || !deck || !fcRun) { fcRun = null; _fcRenderHome(); return; }
  if (fcRun.i >= fcRun.queue.length) { _fcRenderRunDone(); return; }
  const card = _fcRunCard();
  if (!card) { fcRun.i++; _fcRenderRun(); return; }
  const total = fcRun.queue.length;
  const pct = Math.round((fcRun.i / total) * 100);
  const boxLabel = 'Box ' + ((card.box || 0) + 1) + ' of ' + FC_INTERVAL_DAYS.length;
  c.innerHTML = `
    <div class="fc-run">
      <div class="fc-run-top">
        <button class="btn btn-outline" onclick="fcEndReview()" style="font-size:0.82rem;">← Done for now</button>
        <div class="fc-run-count">Card ${fcRun.i + 1} of ${total}</div>
      </div>
      <div class="fc-bar"><div class="fc-bar-fill" style="width:${pct}%;"></div></div>
      <div class="fc-card${fcRun.flipped ? ' flipped' : ''}" onclick="${fcRun.flipped ? '' : 'fcFlip()'}" role="button" tabindex="0"
        aria-label="${fcRun.flipped ? 'Answer' : 'Question — tap to see the answer'}">
        <div class="fc-card-gap">🏷 ${escapeHtml(card.gap || deck.title)}</div>
        <div class="fc-card-front">${escapeHtml(card.front)}</div>
        ${fcRun.flipped
          ? `<div class="fc-card-back"><div class="fc-card-back-label">Answer</div>${escapeHtml(card.back)}</div>`
          : (card.hint ? `<div class="fc-card-hint">💡 ${escapeHtml(card.hint)}</div>` : '')}
        ${fcRun.flipped ? '' : '<div class="fc-card-tap">Tap the card when you\'ve had a go</div>'}
      </div>
      ${fcRun.flipped ? `
      <div class="fc-run-actions">
        <button class="btn btn-outline fc-again" onclick="fcAnswer(false)">Still shaky — ask me again</button>
        <button class="btn btn-primary" onclick="fcAnswer(true)">I got it ✓</button>
      </div>
      <div class="fc-run-meta">${escapeHtml(boxLabel)} · answer honestly, it only decides how soon this comes back</div>`
      : `<div class="fc-run-meta">Say the answer out loud first — that's the bit that makes it stick.</div>`}
    </div>`;
}

function fcFlip() { if (fcRun) { fcRun.flipped = true; _fcRenderRun(); } }

function fcAnswer(ok) {
  const deck = _fcRunDeck(), card = _fcRunCard();
  if (!deck || !card || !fcRun) return;
  fcGrade(card, !!ok);
  if (ok) fcRun.right++; else fcRun.wrong++;
  fcRun.done++;
  fcRun.i++;
  fcRun.flipped = false;
  // A missed card goes to the back of THIS sitting as well as back to box 0 — the
  // point is to close the gap now, not to be told about it again next week.
  if (!ok && fcRun.queue.length < 60) fcRun.queue.push(card.id);
  fcSaveDeck(deck);
  _fcRenderRun();
}

function _fcRenderRunDone() {
  const c = document.getElementById('flashcardsContainer');
  const deck = _fcRunDeck();
  if (!c || !deck) { fcRun = null; _fcRenderHome(); return; }
  const right = fcRun.right, wrong = fcRun.wrong;
  const mastery = fcDeckMastery(deck);
  const stillDue = fcDueCards(deck).length;
  fcRun = null;
  c.innerHTML = `
    <div class="card card-pad" style="text-align:center;">
      <div style="font-size:2.6rem;line-height:1;">${wrong === 0 ? '🎉' : right >= wrong ? '👏' : '💪'}</div>
      <h3 style="margin:12px 0 6px;justify-content:center;">${wrong === 0 ? 'Every card, first time' : right >= wrong ? 'Good session' : 'That\'s the work paying off'}</h3>
      <p class="fc-lede" style="max-width:440px;margin:0 auto 6px;">
        ${right} got right, ${wrong} to come back to.
        ${mastery ? mastery + '% of this deck has stuck.' : 'A card counts as stuck once you\'ve got it right twice, so that number starts moving next time.'}
        ${wrong ? 'The shaky ones are queued up — they\'ll keep coming back until they aren\'t.' : 'Nothing else is due for a while, so you\'re free.'}
      </p>
      <div class="fc-build-row" style="justify-content:center;">
        ${stillDue ? `<button class="btn btn-primary" onclick="fcStartReview('${deck.id}')">Keep going (${stillDue})</button>` : ''}
        <button class="btn btn-outline" onclick="fcEndReview()">Back to my decks</button>
      </div>
    </div>`;
}

function fcEndReview() {
  const deck = _fcRunDeck();
  if (deck) fcSaveDeck(deck);
  fcRun = null;
  _fcRenderHome();
}

async function loadMyReport() {
  const c = document.getElementById('myReportContainer');
  if (!c) return;
  c.innerHTML = `<div style="padding:40px;text-align:center;color:var(--text-muted);">Loading your report…</div>`;
  if (!cerPerf) await loadCerPerf();
  const p = cerPerf || _emptyPerf();
  if (!p.attempts) {
    c.innerHTML = `<div class="empty-state"><h3>No practice yet</h3><p>Answer some questions in Quick or Topical Practice and your live report will appear here.</p></div>`;
    return;
  }
  let percentile = null, peers = 0;
  try {
    const snap = await getDocs(collection(db, PROGRESS_COL));
    const retired = await _getRetiredUids();
    const scores = []; snap.forEach(d => { if (retired.has(d.id)) return; const v = d.data(); if (v && typeof v.score100 === 'number') scores.push(v.score100); });
    peers = scores.length;
    if (peers > 1) { const atOrBelow = scores.filter(s => s <= p.score100).length; percentile = Math.max(1, Math.round(100 * atOrBelow / peers)); }
  } catch (e) { console.warn('leaderboard read', e); }

  const topics = _topicAccuracy(p).sort((a, b) => b.acc - a.acc);
  const strengths = topics.slice(0, 3);
  const improvements = topics.slice().reverse().slice(0, 3);
  const sc = p.score100 || 0;
  const overallPct = p.totalPossible ? Math.round(100 * p.totalScore / p.totalPossible) : 0;
  const chip = (t, color) => `<span style="display:inline-block;padding:5px 10px;border-radius:999px;background:${color}1a;color:${color};font-weight:600;font-size:0.82rem;margin:3px 4px 0 0;">${escapeHtml(t.topic)} — ${t.acc}%</span>`;

  c.innerHTML = `
    <div class="card card-pad" style="display:flex;gap:24px;flex-wrap:wrap;align-items:center;">
      <div style="text-align:center;min-width:150px;">
        <div style="font-size:3.2rem;font-weight:800;line-height:1;color:${_scoreColor(sc)};">${sc}<span style="font-size:1.1rem;color:var(--text-muted);font-weight:600;">/100</span></div>
        <div style="font-size:0.8rem;color:var(--text-muted);margin-top:4px;">Performance score</div>
      </div>
      <div style="text-align:center;min-width:130px;">
        <div style="font-size:2.2rem;font-weight:800;line-height:1;color:var(--primary);">${percentile != null ? percentile + '<span style="font-size:0.9rem;color:var(--text-muted);font-weight:600;">th</span>' : '—'}</div>
        <div style="font-size:0.8rem;color:var(--text-muted);margin-top:4px;">Percentile${peers > 1 ? ' of ' + peers + ' students' : ''}</div>
      </div>
      <div style="flex:1;min-width:200px;font-size:0.86rem;color:var(--text-muted);">
        <div><strong style="color:var(--text);">${p.attempts}</strong> questions practised</div>
        <div><strong style="color:var(--text);">${overallPct}%</strong> overall accuracy</div>
        <div style="margin-top:4px;font-size:0.78rem;">Updates automatically and reflects your most recent work.</div>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px;">
      <div class="card card-pad">
        <div style="font-weight:700;margin-bottom:8px;color:var(--primary);">💪 Strengths</div>
        ${strengths.length ? strengths.map(t => chip(t, 'var(--primary)')).join('') : '<span style="color:var(--text-muted);font-size:0.85rem;">Keep practising to reveal your strengths.</span>'}
      </div>
      <div class="card card-pad">
        <div style="font-weight:700;margin-bottom:8px;color:var(--accent-orange);">🎯 Focus areas</div>
        ${improvements.length ? improvements.map(t => chip(t, 'var(--accent-orange)')).join('') : '<span style="color:var(--text-muted);font-size:0.85rem;">No weak spots yet — great job!</span>'}
      </div>
    </div>
    <div class="card card-pad" style="margin-top:14px;">
      <div style="font-weight:700;margin-bottom:8px;">🧠 AI coach</div>
      <div id="reportAiNarrative" style="font-size:0.92rem;line-height:1.6;color:var(--text);"><span style="color:var(--text-muted);">Generating personalised feedback…</span></div>
    </div>`;

  generateReportNarrative(p, topics);
}
async function generateReportNarrative(p, topics) {
  const el = document.getElementById('reportAiNarrative');
  if (!el) return;
  if (!window.__aiReady || !window.__aiReady()) { el.innerHTML = '<span style="color:var(--text-muted);">AI is not ready right now — tap Refresh shortly.</span>'; return; }
  try {
    const topicLine = topics.map(t => `${t.topic}: ${t.acc}% over ${t.n}`).join('; ');
    const recent = (p.recent || []).slice(-12).map(r => `${r.topic} ${r.pct}%`).join(', ');
    const prompt =
      `You are an encouraging Singapore primary-school English tutor writing a brief progress report for a student. ` +
      `Overall performance score ${p.score100}/100 across ${p.attempts} practice questions. ` +
      `Per-topic accuracy: ${topicLine || 'n/a'}. Recent results: ${recent || 'n/a'}. ` +
      `Write warm, specific, actionable feedback addressed to "you". ` +
      `Return ONLY JSON: {"summary":"1-2 sentences","strengths":["..."],"improvements":["..."],"nextSteps":["one concrete action","..."]}. Keep each item under 18 words.`;
    const raw = await askGemini(prompt, { maxOutputTokens: 500, temperature: 0.4, json: true });
    const d = _parseAIJson(raw);
    const list = (arr) => (Array.isArray(arr) && arr.length) ? '<ul style="margin:4px 0 0 18px;">' + arr.map(x => `<li>${escapeHtml(String(x))}</li>`).join('') + '</ul>' : '';
    el.innerHTML =
      (d.summary ? `<p style="margin-bottom:8px;">${escapeHtml(d.summary)}</p>` : '') +
      (d.strengths ? `<div style="margin-bottom:6px;"><strong style="color:var(--primary);">What you're doing well</strong>${list(d.strengths)}</div>` : '') +
      (d.improvements ? `<div style="margin-bottom:6px;"><strong style="color:var(--accent-orange);">Where to improve</strong>${list(d.improvements)}</div>` : '') +
      (d.nextSteps ? `<div><strong>Next steps</strong>${list(d.nextSteps)}</div>` : '');
    if (!el.innerHTML.trim()) el.innerHTML = '<span style="color:var(--text-muted);">No feedback generated — tap Refresh.</span>';
  } catch (e) {
    console.warn('report narrative', e);
    el.innerHTML = '<span style="color:var(--text-muted);">Could not generate feedback right now. Tap Refresh to try again.</span>';
  }
}
// Reveal an explanation after marking. The answer-specific AI explanation gets
// its own "A.I. Explanation" box. The question's authored explanation block(s)
// are generic, so they're only shown as a fallback when there's no AI
// explanation. Placed right after the score so it's visible without scrolling.
// Build the model answer from the question itself (fallback when the AI did
// not supply one).
function _deriveModelAnswer(q) {
  if (!q || !Array.isArray(q.blocks)) return '';
  const parts = [];
  // The on-screen twin of the printed answer key: without the part label a
  // four-part question showed the student four unlabelled consecutive lines.
  const pMap = qHasParts(q.blocks) ? qPartMap(q.blocks) : null;
  let shown = null;
  const pre = b => {
    if (!pMap) return '';
    const p = qPartOf(pMap, b);
    if (!p || p === shown) { if (!p) shown = null; return ''; }
    shown = p;
    return qPartLabel(p) + ' ';
  };
  q.blocks.forEach(b => {
    if (b.type === 'answer') {
      const c = stripHtml(b.claim || ''), e = stripHtml(b.evidence || ''), r = stripHtml(b.reasoning || '');
      const p = (c || e || r) ? pre(b) : '';
      if (c) parts.push(p + 'Claim: ' + c);
      if (e) parts.push((p && !c ? p : '') + 'Evidence: ' + e);
      if (r) parts.push((p && !c && !e ? p : '') + 'Reasoning: ' + r);
    } else if (b.type === 'plainanswer') {
      const t = stripHtml(b.content || ''); if (t) parts.push(pre(b) + t);
    } else if (b.type === 'workingSpace' && b.annotate) {
      const t = stripHtml(b.answerKey || '').trim(); if (t) parts.push(pre(b) + 'Working area: ' + t);
    } else if (b.type === 'mcq') {
      const opt = (b.options || []).find(o => o.id === b.correctId);
      if (opt && stripHtml(opt.text || '')) parts.push(pre(b) + 'Correct option: ' + stripHtml(opt.text));
    }
  });
  return parts.join('\n');
}
function showExplanation(containerSel, q, aiText, scoreElId, modelAnswer) {
  const c = document.querySelector(containerSel);
  if (!c) return;
  c.querySelectorAll('.post-explanation').forEach(el => el.remove());
  const exps = ((q && q.blocks) || []).filter(b => b.type === 'explanation' && stripHtml(b.content || '').trim());
  const blockHtml = exps.map(b => `<div style="line-height:1.7;margin-bottom:4px;">${b.content}</div>`).join('');
  const aiText2 = (aiText && String(aiText).trim()) ? String(aiText).trim() : '';
  let cards = '';
  // A.I. Explanation card on top — the feedback specific to the student's answer.
  if (aiText2) {
    cards +=
      `<div class="post-explanation" style="margin-top:14px;padding:12px 14px;border:1px solid var(--accent-blue);background:var(--accent-blue-light,#eaf1f8);border-radius:10px;">
        <div style="font-weight:700;color:var(--accent-blue);margin-bottom:6px;">🤖 A.I. Explanation</div><div style="line-height:1.7;">${escapeHtml(aiText2)}</div></div>`;
  } else if (blockHtml) {
    // The question's authored explanation is generic (written at authoring time),
    // so it's only shown as a fallback when there's no answer-specific A.I.
    // explanation — e.g. the MCQ / fill-blank paths that don't generate one.
    cards +=
      `<div class="post-explanation" style="margin-top:14px;padding:12px 14px;border:1px solid var(--accent-blue);background:var(--accent-blue-light,#eaf1f8);border-radius:10px;">
        <div style="font-weight:700;color:var(--accent-blue);margin-bottom:6px;">💡 Explanation</div>${blockHtml}</div>`;
  }
  // Model answer card below the explanation, full width and aligned with it.
  const model = (modelAnswer && String(modelAnswer).trim()) ? String(modelAnswer).trim() : _deriveModelAnswer(q);
  if (model) {
    cards +=
      `<div class="post-explanation" style="margin-top:14px;padding:12px 14px;border:1px solid var(--primary);background:var(--primary-light,#e4f1ec);border-radius:10px;">
        <div style="font-weight:700;color:var(--primary);margin-bottom:6px;">✅ Model answer</div><div style="line-height:1.7;white-space:pre-wrap;">${escapeHtml(model)}</div></div>`;
  }
  // Interactive widget(s) authored on the question: revealed only here, after
  // the answer, in a sandboxed iframe. allow-scripts WITHOUT allow-same-origin
  // means the widget cannot reach storage, Firebase or the parent DOM; the csp
  // attribute additionally blocks outbound requests where the browser supports
  // embedded enforcement (the prompt forbids them everywhere).
  ((q && q.blocks) || []).filter(b => b && b.type === 'widget' && (b.html || '').trim()).forEach(b => {
    cards +=
      `<div class="post-explanation" style="margin-top:14px;padding:12px 14px;border:1px solid var(--accent-orange,#c77b28);background:var(--accent-orange-light,#f8efe2);border-radius:10px;">
        <div style="font-weight:700;color:var(--accent-orange,#c77b28);margin-bottom:8px;">🧩 Explore it — interactive</div>
        <div style="border-radius:8px;overflow:hidden;border:1px solid var(--border);">
          <iframe sandbox="allow-scripts" csp="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:"
                  srcdoc="${_widgetSrcdocAttr(b.html)}"
                  style="display:block;width:100%;height:${Math.max(240, Math.min(900, Number(b.height) || 480))}px;border:0;background:#fff;" loading="lazy"></iframe>
        </div></div>`;
  });
  if (!cards) return;
  // Place the cards as a full-width stack below the action bar. Inserting them
  // after the score element would drop them inside the flex action row, where
  // they get squashed beside the buttons (the cramped side-by-side layout).
  const actionsBar = c.querySelector('.practice-actions');
  if (actionsBar) actionsBar.insertAdjacentHTML('afterend', cards);
  else {
    const anchor = scoreElId ? document.getElementById(scoreElId) : null;
    if (anchor && c.contains(anchor)) anchor.insertAdjacentHTML('afterend', cards);
    else c.insertAdjacentHTML('beforeend', cards);
  }
}
let tpCurrentTopic = '';
let tpSelectedTopics = new Set();
let tpActiveTopics = []; // topics being practiced in current session

function tpRenderTopics() {
  const grid = document.getElementById('tpTopicGrid');
  if (!grid) return;
  // Show topic grid, hide practice area
  grid.style.display = '';
  document.getElementById('tpPracticeArea').style.display = 'none';
  document.getElementById('tpBackBtn').style.display = 'none';
  document.getElementById('tpLevelBar').style.display = '';
  document.getElementById('tpPageTitle').textContent = 'Topical Practice';
  document.getElementById('tpPageSubtitle').textContent = 'Select one or more topics, then click Practice';

  const studentLevel = document.getElementById('tpLevelSelect').value;
  const studentLevelNum = getLevelNumber(studentLevel);

  // Count questions per topic (only those the AI can mark, and in-syllabus)
  const topicCounts = {};
  questionBank.forEach(q => {
    if (questionHasMarkableAnswer(q) && qInSyllabus(q)) {
      qTopicList(q).forEach(t => { topicCounts[t] = (topicCounts[t] || 0) + 1; });
    }
  });

  // Remove selected topics that are no longer accessible at this level
  tpSelectedTopics.forEach(t => {
    const tLevel = getTopicLevel(t);
    if (getLevelNumber(tLevel) > studentLevelNum) tpSelectedTopics.delete(t);
  });

  // ONE flat grid. The P3/P4/P5/P6 headings that used to bracket this list are
  // gone — an English topic is not owned by a year the way a Science one is, and
  // four headings on a phone pushed the actual topics below the fold. The level
  // each topic is filed under still decides whether it is unlocked; it is simply
  // no longer announced. Topics stay in level order, so everything a student can
  // reach still comes before everything they cannot.
  let html = '<div class="tp-topic-grid">';
  const flatTopics = TOPIC_LEVELS.reduce((a, lv) => a.concat(topicsByLevel[lv] || []), []);

  flatTopics.forEach(topic => {
    const level = getTopicLevel(topic);
    const isAccessible = getLevelNumber(level) <= studentLevelNum;
    const colors = levelColors[level] || levelColors['P6'];
    const count = topicCounts[topic] || 0;
    const emoji = topicEmojis[topic] || '📘';
    const isSelected = tpSelectedTopics.has(topic);
    if (isAccessible) {
      html += `<button class="tp-topic-btn${count === 0 ? ' disabled' : ''}${isSelected ? ' selected' : ''}" onclick="${count > 0 ? `tpToggleTopic('${topic.replace(/'/g, "\\'")}')` : ''}">
        <div class="tp-topic-icon" style="background:${colors.bg};font-size:1.3rem;">
          ${emoji}
        </div>
        <span class="tp-topic-name">${escapeHtml(topic)}</span>
        <span class="tp-topic-count">${count} Q</span>
      </button>`;
    } else {
      html += `<button class="tp-topic-btn disabled" title="Locked — choose a higher level to unlock">
        <div class="tp-topic-icon" style="background:var(--surface-alt);font-size:1.3rem;filter:grayscale(1) opacity(0.4);">
          ${emoji}
        </div>
        <span class="tp-topic-name">${escapeHtml(topic)}</span>
        <span class="tp-lock-icon">🔒</span>
      </button>`;
    }
  });

  html += `</div>`;

  grid.innerHTML = html;
  tpUpdateSelectionBar();
}

function tpToggleTopic(topic) {
  if (tpSelectedTopics.has(topic)) {
    tpSelectedTopics.delete(topic);
  } else {
    tpSelectedTopics.add(topic);
  }
  tpRenderTopics();
}

function tpClearSelection() {
  tpSelectedTopics.clear();
  tpRenderTopics();
}

function tpRemoveSelectedTopic(topic) {
  tpSelectedTopics.delete(topic);
  tpRenderTopics();
}

function tpUpdateSelectionBar() {
  const bar = document.getElementById('tpSelectionBar');
  const tagsEl = document.getElementById('tpSelectionTags');
  const countEl = document.getElementById('tpSelectionCount');
  if (!bar) return;

  if (tpSelectedTopics.size === 0) {
    bar.style.display = 'none';
    return;
  }

  bar.style.display = '';
  countEl.textContent = tpSelectedTopics.size;

  let tagsHtml = '';
  tpSelectedTopics.forEach(topic => {
    const emoji = topicEmojis[topic] || '📘';
    tagsHtml += `<span class="tp-selection-tag">
      ${emoji} ${escapeHtml(topic)}
      <span class="tp-tag-remove" onclick="event.stopPropagation();tpRemoveSelectedTopic('${topic.replace(/'/g, "\\'")}')">&times;</span>
    </span>`;
  });
  tagsEl.innerHTML = tagsHtml;
}

async function tpStartPractice() {
  if (tpSelectedTopics.size === 0) {
    showToast('Select at least one topic first', 'error');
    return;
  }

  tpActiveTopics = Array.from(tpSelectedTopics);

  // Gather questions per topic, each ordered unattempted-first then weakest-first
  // (orderByAttemptPriority shuffles within those groups).
  await loadAttemptStats();
  const questionsByTopic = {};
  const tpServed = new Set(qpLoadSeen());   // same served memory as quick practice
  tpActiveTopics.forEach(topic => {
    const markable = questionBank.filter(q => questionHasMarkableAnswer(q) && qInSyllabus(q) && qMatchesTopic(q, topic) && qWithinStudentLevel(q));
    const ordered = orderByAttemptPriority(markable);
    // Demote questions served recently in any practice session so abandoned
    // sessions don't lead with the same questions every time.
    questionsByTopic[topic] = ordered.filter(q => !tpServed.has(String(q.id)))
      .concat(ordered.filter(q => tpServed.has(String(q.id))));
  });

  // Interleave: round-robin across topics, skip exhausted topics
  const queue = [];
  const indices = {};
  tpActiveTopics.forEach(t => { indices[t] = 0; });
  let remaining = tpActiveTopics.filter(t => questionsByTopic[t].length > 0);

  while (remaining.length > 0) {
    for (const topic of remaining) {
      if (indices[topic] < questionsByTopic[topic].length) {
        queue.push(questionsByTopic[topic][indices[topic]]);
        indices[topic]++;
      }
    }
    remaining = remaining.filter(t => indices[t] < questionsByTopic[t].length);
  }

  let title, subtitle, labelHtml;
  if (tpActiveTopics.length === 1) {
    tpCurrentTopic = tpActiveTopics[0];
    const topicLevel = getTopicLevel(tpCurrentTopic);
    const colors = levelColors[topicLevel] || levelColors['P6'];
    title = tpCurrentTopic;
    subtitle = topicLevel + ' — ' + queue.length + ' question' + (queue.length !== 1 ? 's' : '');
    labelHtml = `
      <span class="tp-level-badge" style="background:${colors.bg};color:${colors.fg};">${topicLevel}</span>
      ${escapeHtml(tpCurrentTopic)}`;
  } else {
    tpCurrentTopic = tpActiveTopics.join(', ');
    title = 'Mixed Topics Practice';
    subtitle = tpActiveTopics.length + ' topics — ' + queue.length + ' question' + (queue.length !== 1 ? 's' : '');
    labelHtml = tpActiveTopics.map(t => {
      const lv = getTopicLevel(t);
      const c = levelColors[lv] || levelColors['P6'];
      const em = topicEmojis[t] || '📘';
      return `<span class="tp-level-badge" style="background:${c.bg};color:${c.fg};margin-right:4px;">${em} ${escapeHtml(t)}</span>`;
    }).join('');
  }

  await tpRunQueue(queue, {
    title, subtitle, labelHtml,
    emptyMsg: 'No markable questions found for the selected topics',
    restart: () => tpStartPractice(),
  });
}

// How to run the session that just finished, again. Set by whoever filled the
// queue, because "Restart" on the end-of-session report cannot know whether it
// is restarting a topic selection or a gap — and a gap session left to the
// topic path lands on "Select at least one topic first", a button that does
// nothing but tell you off.
let _tpRestart = null;
function tpRestart() { if (typeof _tpRestart === 'function') _tpRestart(); else tpStartPractice(); }

// Put a queue of questions on this surface and start it. Topical Practice and
// gap practice both come through here, so a session started from the gap list
// is the same session in every respect but what filled the queue.
async function tpRunQueue(queue, opts) {
  const cfg = opts || {};
  _tpRestart = (typeof cfg.restart === 'function') ? cfg.restart : null;
  tpQueue = Array.isArray(queue) ? queue : [];
  tpSessionResults = [];
  tpIndex = -1;
  tpAnswered = 0;

  if (tpQueue.length === 0) {
    showToast(cfg.emptyMsg || 'No markable questions found', 'error');
    return false;
  }

  // Switch to practice view
  document.getElementById('tpTopicGrid').style.display = 'none';
  document.getElementById('tpLevelBar').style.display = 'none';
  document.getElementById('tpSelectionBar').style.display = 'none';
  document.getElementById('tpPracticeArea').style.display = '';
  document.getElementById('tpBackBtn').style.display = '';

  document.getElementById('tpPageTitle').textContent = cfg.title || 'Practice';
  document.getElementById('tpPageSubtitle').textContent = cfg.subtitle || '';
  document.getElementById('tpCurrentTopicLabel').innerHTML = cfg.labelHtml || '';

  // Preload all images in the queue before starting
  await preloadQueueImages(tpQueue);
  tpLoadNextQuestion();
  return true;
}

// Legacy single-topic start (kept for compatibility but routes through multi-select)
function tpStartTopic(topic) {
  tpSelectedTopics.clear();
  tpSelectedTopics.add(topic);
  tpStartPractice();
}

function tpLoadNextQuestion() {
  tpIndex++;
  if (tpIndex >= tpQueue.length) {
    renderPracticeReport('#tpContainer', tpSessionResults, `
        <button class="btn btn-outline" onclick="tpBackToTopics()">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:14px;height:14px;"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>
          Back to Topics
        </button>
        <button class="btn btn-primary" onclick="tpRestart()">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:14px;height:14px;"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>
          Restart
        </button>`);
    tpUpdateProgress();
    return;
  }
  const _tpQ = tpQueue[tpIndex];
  if (_tpQ && _tpQ.id) qpMarkServed(_tpQ.id); // shared served memory with quick practice
  tpRenderQuestion(_tpQ);
  tpUpdateProgress();
}

function tpUpdateProgress() {
  const total = tpQueue.length;
  const textEl = document.getElementById('tpProgressText');
  const fillEl = document.getElementById('tpProgressFill');
  if (textEl) textEl.textContent = `${tpAnswered} / ${total} answered`;
  if (fillEl) fillEl.style.width = total > 0 ? `${Math.round((tpAnswered / total) * 100)}%` : '0%';
}

function tpRenderQuestion(q) {
  const qLevel = getTopicLevel(q.topic || '');
  let html = `
    <div class="practice-card">
      <div class="practice-card-header">
        <h3>${escapeHtml(q.title)}</h3>
        <div style="display:flex;gap:6px;align-items:center;">
          <span class="qp-level-badge">${escapeHtml(qLevel)}</span>
          <span class="qb-tag category">${escapeHtml(normalizeCategoryValue(q.category))}</span>
          <span class="qb-tag topic">${escapeHtml(q.topic)}</span>
          ${qSecondaryTagsHtml(q)}
        </div>
      </div>
      <div class="practice-card-body">`;

  html += buildOpenBody(q, '#tpContainer', {
    scoreElId: 'tpScoreDisplay', scorePrefix: 'AI Score', mode: 'topicalpractice-open', onAllMarked: _tpAllPartsMarked
  });

  html += `</div>
      <div class="practice-actions">
        <div style="display:flex;align-items:center;gap:10px;">
          <div class="practice-score" id="tpScoreDisplay"></div>
          <button class="flag-question-btn" onclick="openFlagDialog('${q.id}','${escapeHtml(q.title).replace(/'/g,"\\'")}')">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg>
            Flag
          </button>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;">
          <button class="btn btn-outline" onclick="tpResetOpenAnswers()">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:14px;height:14px;"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>
            Reset
          </button>
          <button class="btn btn-primary" id="tpNextBtn" onclick="tpLoadNextQuestion()" style="display:none;">
            Next &rarr;
          </button>
        </div>
      </div>
    </div>`;

  tpSubmitted = false;
  document.getElementById('tpContainer').innerHTML = html;
  // Nothing for the AI to mark — let the student move on straight away.
  if (!questionHasMarkableAnswer(q)) {
    const nextBtn = document.getElementById('tpNextBtn');
    if (nextBtn) nextBtn.style.display = '';
  }
}

function tpResetOpenAnswers() {
  if (tpSubmitted) return;
  resetOpenAnswersIn('#tpContainer', 'tpScoreDisplay');
}

// Every part of the current Topical Practice question has been AI-marked.
function _tpAllPartsMarked(res) {
  if (tpSubmitted) return;
  tpSubmitted = true;
  document.querySelectorAll('#tpContainer .open-answer').forEach(a => a.disabled = true);
  document.querySelectorAll('#tpContainer .part-ai-btn').forEach(b => b.disabled = true);
  _recordTpResult(res.score, res.total, res.mistakes);
  tpAnswered = Math.max(tpAnswered, tpIndex + 1);
  tpUpdateProgress();
  const nextBtn = document.getElementById('tpNextBtn');
  if (nextBtn) nextBtn.style.display = '';
}

function tpBackToTopics() {
  tpQueue = [];
  tpIndex = -1;
  tpAnswered = 0;
  tpCurrentTopic = '';
  tpActiveTopics = [];
  tpRenderTopics();
}

// =====================================================================
// STUDENT USAGE DASHBOARD (Admin Only)
// =====================================================================
let usageDashboardLoaded = false;
// Cache of the latest per-student stats (keyed by uid) so the drill-in modal
// can show name/email without re-fetching profiles.
let _usageStudentStats = {};
// Two consecutive attempts closer than this are flagged as suspiciously fast.
const RAPID_ATTEMPT_MS = 15000;

async function loadUsageDashboard() {
  if (!currentUser || currentUser.role !== 'admin') return;

  try {
    // Load all user profiles (students only). Accounts retired by a password
    // reset are excluded everywhere — their progress lives on the new uid.
    const profilesSnap = await getDocs(collection(db, PROFILES_COL));
    const profiles = {};
    const retiredUids = new Set();
    profilesSnap.forEach(d => {
      const p = d.data();
      if (p.supersededBy || p.retired) { retiredUids.add(p.uid || d.id); return; }
      if (p.role !== 'admin') profiles[p.uid] = p;
    });

    // Load all login events
    const loginsSnap = await getDocs(collection(db, LOGINS_COL));
    const allLogins = [];
    loginsSnap.forEach(d => {
      const l = d.data();
      if (!ADMIN_EMAILS.includes(l.email) && !retiredUids.has(l.uid)) allLogins.push(l);
    });

    // Sort by timestamp descending
    allLogins.sort((a, b) => {
      const ta = a.timestamp ? (a.timestamp.toDate ? a.timestamp.toDate() : new Date(a.timestamp)) : new Date(0);
      const tb = b.timestamp ? (b.timestamp.toDate ? b.timestamp.toDate() : new Date(b.timestamp)) : new Date(0);
      return tb - ta;
    });

    // Load all question attempts
    const attemptsSnap = await getDocs(collection(db, ATTEMPTS_COL));
    const allAttempts = [];
    attemptsSnap.forEach(d => {
      const a = d.data();
      if (!retiredUids.has(a.uid)) allAttempts.push(a);
    });

    // Compute per-student stats
    const studentStats = {};
    // From profiles
    Object.values(profiles).forEach(p => {
      studentStats[p.uid] = {
        uid: p.uid,
        email: p.email || '',
        name: p.displayName || p.email || 'Unknown',
        level: /^P[3-6]$/.test(p.level || '') ? p.level : '',
        // What the app is actually serving them at. A family that declared
        // "Aiken is P4" writes that into students[], never into level — so the
        // assigned-level column showed "—" for a child with a perfectly clear
        // level, and nothing on this page revealed the real cap.
        servingLevel: /^P[3-6]$/.test(p.servingLevel || '') ? p.servingLevel : '',
        servingName: typeof p.servingName === 'string' ? p.servingName : '',
        declaredLevels: Array.isArray(p.students)
          ? p.students.filter(x => x && /^P[3-6]$/.test(x.level || '')).map(x => x.level) : [],
        famStudents: Array.isArray(p.students) ? p.students.filter(x => x && x.name).map(x => `${x.name} (${x.level || '?'})`).join(', ') : '',
        famAddress: typeof p.address === 'string' ? p.address : '',
        // Terms of access: null until they accept, and stale once
        // AGREEMENT_VERSION moves on (they'll be asked again on next visit).
        agreement: (p.agreement && typeof p.agreement === 'object') ? p.agreement : null,
        lastLogin: p.lastLogin ? (p.lastLogin.toDate ? p.lastLogin.toDate() : new Date(p.lastLogin)) : null,
        loginCount: 0,
        questionsAttempted: 0,
        totalScore: 0,
        totalBlanks: 0
      };
    });

    // Count logins per student
    allLogins.forEach(l => {
      if (!studentStats[l.uid]) {
        studentStats[l.uid] = {
          uid: l.uid,
          email: l.email || '',
          name: l.displayName || l.email || 'Unknown',
          lastLogin: null,
          loginCount: 0,
          questionsAttempted: 0,
          totalScore: 0,
          totalBlanks: 0
        };
      }
      studentStats[l.uid].loginCount++;
      const loginDate = l.timestamp ? (l.timestamp.toDate ? l.timestamp.toDate() : new Date(l.timestamp)) : null;
      if (loginDate && (!studentStats[l.uid].lastLogin || loginDate > studentStats[l.uid].lastLogin)) {
        studentStats[l.uid].lastLogin = loginDate;
      }
    });

    // Count attempts per student
    allAttempts.forEach(a => {
      if (!studentStats[a.uid]) {
        studentStats[a.uid] = {
          uid: a.uid,
          email: a.email || '',
          name: a.displayName || a.email || 'Unknown',
          lastLogin: null,
          loginCount: 0,
          questionsAttempted: 0,
          totalScore: 0,
          totalBlanks: 0
        };
      }
      studentStats[a.uid].questionsAttempted++;
      studentStats[a.uid].totalScore += (a.score || 0);
      studentStats[a.uid].totalBlanks += (a.totalBlanks || 0);
      const at = a.timestamp ? (a.timestamp.toDate ? a.timestamp.toDate() : new Date(a.timestamp)) : null;
      if (at && (!studentStats[a.uid].lastAttempt || at > studentStats[a.uid].lastAttempt)) studentStats[a.uid].lastAttempt = at;
    });

    // How each student ANSWERS, for the audit view: attempts that landed less
    // than RAPID_ATTEMPT_MS after the previous one, and attempts a game clocked
    // at under AUDIT_FAST_MS. Both are "went too fast to have read it" signals.
    const byUid = {};
    allAttempts.forEach(a => { (byUid[a.uid] = byUid[a.uid] || []).push(a); });
    Object.keys(byUid).forEach(uid => {
      const list = byUid[uid].slice().sort((x, y) => attemptTime(x) - attemptTime(y));
      let prev = null, rapid = 0, fast = 0, modes = {};
      list.forEach(a => {
        const t = attemptTime(a);
        if (prev != null && t - prev < RAPID_ATTEMPT_MS) rapid++;
        prev = t;
        const ms = Number(a.ms) || 0;
        if (ms > 0 && ms < AUDIT_FAST_MS) fast++;
        const m = a.mode || 'practice';
        modes[m] = (modes[m] || 0) + 1;
      });
      if (!studentStats[uid]) return;
      studentStats[uid].rapidAttempts = rapid;
      studentStats[uid].fastAttempts = fast;
      studentStats[uid].modes = modes;
    });

    // Cache so the per-student drill-in (showStudentDetail) can read name/email.
    _usageStudentStats = studentStats;

    const studentList = Object.values(studentStats).sort((a, b) => {
      if (b.lastLogin && a.lastLogin) return b.lastLogin - a.lastLogin;
      if (b.lastLogin) return 1;
      if (a.lastLogin) return -1;
      return 0;
    });

    // Today's logins
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const loginsToday = allLogins.filter(l => {
      const d = l.timestamp ? (l.timestamp.toDate ? l.timestamp.toDate() : new Date(l.timestamp)) : null;
      return d && d >= today;
    }).length;

    // Update summary cards
    document.getElementById('usageTotalStudents').textContent = studentList.length;
    document.getElementById('usageTotalLogins').textContent = allLogins.length;
    document.getElementById('usageTotalAttempts').textContent = allAttempts.length;
    document.getElementById('usageLoginToday').textContent = loginsToday;

    // Render student table
    const tbody = document.getElementById('usageStudentBody');
    if (studentList.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:40px;color:var(--text-muted);">No student data yet. Students will appear here after they log in.</td></tr>';
    } else {
      tbody.innerHTML = studentList.map(s => {
        const lastLoginStr = s.lastLogin ? formatDateTimeSGT(s.lastLogin) : 'Never';
        const avgScore = s.totalBlanks > 0 ? Math.round((s.totalScore / s.totalBlanks) * 100) + '%' : '--';
        const levelOpts = ['', 'P3', 'P4', 'P5', 'P6'].map(lv =>
          `<option value="${lv}"${(s.level || '') === lv ? ' selected' : ''}>${lv || '—'}</option>`).join('');
        // The cap actually in force = the lower of what you assigned and what
        // the family declared. Shown under the drop-down whenever it isn't just
        // your assignment, so "—" never again hides a real level.
        const declared = (s.declaredLevels || []).length
          ? 'P' + Math.min.apply(null, s.declaredLevels.map(l => parseInt(l.slice(1), 10)))
          : '';
        const effective = s.servingLevel || (s.level && declared
          ? ('P' + Math.min(parseInt(s.level.slice(1), 10), parseInt(declared.slice(1), 10)))
          : (s.level || declared));
        const capNote = (effective && effective !== s.level)
          ? `<div style="font-size:0.68rem;color:var(--text-muted);margin-top:3px;line-height:1.3;" title="${s.servingLevel ? 'The level this account was last served at' : 'Declared by the family when they set up their students'}">serving <b>${escapeHtml(effective)}</b>${s.servingName ? ' · ' + escapeHtml(s.servingName) : ''}</div>`
          : (!effective ? `<div style="font-size:0.68rem;color:var(--accent-orange);margin-top:3px;line-height:1.3;" title="No level assigned and none declared — this account is served every level, up to P6">no level → P6</div>` : '');
        // Terms of access — the "not enrolled" route is a $150/month billing
        // commitment, so it gets its own colour rather than a quiet tick.
        const ag = s.agreement;
        const agCur = !!(ag && ag.version === AGREEMENT_VERSION);
        const agHtml = !ag
          ? `<span class="agree-tag pending" title="Hasn't seen or accepted the terms yet — they'll be asked on their next visit">⏳ Not yet</span>`
          : ag.choice === 'paying'
            ? `<span class="agree-tag paying" title="Agreed as NOT enrolled — parent/guardian committed to ${escapeHtml(ag.fee || AGREEMENT_FEE)} on ${escapeHtml(formatDateTimeSGT(new Date(ag.at)))}">💳 Paying${agCur ? '' : ' (old)'}</span>`
            : `<span class="agree-tag ok" title="Agreed as a currently enrolled student on ${escapeHtml(formatDateTimeSGT(new Date(ag.at)))}">✅ Enrolled${agCur ? '' : ' (old)'}</span>`;
        return `<tr class="clickable" onclick="showStudentDetail('${escapeHtml(s.uid)}')" title="Click to see every question this student attempted, with times">
          <td style="font-weight:600;">${escapeHtml(s.name)}<div style="font-weight:400;margin-top:4px;">${agHtml}</div>${s.famStudents ? `<div style="font-weight:400;font-size:0.74rem;color:var(--text-muted);margin-top:2px;">👧 ${escapeHtml(s.famStudents)}</div>` : ''}${s.famAddress ? `<div style="font-weight:400;font-size:0.72rem;color:var(--text-muted);margin-top:1px;">📍 ${escapeHtml(s.famAddress)}</div>` : ''}</td>
          <td style="color:var(--text-muted);font-size:0.82rem;">${escapeHtml(s.email)}</td>
          <td style="text-align:center;" onclick="event.stopPropagation()">
            <select onchange="setStudentLevel('${escapeHtml(s.uid)}', this.value)" title="Assigned level — the student is never served questions above this" style="padding:4px 8px;border:1px solid var(--border);border-radius:8px;background:var(--surface);font-size:0.8rem;">${levelOpts}</select>${capNote}
          </td>
          <td style="font-size:0.82rem;">${lastLoginStr}</td>
          <td style="text-align:center;"><span style="background:var(--accent-blue-light);color:var(--accent-blue);padding:2px 10px;border-radius:10px;font-family:'Space Mono',monospace;font-size:0.75rem;font-weight:600;">${s.loginCount}</span></td>
          <td style="text-align:center;"><span style="background:var(--accent-orange-light);color:var(--accent-orange);padding:2px 10px;border-radius:10px;font-family:'Space Mono',monospace;font-size:0.75rem;font-weight:600;">${s.questionsAttempted}</span></td>
          <td style="text-align:center;font-family:'Space Mono',monospace;font-size:0.82rem;font-weight:600;color:${s.totalBlanks > 0 ? 'var(--primary)' : 'var(--text-muted)'};">${avgScore}</td>
          <td style="text-align:center;white-space:nowrap;" onclick="event.stopPropagation()">
            <button class="btn btn-outline" onclick="openResetStudentLogin('${escapeHtml(s.uid)}')" title="Reset this student's password — for when they've forgotten it. Their username and all progress are kept." style="padding:4px 10px;font-size:0.78rem;margin-right:6px;">🔑 Reset</button>
            <span class="usage-open-hint clickable" onclick="showStudentDetail('${escapeHtml(s.uid)}')" style="cursor:pointer;">View log&nbsp;›</span>
          </td>
        </tr>`;
      }).join('');
    }

    // Render recent logins (last 50)
    const loginBody = document.getElementById('usageLoginBody');
    const recentLogins = allLogins.slice(0, 50);
    if (recentLogins.length === 0) {
      loginBody.innerHTML = '<tr><td colspan="3" style="text-align:center;padding:40px;color:var(--text-muted);">No login activity yet.</td></tr>';
    } else {
      loginBody.innerHTML = recentLogins.map(l => {
        const ts = l.timestamp ? (l.timestamp.toDate ? l.timestamp.toDate() : new Date(l.timestamp)) : null;
        const timeStr = ts ? formatDateTimeSGT(ts) : 'Unknown';
        return `<tr>
          <td style="font-weight:600;">${escapeHtml(l.displayName || l.email || 'Unknown')}</td>
          <td style="color:var(--text-muted);font-size:0.82rem;">${escapeHtml(l.email || '')}</td>
          <td style="font-size:0.82rem;">${timeStr}</td>
        </tr>`;
      }).join('');
    }

    renderPracticeReminders();
    try { await renderActivityAudit(); } catch (e) { console.warn('activity audit', e); }

    usageDashboardLoaded = true;
    showToast('Usage data loaded', 'success');
  } catch (err) {
    console.error('loadUsageDashboard failed:', err);
    showToast('Could not load usage data — check your connection', 'error');
  }
}

// Admin: assign a student's level (P3–P6, or '' to clear). Written to the
// student's profile AND mirrored into the admin's shared studentLevels map so
// the student can read it regardless of how userProfiles is locked down.
async function setStudentLevel(uid, level) {
  if (!currentUser || currentUser.role !== 'admin' || !uid) return;
  const lvl = /^P[3-6]$/.test(level || '') ? level : '';
  try {
    await setDoc(doc(db, PROFILES_COL, uid), { level: lvl }, { merge: true });
    await setDoc(doc(db, 'users', currentUser.uid, SETTINGS_COL, 'studentLevels'),
      { levels: { [uid]: lvl } }, { merge: true });
    if (_usageStudentStats[uid]) _usageStudentStats[uid].level = lvl;
    const who = (_usageStudentStats[uid] && _usageStudentStats[uid].name) || 'Student';
    showToast(lvl ? `${who} set to ${lvl} — they'll only get ${lvl}-and-below questions` : `${who}'s level cleared (no restriction)`, 'success');
  } catch (e) {
    console.error('setStudentLevel failed', e);
    showToast('Could not save the level — check your connection', 'error');
  }
}

// =====================================================================
// 🕵️ ACTIVITY — what each student has actually been doing
//
// Everything here comes from the two shared logs (`loginEvents` and
// `questionAttempts`, joined by the Usage dashboard above) and from the small
// counts each student publishes about their own work. The flags are prompts to
// LOOK, not verdicts — every one of them has an innocent explanation, so the
// raw numbers sit next to the flag.
// =====================================================================
const AUDIT_FAST_MS = 4000;   // an answer this quick was not read
const AUDIT_FLAGS = [
  { id: 'rapid', icon: '⚡', label: 'Rapid answers',
    hint: 'A quarter or more of their attempts arrived less than 15s after the previous one.',
    test: r => r.attempts >= 20 && (r.rapid / r.attempts) >= 0.25 },
  { id: 'fast', icon: '⏱️', label: 'Answered too fast',
    hint: 'A quarter or more of their answers were clocked under ' + (AUDIT_FAST_MS / 1000) + 's — faster than the question can be read.',
    test: r => r.attempts >= 20 && (r.fast / r.attempts) >= 0.25 },
  { id: 'idle', icon: '💤', label: 'Signing in without working',
    hint: 'Ten or more sign-ins but barely any questions answered.',
    test: r => r.logins >= 10 && r.attempts < 5 }
];
let _auditSort = 'flags';
let _auditRows = [];
function setAuditSort(k) { _auditSort = k || 'flags'; renderActivityAudit(); }

// Join the dashboard's per-student activity with what the student published.
function _buildAuditRows(classRows) {
  const pub = {};
  (classRows || []).forEach(r => { if (r && r.uid) pub[r.uid] = r; });
  const uids = new Set(Object.keys(_usageStudentStats || {}));
  Object.keys(pub).forEach(u => uids.add(u));
  return Array.from(uids).map(uid => {
    const s = (_usageStudentStats && _usageStudentStats[uid]) || {};
    const b = pub[uid] || {};
    const row = {
      uid,
      name: s.name || b.name || 'Unknown',
      email: s.email || '',
      logins: s.loginCount | 0,
      attempts: s.questionsAttempted | 0,
      rapid: s.rapidAttempts | 0,
      fast: s.fastAttempts | 0,
      accuracy: s.totalBlanks > 0 ? Math.round((s.totalScore / s.totalBlanks) * 100) : null,
      lastActive: s.lastAttempt || s.lastLogin || null,
      marked: b.marked | 0,
      correct: b.correct | 0,
      ownAccuracy: b.accuracy == null ? null : (b.accuracy | 0),
      streak: b.streak | 0,
      monthQ: b.monthQ | 0,
      agreement: s.agreement || null,
      published: !!b.uid
    };
    row.flags = AUDIT_FLAGS.filter(f => { try { return f.test(row); } catch (e) { return false; } });
    return row;
  });
}
function _auditSortRows(rows) {
  const by = {
    flags: (a, b) => b.flags.length - a.flags.length || b.attempts - a.attempts,
    questions: (a, b) => b.attempts - a.attempts,
    marked: (a, b) => b.marked - a.marked,
    accuracy: (a, b) => (b.ownAccuracy == null ? -1 : b.ownAccuracy) - (a.ownAccuracy == null ? -1 : a.ownAccuracy),
    streak: (a, b) => b.streak - a.streak,
    rapid: (a, b) => (b.rapid + b.fast) - (a.rapid + a.fast),
    recent: (a, b) => (b.lastActive ? b.lastActive.getTime() : 0) - (a.lastActive ? a.lastActive.getTime() : 0),
    name: (a, b) => String(a.name).localeCompare(String(b.name))
  };
  return rows.slice().sort(by[_auditSort] || by.flags);
}
async function renderActivityAudit() {
  if (!currentUser || currentUser.role !== 'admin') return;
  const tbody = document.getElementById('usageAuditBody');
  if (!tbody) return;
  let classRows = [];
  try { classRows = await progressFetchClass(true); } catch (e) { console.warn('class progress load', e); }
  _auditRows = _buildAuditRows(classRows);
  const rows = _auditSortRows(_auditRows);
  const flagged = _auditRows.filter(r => r.flags.length).length;
  const note = document.getElementById('usageAuditNote');
  if (note) {
    note.innerHTML = `${_auditRows.length} student${_auditRows.length === 1 ? '' : 's'} · `
      + `<b style="color:${flagged ? 'var(--accent-red)' : 'var(--text-muted)'};">${flagged} flagged</b>`;
  }
  const sel = document.getElementById('usageAuditSort');
  if (sel && sel.value !== _auditSort) sel.value = _auditSort;
  if (!rows.length) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:40px;color:var(--text-muted);">No student data yet.</td></tr>';
    return;
  }
  const num = n => (n | 0).toLocaleString();
  tbody.innerHTML = rows.map(r => {
    const flags = r.flags.map(f =>
      `<span class="audit-flag" title="${escapeHtml(f.hint)}">${f.icon} ${escapeHtml(f.label)}</span>`).join('');
    // A row nobody has published is a student who has not opened the app since
    // this build shipped — say so rather than showing a misleading 0.
    const workCell = r.published
      ? `<b>${num(r.marked)}</b><div class="audit-sub">${r.ownAccuracy != null ? r.ownAccuracy + '% correct' : '—'} · ${num(r.monthQ)} this month</div>`
      : `<span class="audit-pending" title="This student has not opened the app since their progress started being published.">not yet published</span>`;
    return `<tr class="${r.flags.length ? 'audit-flagged' : ''}">
      <td style="font-weight:600;">
        <span class="clickable" onclick="showStudentDetail('${escapeHtml(r.uid)}')" style="cursor:pointer;">${escapeHtml(r.name)}</span>
        <div class="audit-sub">${escapeHtml(r.email)}</div>
      </td>
      <td style="text-align:right;">${workCell}</td>
      <td style="text-align:right;">${num(r.attempts)}<div class="audit-sub">${r.accuracy != null ? r.accuracy + '% avg' : '—'} · ${num(r.logins)} logins</div></td>
      <td style="text-align:right;">${num(r.rapid)}<div class="audit-sub">${num(r.fast)} under ${AUDIT_FAST_MS / 1000}s</div></td>
      <td style="text-align:right;">${num(r.streak)}<div class="audit-sub">day streak</div></td>
      <td style="max-width:220px;">${flags || '<span class="audit-sub">—</span>'}</td>
      <td style="text-align:center;white-space:nowrap;font-size:0.8rem;color:var(--text-muted);">
        ${r.lastActive ? escapeHtml(formatDateTimeSGT(r.lastActive)) : '—'}
      </td>
    </tr>`;
  }).join('');
}
function exportActivityAudit() {
  if (!_auditRows.length) { showToast('Nothing to export yet — load the dashboard first', 'error'); return; }
  const cols = ['Name', 'Email', 'Questions marked', 'Correct', 'Accuracy %', 'Questions this month', 'Day streak',
    'Attempts logged', 'Avg score %', 'Rapid attempts', 'Answers under ' + (AUDIT_FAST_MS / 1000) + 's', 'Logins',
    'Agreement', 'Agreed on', 'Flags', 'Last active'];
  const esc = v => {
    const s = v == null ? '' : String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const lines = [cols.join(',')].concat(_auditSortRows(_auditRows).map(r => [
    r.name, r.email, r.marked, r.correct, r.ownAccuracy == null ? '' : r.ownAccuracy, r.monthQ, r.streak,
    r.attempts, r.accuracy == null ? '' : r.accuracy, r.rapid, r.fast, r.logins,
    r.agreement ? (r.agreement.choice === 'paying' ? 'not enrolled — ' + (r.agreement.fee || AGREEMENT_FEE) : 'enrolled') : 'not yet',
    r.agreement && r.agreement.at ? formatDateTimeSGT(new Date(r.agreement.at)) : '',
    r.flags.map(f => f.label).join(' | '),
    r.lastActive ? formatDateTimeSGT(r.lastActive) : ''
  ].map(esc).join(',')));
  const blob = new Blob(['\ufeff' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'student-activity-' + _todayKey() + '.csv';
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
  showToast('⬇️ Exported ' + _auditRows.length + ' students', 'success');
}

// ---- Practice reminders (admin) ------------------------------------------
// Reuses the usage dashboard's per-student stats (lastAttempt from the
// questionAttempts log) to surface students who haven't practised in 3+ days,
// then helps the admin email them a one-click #practice link.
const REMINDER_DAYS = 3;
function _practiceLink() { return location.origin + location.pathname + '#practice'; }
function _reminderEmailTemplate() {
  const subject = '📖 Time to practise your English';
  const body = [
    'Hi!',
    '',
    "It's been a few days since your last practice. Jump back in and answer a few questions —",
    'ten minutes is enough to keep the habit going.',
    '',
    '👉 Practise now: ' + _practiceLink(),
    '',
    'See you in class!'
  ].join('\n');
  return { subject, body };
}
function _reminderList() {
  const now = Date.now();
  return Object.values(_usageStudentStats || {})
    .filter(s => s.email)
    .map(s => {
      const last = s.lastAttempt ? (s.lastAttempt.getTime ? s.lastAttempt.getTime() : new Date(s.lastAttempt).getTime()) : null;
      const days = last ? Math.floor((now - last) / 86400000) : null;
      return { uid: s.uid, name: s.name, email: s.email, last, days, q: s.questionsAttempted || 0 };
    })
    .filter(r => r.days === null || r.days >= REMINDER_DAYS)
    .sort((a, b) => (b.days === null ? Infinity : b.days) - (a.days === null ? Infinity : a.days));
}
function renderPracticeReminders() {
  const body = document.getElementById('reminderBody');
  if (!body) return;
  const list = _reminderList();
  const cnt = document.getElementById('reminderCount');
  if (cnt) cnt.textContent = list.length ? `${list.length} student${list.length === 1 ? '' : 's'} to remind` : 'Everyone is up to date 🎉';
  if (!list.length) {
    body.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:30px;color:var(--text-muted);">No students are overdue — every active student practised within the last 3 days. 🎉</td></tr>';
    return;
  }
  body.innerHTML = list.map(r => {
    const lastStr = r.last ? formatDateTimeSGT(new Date(r.last)) : 'Never';
    const daysStr = r.days === null ? 'Never' : r.days + 'd';
    return `<tr>
      <td style="text-align:center;"><input type="checkbox" class="reminder-cb" data-email="${escapeHtml(r.email)}" checked></td>
      <td style="font-weight:600;">${escapeHtml(r.name)}</td>
      <td style="color:var(--text-muted);font-size:0.82rem;">${escapeHtml(r.email)}</td>
      <td style="font-size:0.82rem;">${lastStr}</td>
      <td style="text-align:center;font-family:'Space Mono',monospace;font-size:0.82rem;font-weight:600;color:var(--accent-orange);">${daysStr}</td>
      <td style="text-align:center;font-family:'Space Mono',monospace;font-size:0.8rem;">${r.q}</td>
    </tr>`;
  }).join('');
  const sa = document.getElementById('reminderSelAll'); if (sa) sa.checked = true;
}
function toggleReminderSelAll(on) {
  document.querySelectorAll('#reminderBody .reminder-cb').forEach(cb => { cb.checked = on; });
}
function _selectedReminderEmails() {
  return Array.from(document.querySelectorAll('#reminderBody .reminder-cb'))
    .filter(cb => cb.checked).map(cb => cb.dataset.email).filter(Boolean);
}
function _fallbackCopy(text) {
  try { const ta = document.createElement('textarea'); ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); } catch (_) {}
}
function copyReminderEmails() {
  const emails = _selectedReminderEmails();
  if (!emails.length) { showToast('Select at least one student first', 'error'); return; }
  const text = emails.join(', ');
  const done = () => showToast(`Copied ${emails.length} email${emails.length === 1 ? '' : 's'} — paste into your BCC field`, 'success');
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done).catch(() => { _fallbackCopy(text); done(); });
  else { _fallbackCopy(text); done(); }
}
function composeReminderEmail() {
  const emails = _selectedReminderEmails();
  if (!emails.length) { showToast('Select at least one student first', 'error'); return; }
  const t = _reminderEmailTemplate();
  const url = 'mailto:?bcc=' + encodeURIComponent(emails.join(',')) + '&subject=' + encodeURIComponent(t.subject) + '&body=' + encodeURIComponent(t.body);
  // mailto URLs choke past ~2000 chars; for a big class, copy the BCC list instead.
  if (url.length > 1900 && emails.length > 1) {
    _fallbackCopy(emails.join(', '));
    showToast(`${emails.length} recipients is too many for one draft — emails copied; paste into BCC`, '');
    window.location.href = 'mailto:?subject=' + encodeURIComponent(t.subject) + '&body=' + encodeURIComponent(t.body);
    return;
  }
  window.location.href = url;
}

function formatDateTimeSGT(date) {
  try {
    return date.toLocaleString('en-SG', {
      timeZone: 'Asia/Singapore',
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    });
  } catch (e) {
    return date.toLocaleString();
  }
}

// Milliseconds for a question-attempt's timestamp (Firestore Timestamp or raw).
function attemptTime(a) {
  if (!a || !a.timestamp) return 0;
  return a.timestamp.toDate ? a.timestamp.toDate().getTime() : new Date(a.timestamp).getTime();
}

// Human-friendly gap between two attempts: "8s", "3m 12s", "2h 5m", "1d".
function formatGap(ms) {
  if (ms == null) return '—';
  const s = Math.round(ms / 1000);
  if (s < 60) return s + 's';
  const m = Math.floor(s / 60), rs = s % 60;
  if (m < 60) return rs ? `${m}m ${rs}s` : `${m}m`;
  const h = Math.floor(m / 60), rm = m % 60;
  if (h < 24) return rm ? `${h}h ${rm}m` : `${h}h`;
  return `${Math.floor(h / 24)}d`;
}

// Drill into one student: list every question they attempted, in order, with the
// exact time (SGT). Consecutive attempts under RAPID_ATTEMPT_MS apart are flagged
// red so a teacher can spot rapid-fire (potentially copied) answers.
async function showStudentDetail(uid) {
  const s = _usageStudentStats[uid] || { uid, name: 'Student', email: '' };
  document.getElementById('studentDetailName').textContent = s.name || 'Student';
  document.getElementById('studentDetailEmail').textContent = s.email || '';
  document.getElementById('studentDetailSummary').innerHTML = '';
  document.getElementById('studentDetailBody').innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--text-muted);">Loading…</td></tr>';
  document.getElementById('studentDetailOverlay').classList.add('active');

  try {
    // Single-field equality query — no composite index needed; we sort client-side.
    const snap = await getDocs(query(collection(db, ATTEMPTS_COL), where('uid', '==', uid)));
    const attempts = [];
    snap.forEach(d => attempts.push(d.data()));
    // Chronological order so we can measure the gap between consecutive attempts.
    attempts.sort((a, b) => attemptTime(a) - attemptTime(b));

    let prev = null, rapidCount = 0, totalScore = 0, totalBlanks = 0;
    attempts.forEach(a => {
      const t = attemptTime(a);
      a._date = t ? new Date(t) : null;
      a._gapMs = prev != null ? (t - prev) : null;
      if (a._gapMs != null && a._gapMs < RAPID_ATTEMPT_MS) rapidCount++;
      totalScore += (a.score || 0);
      totalBlanks += (a.totalBlanks || 0);
      prev = t;
    });

    const last = attempts.length ? attempts[attempts.length - 1]._date : null;
    const avgPct = totalBlanks > 0 ? Math.round((totalScore / totalBlanks) * 100) + '%' : '--';

    // The points side of the record, from the audit block on this student's
    // published leaderboard row — so the log and the wallet read together.
    const ar = (_auditRows || []).find(x => x.uid === uid);
    const cards = [
      { label: 'Questions Attempted', value: attempts.length, color: 'var(--accent-orange)' },
      { label: 'Average Score', value: avgPct, color: 'var(--primary)' },
      { label: 'Rapid (&lt;15s apart)', value: rapidCount, color: rapidCount ? 'var(--accent-red)' : 'var(--text-muted)' },
      { label: 'Last Active', value: last ? formatDateTimeSGT(last) : '--', color: 'var(--accent-blue)', small: true }
    ];
    if (ar && ar.hasAudit) {
      const perQ = ar.marked > 0 ? Math.round(ar.earned / ar.marked) : null;
      cards.push(
        { label: '🪙 Points now', value: (ar.points | 0).toLocaleString(), color: 'var(--accent-orange)' },
        { label: 'Points earned all-time', value: (ar.earned | 0).toLocaleString() + (perQ != null ? ` (${perQ}/Q)` : ''), color: 'var(--primary)', small: true },
        { label: '👻 Duels won', value: (ar.duelWins | 0).toLocaleString(), color: ar.duelWins >= 20 ? 'var(--accent-red)' : 'var(--text-muted)' },
        { label: '🔥 Embers power', value: (ar.power | 0).toLocaleString(), color: 'var(--accent-blue)' }
      );
    }
    document.getElementById('studentDetailSummary').innerHTML = cards.map(c =>
      `<div class="usage-card"><div class="usage-card-value" style="color:${c.color};${c.small ? 'font-size:0.8rem;line-height:1.35;' : ''}">${c.value}</div><div class="usage-card-label">${c.label}</div></div>`
    ).join('');

    const tbody = document.getElementById('studentDetailBody');
    if (!attempts.length) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--text-muted);">No question attempts recorded for this student yet.</td></tr>';
      return;
    }
    // Display newest first, but the gap was already computed in chronological order.
    tbody.innerHTML = attempts.slice().reverse().map((a, i) => {
      const n = attempts.length - i; // attempt number in chronological order
      const timeStr = a._date ? formatDateTimeSGT(a._date) : 'Unknown';
      const pct = a.totalBlanks > 0 ? Math.round((a.score / a.totalBlanks) * 100) : null;
      const scoreStr = a.totalBlanks > 0 ? `${a.score}/${a.totalBlanks} (${pct}%)` : (a.score != null ? String(a.score) : '--');
      const rapid = a._gapMs != null && a._gapMs < RAPID_ATTEMPT_MS;
      const gapStr = a._gapMs == null ? '—' : formatGap(a._gapMs);
      return `<tr${rapid ? ' class="attempt-rapid"' : ''}>
        <td style="color:var(--text-muted);font-family:'Space Mono',monospace;font-size:0.78rem;">${n}</td>
        <td style="font-size:0.82rem;white-space:nowrap;">${timeStr}</td>
        <td style="font-weight:600;font-size:0.85rem;">${escapeHtml(a.questionTitle || a.questionId || 'Untitled question')}</td>
        <td style="text-align:center;font-family:'Space Mono',monospace;font-size:0.8rem;font-weight:600;color:${pct != null ? (pct >= 50 ? 'var(--primary)' : 'var(--accent-orange)') : 'var(--text-muted)'};">${scoreStr}</td>
        <td style="font-size:0.78rem;color:var(--text-muted);">${escapeHtml(a.mode || '—')}</td>
        <td style="font-size:0.78rem;${rapid ? 'color:var(--accent-red);font-weight:700;' : 'color:var(--text-muted);'}">${rapid ? '⚡ ' : ''}${gapStr}</td>
      </tr>`;
    }).join('');
  } catch (err) {
    console.error('showStudentDetail failed:', err);
    document.getElementById('studentDetailBody').innerHTML = '<tr><td colspan="6" style="text-align:center;padding:40px;color:var(--accent-red);">Could not load this student\'s attempts — check your connection.</td></tr>';
  }
}

function closeStudentDetail() {
  document.getElementById('studentDetailOverlay').classList.remove('active');
}

// =====================================================================
// SCHEDULED QUESTIONS
// =====================================================================
let scheduledQuestions = []; // [{ id (firestore doc id), questionId, questionTitle, category, topic, releaseDate, released, questionData }]
let editingScheduleId = null;
let selectedScheduleQuestionId = null;

async function loadScheduledQuestions() {
  if (!currentUser || currentUser.role !== 'admin') return;
  try {
    const schedCol = collection(db, 'users', currentUser.uid, SCHEDULED_COL);
    const snap = await getDocs(schedCol);
    scheduledQuestions = [];
    snap.forEach(d => {
      const data = d.data();
      scheduledQuestions.push({ ...data, _docId: d.id });
    });
    scheduledQuestions.sort((a, b) => {
      const da = a.releaseDate || '';
      const db2 = b.releaseDate || '';
      return da.localeCompare(db2);
    });
    renderScheduledQuestions();
    // Check and release any due questions
    await checkAndReleaseScheduledQuestions();
  } catch (err) {
    console.error('loadScheduledQuestions failed:', err);
  }
}

async function checkAndReleaseScheduledQuestions() {
  // Get current date in Singapore time
  const now = new Date();
  const sgtStr = now.toLocaleDateString('en-CA', { timeZone: 'Asia/Singapore' }); // YYYY-MM-DD format

  // A question the scheduler releases on its own is not a question the author
  // wrote just now — keep it out of any running work session.
  _wkSuppress++;
  try {
  for (const sq of scheduledQuestions) {
    if (!sq.released && sq.releaseDate && sq.releaseDate <= sgtStr) {
      // Release this question - add to question bank
      if (sq.questionData) {
        const q = JSON.parse(JSON.stringify(sq.questionData));
        // Check if already in bank
        if (!questionBank.find(existing => existing.id === q.id)) {
          questionBank.push(normalizeLoadedQuestion(q));
          await saveQuestion(q);
        }
      }
      // Mark as released
      sq.released = true;
      try {
        const schedRef = doc(db, 'users', currentUser.uid, SCHEDULED_COL, sq._docId);
        await updateDoc(schedRef, { released: true });
      } catch (err) {
        console.warn('Could not mark scheduled question as released:', err);
      }
    }
  }
  } finally { _wkSuppress--; }
  updateCounts();
  renderScheduledQuestions();
}

function renderScheduledQuestions() {
  const container = document.getElementById('scheduledQuestionsContainer');
  if (!container) return;

  if (scheduledQuestions.length === 0) {
    container.innerHTML = `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:48px;height:48px;opacity:0.4;margin-bottom:12px;"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
        <h3>No Scheduled Questions</h3>
        <p>Click "Schedule New Question" to add a question that will be released at a future date.</p>
      </div>`;
    return;
  }

  const now = new Date();
  const todayStr = now.toLocaleDateString('en-CA', { timeZone: 'Asia/Singapore' });

  container.innerHTML = scheduledQuestions.map(sq => {
    const isReleased = sq.released;
    const isToday = sq.releaseDate === todayStr;
    const isFuture = sq.releaseDate > todayStr;
    let statusClass = 'released';
    let statusLabel = 'Released';
    if (isFuture && !isReleased) { statusClass = 'future'; statusLabel = 'Scheduled'; }
    else if (isToday && !isReleased) { statusClass = 'today'; statusLabel = 'Today'; }

    const dateObj = new Date(sq.releaseDate + 'T00:00:00+08:00');
    const dateStr = dateObj.toLocaleDateString('en-SG', { timeZone: 'Asia/Singapore', year: 'numeric', month: 'short', day: 'numeric' });

    return `<div class="scheduled-card">
      <div class="sc-info">
        <div class="sc-title">${escapeHtml(sq.questionTitle || sq.questionData?.title || 'Untitled')}</div>
        <div class="sc-meta">
          <span class="sc-date ${statusClass}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
            ${dateStr}
          </span>
          <span class="qb-tag category">${escapeHtml(sq.category || sq.questionData?.category || '')}</span>
          <span class="qb-tag topic">${escapeHtml(sq.topic || sq.questionData?.topic || '')}</span>
          <span class="sc-date ${statusClass}" style="font-size:0.7rem;">${statusLabel}</span>
        </div>
      </div>
      <div class="sc-actions">
        ${!isReleased ? `<button class="btn btn-outline" onclick="editScheduledQuestion('${sq._docId}')">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
          Edit
        </button>` : ''}
        <button class="btn btn-outline" onclick="deleteScheduledQuestion('${sq._docId}')" style="color:var(--accent-red);border-color:var(--accent-red-light);">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
          Delete
        </button>
      </div>
    </div>`;
  }).join('');
}

function openScheduleQuestionDialog() {
  selectedScheduleQuestionId = null;
  document.getElementById('scheduleDialogTitle').textContent = 'Schedule New Question';
  document.getElementById('scheduleDate').value = '';
  document.getElementById('scheduleSearchInput').value = '';
  document.getElementById('scheduleSelectedInfo').style.display = 'none';

  // Set minimum date to tomorrow SGT
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const minDate = tomorrow.toLocaleDateString('en-CA', { timeZone: 'Asia/Singapore' });
  document.getElementById('scheduleDate').min = minDate;

  renderScheduleQuestionList();
  document.getElementById('scheduleQuestionOverlay').classList.add('active');
}

function closeScheduleDialog() {
  document.getElementById('scheduleQuestionOverlay').classList.remove('active');
}

function filterScheduleQuestions() {
  renderScheduleQuestionList();
}

function renderScheduleQuestionList() {
  const list = document.getElementById('scheduleQuestionList');
  const searchTerm = (document.getElementById('scheduleSearchInput')?.value || '').toLowerCase().trim();

  let filtered = questionBank.filter(q => {
    if (!qInSyllabus(q)) return false;             // retired topics are never released to students
    if (searchTerm) {
      const haystack = (q.title + ' ' + q.topic + ' ' + qSecondaryTopic(q) + ' ' + q.category + ' ' + qSecondaryCategory(q)).toLowerCase();
      return haystack.includes(searchTerm);
    }
    return true;
  });

  if (filtered.length === 0) {
    list.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-muted);font-size:0.85rem;">No questions found in the bank.</div>';
    return;
  }

  list.innerHTML = filtered.map(q => {
    const isSelected = selectedScheduleQuestionId === q.id;
    return `<div class="schedule-q-item${isSelected ? ' selected' : ''}" onclick="selectScheduleQuestion('${q.id}')">
      <div style="flex:1;">
        <div class="q-title">${escapeHtml(q.title)}</div>
        <div class="q-meta">
          <span class="qb-tag category" style="font-size:0.7rem;">${escapeHtml(normalizeCategoryValue(q.category))}</span>
          <span class="qb-tag topic" style="font-size:0.7rem;">${escapeHtml(q.topic)}</span>
        </div>
      </div>
      ${isSelected ? '<svg viewBox="0 0 24 24" fill="none" stroke="var(--primary)" stroke-width="2.5" style="width:18px;height:18px;flex-shrink:0;"><polyline points="20 6 9 17 4 12"/></svg>' : ''}
    </div>`;
  }).join('');
}

function selectScheduleQuestion(qId) {
  selectedScheduleQuestionId = qId;
  const q = questionBank.find(q => q.id === qId);
  if (q) {
    document.getElementById('scheduleSelectedInfo').style.display = '';
    document.getElementById('scheduleSelectedCard').innerHTML = `
      <strong>${escapeHtml(q.title)}</strong>
      <div style="margin-top:4px;">
        <span class="qb-tag category" style="font-size:0.72rem;">${escapeHtml(normalizeCategoryValue(q.category))}</span>
        <span class="qb-tag topic" style="font-size:0.72rem;">${escapeHtml(q.topic)}</span>
      </div>`;
  }
  renderScheduleQuestionList();
}

async function submitScheduledQuestion() {
  const releaseDate = document.getElementById('scheduleDate').value;
  if (!releaseDate) {
    showToast('Please select a release date', 'error');
    return;
  }
  if (!selectedScheduleQuestionId) {
    showToast('Please select a question', 'error');
    return;
  }

  const q = questionBank.find(q => q.id === selectedScheduleQuestionId);
  if (!q) {
    showToast('Question not found', 'error');
    return;
  }

  try {
    const schedData = {
      questionId: q.id,
      questionTitle: q.title,
      category: normalizeCategoryValue(q.category),
      topic: q.topic,
      releaseDate: releaseDate, // YYYY-MM-DD format
      released: false,
      createdAt: Timestamp.now(),
      questionData: JSON.parse(JSON.stringify(q))
    };

    // Convert table data for Firestore safety
    if (schedData.questionData.blocks) {
      schedData.questionData.blocks.forEach(b => {
        if (b.type === 'table' && Array.isArray(b.data)) {
          b.data = tableDataToFirestore(b.data);
        }
        if (b.type === 'table' && Array.isArray(b.colWidths)) {
          const cw = {};
          b.colWidths.forEach((w, i) => { if (w !== null && w !== undefined) cw[String(i)] = w; });
          b.colWidths = cw;
        }
      });
    }

    const schedCol = collection(db, 'users', currentUser.uid, SCHEDULED_COL);
    const docRef = await addDoc(schedCol, schedData);
    scheduledQuestions.push({ ...schedData, _docId: docRef.id });
    scheduledQuestions.sort((a, b) => (a.releaseDate || '').localeCompare(b.releaseDate || ''));

    closeScheduleDialog();
    renderScheduledQuestions();
    showToast('Question scheduled for ' + releaseDate, 'success');
  } catch (err) {
    console.error('submitScheduledQuestion failed:', err);
    showToast('Could not schedule question — check your connection', 'error');
  }
}

function editScheduledQuestion(docId) {
  const sq = scheduledQuestions.find(s => s._docId === docId);
  if (!sq) return;
  editingScheduleId = docId;

  document.getElementById('editScheduleDate').value = sq.releaseDate || '';
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  document.getElementById('editScheduleDate').min = tomorrow.toLocaleDateString('en-CA', { timeZone: 'Asia/Singapore' });

  document.getElementById('editScheduleQuestionInfo').innerHTML = `
    <div class="schedule-selected-card">
      <strong>${escapeHtml(sq.questionTitle || 'Untitled')}</strong>
      <div style="margin-top:4px;">
        <span class="qb-tag category" style="font-size:0.72rem;">${escapeHtml(sq.category || '')}</span>
        <span class="qb-tag topic" style="font-size:0.72rem;">${escapeHtml(sq.topic || '')}</span>
      </div>
      <div style="margin-top:6px;font-size:0.8rem;color:var(--text-muted);">Current release: ${sq.releaseDate}</div>
    </div>`;

  document.getElementById('editScheduleOverlay').classList.add('active');
}

function closeEditScheduleDialog() {
  document.getElementById('editScheduleOverlay').classList.remove('active');
  editingScheduleId = null;
}

async function saveEditedSchedule() {
  if (!editingScheduleId) return;
  const newDate = document.getElementById('editScheduleDate').value;
  if (!newDate) {
    showToast('Please select a new release date', 'error');
    return;
  }

  try {
    const schedRef = doc(db, 'users', currentUser.uid, SCHEDULED_COL, editingScheduleId);
    await updateDoc(schedRef, { releaseDate: newDate });

    const sq = scheduledQuestions.find(s => s._docId === editingScheduleId);
    if (sq) sq.releaseDate = newDate;
    scheduledQuestions.sort((a, b) => (a.releaseDate || '').localeCompare(b.releaseDate || ''));

    closeEditScheduleDialog();
    renderScheduledQuestions();
    showToast('Release date updated to ' + newDate, 'success');
  } catch (err) {
    console.error('saveEditedSchedule failed:', err);
    showToast('Could not update schedule — check your connection', 'error');
  }
}

function deleteScheduledQuestion(docId) {
  showConfirm('Delete Scheduled Question', 'Are you sure you want to remove this scheduled question?', async () => {
    try {
      const schedRef = doc(db, 'users', currentUser.uid, SCHEDULED_COL, docId);
      await deleteDoc(schedRef);
      scheduledQuestions = scheduledQuestions.filter(s => s._docId !== docId);
      renderScheduledQuestions();
      showToast('Scheduled question removed', 'success');
    } catch (err) {
      console.error('deleteScheduledQuestion failed:', err);
      showToast('Could not delete — check your connection', 'error');
    }
  });
}

// =====================================================================
// MOVE EDITED QUESTION TO VETTING (Admin)
// =====================================================================
function moveEditToVetting() {
  if (blocks.length === 0) {
    showToast('Add some blocks before saving', 'error');
    return;
  }
  if (!currentEditingQuestion) {
    showToast('No question being edited', 'error');
    return;
  }
  const q = collectQuestionData();
  q.id = currentEditingQuestion;
  carryOverQuestionMeta(q);

  // Remove from question bank if it was there
  const qIdx = questionBank.findIndex(qb => qb.id === currentEditingQuestion);
  if (qIdx !== -1) {
    questionBank.splice(qIdx, 1);
    deleteQuestionDoc(currentEditingQuestion);
  }

  // Remove from vetting if already there (will re-add)
  const vIdx = vettingList.findIndex(v => v.id === currentEditingQuestion);
  if (vIdx !== -1) {
    vettingList.splice(vIdx, 1);
  }

  // Add to vetting
  q.status = 'pending';
  vettingList.push(q);
  saveVettingQuestion(q);

  currentEditingQuestion = null;
  setEditMode(false);
  updateCounts();
  renderQuestionBank();
  showToast('Question moved to vetting list', 'success');
  // Land on the Vetting List; if the edit began there, restore the old view.
  _editReturnPage = 'vetting';
  _afterEditNavigate();
}

// =====================================================================
// FLAG QUESTION (Student)
// =====================================================================
let flaggingQuestionId = null;
let flaggingQuestionTitle = '';

function openFlagDialog(questionId, questionTitle) {
  flaggingQuestionId = questionId;
  flaggingQuestionTitle = questionTitle;
  document.getElementById('flagCommentInput').value = '';
  document.getElementById('flagQuestionOverlay').classList.add('active');
}

function closeFlagDialog() {
  document.getElementById('flagQuestionOverlay').classList.remove('active');
  flaggingQuestionId = null;
  flaggingQuestionTitle = '';
}

async function submitFlag() {
  const comment = document.getElementById('flagCommentInput').value.trim();
  if (!comment) {
    showToast('Please describe the issue', 'error');
    return;
  }
  if (!flaggingQuestionId || !currentUser) {
    showToast('Unable to submit flag', 'error');
    return;
  }
  if (await _flagsTodayCount() >= FLAG_DAILY_LIMIT) {
    showToast(`Daily flag limit reached (${FLAG_DAILY_LIMIT}/day) — try again tomorrow`, 'error');
    return;
  }

  try {
    await addDoc(collection(db, FLAGS_COL), {
      questionId: flaggingQuestionId,
      questionTitle: flaggingQuestionTitle,
      comment: comment,
      flaggedBy: currentUser.name,
      flaggedByEmail: currentUser.email,
      flaggedByUid: currentUser.uid,
      timestamp: Timestamp.now(),
      status: 'open' // open | resolved | dismissed
    });
    closeFlagDialog();
    showToast('Question flagged — your teacher will review it', 'success');
  } catch (err) {
    console.error('submitFlag failed:', err);
    showToast('Could not submit flag — check your connection', 'error');
  }
}

// =====================================================================
// FLAGGED QUESTIONS MANAGEMENT (Admin)
// =====================================================================
let flaggedQuestions = [];

async function loadFlaggedQuestions() {
  if (!currentUser || currentUser.role !== 'admin') return;
  try {
    const snap = await getDocs(collection(db, FLAGS_COL));
    flaggedQuestions = [];
    snap.forEach(d => {
      flaggedQuestions.push({ ...d.data(), _docId: d.id });
    });
    // Sort: open first, then by timestamp descending
    flaggedQuestions.sort((a, b) => {
      const statusOrder = { open: 0, resolved: 1, dismissed: 2 };
      const sa = statusOrder[a.status] ?? 0;
      const sb = statusOrder[b.status] ?? 0;
      if (sa !== sb) return sa - sb;
      const ta = a.timestamp ? (a.timestamp.toDate ? a.timestamp.toDate() : new Date(a.timestamp)) : new Date(0);
      const tb = b.timestamp ? (b.timestamp.toDate ? b.timestamp.toDate() : new Date(b.timestamp)) : new Date(0);
      return tb - ta;
    });
    // Flagged questions are NOT auto-moved out of the bank any more — they stay
    // live and simply appear here on the Flagged page, where the admin decides
    // what to do (Edit / Move to Vetting / Resolve / Dismiss).
    updateFlaggedCount();
    renderFlaggedQuestions();
  } catch (err) {
    console.error('loadFlaggedQuestions failed:', err);
    showToast('Could not load flagged questions', 'error');
  }
}

function updateFlaggedCount() {
  const openCount = flaggedQuestions.filter(f => f.status === 'open').length;
  const el = document.getElementById('flaggedCount');
  if (el) el.textContent = openCount;
}

// Flag note builder — kept for the manual "Move to Vetting" flow and for any
// legacy questions already carrying a 'flagged' status in the vetting list.
// (Student flags no longer auto-move questions out of the bank; the admin
// decides what to do from the Flagged Questions page.)
function _flagInfo(f) {
  let when = '';
  try { const d = f.timestamp ? (f.timestamp.toDate ? f.timestamp.toDate() : new Date(f.timestamp)) : null; if (d) when = d.toLocaleDateString(); } catch (e) {}
  return { comment: f.comment || '', by: f.flaggedBy || 'a student', when };
}

function renderFlaggedQuestions() {
  const container = document.getElementById('flaggedQuestionsContainer');
  if (!container) return;

  if (flaggedQuestions.length === 0) {
    container.innerHTML = `
      <div class="empty-state">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:48px;height:48px;opacity:0.4;margin-bottom:12px;"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg>
        <h3>No Flagged Questions</h3>
        <p>Questions flagged by students will appear here for review.</p>
      </div>`;
    return;
  }

  container.innerHTML = flaggedQuestions.map(f => {
    const ts = f.timestamp ? (f.timestamp.toDate ? f.timestamp.toDate() : new Date(f.timestamp)) : null;
    const timeStr = ts ? formatDateTimeSGT(ts) : 'Unknown';
    const statusClass = f.status || 'open';
    const statusLabel = statusClass.charAt(0).toUpperCase() + statusClass.slice(1);

    return `<div class="flagged-card">
      <div class="fc-header">
        <div>
          <div class="fc-question-title">${escapeHtml(f.questionTitle || 'Untitled Question')}</div>
          <div class="fc-meta">
            <span class="fc-status ${statusClass}">${statusLabel}</span>
            <span style="font-size:0.78rem;color:var(--text-muted);">Flagged by <strong>${escapeHtml(f.flaggedBy || 'Unknown')}</strong> (${escapeHtml(f.flaggedByEmail || '')})</span>
            <span style="font-size:0.75rem;color:var(--text-light);">${timeStr}</span>
          </div>
        </div>
      </div>
      <div class="fc-comment">
        <div class="fc-comment-header">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          Student Comment
        </div>
        ${escapeHtml(f.comment || 'No comment provided')}
      </div>
      <div class="fc-actions">
        ${f.status === 'open' ? `
          <button class="btn btn-primary" onclick="flagEditQuestion('${f._docId}','${f.questionId}')" style="font-size:0.78rem;">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            Edit Question
          </button>
          <button class="btn btn-outline" onclick="flagMoveToVetting('${f._docId}','${f.questionId}')" style="font-size:0.78rem;">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
            Move to Vetting
          </button>
          <button class="btn btn-outline" onclick="resolveFlaggedQuestion('${f._docId}')" style="color:var(--primary);font-size:0.78rem;">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><polyline points="20 6 9 17 4 12"/></svg>
            Resolve
          </button>
          <button class="btn btn-outline" onclick="dismissFlaggedQuestion('${f._docId}')" style="color:var(--text-muted);font-size:0.78rem;">
            Dismiss
          </button>
        ` : `
          <button class="btn btn-outline" onclick="deleteFlaggedQuestion('${f._docId}')" style="color:var(--accent-red);font-size:0.78rem;">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            Delete
          </button>
        `}
      </div>
      <div class="fc-reply" style="margin-top:10px;border-top:1px solid #f1f5f9;padding-top:10px;">
        ${f.reply ? `<div style="font-size:0.78rem;color:#16a34a;background:#f0fdf4;border-radius:6px;padding:6px 9px;">↩ You replied: “${escapeHtml(f.reply)}”</div>` : ''}
        <div style="display:flex;gap:6px;margin-top:8px;">
          <input id="flagReply_${f._docId}" placeholder="Reply to ${escapeHtml(f.flaggedBy || 'student')} — e.g. why this isn't an error…" style="flex:1;font-size:0.8rem;padding:7px 10px;border:1px solid #cbd5e1;border-radius:8px;outline:none;">
          <button class="btn btn-primary" onclick="replyToFlag('${f._docId}')" style="font-size:0.78rem;white-space:nowrap;">↩ Reply</button>
        </div>
      </div>
    </div>`;
  }).join('');
}

function flagEditQuestion(flagDocId, questionId) {
  // Open the question in the editor
  const q = questionBank.find(qb => qb.id === questionId) || vettingList.find(v => v.id === questionId);
  if (q) {
    editQuestion(questionId);
  } else {
    showToast('Question not found in bank or vetting list', 'error');
  }
}

async function flagMoveToVetting(flagDocId, questionId) {
  // Move the question from bank to vetting — an explicit admin choice, carrying
  // the student's flag note so it shows on the vetting card.
  const qIdx = questionBank.findIndex(qb => qb.id === questionId);
  if (qIdx !== -1) {
    const q = questionBank[qIdx];
    const f = flaggedQuestions.find(x => x._docId === flagDocId);
    q.status = 'flagged';
    if (f) q._flag = _flagInfo(f);
    q.vettedAt = new Date().toISOString();   // it re-enters vetting now, regardless of when it was first created
    questionBank.splice(qIdx, 1);
    vettingList.unshift(q);
    deleteQuestionDoc(questionId);
    saveVettingQuestion(q);
    updateCounts();
    if (document.querySelector('#page-vetting.active')) renderVettingList();
    showToast('Question moved to vetting list', 'success');
  } else {
    showToast('Question is already in vetting or not found', 'info');
  }
  // Mark flag as resolved
  await updateFlagStatus(flagDocId, 'resolved');
}

async function resolveFlaggedQuestion(docId) {
  await updateFlagStatus(docId, 'resolved');
  showToast('Flag marked as resolved', 'success');
}

async function dismissFlaggedQuestion(docId) {
  await updateFlagStatus(docId, 'dismissed');
  showToast('Flag dismissed', 'info');
}

// Resolve every open flag tied to a question (used when a flagged question has
// been reviewed and re-approved back into the bank).
function _resolveFlagsForQuestion(questionId) {
  flaggedQuestions.filter(f => f && f.questionId === questionId && f.status === 'open' && f._docId)
    .forEach(f => { updateFlagStatus(f._docId, 'resolved'); });
}

async function updateFlagStatus(docId, status) {
  try {
    const ref = doc(db, FLAGS_COL, docId);
    await updateDoc(ref, { status });
    const f = flaggedQuestions.find(f => f._docId === docId);
    if (f) f.status = status;
    updateFlaggedCount();
    renderFlaggedQuestions();
  } catch (err) {
    console.error('updateFlagStatus failed:', err);
    showToast('Could not update flag status', 'error');
  }
}

async function deleteFlaggedQuestion(docId) {
  showConfirm('Delete Flag', 'Remove this flagged question report?', async () => {
    try {
      await deleteDoc(doc(db, FLAGS_COL, docId));
      flaggedQuestions = flaggedQuestions.filter(f => f._docId !== docId);
      updateFlaggedCount();
      renderFlaggedQuestions();
      showToast('Flag removed', 'info');
    } catch (err) {
      console.error('deleteFlaggedQuestion failed:', err);
      showToast('Could not delete flag', 'error');
    }
  });
}


// =====================================================================
// QUESTION DOCTOR (admin) — scan the bank for likely problems (duplicates,
// answer/MCQ mistakes, unclear wording…), render them as clickable cards, and
// fix them (open in the editor / delete) right from the page. Local structural
// checks run instantly; an editable prompt drives an AI pass for deeper issues.
// =====================================================================
const DOCTOR_PRESETS = {
  everything: "Find any problems with these questions: duplicate or near-duplicate questions; a model answer or marked MCQ option that is wrong or doesn't match the question; MCQs with no correct option, repeated options or no real answer; unclear, ambiguous or grammatically broken wording; scientific mistakes; a question that refers to a picture or diagram but has none; blank or incomplete answers.",
  duplicates: "Find duplicate or near-duplicate questions — ones that ask essentially the same thing, test the same fact, or are lightly reworded copies of each other.",
  answers: "Check each question's answer: flag any where the model answer, the marked MCQ option, or the explanation is wrong, doesn't match the question, or is incomplete for the marks awarded.",
  mcq: "Check multiple-choice questions: flag ones with no correct option marked, repeated or identical options, fewer than two real options, or where the marked option looks wrong.",
  wording: "Find questions with unclear, ambiguous, confusing or grammatically broken wording, or spelling / scientific-term errors that would confuse a student."
};
const DOCTOR_DEFAULT = DOCTOR_PRESETS.everything;
let _doctorIssues = [];
let _doctorScan = { running: false, done: 0, total: 0, stop: false };
const _doctorDismissed = new Set();
const _doctorExpanded = new Set();

function renderDoctorPage() {
  const box = document.getElementById('doctorQuery');
  if (box && !box.value.trim()) box.value = DOCTOR_DEFAULT;
  _doctorRenderResults();
}
function doctorSetPreset(key) {
  const box = document.getElementById('doctorQuery');
  if (box && DOCTOR_PRESETS[key]) { box.value = DOCTOR_PRESETS[key]; box.focus(); }
}

// ---- helpers: pull a question apart, normalise text, build a signature ----
function _docQParts(q) {
  const p = { title: (q.title || '').trim(), text: '', mcq: null, answers: [], filledImages: 0, emptyImages: 0, inlineImages: 0 };
  const scanInline = html => { const m = String(html || '').match(/<img[\s>]/gi); if (m) p.inlineImages += m.length; };
  (q.blocks || []).forEach(b => {
    if (b.type === 'text') { p.text += ' ' + stripHtml(b.content || ''); scanInline(b.content); }
    else if (b.type === 'image') { if (b.url) p.filledImages++; else p.emptyImages++; }
    else if (b.type === 'mcq') p.mcq = b;
    else if (b.type === 'answer') { p.answers.push({ kind: 'cer', claim: stripHtml(b.claim || ''), evidence: stripHtml(b.evidence || ''), reasoning: stripHtml(b.reasoning || '') }); scanInline(b.claim); scanInline(b.evidence); scanInline(b.reasoning); }
    else if (b.type === 'plainanswer') { p.answers.push({ kind: 'plain', text: stripHtml(b.content || '') }); scanInline(b.content); }
    else if (b.type === 'fillblank') { const fp = _fbParse(b.text || ''); p.text += ' ' + fp.map(x => x.type === 'blank' ? x.answer : x.text).join(''); const ans = fp.filter(x => x.type === 'blank').map(x => x.answer).join('; '); if (ans) p.answers.push({ kind: 'plain', text: ans }); }
    else if (b.type === 'explanation') scanInline(b.content);
  });
  p.text = p.text.replace(/\s+/g, ' ').trim();
  // A real picture is present if any image block has a URL OR any block's HTML
  // has an inline <img> (pasted diagrams live inside text/answer content).
  p.hasImage = p.filledImages > 0 || p.inlineImages > 0;
  return p;
}
// Clip long text for the AI, marking the cut so the model doesn't mistake an
// abbreviated question for a truncated/broken one.
function _docClip(s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n) + '…' : s; }
function _docNorm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim(); }
function _docSignature(q) {
  const p = _docQParts(q);
  let sig = _docNorm(p.title) + ' | ' + _docNorm(p.text);
  if (p.mcq) sig += ' | ' + (p.mcq.options || []).map(o => _docNorm(o.text)).filter(Boolean).sort().join(' ');
  return sig;
}
function _docQById(id) { return questionBank.find(q => q.id === id); }
function _sevRank(s) { return s === 'high' ? 0 : s === 'med' ? 1 : 2; }
function _iss(tag, q, type, severity, title, detail) {
  return { key: tag + ':' + q.id, type, severity, ids: [q.id], title, summary: '“' + (q.title || 'Untitled') + '”', detail };
}

// ---- instant, deterministic structural checks — emitted progressively so a
// big bank never freezes the page (we yield to the browser between chunks) ----
async function _doctorRunLocalChecks() {
  const bank = questionBank.slice();
  // 1) duplicates by content signature (one fast pass, then emit each group)
  const bySig = {};
  bank.forEach(q => { const s = _docSignature(q); if (s.replace(/[|\s]/g, '').length < 5) return; (bySig[s] = bySig[s] || []).push(q); });
  Object.values(bySig).forEach(group => {
    if (group.length > 1) {
      _doctorEmitIssue({
        key: 'dup:' + group.map(q => q.id).sort().join(','), type: 'Duplicate', severity: 'high', ids: group.map(q => q.id),
        title: group.length + ' identical / near-identical questions', summary: '“' + (group[0].title || 'Untitled') + '” appears ' + group.length + ' times',
        detail: 'These questions are essentially the same. Keep the best one and delete the extras.'
      });
    }
  });
  // 2) per-question structural checks, chunked with a yield so cards stream in
  const CHUNK = 60;
  for (let i = 0; i < bank.length; i++) {
    if (_doctorScan.stop) return;
    const q = bank[i];
    const p = _docQParts(q);
    if (p.mcq) {
      const opts = (p.mcq.options || []).filter(o => stripHtml(o.text || '').trim());
      const correct = (p.mcq.options || []).find(o => o.id === p.mcq.correctId);
      if (!correct) _doctorEmitIssue(_iss('mcqnc', q, 'MCQ', 'high', 'No correct option marked', 'This multiple-choice question has no correct option selected, so it can never be marked right.'));
      else if (opts.length < 2) _doctorEmitIssue(_iss('mcqfew', q, 'MCQ', 'med', 'Too few options', 'This multiple-choice question has fewer than two real options.'));
      else {
        const norm = opts.map(o => _docNorm(o.text));
        if (new Set(norm).size < norm.length) _doctorEmitIssue(_iss('mcqdupo', q, 'MCQ', 'med', 'Repeated options', 'Two or more of the options are identical.'));
      }
    }
    if (p.emptyImages > 0 && !p.hasImage) _doctorEmitIssue(_iss('img', q, 'Image', 'med', 'Missing diagram', 'An image block has no picture and the question has no other image, so students will see a blank diagram.'));
    p.answers.forEach(a => {
      if (a.kind === 'cer' && !(a.claim || a.evidence || a.reasoning)) _doctorEmitIssue(_iss('cerempty', q, 'Answer', 'med', 'Blank model answer', 'The CER answer (claim / evidence / reasoning) is empty, so there is nothing for the AI to mark against.'));
      if (a.kind === 'plain' && !a.text) _doctorEmitIssue(_iss('plainempty', q, 'Answer', 'med', 'Blank model answer', 'The answer field is empty, so there is nothing for the AI to mark against.'));
    });
    if (!questionHasMarkableAnswer(q) && !q.annotation) _doctorEmitIssue(_iss('noans', q, 'Answer', 'low', 'No answer to mark', 'This question has no answer section (CER, answer, open-ended or MCQ) and is not an annotation question, so practice cannot score it.'));
    if (!(q.topic || '').trim()) _doctorEmitIssue(_iss('notopic', q, 'Meta', 'low', 'No topic set', 'This question has no topic, so it will not appear under any topic in practice.'));
    if (!normalizeCategoryValue(q.category || '').trim()) _doctorEmitIssue(_iss('nocat', q, 'Meta', 'low', 'No category set', 'This question has no category.'));
    if (i % CHUNK === CHUNK - 1) await new Promise(r => setTimeout(r, 0)); // let the browser paint the new cards
  }
}

// ---- AI pass: batch compact question reps and ask the model for problems ----
function _docAiRepr(q, num) {
  const p = _docQParts(q);
  let s = '#' + num + ' [' + (q.topic || 'no topic') + ' / ' + (normalizeCategoryValue(q.category) || 'no category') + '] Title: ' + (q.title || '(untitled)');
  if (p.text) s += ' | Q: ' + _docClip(p.text, 500);
  if (p.mcq) {
    const opts = (p.mcq.options || []).map((o, i) => (i + 1) + ') ' + stripHtml(o.text || '')).join('  ');
    const c = (p.mcq.options || []).findIndex(o => o.id === p.mcq.correctId);
    s += ' | Options: ' + opts + ' | Marked correct: ' + (c >= 0 ? (c + 1) : 'NONE');
  }
  p.answers.forEach(a => { s += a.kind === 'cer' ? ' | Model: ' + _docClip([a.claim, a.evidence, a.reasoning].filter(Boolean).join('; '), 400) : ' | Answer: ' + _docClip(a.text, 400); });
  if (p.hasImage) s += ' | NOTE: this question DOES include a diagram/image (you cannot see it — assume it is present and fine).';
  else if (p.emptyImages) s += ' | NOTE: this question has an empty image placeholder with no picture.';
  return s;
}
async function _docAiBatch(items, startNum, instruction) {
  const lines = items.map((q, i) => _docAiRepr(q, startNum + i)).join('\n');
  const prompt =
    `You are a meticulous English-language editor reviewing a teacher's question bank for problems. ` +
    `The teacher is specifically looking for: ${instruction}\n` +
    `Only report REAL, clear problems — never invent issues; if a question is fine, say nothing about it. ` +
    `IMPORTANT: the question text may be ABBREVIATED (shown with a trailing …) and you CANNOT see any images. ` +
    `Do NOT report a question as cut off, incomplete or truncated just because the shown text looks short, and do NOT report a missing, blank or unloaded diagram/image — image presence is verified separately and noted per question. ` +
    `Only flag a diagram problem when the text clearly needs a figure AND its NOTE says it has no picture.\n` +
    `Here are the questions (each line starts with #<number>):\n${lines}\n` +
    `Return ONLY a JSON array. Each element describes ONE problem: {"refs":[<the #numbers involved>],"type":"Duplicate|Answer|MCQ|Wording|Language|Other","severity":"high|medium|low","summary":"<=14 words naming the problem","detail":"one or two sentences: the problem and how to fix it"}. ` +
    `Put a duplicate/near-duplicate set into ONE element with all its numbers in refs. If nothing is wrong, return [].`;
  const raw = await askGemini(prompt, { maxOutputTokens: 1500, temperature: 0.2, json: true });
  const arr = _parseAIJson(raw);
  return Array.isArray(arr) ? arr : ((arr && arr.issues) || []);
}
function _docAiToIssue(f, snapshot) {
  if (!f || !Array.isArray(f.refs)) return null;
  const ids = f.refs.map(n => snapshot[Number(n)] && snapshot[Number(n)].id).filter(Boolean);
  if (!ids.length) return null;
  const sev = /high/i.test(f.severity) ? 'high' : /low/i.test(f.severity) ? 'low' : 'med';
  const type = String(f.type || 'Issue').replace(/[^a-z]/gi, '') || 'Issue';
  return {
    key: 'ai:' + type + ':' + ids.slice().sort().join(','), type, severity: sev, ids, ai: true,
    title: String(f.summary || 'Possible issue').slice(0, 140),
    summary: ids.map(id => '“' + ((_docQById(id) || {}).title || '?') + '”').join(', '),
    detail: String(f.detail || '')
  };
}
// Clear the board for a fresh scan.
function _doctorClearResults() {
  _doctorIssues = [];
  const host = document.getElementById('doctorResults');
  if (host) host.innerHTML = '';
  _doctorUpdateCount();
}
// Add ONE issue and paint its card immediately (progressive fill — the page
// never waits for the whole scan to finish before showing what it found).
function _doctorEmitIssue(issue) {
  if (!issue || _doctorIssues.some(x => x.key === issue.key)) return;
  if (/duplicate/i.test(issue.type)) {
    const idset = issue.ids.slice().sort().join(',');
    if (_doctorIssues.some(x => /duplicate/i.test(x.type) && x.ids.slice().sort().join(',') === idset)) return; // already found structurally
  }
  if (!issue.ids.some(id => _docQById(id))) return; // references a deleted question
  _doctorIssues.push(issue);
  if (!_doctorDismissed.has(issue.key)) _doctorInsertCard(issue);
  _doctorUpdateCount();
}
// Insert a single card in severity order, without re-rendering the whole list.
function _doctorInsertCard(iss) {
  const host = document.getElementById('doctorResults'); if (!host) return;
  const empty = host.querySelector('.empty-state'); if (empty) empty.remove();
  const tmp = document.createElement('div');
  tmp.innerHTML = _doctorCardHtml(iss);
  const el = tmp.firstElementChild; if (!el) return;
  const rank = _sevRank(iss.severity);
  let placed = false;
  for (const child of host.children) {
    if (Number(child.dataset.sev || 9) > rank) { host.insertBefore(el, child); placed = true; break; }
  }
  if (!placed) host.appendChild(el);
}
function _doctorUpdateCount() {
  const list = _doctorVisibleIssues();
  const countEl = document.getElementById('doctorCount');
  if (countEl) countEl.textContent = list.length ? (list.length + ' possible issue' + (list.length === 1 ? '' : 's') + (_doctorScan.running ? ' so far…' : '')) : (_doctorScan.running ? 'Scanning…' : '');
  const badge = document.getElementById('doctorBadge');
  if (badge) { if (list.length) { badge.style.display = ''; badge.textContent = list.length; } else badge.style.display = 'none'; }
}

async function doctorScan() {
  if (_doctorScan.running) return;
  if (!currentUser || currentUser.role !== 'admin') { showToast('Admins only', 'error'); return; }
  if (!Array.isArray(questionBank) || !questionBank.length) { showToast('No questions in the bank to scan yet', 'info'); return; }
  const instruction = (document.getElementById('doctorQuery')?.value || '').trim() || DOCTOR_DEFAULT;
  const useAi = !!(window.__aiReady && window.__aiReady());
  _doctorDismissed.clear();
  _doctorExpanded.clear();
  _doctorScan = { running: true, done: 0, total: 0, stop: false };
  _doctorClearResults();                    // start from an empty board
  _doctorSetStatus('Checking structure…');
  // Structural checks stream in first (cards appear as they're found)…
  await _doctorRunLocalChecks();
  // …then the AI pass fills in deeper issues batch by batch, each painting
  // its cards the moment it returns — nothing waits for the whole scan.
  if (useAi && !_doctorScan.stop) {
    const snapshot = questionBank.slice();
    const BATCH = 12;
    const batches = [];
    for (let i = 0; i < snapshot.length; i += BATCH) batches.push({ start: i, items: snapshot.slice(i, i + BATCH) });
    _doctorScan.total = batches.length;
    _doctorSetStatus(`Scanning with AI… 0 / ${batches.length}`);
    let bi = 0;
    const worker = async () => {
      while (bi < batches.length && !_doctorScan.stop) {
        const my = batches[bi++];
        try {
          const found = await _docAiBatch(my.items, my.start, instruction);
          found.forEach(f => _doctorEmitIssue(_docAiToIssue(f, snapshot)));
        } catch (e) { console.warn('doctor batch failed', e); }
        _doctorScan.done++;
        _doctorSetStatus(`Scanning with AI… ${_doctorScan.done} / ${batches.length}`);
      }
    };
    await Promise.all(Array.from({ length: Math.min(4, batches.length) }, worker));
  } else if (!useAi) {
    _doctorSetStatus('');
    showToast('AI is off — showing structural checks only', 'info');
  }
  _doctorScan.running = false;
  _doctorSetStatus('');
  _doctorRenderResults();                    // one final tidy (sorted, consistent)
  const n = _doctorVisibleIssues().length;
  showToast(`Scan complete — ${n} possible issue${n === 1 ? '' : 's'} found`, n ? 'info' : 'success');
}
function doctorStop() { if (_doctorScan.running) { _doctorScan.stop = true; _doctorSetStatus('Stopping…'); } }
function _doctorSetStatus(txt) {
  const el = document.getElementById('doctorStatus'); if (el) el.textContent = txt || '';
  const scanBtn = document.getElementById('doctorScanBtn'); const stopBtn = document.getElementById('doctorStopBtn');
  if (scanBtn) scanBtn.style.display = _doctorScan.running ? 'none' : '';
  if (stopBtn) stopBtn.style.display = _doctorScan.running ? '' : 'none';
}

function _doctorVisibleIssues() {
  return _doctorIssues.filter(i => !_doctorDismissed.has(i.key) && i.ids.some(id => _docQById(id)));
}
function _doctorRenderResults() {
  const host = document.getElementById('doctorResults'); if (!host) return;
  const list = _doctorVisibleIssues().slice().sort((a, b) => _sevRank(a.severity) - _sevRank(b.severity));
  _doctorUpdateCount();
  if (!list.length) {
    host.innerHTML = _doctorScan.running ? '' :
      `<div class="empty-state"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:44px;height:44px;opacity:0.4;margin-bottom:10px;"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg><h3>No issues to show</h3><p>Edit the search box above and hit <strong>Scan questions</strong> to check your bank.</p></div>`;
    return;
  }
  host.innerHTML = list.map(_doctorCardHtml).join('');
}
function _doctorCardHtml(iss) {
  const expanded = _doctorExpanded.has(iss.key);
  const color = iss.severity === 'high' ? '#dc2626' : iss.severity === 'med' ? '#d97706' : '#6b7280';
  const bg = iss.severity === 'high' ? '#fef2f2' : iss.severity === 'med' ? '#fffbeb' : '#f3f4f6';
  return `<div class="doc-card" data-sev="${_sevRank(iss.severity)}" style="border-left:4px solid ${color};">
      <div class="doc-card-head" onclick="doctorToggle('${_docKeyAttr(iss.key)}')">
        <span class="doc-badge" style="background:${bg};color:${color};">${escapeHtml(iss.type)}${iss.ai ? ' · AI' : ''}</span>
        <div style="flex:1;min-width:0;">
          <div class="doc-card-title">${escapeHtml(iss.title)}</div>
          <div class="doc-card-sub">${escapeHtml(iss.summary)}</div>
        </div>
        <span class="doc-chev">${expanded ? '▲' : '▼'}</span>
      </div>
      ${expanded ? _doctorDetailHtml(iss) : ''}
    </div>`;
}
function _doctorDetailHtml(iss) {
  const qs = iss.ids.map(id => _docQById(id)).filter(Boolean);
  const body = qs.map(q => `<div class="doc-q">
      <div class="doc-q-head"><strong>${escapeHtml(q.title || 'Untitled')}</strong> <span style="color:var(--text-muted);font-size:0.76rem;">${escapeHtml(q.topic || '')}${q.category ? ' · ' + escapeHtml(normalizeCategoryValue(q.category)) : ''}</span></div>
      <div class="doc-q-prev">${renderQuestionPreviewHtml(q.id)}</div>
      <div class="doc-q-actions">
        <button class="btn btn-outline" style="font-size:0.78rem;padding:5px 11px;" onclick="doctorOpen('${escapeHtml(q.id)}')">✏️ Open in editor</button>
        <button class="btn btn-outline" style="font-size:0.78rem;padding:5px 11px;color:var(--accent-red);border-color:#f0b9b9;" onclick="doctorDelete('${escapeHtml(q.id)}')">🗑 Delete this question</button>
      </div>
    </div>`).join('');
  return `<div class="doc-detail">
      ${iss.detail ? `<div class="doc-detail-note">${escapeHtml(iss.detail)}</div>` : ''}
      ${body}
      <div style="text-align:right;margin-top:6px;"><button class="btn btn-outline" style="font-size:0.76rem;padding:4px 10px;" onclick="doctorDismiss('${_docKeyAttr(iss.key)}')">✓ Dismiss (not an issue)</button></div>
    </div>`;
}
function _docKeyAttr(k) { return String(k).replace(/'/g, "\\'"); }
function doctorToggle(key) { if (_doctorExpanded.has(key)) _doctorExpanded.delete(key); else _doctorExpanded.add(key); _doctorRenderResults(); }
function doctorDismiss(key) { _doctorDismissed.add(key); _doctorRenderResults(); }
function doctorOpen(id) { if (_docQById(id)) editQuestion(id); else showToast('That question no longer exists', 'info'); }
function doctorDelete(id) {
  const q = _docQById(id); if (!q) { _doctorRenderResults(); return; }
  showConfirm('Delete question', `“${q.title || 'Untitled'}” goes to the bin. You can restore it there for ${BIN_DAYS} days.`, async () => {
    if (!await binQuestion(id)) return;
    showToast(`Moved to the bin — restorable for ${BIN_DAYS} days`, 'info');
    if (document.querySelector('#page-bank.active')) renderQuestionBank();
    _doctorRenderResults();
  });
}


// =====================================================================
// ✅ CHECK QUESTIONS (admin + employee) — the questions added MOST RECENTLY,
// served ONE at a time for a second pair of eyes. It is deliberately not the
// Question Doctor: the Doctor is a whole-bank audit an admin runs occasionally
// and reads as a list of problems, while this is a queue an employee works
// through a question at a time and which never stops offering the next one.
//
// The headline check is the one the whole page exists for: a question whose
// TABLE OR DIAGRAM already shows the four choices, with the options underneath
// repeating what the picture has already said. Those options should read just
// (1) (2) (3) (4) — the picture is the choice list — and the fix is one tap
// (`mcqNumberOptions` writes exactly the same thing in the block editor).
//
// Two layers find it, because neither can do the job alone:
//   · STRUCTURAL, instant, no AI — decidable when the choices are in a TABLE
//     block: the table labels its rows 1..n, or the option wording is already
//     printed in the cells.
//   · AI WITH VISION — the same question in a PICTURE is invisible to any text
//     check, so the diagrams are attached and the model is asked about them
//     FIRST. Without the images this check cannot be made at all; do not
//     "optimise" the pass down to askGemini.
//
// Checked state lives on the question (`q.checked`) rather than per user, so
// two employees never read the same question twice. It is written with a QUIET
// save: marking a question read is housekeeping, not authoring, and must not
// land in anybody's work-session log as a question written.
// =====================================================================
const CQ_RECENT_DAYS = 45;   // what "recently added" means for the badge + queue
const CQ_MIN_QUEUE = 25;     // …but never offer an empty queue while unread questions exist
const CQ_AI_IMAGES = 3;      // diagrams attached to one AI check
const CQ_LONG_OPTION = 20;   // avg chars before wordy options are worth a look

let _cqQueue = [];               // question ids, newest first
let _cqPos = 0;                  // where we are in it
const _cqReviews = new Map();    // id -> { state:'running'|'done'|'error', findings, error }
let _cqAuto = true;              // run the AI pass automatically on each question
let _cqLastChecked = '';         // id the last ✓ marked — for Undo
let _cqLastDeleted = '';         // id the last 🗑 binned — for the same Undo

// ---- reading a question -------------------------------------------------
function _cqCheckedAt(q) { return (q && q.checked && q.checked.at) || ''; }
function _cqAddedAt(q) { return String((q && q.createdAt) || ''); }
function _cqRecentCut() { return new Date(Date.now() - CQ_RECENT_DAYS * 864e5).toISOString(); }
function _cqUnchecked() {
  return (Array.isArray(questionBank) ? questionBank : [])
    .filter(q => q && q.id && !_cqCheckedAt(q))
    .sort((a, b) => _cqAddedAt(b).localeCompare(_cqAddedAt(a)));
}
// The badge counts only what the page PROMISES — the recent ones. A bank of
// several thousand older questions would otherwise show a number nobody could
// ever clear, which reads as broken rather than as work to do.
function _cqRecentUncheckedCount() {
  const cut = _cqRecentCut();
  return (Array.isArray(questionBank) ? questionBank : [])
    .filter(q => q && q.id && !_cqCheckedAt(q) && _cqAddedAt(q) >= cut).length;
}
function _cqBuildQueue() {
  const all = _cqUnchecked();
  const cut = _cqRecentCut();
  const recent = all.filter(q => _cqAddedAt(q) >= cut);
  // Recent first — but a bank whose newest question predates the window still
  // gets a queue, or the page sits empty while nothing has ever been read.
  const list = recent.length >= CQ_MIN_QUEUE ? recent : all.slice(0, Math.max(CQ_MIN_QUEUE, recent.length));
  _cqQueue = list.map(q => q.id);
  _cqPos = 0;
}
// The question on show. Anything deleted or checked since the queue was built
// is stepped over rather than rendered as a gap.
function _cqCurrent() {
  while (_cqPos < _cqQueue.length) {
    const q = _docQById(_cqQueue[_cqPos]);
    if (q && !_cqCheckedAt(q)) return q;
    _cqPos++;
  }
  return null;
}

// ---- the tables an option list can be repeating -------------------------
// A LOADED question carries table data as array-of-arrays (normalizeLoadedQuestion
// restores it), but a question held straight from a Firestore read has the
// object-of-rows shape — so read both rather than crashing on one of them.
function _cqTableRows(b) {
  let data = b && b.data;
  if (!data) return [];
  const rowsOf = v => Array.isArray(v) ? v
    : (v && typeof v === 'object' ? Object.keys(v).sort((x, y) => Number(x) - Number(y)).map(k => v[k]) : []);
  return rowsOf(data).map(row => rowsOf(row).map(c => stripHtml(String(c == null ? '' : c)).replace(/\s+/g, ' ').trim()));
}
function _cqTableCells(b) { return _cqTableRows(b).flat().filter(Boolean); }
function _cqOptText(o) { return stripHtml((o && o.text) || '').replace(/\s+/g, ' ').trim(); }
function _cqMcqBlock(q) { return ((q && q.blocks) || []).find(b => b && b.type === 'mcq'); }
// "(1)", "2.", "  3 )" — an option that is already nothing but its own number.
const CQ_NUMBERISH_RE = /^[\s([]*\d{1,2}[\s)\].:-]*$/;
function _cqOptsAreBareNumbers(mcq) {
  const t = ((mcq && mcq.options) || []).map(_cqOptText);
  return t.length > 0 && t.every(s => !s || CQ_NUMBERISH_RE.test(s));
}
// Can the one-tap fix be offered at all? Only for a real option list that is
// not already numbered — the button must never be a no-op.
function _cqMcqFixable(q) {
  const mcq = _cqMcqBlock(q);
  if (!mcq || !Array.isArray(mcq.options) || mcq.options.length < 2) return null;
  if (_cqOptsAreBareNumbers(mcq)) return null;
  return mcq;
}
const CQ_STOPWORDS = new Set(['the', 'and', 'for', 'with', 'that', 'this', 'from', 'are', 'was', 'were', 'has', 'have', 'had', 'its', 'his', 'her', 'their', 'than', 'then', 'into', 'onto', 'out', 'not', 'but', 'all', 'any', 'each', 'more', 'most', 'only', 'same']);
function _cqWords(s) {
  return _docNorm(s).split(' ').filter(w => w.length >= 3 && !CQ_STOPWORDS.has(w));
}
// A table that labels its own rows 1..n IS the option list — the strongest
// signal there is, and it needs no wording match at all.
function _cqTableLabelsChoices(tables, n) {
  if (n < 2) return false;
  const nums = new Set();
  tables.forEach(b => _cqTableCells(b).forEach(c => {
    const m = c.match(/^\(?\s*(\d{1,2})\s*\)?[.)]?$/);
    if (m) nums.add(Number(m[1]));
  }));
  for (let i = 1; i <= n; i++) if (!nums.has(i)) return false;
  return true;
}

// ---- structural findings (instant, no AI) -------------------------------
function _cqFinding(type, severity, title, detail, fix) {
  return { type, severity, title, detail, fix: fix || '' };
}
function _cqLocalFindings(q, aiAnswered) {
  const out = [];
  // `bl`, not `blocks` — the module-level `blocks` is the block EDITOR's array
  // and shadowing it inside a checker that never touches the editor is exactly
  // the kind of confusion that costs an afternoon.
  const bl = (q && q.blocks) || [];
  const mcq = _cqMcqBlock(q);
  const tables = bl.filter(b => b && b.type === 'table');
  const pics = bl.filter(b => b && b.type === 'image');
  const hasPicture = pics.some(b => b.url) || bl.some(b => /<img[\s>]/i.test(String(b && (b.content || b.claim || b.evidence || b.reasoning) || '')));

  if (mcq) {
    const opts = (mcq.options || []).map(_cqOptText);
    const real = opts.filter(Boolean);
    const fixable = !!_cqMcqFixable(q);
    // ── THE HEADLINE CHECK, decidable half ──────────────────────────────
    if (fixable && tables.length && real.length >= 2) {
      const labelled = _cqTableLabelsChoices(tables, opts.length);
      const cellWords = new Set(tables.flatMap(b => _cqTableCells(b)).flatMap(_cqWords));
      const echoed = real.filter(t => {
        const w = _cqWords(t);
        return w.length > 0 && w.filter(x => cellWords.has(x)).length / w.length >= 0.8;
      }).length;
      const mostEchoed = echoed >= Math.max(2, Math.ceil(real.length / 2));
      if (labelled || mostEchoed) {
        out.push(_cqFinding('Options', 'high', 'The table already shows the choices — the options repeat it',
          labelled
            ? 'The table in this question labels its rows 1, 2, 3… so the table IS the list of choices. The options underneath should read just (1) (2) (3) (4) and let the table do the work.'
            : `${echoed} of the ${real.length} options are already written out in the table. Where the table shows the choice, the option only needs to be its number — (1) (2) (3) (4).`,
          'numberOptions'));
      }
    }
    // ── the same shape with a PICTURE is undecidable here: only the AI can
    // read the diagram, so this is a nudge and it stands down once it has.
    if (fixable && !tables.length && hasPicture && real.length >= 2 && !aiAnswered) {
      const avg = real.reduce((n, t) => n + t.length, 0) / real.length;
      if (avg >= CQ_LONG_OPTION) {
        out.push(_cqFinding('Options', 'low', 'Wordy options next to a diagram — does the picture already show them?',
          'If the diagram already labels each choice, the options should be just (1) (2) (3) (4) rather than repeating the picture in words. The AI check below reads the diagram and will say.'));
      }
    }
    const correct = (mcq.options || []).find(o => o.id === mcq.correctId);
    if (!correct) out.push(_cqFinding('MCQ', 'high', 'No correct option is marked', 'Nothing is ticked as the answer, so this question can never be marked right.'));
    if (real.length < 2) out.push(_cqFinding('MCQ', 'high', 'Fewer than two real options', 'A multiple-choice question needs at least two options with text in them.'));
    const norm = real.map(_docNorm);
    if (new Set(norm).size < norm.length) out.push(_cqFinding('MCQ', 'med', 'Two options are identical', 'Two or more options say exactly the same thing — one of them cannot be right.'));
  }

  if (pics.some(b => !b.url) && !hasPicture) {
    out.push(_cqFinding('Diagram', 'med', 'An empty picture placeholder', 'A picture block has no picture in it, so students will see a blank space where the diagram should be.'));
  }
  // Wording that promises a figure the question does not have.
  const stem = bl.filter(b => b && (b.type === 'text' || b.type === 'part')).map(b => stripHtml(b.content || '')).join(' ');
  if (!hasPicture && !tables.length && /\b(diagram|figure|picture|graph|the table|shown below|as shown)\b/i.test(stem)) {
    out.push(_cqFinding('Diagram', 'med', 'The wording refers to something that is not there', 'The question mentions a diagram, table or picture, but none is attached.'));
  }
  bl.forEach(b => {
    if (!b) return;
    if (b.type === 'answer' && !stripHtml([b.claim, b.evidence, b.reasoning].join(' ')).trim()) {
      out.push(_cqFinding('Answer', 'high', 'The model answer is blank', 'Claim / Evidence / Reasoning are all empty, so there is nothing for the AI to mark a student against.'));
    }
    if (b.type === 'plainanswer' && !stripHtml(b.content || '').trim()) {
      out.push(_cqFinding('Answer', 'high', 'The model answer is blank', 'The answer box is empty, so there is nothing for the AI to mark a student against.'));
    }
  });
  if (bl.length && !questionHasMarkableAnswer(q) && !(q && q.annotation)) {
    out.push(_cqFinding('Answer', 'high', 'Nothing here can be marked', 'This question has no answer section at all and is not an annotation question, so practice cannot score it.'));
  }
  if (bl.length && !String((q && q.topic) || '').trim()) out.push(_cqFinding('Filing', 'low', 'No topic set', 'Without a topic this question never appears in topical practice.'));
  return out;
}

// ---- the AI pass: the question AND its diagrams -------------------------
async function _cqMedia(q) {
  const urls = [];
  ((q && q.blocks) || []).forEach(b => {
    if (!b) return;
    if (b.type === 'image' && b.url) urls.push(b.url);
    // Pasted diagrams live inside a text or answer box as an inline <img>.
    ['content', 'claim', 'evidence', 'reasoning'].forEach(f => {
      const html = typeof b[f] === 'string' ? b[f] : '';
      const re = /<img[^>]+src\s*=\s*["']([^"']+)["']/gi;
      let m;
      while ((m = re.exec(html))) urls.push(m[1]);
    });
  });
  const media = [];
  for (const u of urls) {
    if (media.length >= CQ_AI_IMAGES) break;
    try {
      const dataUrl = await _urlToDataUrlRobust(transformImageUrl(u));
      const parsed = _parseImageDataUrl(dataUrl);
      if (parsed) media.push({ mimeType: parsed.mime, data: dataUrl.split(',')[1] || '' });
    } catch (e) { console.warn('check-questions: could not read a diagram', e); }
  }
  return media;
}
// The question as words. Unlike the Doctor's representation this spells the
// TABLE out in full — the table is the very thing the options may be echoing.
function _cqRepr(q) {
  const lines = [];
  lines.push('Title: ' + (q.title || '(untitled)'));
  const meta = [q.topic, normalizeCategoryValue(q.category || '')].filter(Boolean).join(' / ');
  if (meta) lines.push('Filed under: ' + meta);
  ((q && q.blocks) || []).forEach(b => {
    if (!b) return;
    switch (b.type) {
      case 'text': { const t = stripHtml(b.content || '').trim(); if (t) lines.push(t); break; }
      case 'part': { const t = ((b.label || '') + ' ' + stripHtml(b.content || '')).trim(); if (t) lines.push(t); break; }
      case 'table': {
        const rows = _cqTableRows(b).filter(r => r.some(Boolean));
        if (rows.length) lines.push('TABLE printed in the question:\n' + rows.map(r => '  | ' + r.join(' | ') + ' |').join('\n'));
        break;
      }
      case 'image':
        lines.push(b.url
          ? '[a picture is printed here' + (b.caption ? ': ' + stripHtml(b.caption) : '') + ' — it is attached to this message]'
          : '[an EMPTY picture placeholder — no picture has been added]');
        break;
      case 'mcq': {
        const opts = (b.options || []).map((o, i) => '  (' + (i + 1) + ') ' + (_cqOptText(o) || '(blank)'));
        const c = (b.options || []).findIndex(o => o.id === b.correctId);
        lines.push('OPTIONS exactly as they are written now:\n' + opts.join('\n') + '\nMarked correct: ' + (c >= 0 ? '(' + (c + 1) + ')' : 'NONE'));
        break;
      }
      case 'answer':
        lines.push('Model answer — Claim: ' + stripHtml(b.claim || '') + ' | Evidence: ' + stripHtml(b.evidence || '') + ' | Reasoning: ' + stripHtml(b.reasoning || ''));
        break;
      case 'plainanswer': lines.push('Model answer: ' + stripHtml(b.content || '')); break;
      case 'answerLine': lines.push('Answer line' + (b.label ? ' (' + stripHtml(b.label) + ')' : '') + ': ' + stripHtml(b.answer || '')); break;
      case 'fillblank': lines.push('Fill in the blanks: ' + stripHtml(b.text || '')); break;
      case 'explanation': lines.push('Explanation given to the student: ' + stripHtml(b.content || '')); break;
      default: break;
    }
  });
  return _docClip(lines.join('\n'), 4000);
}
async function _cqAiCheck(q) {
  const media = await _cqMedia(q);
  const prompt =
    `You are a meticulous Singapore primary-school English question editor. A colleague has just written the question below and you are giving it a second read before it is used with a class.\n\n` +
    `CHECK THIS FIRST — options that repeat the picture.\n` +
    `If the question's TABLE, DIAGRAM or PICTURE already sets out the choices — for example its rows or parts are labelled 1, 2, 3, 4 — and the multiple-choice options underneath simply repeat in words what the picture already shows, that is the problem to report. Those options should read just "(1)", "(2)", "(3)", "(4)" and let the picture do the work. Report it with "fix":"numberOptions".\n` +
    `Do NOT report it when the options carry information that is NOT already in the picture or table, and do NOT report it when the options are already bare numbers.\n\n` +
    `Then check for: an answer or marked option that is wrong or does not match the question; a blank or incomplete model answer; options that do not match the diagram; unclear, ambiguous or grammatically broken wording; a scientific mistake; wording that refers to a figure the question does not have.\n\n` +
    (media.length
      ? `${media.length} picture${media.length === 1 ? '' : 's'} from this question ${media.length === 1 ? 'is' : 'are'} attached — study ${media.length === 1 ? 'it' : 'them'} against the options.\n`
      : `This question has no picture attached.\n`) +
    `Report only REAL, clear problems — if the question is fine, say so by returning an empty list. Never invent an issue, and never report the question as truncated or cut off.\n\n` +
    `THE QUESTION:\n${_cqRepr(q)}\n\n` +
    `Return ONLY JSON: {"findings":[{"type":"Options|MCQ|Answer|Wording|Language|Diagram|Other","severity":"high|medium|low","summary":"<=14 words naming the problem","detail":"one or two sentences: what is wrong and how to fix it","fix":"numberOptions or empty string"}]}`;
  const raw = media.length
    ? await askGeminiVision(prompt, media, { maxOutputTokens: 900, json: true })
    : await askGemini(prompt, { maxOutputTokens: 900, temperature: 0.2, json: true });
  const parsed = _parseAIJson(raw);
  const arr = Array.isArray(parsed) ? parsed : ((parsed && parsed.findings) || []);
  const fixable = !!_cqMcqFixable(q);
  return arr.map(f => _cqNormFinding(f, fixable)).filter(Boolean);
}
function _cqNormFinding(f, fixable) {
  if (!f || typeof f !== 'object') return null;
  const summary = String(f.summary || f.title || '').trim();
  if (!summary) return null;
  return {
    type: (String(f.type || 'Check').replace(/[^A-Za-z ]/g, '').trim() || 'Check').slice(0, 18),
    severity: /high/i.test(f.severity) ? 'high' : /low/i.test(f.severity) ? 'low' : 'med',
    title: summary.slice(0, 160),
    detail: String(f.detail || '').slice(0, 600),
    // The button must never be a no-op: offer the fix only when there really
    // is an option list to renumber and it is not already numbered.
    fix: (fixable && /numberoptions/i.test(String(f.fix || ''))) ? 'numberOptions' : '',
    ai: true
  };
}

// ---- rendering ----------------------------------------------------------
function renderCheckQPage() {
  if (!_canAuthor()) return;
  const auto = document.getElementById('cqAuto');
  if (auto) auto.checked = _cqAuto;
  if (!_cqQueue.length) _cqBuildQueue();
  _cqRender();
}
function _cqRender() {
  const host = document.getElementById('cqBody');
  if (!host) return;
  // ONE Undo, for whichever of the two undoable things happened last. A binned
  // question is no longer in the bank, so it is checked for in the bin instead.
  const undo = document.getElementById('cqUndoBtn');
  if (undo) {
    const canUndoDelete = !!(_cqLastDeleted && _binList.some(r => r && r.id === _cqLastDeleted));
    const canUndoCheck = !!(_cqLastChecked && _docQById(_cqLastChecked));
    undo.style.display = (canUndoDelete || canUndoCheck) ? '' : 'none';
    undo.textContent = canUndoDelete ? '↩ Undo delete' : '↩ Undo last ✓';
  }
  const q = _cqCurrent();
  _cqUpdateBadge();
  if (!q) {
    host.innerHTML = `<div class="cq-empty">
      <div style="font-size:2rem;margin-bottom:10px;">🎉</div>
      <h3>Nothing waiting to be checked</h3>
      <p>Every recently added question has been read. New ones appear here as soon as they are saved to the bank — press Refresh to pick them up.</p>
      <button class="btn btn-outline" style="font-size:0.86rem;" onclick="cqRefresh()">🔄 Refresh queue</button>
    </div>`;
    _cqSetProgress('');
    return;
  }
  const total = _cqQueue.length;
  const recent = _cqRecentUncheckedCount();
  _cqSetProgress(`Question ${Math.min(_cqPos + 1, total)} of ${total} in this queue${recent ? ` · ${recent} added in the last ${CQ_RECENT_DAYS} days still unchecked` : ''}`);
  host.innerHTML = _cqCardHtml(q);
  _cqRenderFindings();
  _cqMaybeRunAi(q.id);
}
function _cqSetProgress(txt) {
  const el = document.getElementById('cqProgress'); if (el) el.textContent = txt || '';
  const c = document.getElementById('cqCount');
  if (c) { const n = _cqRecentUncheckedCount(); c.textContent = n ? n + ' to check' : ''; }
}
function _cqCardHtml(q) {
  const added = q.createdAt ? new Date(q.createdAt).toLocaleString() : 'date unknown';
  const by = String(q.createdBy || '').trim();
  const id = escapeHtml(q.id);
  const meta = [
    escapeHtml(q.topic || 'no topic'),
    q.category ? escapeHtml(normalizeCategoryValue(q.category)) : '',
    'added ' + escapeHtml(added) + (by ? ' by ' + escapeHtml(by) : '')
  ].filter(Boolean).join(' · ');
  const btn = 'font-size:0.84rem;padding:8px 14px;';
  return `<div class="cq-card">
      <div class="cq-head">
        <div class="cq-title">${escapeHtml(q.title || 'Untitled question')}</div>
        <div class="cq-meta">${meta}</div>
      </div>
      <div class="cq-find" id="cqFindings"></div>
      <div class="cq-preview"><div class="cq-preview-inner">${renderQuestionPreviewHtml(q.id, { tryIt: false })}</div></div>
      <div class="cq-actions">
        <button class="btn btn-primary" style="${btn}" onclick="cqLooksFine('${id}')">✓ Looks fine</button>
        ${_cqMcqFixable(q) ? `<button class="btn btn-outline" style="${btn}" title="Set every option to its own number and let the table or diagram show the choices" onclick="cqNumberOptions('${id}')">＃ Make options (1)(2)(3)(4)</button>` : ''}
        <button class="btn btn-outline" style="${btn}" onclick="cqOpenEditor('${id}')">✏️ Open in editor</button>
        <button class="btn btn-outline" style="${btn}" onclick="cqSkip()">⏭ Skip for now</button>
        <button class="btn btn-outline" style="${btn}margin-left:auto;" onclick="cqRecheck()">🤖 Check with AI</button>
        <!-- Far right and on its own, away from the buttons this queue is worked
             with, because it is the one action here that removes something. It
             asks nothing first: the question goes to the bin, ↩ Undo is at the
             top of the page, and the bin holds it for a week. -->
        <button class="btn btn-outline cq-del" style="${btn}" title="Move this question to the bin — restorable for ${BIN_DAYS} days" onclick="cqDelete('${id}')">🗑 Delete</button>
      </div>
    </div>`;
}
// Only the findings panel is repainted when the AI answers — rebuilding the
// whole card would re-fetch every diagram in the preview underneath it.
function _cqRenderFindings() {
  const host = document.getElementById('cqFindings');
  if (!host) return;
  const q = _cqCurrent(); if (!q) return;
  const rev = _cqReviews.get(q.id) || { state: 'idle', findings: [] };
  const list = _cqLocalFindings(q, rev.state === 'done')
    .concat(rev.findings || [])
    .sort((a, b) => _sevRank(a.severity) - _sevRank(b.severity));
  let head = '';
  if (rev.state === 'running') head = `<div class="cq-note">🤖 The AI is reading this question and its diagrams…</div>`;
  else if (rev.state === 'error') head = `<div class="cq-note">🤖 The AI check could not run${rev.error ? ' (' + escapeHtml(rev.error) + ')' : ''} — the instant checks still apply. Press <b>🤖 Check with AI</b> to try again.</div>`;
  if (!list.length) {
    const aiOn = !!(window.__aiReady && window.__aiReady());
    host.innerHTML = head + (rev.state === 'running' ? ''
      : rev.state === 'done' ? `<div class="cq-note">✅ Nothing flagged — read it over, then mark it fine.</div>`
      : `<div class="cq-note">Nothing flagged by the instant checks.${aiOn ? '' : ' AI is off, so only those ran.'}</div>`);
    return;
  }
  host.innerHTML = head + list.map(f => _cqFindingHtml(f, q.id)).join('');
}
function _cqFindingHtml(f, qid) {
  const color = f.severity === 'high' ? '#dc2626' : f.severity === 'med' ? '#d97706' : '#6b7280';
  const bg = f.severity === 'high' ? '#fef2f2' : f.severity === 'med' ? '#fffbeb' : '#f3f4f6';
  return `<div class="cq-find-row" style="border-left:4px solid ${color};">
      <span class="cq-badge" style="background:${bg};color:${color};">${escapeHtml(f.type)}${f.ai ? ' · AI' : ''}</span>
      <div style="flex:1;min-width:0;">
        <div class="cq-find-title">${escapeHtml(f.title)}</div>
        ${f.detail ? `<div class="cq-find-detail">${escapeHtml(f.detail)}</div>` : ''}
        ${f.fix === 'numberOptions' ? `<div class="cq-find-fix"><button class="btn btn-outline" style="font-size:0.8rem;padding:6px 12px;" onclick="cqNumberOptions('${escapeHtml(qid)}')">＃ Make options (1)(2)(3)(4)</button></div>` : ''}
      </div>
    </div>`;
}

// ---- the AI pass, driven from the page ----------------------------------
function _cqMaybeRunAi(id) {
  if (!_cqAuto) return;
  const rev = _cqReviews.get(id);
  if (rev && (rev.state === 'running' || rev.state === 'done')) return;   // already answered
  _cqRunAi(id);
}
async function _cqRunAi(id) {
  if (!(window.__aiReady && window.__aiReady())) return;
  const q = _docQById(id); if (!q) return;
  const rev = _cqReviews.get(id);
  if (rev && rev.state === 'running') return;
  _cqReviews.set(id, { state: 'running', findings: [] });
  _cqRenderFindings();
  try {
    _cqReviews.set(id, { state: 'done', findings: await _cqAiCheck(q) });
  } catch (e) {
    console.warn('check-questions AI pass failed', e);
    _cqReviews.set(id, { state: 'error', findings: [], error: (e && e.message) || 'AI error' });
  }
  // The employee may have moved on while it was thinking — only paint the
  // answer if it still belongs to the question on screen.
  const cur = _cqCurrent();
  if (cur && cur.id === id) _cqRenderFindings();
}

// ---- actions ------------------------------------------------------------
function cqToggleAuto(on) {
  _cqAuto = !!on;
  if (_cqAuto) { const q = _cqCurrent(); if (q) _cqMaybeRunAi(q.id); }
}
function cqRefresh() {
  _cqBuildQueue();
  _cqRender();
  showToast(_cqQueue.length ? `${_cqQueue.length} question${_cqQueue.length === 1 ? '' : 's'} to check` : 'Nothing left to check', 'info');
}
function cqSkip() { _cqPos++; _cqRender(); }
function cqRecheck() {
  const q = _cqCurrent(); if (!q) return;
  if (!(window.__aiReady && window.__aiReady())) { showToast('AI is not ready yet — try again in a moment', 'error'); return; }
  _cqReviews.delete(q.id);
  _cqRunAi(q.id);
}
function cqOpenEditor(id) {
  if (!_docQById(id)) { showToast('That question no longer exists', 'info'); _cqRender(); return; }
  // Whatever the AI said is about to be about an older version of the question.
  _cqReviews.delete(id);
  editQuestion(id);
  _editReturnPage = 'checkq';   // editQuestion resets it — callers override after
  try { _syncBackToPapersBtn(); } catch (e) {}
}
// Mark the question read. The advance is optimistic so the queue never stalls
// on the network, and it is rolled back if the write does not land.
async function cqLooksFine(id) {
  const q = _docQById(id); if (!q) { _cqRender(); return; }
  q.checked = {
    at: new Date().toISOString(),
    by: (currentUser && currentUser.uid) || '',
    name: (currentUser && (currentUser.name || currentUser.email)) || ''
  };
  _cqLastChecked = id;
  _cqPos++;
  _cqRender();
  // Quiet: reading a question is housekeeping, not a question authored, so it
  // must never land in a work session's log.
  const ok = await saveQuestion(q, { quiet: true });
  if (!ok) {
    delete q.checked;
    _cqLastChecked = '';
    _cqPos = Math.max(0, _cqQueue.indexOf(id) >= 0 ? _cqQueue.indexOf(id) : _cqPos - 1);
    showToast('Could not save that check — try again', 'error');
    _cqRender();
  }
}
// Move the question on show to the bin and step on. No confirm: the bin holds
// it for a week, ↩ Undo is at the top of the page, and this is a queue somebody
// is working through — a dialog on every deletion is how a queue stops getting
// worked through.
async function cqDelete(id) {
  const q = _docQById(id);
  if (!q) { _cqRender(); return; }
  const title = q.title || 'Untitled question';
  if (!await binQuestion(id)) { _cqRender(); return; }
  _cqLastDeleted = id;
  _cqLastChecked = '';          // the Undo button means the deletion now
  _cqReviews.delete(id);        // nothing left to have an opinion about
  _cqRender();
  if (document.querySelector('#page-bank.active')) renderQuestionBank();
  showToast(`“${title}” moved to the bin — restorable for ${BIN_DAYS} days`, 'info');
}

// One Undo for both actions, newest first: a deletion if that was the last
// thing, otherwise the last ✓.
async function cqUndo() {
  if (_cqLastDeleted && _binList.some(r => r && r.id === _cqLastDeleted)) {
    const id = _cqLastDeleted;
    _cqLastDeleted = '';
    const ok = await binRestore(id);
    if (ok) {
      // It comes back unchecked, so put the queue back on it rather than
      // leaving it to surface again whenever the queue is next rebuilt.
      _cqBuildQueue();
      const at = _cqQueue.indexOf(id);
      if (at >= 0) _cqPos = at;
      showToast('Question restored ✓', 'success');
    }
    _cqRender();
    if (document.querySelector('#page-bank.active')) renderQuestionBank();
    return;
  }
  const id = _cqLastChecked;
  const q = id && _docQById(id);
  if (!q) { _cqLastChecked = ''; _cqRender(); return; }
  delete q.checked;
  _cqLastChecked = '';
  const at = _cqQueue.indexOf(id);
  if (at >= 0) _cqPos = at;
  _cqRender();
  await saveQuestion(q, { quiet: true });
}
// The one-tap fix — the same thing the block editor's ＃ button writes, so a
// question fixed from here and one fixed by hand come out identical.
async function cqNumberOptions(id) {
  const q = _docQById(id);
  const mcq = q && _cqMcqFixable(q);
  if (!mcq) { showToast('There are no options here to renumber', 'error'); _cqRender(); return; }
  const before = mcq.options.map(o => o.text);
  mcq.options.forEach((o, i) => { o.text = `(${i + 1})`; });
  // A real edit to the question — NOT quiet: the other tabs must pick it up
  // and a running work session should count it as work done.
  const ok = await saveQuestion(q);
  if (!ok) { mcq.options.forEach((o, i) => { o.text = before[i]; }); _cqRender(); return; }
  // The finding is answered — drop it rather than binning the whole review,
  // which would spend another AI call re-reading a question we just fixed.
  const rev = _cqReviews.get(id);
  if (rev) rev.findings = (rev.findings || []).filter(f => f.fix !== 'numberOptions');
  showToast('Options are now (1) (2) (3) (4) — the picture shows the choices', 'success');
  if (document.querySelector('#page-bank.active')) renderQuestionBank();
  _cqRender();
}
function _cqUpdateBadge() {
  const badge = document.getElementById('cqBadge');
  if (!badge) return;
  const n = _canAuthor() ? _cqRecentUncheckedCount() : 0;
  if (n) { badge.style.display = ''; badge.textContent = n > 999 ? '999+' : String(n); }
  else badge.style.display = 'none';
}


// =====================================================================
// LEARNER PROGRESS — the plain record of work done
//
// The Science portal this app was forked from wrapped every answered
// question in a game: XP, gold, a dungeon crawl, a trading-card game, a
// first-person shooter. None of that is here. What IS still needed is the
// honest record underneath it — how many questions a student has answered,
// how many they got right, and whether they turned up today — because My
// Report, the student Home screen, the teacher's Usage dashboard and the
// Ai-nstein study buddy all read it.
//
// Storage: the student's own progress doc under their user tree, mirrored
// to a shared class collection so a teacher (who cannot read another
// account's settings) can see the class at a glance. That mirror carries
// COUNTS ONLY — never answers, never marks on a particular question.
// =====================================================================
const $ = (id) => document.getElementById(id);
function toast(msg, type = "") { showToast(msg, type || "info"); }

// A gap longer than this means the student walked away — it is not an answer
// pace. PACE_MIN_PRACTICE_MS is the floor a considered answer clears; the
// practice page has no per-question timer, so the gap since the previously
// marked question stands in for one.
const PACE_MIN_PRACTICE_MS = 15000;
const PACE_MAX_MS = 360000;

let progress = null;            // null until hydrated, and again after sign-out
let _progressSaveTimer = null;
let _progressPublishTimer = null;

function progressToday(d = new Date()) {
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}
function progressYesterday() { const d = new Date(); d.setDate(d.getDate() - 1); return progressToday(d); }
function progressMonthKey(d = new Date()) { return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0"); }

function progressDefaults() {
  return {
    stats: { marked: 0, correct: 0, creditSum: 0 },
    streak: { count: 0, best: 0, lastDay: null, dayKey: null, dayMarks: 0 },
    pace: { n: 0, ok: 0, sumMs: 0, lastAt: 0 },
    seenQ: {},          // question id → times answered, so a re-attempt is visible
    monthKey: null, monthQ: 0, monthQids: {}, monthPrints: {},
    lastMonthKey: null, lastMonthQ: 0,
    papersQ: 0,
    encounter: {},      // per-quest progress on the community board
    prizeAck: {},
    updatedAt: null
  };
}

// A missing field on an older doc must never come back as `undefined` and take
// a render down, so every nested object is rebuilt rather than trusted.
function progressHydrate(saved) {
  const d = progressDefaults();
  const st = Object.assign(d, saved || {});
  st.stats = Object.assign(d.stats, (saved && saved.stats) || {});
  st.streak = Object.assign(d.streak, (saved && saved.streak) || {});
  st.pace = Object.assign(d.pace, (saved && saved.pace) || {});
  st.seenQ = Object.assign({}, (saved && saved.seenQ) || {});
  st.monthQids = Object.assign({}, (saved && saved.monthQids) || {});
  st.monthPrints = Object.assign({}, (saved && saved.monthPrints) || {});
  st.encounter = Object.assign({}, (saved && saved.encounter) || {});
  st.prizeAck = Object.assign({}, (saved && saved.prizeAck) || {});
  // `creditSum` is the fractional marks total and is younger than the binary
  // `correct` count. An honestly accumulated creditSum can never sit below
  // 0.95 × correct — every question in that count scored at least 0.95 — so
  // anything lower is history the counter never saw, and it is seeded from the
  // binary count once. Without this, every question answered before the
  // fractional counter existed reads as WRONG for the rest of the account's life.
  const sc = Number(st.stats.creditSum) || 0, sb = st.stats.correct | 0;
  if (sc < sb * 0.95) st.stats.creditSum = Math.min(st.stats.marked | 0, sb);
  return st;
}

async function progressInit() {
  if (!currentUser || !db) { progress = null; return; }
  try {
    const s = await getDoc(doc(db, "users", currentUser.uid, SETTINGS_COL, "progress"));
    progress = progressHydrate(s.exists() ? s.data() : null);
  } catch (e) {
    console.warn("progress load", e);
    progress = progressHydrate(null);
  }
  progressRolloverMonth();
}

function progressOnSignOut() {
  progress = null;
  if (_progressSaveTimer) { clearTimeout(_progressSaveTimer); _progressSaveTimer = null; }
  if (_progressPublishTimer) { clearTimeout(_progressPublishTimer); _progressPublishTimer = null; }
}

// Writes coalesce: a burst of marking (a photo answer marks every part at once)
// would otherwise be one document write per part.
function progressSave() {
  if (!progress || !currentUser || !db) return;
  progress.updatedAt = new Date().toISOString();
  if (_progressSaveTimer) clearTimeout(_progressSaveTimer);
  _progressSaveTimer = setTimeout(() => {
    _progressSaveTimer = null;
    setDoc(doc(db, "users", currentUser.uid, SETTINGS_COL, "progress"), progress)
      .catch(e => console.warn("progress save", e));
  }, 600);
  progressPublish();
}

// The teacher's half. Counts only — a student's own answers stay in their tree.
function progressPublish() {
  if (!progress || !currentUser || currentUser.role !== "student" || !db) return;
  if (_progressPublishTimer) clearTimeout(_progressPublishTimer);
  _progressPublishTimer = setTimeout(() => {
    _progressPublishTimer = null;
    const st = progress.stats || {};
    const marked = st.marked | 0;
    // `correct` is a valid lower bound on creditSum, so the higher of the two is
    // the honest figure whichever counter started first.
    const credit = Math.max(Number(st.creditSum) || 0, st.correct | 0);
    setDoc(doc(db, PROGRESS_COL, currentUser.uid), {
      uid: currentUser.uid,
      name: currentUser.displayName || currentUser.email || "Student",
      level: currentUser.level || "",
      marked,
      correct: st.correct | 0,
      creditSum: Math.round(credit * 100) / 100,
      accuracy: marked ? Math.round((credit / marked) * 100) : null,
      streak: (progress.streak && progress.streak.count) | 0,
      monthKey: progress.monthKey || null,
      monthQ: progress.monthQ | 0,
      papersQ: progress.papersQ | 0,
      pace: progress.pace ? { n: progress.pace.n | 0, ok: progress.pace.ok | 0, sumMs: progress.pace.sumMs | 0 } : null,
      updatedAt: new Date().toISOString()
    }, { merge: true }).catch(e => console.warn("progress publish", e));
  }, 1500);
}

// The teacher's class-wide read, used by the Usage dashboard.
let _progressClassRows = null;
async function progressFetchClass(force) {
  if (_progressClassRows && !force) return _progressClassRows;
  if (!db) return [];
  try {
    const snap = await getDocs(collection(db, PROGRESS_COL));
    const retired = await _getRetiredUids();
    const rows = [];
    snap.forEach(d => { const r = d.data(); if (r && r.uid && !retired.has(r.uid)) rows.push(r); });
    _progressClassRows = rows;
    return rows;
  } catch (e) { console.warn("class progress read", e); return _progressClassRows || []; }
}

// ---- Day streak ---------------------------------------------------------
// A day counts once the student has marked anything at all; the run breaks the
// first day they answer nothing.
function progressNoteStreakActivity() {
  if (!progress) return;
  const s = progress.streak || (progress.streak = progressDefaults().streak);
  const today = progressToday();
  if (s.dayKey !== today) { s.dayKey = today; s.dayMarks = 0; }
  s.dayMarks = (s.dayMarks || 0) + 1;
  if (s.lastDay !== today) {
    s.count = (s.lastDay === progressYesterday()) ? (s.count || 0) + 1 : 1;
    s.lastDay = today;
    s.best = Math.max(s.best || 0, s.count);
  }
}

// ---- Answer pace --------------------------------------------------------
// Measured, reported to the teacher, and ranked on by nothing. It is one of the
// prompts on the Activity view — an answer fired off in under fifteen seconds
// was not read — and it is deliberately not a score.
function progressNotePace(ms, minMs) {
  if (!progress) return;
  const now = Date.now();
  let p = progress.pace;
  if (!p || typeof p !== "object") p = progress.pace = { n: 0, ok: 0, sumMs: 0, lastAt: 0 };
  const clocked = ms > 0 ? Math.round(ms) : (p.lastAt ? now - p.lastAt : 0);
  p.lastAt = now;
  if (clocked <= 0 || clocked > PACE_MAX_MS) return;   // nobody was at the keyboard
  p.n = (p.n | 0) + 1;
  p.sumMs = (p.sumMs | 0) + clocked;
  if (clocked >= Math.max(1000, minMs | 0)) p.ok = (p.ok | 0) + 1;
}

// A small, stable fingerprint of a written answer (letters and digits only).
// Empty for a blank or very short answer — a multiple-choice pick is not
// evidence of anything — so those count on the unique-question rule alone.
function progressAnswerHash(text) {
  const s = String(text || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  if (s.length < 4) return "";
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(h, 31) + s.charCodeAt(i)) | 0;
  return "p" + (h >>> 0).toString(36);
}

function progressRolloverMonth() {
  if (!progress) return;
  const key = progressMonthKey();
  if (progress.monthKey === key) return;
  progress.lastMonthKey = progress.monthKey || null;
  progress.lastMonthQ = progress.monthQ | 0;
  progress.monthKey = key;
  progress.monthQ = 0;
  progress.monthQids = {};
  progress.monthPrints = {};
}

// One question counts ONCE a month, and an answer word-for-word identical to one
// already submitted this month does not count again.
function progressNoteUniqueQuestion(qid, answerText) {
  qid = String(qid || "");
  if (!progress || !qid) return;
  progressRolloverMonth();
  if (progress.monthQids[qid]) return;
  const print = progressAnswerHash(answerText);
  if (print) {
    if (progress.monthPrints[print]) return;
    progress.monthPrints[print] = 1;
  }
  progress.monthQids[qid] = 1;
  progress.monthQ = (progress.monthQ || 0) + 1;
}

// ---- The one hook every marking path calls ------------------------------
// `score` out of `total`, so a part-right written answer is worth part of a mark.
function progressOnMarked(q, score, total, opts = {}) {
  if (!progress || !q || !total) return;
  const credit = Math.max(0, Math.min(1, (Number(score) || 0) / total));
  const qid = String(q.id || "");
  const seen = progress.seenQ || (progress.seenQ = {});
  if (!opts.simulated && qid) seen[qid] = (seen[qid] || 0) + 1;

  progress.stats.marked++;
  if (credit >= 0.95) progress.stats.correct++;
  progress.stats.creditSum = Math.round(((Number(progress.stats.creditSum) || 0) + credit) * 100) / 100;

  if (!opts.simulated) {
    try { progressNoteStreakActivity(); } catch (_) {}
    try { progressNotePace(0, PACE_MIN_PRACTICE_MS); } catch (_) {}
    const before = progress.monthQ || 0;
    progressNoteUniqueQuestion(qid, opts.answerText);
    if ((progress.monthQ || 0) > before) {
      try { commNoteEncounterProgress(q); } catch (_) {}
      if (isPastPaperQuestion(q)) progress.papersQ = (progress.papersQ || 0) + 1;
      try { commQuestRunCapture(q, credit); } catch (_) {}
    }
  }
  progressSave();
}

// ---- Carried over from the deleted game layer ---------------------------
// These four are not game code; they merely lived inside it.

// A past-year exam-paper question is one filed under a PSLE category.
function isPastPaperQuestion(q) {
  const cats = (typeof qCategoryList === 'function') ? qCategoryList(q)
    : [((typeof normalizeCategoryValue === 'function' ? normalizeCategoryValue(q && q.category) : (q && q.category)) || '')];
  return cats.some(c => /^PSLE\b/i.test(String(c).trim()));
}

// Accounts retired by an admin password reset: this shared map (written by the
// admin, readable like the other admin settings docs) hides any that survive.
let _retiredUidsCache = null;
async function _getRetiredUids() {
  if (_retiredUidsCache) return _retiredUidsCache;
  const owner = (currentUser && currentUser.role === 'admin') ? currentUser.uid : adminUid;
  const out = new Set();
  if (owner) {
    try {
      const s = await getDoc(doc(db, 'users', owner, SETTINGS_COL, 'retiredAccounts'));
      const uids = (s.exists() && s.data().uids) || {};
      Object.keys(uids).forEach(u => { if (uids[u]) out.add(u); });
    } catch (e) { console.warn('retired map read', e); }
  }
  _retiredUidsCache = out;
  return out;
}

// A student may flag at most this many questions per calendar day, to deter
// spamming the review queue.
const FLAG_DAILY_LIMIT = 10;
// Best-effort: returns 0 on a read error so a transient failure never blocks a
// genuine flag.
async function _flagsTodayCount() {
  try {
    if (!currentUser || !currentUser.uid) return 0;
    const start = new Date(); start.setHours(0, 0, 0, 0);
    const snap = await getDocs(query(collection(db, FLAGS_COL), where('flaggedByUid', '==', currentUser.uid)));
    let n = 0;
    snap.forEach(doc => {
      const a = doc.data(); if (!a) return;
      const t = a.timestamp ? (a.timestamp.toDate ? a.timestamp.toDate() : new Date(a.timestamp)) : null;
      if (t && t >= start) n++;
    });
    return n;
  } catch (e) { console.warn('flag count read failed', e); return 0; }
}

function _todayKey() { return progressToday(); }

async function _scaleDownDataUrl(dataUrl, maxSide) {
  const img = await _loadImageEl(dataUrl);
  const w = img.naturalWidth || img.width, h = img.naturalHeight || img.height;
  if (Math.max(w, h) <= maxSide) return dataUrl;
  const s = maxSide / Math.max(w, h);
  const cw = Math.max(1, Math.round(w * s)), ch = Math.max(1, Math.round(h * s));
  const c = document.createElement('canvas'); c.width = cw; c.height = ch;
  c.getContext('2d').drawImage(img, 0, 0, cw, ch);
  return c.toDataURL('image/png');
}

// Where a student lands, and where "practise" means, for each role.
function isAdminPreview() { return !!currentUser && currentUser.role === 'admin'; }
function homePageFor() { return isAdminPreview() ? 'create' : 'home'; }
function practicePageFor() { return isAdminPreview() ? 'practice' : 'quickpractice'; }

// =====================================================================
// COMMUNITY BOARD  +  ENCOUNTER QUESTS
//   community       — bulletin-board feed (admin posts auto-approved,
//                     student messages start 'pending' until approved)
//   encounterQuests — timed surprise quests; first student to finish N
//                     questions before the timer ends wins a $10 voucher
//                     (delivered through the normal prizeClaims flow)
// =====================================================================
let _commPosts = [], _commQuests = [];
let _commUnsub = null, _questUnsub = null, _questTick = null, _questSeen = {};
let _commImg = {};                 // dataURL keyed by file-input id
let _questMode = 'auto';            // admin authoring mode: 'auto' | 'race' | 'score'
let _questPick = new Set();         // selected question ids (score mode)
let _questRun = null;              // active score-quest run for this student
let _questOffered = {};            // guards the win overlay per quest id
let _questScorePub = {};           // debounce timers for score publishing

function _commCanFirestore() { return !!(db && currentUser); }
function _commTypeLabel(t) { return ({ news: 'News', guidance: 'Guidance', photo: 'Photo', update: 'Update' })[t] || 'Update'; }

// ---- identity: avatars + status ----------------------------------------
// Mr Chung (the teacher) always posts as the owl professor with the top
// "Polymath" rank. Students pick an animal avatar and climb the ranks by
// posting more — the rank is computed live from their approved-post count.
const COMM_ADMIN_AVATAR = '🦉';
const COMM_ADMIN_NAME    = 'Mr Chung';
const COMM_ADMIN_STATUS  = 'Polymath';
const COMM_AVATARS = ['🦊','🐼','🦁','🐯','🐨','🐸','🐧','🦄','🐢','🐬','🦋','🐝','🦖','🐙','🐺','🐰'];
const COMM_DEFAULT_AVATAR = '🦊';
// Ranks unlocked by number of approved posts (most-posts-first).
const COMM_STATUS_TIERS = [
  { min: 30, label: 'Luminary' },
  { min: 18, label: 'Sage' },
  { min: 10, label: 'Scholar' },
  { min: 5,  label: 'Explorer' },
  { min: 1,  label: 'Contributor' },
  { min: 0,  label: 'Newcomer' },
];
function _isSuperAdmin() { return !!(currentUser && currentUser.email === SUPER_ADMIN_EMAIL); }
function _commStudentStatus(count) {
  for (const t of COMM_STATUS_TIERS) if (count >= t.min) return t.label;
  return 'Newcomer';
}
// Posts needed to reach the next rank (null once at the top).
function _commNextTier(count) {
  const higher = COMM_STATUS_TIERS.filter(t => t.min > count).sort((a, b) => a.min - b.min);
  return higher.length ? { label: higher[0].label, need: higher[0].min - count } : null;
}
// How many approved posts a student has on the board right now.
function _commPostCount(uid) {
  if (!uid) return 0;
  return _commPosts.filter(p => p.authorUid === uid && p.status === 'approved' && p.authorRole !== 'admin').length;
}
function _commMyAvatar() { return (currentUser && currentUser.avatar) || COMM_DEFAULT_AVATAR; }
function _commTimeAgo(iso) {
  const t = new Date(iso).getTime(); if (!t) return '';
  const s = Math.floor((Date.now() - t) / 1000);
  if (s < 60) return 'just now';
  if (s < 3600) return Math.floor(s / 60) + 'm ago';
  if (s < 86400) return Math.floor(s / 3600) + 'h ago';
  const d = Math.floor(s / 86400);
  return d < 7 ? d + 'd ago' : new Date(iso).toLocaleDateString();
}
function _fmtCountdown(ms) {
  if (ms < 0) ms = 0;
  const s = Math.floor(ms / 1000), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;
  return (h > 0 ? h + ':' : '') + String(m).padStart(2, '0') + ':' + String(ss).padStart(2, '0');
}
// Human-friendly elapsed time (e.g. "2m 5s") for fastest-to-finish quests.
function _fmtDuration(ms) {
  const s = Math.max(0, Math.round((Number(ms) || 0) / 1000));
  const m = Math.floor(s / 60), ss = s % 60;
  return m ? (m + 'm ' + ss + 's') : (ss + 's');
}

// ---- image attach: downscale client-side, upload to Storage (inline fallback)
function commPreviewImg(input, prevId) {
  const file = input.files && input.files[0];
  const prev = document.getElementById(prevId);
  if (!file) { if (prev) { prev.style.display = 'none'; prev.src = ''; } _commImg[input.id] = null; return; }
  _commDownscale(file, 1280, 0.82).then(dataUrl => {
    _commImg[input.id] = dataUrl;
    if (prev) { prev.src = dataUrl; prev.style.display = ''; }
  }).catch(() => showToast('Could not read that image', 'error'));
}
function _commDownscale(file, maxDim, quality) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        const scale = Math.min(1, maxDim / Math.max(w, h));
        w = Math.round(w * scale); h = Math.round(h * scale);
        const c = document.createElement('canvas'); c.width = w; c.height = h;
        c.getContext('2d').drawImage(img, 0, 0, w, h);
        res(c.toDataURL('image/jpeg', quality));
      };
      img.onerror = rej; img.src = r.result;
    };
    r.onerror = rej; r.readAsDataURL(file);
  });
}
async function _commUploadImage(dataUrl, id) {
  if (!dataUrl) return '';
  try {
    const refp = storageRef(storage, 'community/' + id + '.jpg');
    await uploadString(refp, dataUrl, 'data_url');
    return await getDownloadURL(refp);
  } catch (e) {
    console.warn('community image upload failed, inlining', e);
    return dataUrl.length < 900000 ? dataUrl : '';   // small images can live in the doc
  }
}
function _commClearImg(inputId, prevId) {
  _commImg[inputId] = null;
  const i = document.getElementById(inputId); if (i) i.value = '';
  const p = document.getElementById(prevId); if (p) { p.style.display = 'none'; p.src = ''; }
}

// ---- posting -----------------------------------------------------------
async function commAdminPost() {
  if (!_isAdmin() || !_commCanFirestore()) return;
  const type = (document.getElementById('commPostType').value) || 'news';
  const title = (document.getElementById('commPostTitle').value || '').trim();
  const text = (document.getElementById('commPostText').value || '').trim();
  const pin = !!document.getElementById('commPostPin').checked;
  const imgData = _commImg['commPostImg'];
  if (!text && !title && !imgData) { showToast('Add some text or an image', 'error'); return; }
  showToast('Posting…', 'info');
  try {
    const id = currentUser.uid + '_' + Date.now();
    const imageUrl = imgData ? await _commUploadImage(imgData, id) : '';
    await setDoc(doc(db, COMMUNITY_COL, id), {
      type, title, text, imageUrl,
      authorUid: currentUser.uid,
      authorName: _isSuperAdmin() ? COMM_ADMIN_NAME : (currentUser.name || 'Teacher'),
      authorRole: 'admin', authorAvatar: COMM_ADMIN_AVATAR, authorStatus: COMM_ADMIN_STATUS,
      status: 'approved', pinned: pin, createdAt: new Date().toISOString()
    });
    document.getElementById('commPostText').value = '';
    document.getElementById('commPostTitle').value = '';
    document.getElementById('commPostPin').checked = false;
    _commClearImg('commPostImg', 'commPostImgPrev');
    showToast('Posted to the board ✓', 'success');
  } catch (e) { console.warn('admin post', e); showToast('Could not post — check your connection', 'error'); }
}
async function commStudentPost() {
  if (!_commCanFirestore()) { showToast('Sign in to post', 'error'); return; }
  const text = (document.getElementById('commMsgText').value || '').trim();
  const imgData = _commImg['commMsgImg'];
  if (!text && !imgData) { showToast('Write a message or attach an image', 'error'); return; }
  showToast('Sending…', 'info');
  try {
    const id = currentUser.uid + '_' + Date.now();
    const imageUrl = imgData ? await _commUploadImage(imgData, id) : '';
    await setDoc(doc(db, COMMUNITY_COL, id), {
      type: 'message', title: '', text, imageUrl,
      authorUid: currentUser.uid, authorName: currentUser.name || 'Student', authorRole: 'student',
      authorAvatar: _commMyAvatar(),
      status: 'pending', pinned: false, createdAt: new Date().toISOString()
    });
    document.getElementById('commMsgText').value = '';
    _commClearImg('commMsgImg', 'commMsgImgPrev');
    showToast('Sent for approval — the teacher will review it 👍', 'success');
  } catch (e) { console.warn('student post', e); showToast('Could not send — check your connection', 'error'); }
}
async function commApprove(id) { if (!_isAdmin()) return; try { await updateDoc(doc(db, COMMUNITY_COL, id), { status: 'approved', approvedAt: new Date().toISOString() }); showToast('Approved — now public ✓', 'success'); } catch (e) { console.warn(e); showToast('Could not approve', 'error'); } }
async function commReject(id) { if (!_isAdmin()) return; if (!confirm('Reject and remove this message?')) return; commDelete(id); }
async function commPin(id, val) { if (!_isAdmin()) return; try { await updateDoc(doc(db, COMMUNITY_COL, id), { pinned: (val === true || val === 'true') }); } catch (e) { console.warn(e); } }
async function commDelete(id) { if (!_isAdmin()) return; try { await deleteDoc(doc(db, COMMUNITY_COL, id)); showToast('Removed', 'success'); } catch (e) { console.warn(e); showToast('Could not remove', 'error'); } }

// ---- encounter quests --------------------------------------------------
// Two authoring modes:
//   race  — first student to finish N fresh questions wins (mode:'race')
//   score — admin hand-picks the exact questions; the student with the
//           highest percentage when the timer ends wins (mode:'score')
function commQuestMode(mode) {
  _questMode = (mode === 'score' || mode === 'race') ? mode : 'auto';
  document.querySelectorAll('#commTabQuest .comm-mode-btn').forEach(b =>
    b.classList.toggle('active', b.dataset.qmode === _questMode));
  const auto = document.getElementById('commQuestAutoFields');
  const race = document.getElementById('commQuestRaceFields');
  const score = document.getElementById('commQuestScoreFields');
  if (auto) auto.style.display = _questMode === 'auto' ? '' : 'none';
  if (race) race.style.display = _questMode === 'race' ? '' : 'none';
  if (score) score.style.display = _questMode === 'score' ? '' : 'none';
  if (_questMode === 'score') { commPopulateQuestFilters(); commRenderQuestPicker(); }
}
// Fill the picker's Topic / Source / Concept dropdowns from the live bank,
// reusing the same helpers the worksheet builder uses.
function commPopulateQuestFilters() {
  const topicSel = document.getElementById('cqFilterTopic');
  if (topicSel) {
    const prev = topicSel.value;
    const topics = [...new Set((questionBank || []).flatMap(q => qTopicList(q)))].sort();
    topicSel.innerHTML = '<option value="">All Topics</option>';
    topics.forEach(t => { const o = document.createElement('option'); o.value = t; o.textContent = t; topicSel.appendChild(o); });
    if (prev && topics.includes(prev)) topicSel.value = prev;
  }
  const srcSel = document.getElementById('cqFilterSource');
  if (srcSel) {
    const prev = srcSel.value;
    const sources = [...new Set((questionBank || []).map(questionSource).filter(Boolean))].sort();
    srcSel.innerHTML = '<option value="">All Sources</option>';
    sources.forEach(s => { const o = document.createElement('option'); o.value = s; o.textContent = s; srcSel.appendChild(o); });
    if (prev && sources.includes(prev)) srcSel.value = prev;
  }
  const conSel = document.getElementById('cqFilterConcept');
  if (conSel) {
    const prev = conSel.value;
    const counts = new Map();
    (questionBank || []).forEach(q => qConceptLabels(q).forEach(c => {
      const k = c.toLowerCase();
      const rec = counts.get(k) || { label: c, n: 0 };
      rec.n++; counts.set(k, rec);
    }));
    const concepts = [...counts.values()].sort((a, b) => a.label.localeCompare(b.label));
    conSel.innerHTML = '<option value="">All Concepts</option>';
    concepts.forEach(c => {
      const o = document.createElement('option');
      o.value = c.label; o.textContent = '🏷 ' + c.label + ' (' + c.n + ')';
      conSel.appendChild(o);
    });
    if (prev && concepts.some(c => c.label === prev)) conSel.value = prev;
  }
}
// Full question-bank picker — same filtering, cards and expandable preview as
// the worksheet builder, but writing into the encounter-quest selection set.
function commRenderQuestPicker() {
  const grid = document.getElementById('commQuestPickList'); if (!grid) return;
  const levelFilter = document.getElementById('cqFilterLevel')?.value || '';
  const topicFilter = document.getElementById('cqFilterTopic')?.value || '';
  const catFilter = document.getElementById('cqFilterCategory')?.value || '';
  const sourceFilter = document.getElementById('cqFilterSource')?.value || '';
  const formatFilter = document.getElementById('cqFilterFormat')?.value || '';
  const conceptFilter = (document.getElementById('cqFilterConcept')?.value || '').toLowerCase();
  const searchRaw = (document.getElementById('cqSearch')?.value || '').trim().toLowerCase();

  const filtered = (questionBank || []).filter(q => {
    if (!q || q.id == null) return false;
    if (!qInSyllabus(q)) return false;             // retired topics: PSLE papers only
    if (topicFilter && !qMatchesTopic(q, topicFilter)) return false;
    if (catFilter && !qMatchesCategory(q, catFilter)) return false;
    if (sourceFilter && questionSource(q) !== sourceFilter) return false;
    if (formatFilter === 'mcq' && !qpHasMcq(q)) return false;
    if (formatFilter === 'written' && !qpHasWritten(q)) return false;
    if (!qMatchesConceptLabel(q, conceptFilter)) return false;
    if (levelFilter && getTopicLevel(q.topic || '') !== levelFilter) return false;
    if (searchRaw) { if (!extractQuestionSearchText(q).includes(searchRaw)) return false; }
    return true;
  });

  if (!filtered.length) {
    grid.innerHTML = '<div class="empty-state"><h3>No questions found</h3><p>Try adjusting your filters</p></div>';
    _updatePickCount();
    return;
  }
  grid.innerHTML = filtered.map(q => {
    const id = String(q.id);
    const checked = _questPick.has(id);
    const qLevel = getTopicLevel(q.topic || '');
    const qCategory = normalizeCategoryValue(q.category);
    const qSource = questionSource(q);
    return '<div class="ws-q-card' + (checked ? ' selected' : '') + '" data-qid="' + id + '" onclick="commPickCardClick(\'' + id + '\', event)" style="cursor:pointer;">' +
      '<div class="ws-q-top">' +
        '<input type="checkbox" ' + (checked ? 'checked' : '') + ' onchange="commTogglePick(\'' + id + '\', this.checked)">' +
        '<div class="ws-q-info">' +
          '<div class="ws-q-title">' + escapeHtml(q.title || ('Question ' + id)) + '</div>' +
          '<div class="ws-q-meta">' +
            '<span class="qb-tag category">' + escapeHtml(qCategory) + '</span>' +
            '<span class="qb-tag topic">' + escapeHtml(q.topic || '') + '</span>' +
            qSecondaryTagsHtml(q) +
            '<span class="qb-tag">' + escapeHtml(qLevel) + '</span>' +
            (qSource ? '<span class="qb-tag source" title="' + escapeHtml(qSource) + '">' + escapeHtml(qSource) + '</span>' : '') +
          '</div>' +
        '</div>' +
        '<button class="ws-q-expand-btn" onclick="event.stopPropagation();commTogglePickPreview(\'' + id + '\', this)" title="Preview question">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>' +
        '</button>' +
      '</div>' +
      '<div class="ws-q-preview" id="cqPreview_' + id + '"></div>' +
    '</div>';
  }).join('');
  _updatePickCount();
}
function commTogglePickPreview(id, btn) {
  const previewEl = document.getElementById('cqPreview_' + id);
  if (!previewEl) return;
  if (previewEl.classList.contains('open')) {
    previewEl.classList.remove('open'); btn.classList.remove('expanded');
  } else {
    if (!previewEl.dataset.rendered) { previewEl.innerHTML = renderQuestionPreviewHtml(id); previewEl.dataset.rendered = '1'; }
    previewEl.classList.add('open'); btn.classList.add('expanded');
  }
}
function commTogglePick(id, on) {
  id = String(id);
  if (on) _questPick.add(id); else _questPick.delete(id);
  const card = document.querySelector('#commQuestPickList .ws-q-card[data-qid="' + id + '"]');
  if (card) { card.classList.toggle('selected', on); const cb = card.querySelector('input[type="checkbox"]'); if (cb) cb.checked = on; }
  _updatePickCount();
}
function commPickCardClick(id, event) {
  if (event.target.closest('.ws-q-expand-btn') || event.target.closest('.ws-q-preview')) return;
  if (event.target.tagName === 'INPUT') return;   // checkbox handles itself
  commTogglePick(id, !_questPick.has(String(id)));
}
function commClearPick() { _questPick.clear(); commRenderQuestPicker(); }
function _updatePickCount() { const el = document.getElementById('commQuestPickCount'); if (el) el.textContent = _questPick.size; }

async function commCreateQuest() {
  if (!_isAdmin() || !_commCanFirestore()) return;
  const title = (document.getElementById('commQuestTitle').value || '').trim() || '⚡ Encounter Quest';
  const desc = (document.getElementById('commQuestDesc').value || '').trim();
  const hours = Math.max(0.25, parseFloat(document.getElementById('commQuestHours').value) || 3);
  const now = Date.now(), id = 'q_' + now;
  const base = {
    title, desc, prize: '$10 voucher',
    startAt: new Date(now).toISOString(), endAt: new Date(now + hours * 3600000).toISOString(), hours,
    status: 'active', winnerUid: '', winnerName: '', winnerAt: '',
    createdBy: currentUser.uid, createdAt: new Date().toISOString()
  };
  let payload, feedText;
  if (_questMode === 'auto') {
    const winSel = document.getElementById('commQuestWin');
    const win = ['highest', 'fastest', 'graded'].includes(winSel && winSel.value) ? winSel.value : 'highest';
    const format = (document.getElementById('commQuestFormat').value === 'written') ? 'written' : 'mcq';
    const count = Math.max(1, parseInt(document.getElementById('commQuestAutoCount').value, 10) || 5);
    const topic = (document.getElementById('commQuestAutoTopic').value || '').trim();
    payload = Object.assign({ mode: 'auto', win, format, count, total: count, topic: topic || '', scores: {} }, base);
    const fmtLabel = format === 'mcq' ? 'MCQ' : 'open-ended';
    const winLabel = win === 'fastest' ? 'fastest to finish wins' : win === 'graded' ? 'Mr Chung picks the winner' : 'highest score wins';
    feedText = (desc ? desc + '\n\n' : '') + 'Tap “Attempt quest now!” — you\'ll get ' + count + ' ' + fmtLabel +
      ' question' + (count === 1 ? '' : 's') + (topic ? ' on ' + topic : '') + ' chosen just for you (new ones first, then any you found tricky before). ' +
      winLabel.charAt(0).toUpperCase() + winLabel.slice(1) + ' — reward: $10 voucher!';
  } else if (_questMode === 'score') {
    const ids = Array.from(_questPick);
    if (!ids.length) { showToast('Pick at least one question for a Highest-score quest', 'error'); return; }
    payload = Object.assign({ mode: 'score', questionIds: ids, total: ids.length, count: ids.length, scores: {} }, base);
    feedText = (desc ? desc + '\n\n' : '') + 'Tap “Start quest”, answer all ' + ids.length + ' questions, and the student with the highest percentage when the timer ends wins a $10 voucher!';
  } else {
    const count = Math.max(1, parseInt(document.getElementById('commQuestCount').value, 10) || 10);
    const topic = (document.getElementById('commQuestTopic').value || '').trim();
    payload = Object.assign({ mode: 'race', count, topic: topic || '' }, base);
    feedText = (desc ? desc + '\n\n' : '') + 'Finish ' + count + ' questions' + (topic ? ' on ' + topic : '') + ' before the timer runs out — the first to finish wins a $10 voucher!';
  }
  try {
    await setDoc(doc(db, QUESTS_COL, id), payload);
    // announce it on the feed too (pinned)
    await setDoc(doc(db, COMMUNITY_COL, 'quest_' + id), {
      type: 'update', title: '⚡ New Encounter Quest: ' + title,
      text: feedText,
      imageUrl: '', authorUid: currentUser.uid,
      authorName: _isSuperAdmin() ? COMM_ADMIN_NAME : (currentUser.name || 'Teacher'),
      authorRole: 'admin', authorAvatar: COMM_ADMIN_AVATAR, authorStatus: COMM_ADMIN_STATUS,
      status: 'approved', pinned: true, createdAt: new Date().toISOString()
    });
    document.getElementById('commQuestTitle').value = '';
    document.getElementById('commQuestDesc').value = '';
    if (_questMode === 'score') commClearPick();
    showToast('⚡ Quest launched — students see it now!', 'success');
  } catch (e) { console.warn('create quest', e); showToast('Could not launch the quest', 'error'); }
}
async function commEndQuest(id) {
  if (!_isAdmin()) return;
  if (!confirm('End this quest now?')) return;
  try { await updateDoc(doc(db, QUESTS_COL, id), { status: 'ended', endedAt: new Date().toISOString() }); } catch (e) { console.warn(e); }
}
function _activeQuests() {
  const now = Date.now();
  return _commQuests.filter(q => q.status === 'active' && !q.winnerUid && new Date(q.endAt).getTime() > now);
}
function _questProgress(q) { return (progress && progress.encounter && progress.encounter[q._id]) || 0; }

// Count a freshly-answered unique question toward any live quest. Called from
// progressOnMarked only when a genuinely new unique question was recorded.
function commNoteEncounterProgress(q) {
  if (!progress || !currentUser || currentUser.role !== 'student') return;
  // Only "first to finish" (race) quests are won by answering questions anywhere.
  // Score and auto quests are resolved via their own run flow, not this counter.
  const active = _activeQuests().filter(quest => quest.mode === 'race' || !quest.mode);
  if (!active.length) return;
  progress.encounter = progress.encounter || {};
  active.forEach(quest => {
    if (quest.topic && q && q.topic && String(q.topic).toLowerCase() !== String(quest.topic).toLowerCase()) return;
    const cur = (progress.encounter[quest._id] || 0) + 1;
    progress.encounter[quest._id] = cur;
    if (cur >= quest.count) commTryWinQuest(quest);
  });
  progressSave();
  _renderQuestBanners();
}
async function commTryWinQuest(quest) {
  if (!_commCanFirestore()) return;
  progress.encounter = progress.encounter || {};
  if (progress.encounter['_tried_' + quest._id]) return;     // attempt the race once
  progress.encounter['_tried_' + quest._id] = 1; progressSave();
  try {
    const snap = await getDoc(doc(db, QUESTS_COL, quest._id));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) {
      if (d.winnerUid !== currentUser.uid) showToast('⚡ ' + (d.winnerName || 'Another student') + ' finished first — watch out for the next quest!', 'info');
      return;
    }
    if (d.status !== 'active' || new Date(d.endAt).getTime() < Date.now()) { showToast('That quest already ended.', 'info'); return; }
    await updateDoc(doc(db, QUESTS_COL, quest._id), {
      winnerUid: currentUser.uid, winnerName: currentUser.name || 'Student',
      winnerAt: new Date().toISOString(), status: 'ended'
    });
    commOfferQuestPrize(quest);
  } catch (e) { console.warn('win quest', e); }
}
function commOfferQuestPrize(quest) {
  _questOffered[quest._id] = 1;
  const isScore = quest.mode === 'score';
  const isAuto = quest.mode === 'auto';
  const myScore = (isScore || isAuto) && quest.scores ? quest.scores[currentUser.uid] : null;
  const myPct = myScore ? Math.round(myScore.pct || 0) : null;
  const myTime = myScore && myScore.elapsedMs != null ? myScore.elapsedMs : (quest.winnerTimeMs != null ? quest.winnerTimeMs : null);
  let how;
  if (isAuto) {
    how = quest.win === 'fastest' ? ('fastest to finish' + (myTime != null ? ' in ' + _fmtDuration(myTime) : '') + '!')
        : quest.win === 'graded' ? 'your teacher picked you as the winner!'
        : 'top scorer' + (myPct != null ? ' with ' + myPct + '%' : '') + '!';
  } else if (isScore) {
    how = 'top scorer' + (myPct != null ? ' with ' + myPct + '%' : '') + '!';
  } else {
    how = 'first to finish ' + quest.count + ' questions!';
  }
  showToast('🏆 You won "' + (quest.title || 'the Flash Quiz') + '" — ' + how, 'success');
}

// ---- score-mode quest run (student answers the admin-picked questions) ----
function commStartQuestRun(questId) {
  const quest = _commQuests.find(q => q._id === questId);
  if (!quest || quest.mode !== 'score') return;
  if (!(currentUser && currentUser.role === 'student')) return;
  const left = new Date(quest.endAt).getTime() - Date.now();
  if (quest.winnerUid || quest.status === 'ended' || left <= 0) { showToast('That quest has ended.', 'info'); return; }
  const ids = Array.isArray(quest.questionIds) ? quest.questionIds.map(String) : [];
  const byId = {}; (Array.isArray(questionBank) ? questionBank : []).forEach(q => { if (q && q.id != null) byId[String(q.id)] = q; });
  const queue = ids.map(id => byId[id]).filter(Boolean);
  if (!queue.length) { showToast('These quest questions aren\'t available on your device yet — try again shortly.', 'error'); return; }
  _questRun = { questId: quest._id, ids, total: ids.length, best: {} };
  qpQueue = queue;
  qpIndex = -1;
  qpAnswered = 0;
  qpSessionResults = [];
  showToast('⚡ Quest started — answer them all, your best % counts!', 'success');
  navigateTo('quickpractice');
  preloadQueueImages(qpQueue).then(() => loadNextQpQuestion()).catch(() => loadNextQpQuestion());
}
// ---- auto-fed quest run: the system picks each student's questions ----
// Priority: questions the student hasn't done yet, then ones they previously
// struggled with (best score < 50%), then anything else to fill the count.
async function commStartAutoQuest(questId) {
  const quest = _commQuests.find(q => q._id === questId);
  if (!quest || quest.mode !== 'auto') return;
  if (!(currentUser && currentUser.role === 'student')) return;
  const left = new Date(quest.endAt).getTime() - Date.now();
  if (quest.winnerUid || quest.status === 'ended' || left <= 0) { showToast('That quest has ended.', 'info'); return; }
  const count = Math.max(1, quest.count || quest.total || 5);
  const format = quest.format === 'written' ? 'written' : 'mcq';
  const topic = (quest.topic || '').trim().toLowerCase();
  const pool = (Array.isArray(questionBank) ? questionBank : []).filter(q => {
    if (!q || q.id == null) return false;
    if (!qInSyllabus(q)) return false;             // not in syllabus → practice-excluded
    if (format === 'mcq' ? !qpHasMcq(q) : !qpHasWritten(q)) return false;
    if (topic && String(q.topic || '').toLowerCase() !== topic) return false;
    return qWithinStudentLevel(q); // never quest a student above their level
  });
  if (!pool.length) { showToast('No ' + (format === 'mcq' ? 'MCQ' : 'open-ended') + ' questions available' + (quest.topic ? ' on ' + quest.topic : '') + ' yet.', 'error'); return; }
  showToast('Picking your questions…', 'info');
  // Best recorded fraction (0–1) per question from this student's attempt log.
  const _stats = await loadAttemptStats();
  const bestByQ = {};
  Object.keys(_stats).forEach(id => { bestByQ[id] = _stats[id].best; });
  const shuffle = arr => { for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [arr[i], arr[j]] = [arr[j], arr[i]]; } return arr; };
  const seen = id => bestByQ[id] !== undefined;
  const unseen = shuffle(pool.filter(q => !seen(String(q.id))));
  const struggled = pool.filter(q => seen(String(q.id)) && bestByQ[String(q.id)] < 0.5)
    .sort((a, b) => (bestByQ[String(a.id)] || 0) - (bestByQ[String(b.id)] || 0));
  const rest = shuffle(pool.filter(q => seen(String(q.id)) && bestByQ[String(q.id)] >= 0.5));
  const ordered = [];
  const add = list => list.forEach(q => { if (ordered.length < count && !ordered.some(x => String(x.id) === String(q.id))) ordered.push(q); });
  add(unseen); add(struggled); add(rest);
  const queue = ordered.slice(0, count);
  if (!queue.length) { showToast('Couldn\'t pick questions — try again shortly.', 'error'); return; }
  _questRun = { questId: quest._id, mode: 'auto', win: quest.win || 'highest', ids: queue.map(q => String(q.id)), total: queue.length, best: {}, answered: new Set(), startedAt: Date.now(), _finished: false };
  qpQueue = queue; qpIndex = -1; qpAnswered = 0; qpSessionResults = [];
  const winMsg = quest.win === 'fastest' ? 'fastest to finish wins — go!' : quest.win === 'graded' ? 'do your best, Mr Chung grades!' : 'highest score wins!';
  showToast('⚡ Quest started — ' + winMsg, 'success');
  navigateTo('quickpractice');
  preloadQueueImages(qpQueue).then(() => loadNextQpQuestion()).catch(() => loadNextQpQuestion());
}
// Called from rpgOnMarked for every real marked question. If a score-quest run
// is live and this question belongs to it, record the student's best credit
// for that question and publish a fresh percentage to Firestore (debounced).
function commQuestRunCapture(q, credit) {
  if (!_questRun || !q || q.id == null) return;
  const qid = String(q.id);
  if (!_questRun.ids.includes(qid)) return;
  const c = Math.max(0, Math.min(1, Number(credit) || 0));
  if (c > (_questRun.best[qid] || 0)) _questRun.best[qid] = c;
  _questRun.answered = _questRun.answered || new Set();
  _questRun.answered.add(qid);
  _publishQuestScore(_questRun.questId);
  // Auto quests fire a finish handler once every fed question has been answered.
  if (_questRun.mode === 'auto' && !_questRun._finished && _questRun.answered.size >= (_questRun.total || 0)) {
    _questRun._finished = true;
    _commAutoFinished(_questRun);
  }
}
function _questRunDone() { return _questRun && _questRun.answered ? _questRun.answered.size : (_questRun ? Object.keys(_questRun.best).length : 0); }
function _questRunPct() {
  if (!_questRun) return 0;
  const total = _questRun.total || 1;
  const sum = Object.values(_questRun.best).reduce((s, v) => s + v, 0);
  return Math.round((sum / total) * 100);
}
function _publishQuestScore(questId) {
  if (!_questRun || _questRun.questId !== questId || !_commCanFirestore()) return;
  if (_questScorePub[questId]) return;                     // debounce a burst of marks
  _questScorePub[questId] = setTimeout(async () => {
    _questScorePub[questId] = null;
    if (!_questRun || _questRun.questId !== questId) return;
    const total = _questRun.total || 1;
    const done = _questRunDone();
    const pct = _questRunPct();
    // Never let a partial re-attempt lower a better score already recorded.
    const prev = _commQuests.find(q => q._id === questId);
    const prevPct = prev && prev.scores && prev.scores[currentUser.uid] ? (prev.scores[currentUser.uid].pct || 0) : -1;
    if (pct < prevPct) return;
    const entry = { name: currentUser.name || 'Student', pct, done, total, at: new Date().toISOString() };
    if (_questRun.mode === 'auto') {
      entry.win = _questRun.win;
      if (_questRun.startedAt) entry.elapsedMs = Date.now() - _questRun.startedAt;
      entry.finished = done >= total;
    }
    try {
      await updateDoc(doc(db, QUESTS_COL, questId), { ['scores.' + currentUser.uid]: entry });
    } catch (e) { console.warn('publish quest score', e); }
  }, 800);
}
// Auto quest: the student just answered the last fed question.
async function _commAutoFinished(run) {
  const quest = _commQuests.find(q => q._id === run.questId) || { _id: run.questId };
  const total = run.total || 1;
  const pct = _questRunPct();
  const elapsedMs = run.startedAt ? Date.now() - run.startedAt : 0;
  if (_commCanFirestore()) {
    const prev = _commQuests.find(q => q._id === run.questId);
    const prevPct = prev && prev.scores && prev.scores[currentUser.uid] ? (prev.scores[currentUser.uid].pct || 0) : -1;
    // For "highest", keep a better earlier score; always record for the others.
    if (!(run.win === 'highest' && pct < prevPct)) {
      try {
        await updateDoc(doc(db, QUESTS_COL, run.questId), {
          ['scores.' + currentUser.uid]: { name: currentUser.name || 'Student', pct, done: total, total, win: run.win, elapsedMs, finished: true, at: new Date().toISOString() }
        });
      } catch (e) { console.warn('auto finish publish', e); }
    }
  }
  if (run.win === 'fastest') {
    _commClaimFastest(quest, elapsedMs, pct);
  } else if (run.win === 'graded') {
    showToast('✅ Done in ' + _fmtDuration(elapsedMs) + ' — Mr Chung will grade and pick the winner!', 'success');
  } else {
    showToast('✅ Quest complete — you scored ' + pct + '%! Highest score at the deadline wins.', 'success');
  }
}
// Fastest-to-finish: the first student to complete all their questions wins.
async function _commClaimFastest(quest, elapsedMs, pct) {
  if (!_commCanFirestore()) return;
  try {
    const snap = await getDoc(doc(db, QUESTS_COL, quest._id));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) {
      if (d.winnerUid !== currentUser.uid) showToast('⚡ ' + (d.winnerName || 'Another student') + ' finished first — watch for the next quest!', 'info');
      return;
    }
    if (d.status !== 'active' || new Date(d.endAt).getTime() < Date.now()) { showToast('That quest already ended.', 'info'); return; }
    await updateDoc(doc(db, QUESTS_COL, quest._id), {
      winnerUid: currentUser.uid, winnerName: currentUser.name || 'Student',
      winnerAt: new Date().toISOString(), winnerTimeMs: elapsedMs, winnerPct: pct, status: 'ended'
    });
    commOfferQuestPrize(Object.assign({ _id: quest._id }, d));
  } catch (e) { console.warn('claim fastest', e); }
}
// Admin resolves a score quest once the timer is up: highest percentage wins
// (ties broken by more questions done, then earliest submission).
async function commAwardTopScorer(questId) {
  if (!_isAdmin() || !_commCanFirestore()) return;
  try {
    const snap = await getDoc(doc(db, QUESTS_COL, questId));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) { showToast('A winner is already set.', 'info'); return; }
    const scores = d.scores || {};
    const entries = Object.keys(scores).map(uid => Object.assign({ uid }, scores[uid]));
    if (!entries.length) { showToast('No students attempted this quest — nothing to award.', 'info'); return; }
    let top;
    if (d.win === 'fastest') {
      // Fastest to finish: only students who completed all questions, shortest time first.
      const finishers = entries.filter(e => e.finished || (e.total && e.done >= e.total));
      const pool = finishers.length ? finishers : entries;
      pool.sort((a, b) => ((a.elapsedMs == null ? Infinity : a.elapsedMs) - (b.elapsedMs == null ? Infinity : b.elapsedMs)) || (b.pct || 0) - (a.pct || 0));
      top = pool[0];
    } else {
      entries.sort((a, b) => (b.pct || 0) - (a.pct || 0) || (b.done || 0) - (a.done || 0) || String(a.at || '').localeCompare(String(b.at || '')));
      top = entries[0];
    }
    const detail = d.win === 'fastest' ? (top.elapsedMs != null ? _fmtDuration(top.elapsedMs) : 'fastest') : (Math.round(top.pct || 0) + '%');
    if (!confirm('Award the $10 voucher to ' + (top.name || 'top student') + ' (' + detail + ')?')) return;
    await updateDoc(doc(db, QUESTS_COL, questId), {
      winnerUid: top.uid, winnerName: top.name || 'Student', winnerPct: Math.round(top.pct || 0), winnerTimeMs: top.elapsedMs || 0,
      winnerAt: new Date().toISOString(), status: 'ended'
    });
    showToast('🏆 ' + (top.name || 'Top student') + ' wins with ' + detail + '!', 'success');
  } catch (e) { console.warn('award top scorer', e); showToast('Could not award the winner', 'error'); }
}
// "Mr Chung grades" mode: the teacher hand-picks the winner from the entrants.
async function commAwardTo(questId, uid) {
  if (!_isAdmin() || !_commCanFirestore()) return;
  try {
    const snap = await getDoc(doc(db, QUESTS_COL, questId));
    if (!snap.exists()) return;
    const d = snap.data();
    if (d.winnerUid) { showToast('A winner is already set.', 'info'); return; }
    const s = (d.scores || {})[uid];
    if (!s) { showToast('That student has no entry.', 'error'); return; }
    if (!confirm('Award the $10 voucher to ' + (s.name || 'this student') + '?')) return;
    await updateDoc(doc(db, QUESTS_COL, questId), {
      winnerUid: uid, winnerName: s.name || 'Student', winnerPct: Math.round(s.pct || 0), winnerTimeMs: s.elapsedMs || 0,
      winnerAt: new Date().toISOString(), status: 'ended'
    });
    showToast('🏆 ' + (s.name || 'Student') + ' wins!', 'success');
  } catch (e) { console.warn('award to', e); showToast('Could not award the winner', 'error'); }
}

// ---- realtime subscriptions + rendering --------------------------------
function commStartGlobalWatch() {
  if (!_commCanFirestore() || _questUnsub) return;
  try {
    _questUnsub = onSnapshot(collection(db, QUESTS_COL), snap => {
      _commQuests = []; snap.forEach(d => _commQuests.push(Object.assign({ _id: d.id }, d.data())));
      _activeQuests().forEach(q => {
        if (!_questSeen[q._id]) {
          _questSeen[q._id] = 1;
          if (currentUser && currentUser.role === 'student') {
            const how = q.mode === 'auto'
              ? (q.win === 'fastest' ? ' — finish fastest to win $10!' : q.win === 'graded' ? ' — do your best, Mr Chung grades to win $10!' : ' — score the highest to win $10!')
              : (q.mode === 'score' ? ' — score the highest to win $10!' : ' — finish ' + q.count + ' questions to win $10!');
            showToast('⚡ New Encounter Quest: ' + (q.title || '') + how, 'info');
          }
        }
      });
      // A score quest the admin just awarded to me → offer the prize claim.
      if (currentUser && currentUser.role === 'student') {
        const ack = (progress && progress.prizeAck) || {};
        _commQuests.forEach(q => {
          const awardable = q.mode === 'score' || (q.mode === 'auto' && q.win !== 'fastest');
          if (awardable && q.winnerUid === currentUser.uid && !_questOffered[q._id] && !ack['enc_' + q._id]) {
            commOfferQuestPrize(q);
          }
        });
      }
      _renderQuestChip(); _renderQuestBanners();
    }, e => console.warn('quest sub', e));
    if (!_questTick) _questTick = setInterval(() => { _renderQuestChip(); _renderQuestBanners(); }, 1000);
  } catch (e) { console.warn('quest watch', e); }
}
function _commSubscribeFeed() {
  if (!_commCanFirestore() || _commUnsub) return;
  try {
    _commUnsub = onSnapshot(collection(db, COMMUNITY_COL), snap => {
      _commPosts = []; snap.forEach(d => _commPosts.push(Object.assign({ _id: d.id }, d.data())));
      _renderCommFeed(); _renderCommPending(); renderCommAvatarPicker();
    }, e => { console.warn('community sub', e); const f = document.getElementById('commFeed'); if (f) f.innerHTML = '<div class="empty-note">Couldn\'t load the board — check the Firestore rules for the <b>community</b> collection.</div>'; });
  } catch (e) { console.warn('community sub', e); }
}
function _renderQuestChip() {
  const chip = document.getElementById('questChip'); if (!chip) return;
  if (!(currentUser && currentUser.role === 'student')) { chip.classList.remove('show'); return; }
  const qs = _activeQuests();
  if (!qs.length) { chip.classList.remove('show'); return; }
  qs.sort((a, b) => new Date(a.endAt) - new Date(b.endAt));
  const left = new Date(qs[0].endAt).getTime() - Date.now();
  chip.innerHTML = '⚡ Quest ' + _fmtCountdown(left);
  chip.classList.add('show');
}
// Sub-content for an auto-fed quest banner (student attempt button / admin award UI).
function _commAutoBannerSub(q, live) {
  const student = currentUser && currentUser.role === 'student';
  const win = q.win || 'highest';
  const fmt = q.format === 'written' ? 'open-ended' : 'MCQ';
  const nq = q.count || q.total || '';
  const winLabel = win === 'fastest' ? 'fastest to finish wins' : win === 'graded' ? 'Mr Chung grades' : 'highest score wins';
  const scores = q.scores || {};
  const entries = Object.keys(scores).map(uid => Object.assign({ uid }, scores[uid]));
  const n = entries.length;
  if (student) {
    const my = scores[currentUser.uid] || null;
    if (live) {
      const label = my ? '🔁 Attempt again' : '⚡ Attempt quest now!';
      const btn = '<button class="btn btn-primary btn-sm" onclick="commStartAutoQuest(\'' + q._id + '\')">' + label + '</button>';
      let mine = '';
      if (my) {
        mine = win === 'fastest'
          ? (my.finished ? ' Your time: <b>' + _fmtDuration(my.elapsedMs) + '</b>.' : ' Answered ' + (my.done || 0) + '/' + (my.total || nq) + '.')
          : ' Your score: <b>' + Math.round(my.pct || 0) + '%</b>.';
      }
      return '<div class="cq-progress">' + nq + ' ' + fmt + ' questions picked for you · ' + winLabel + '.' + mine + '</div>' + btn;
    }
    if (!n) return '<div class="cq-progress">Time\'s up — no entries this round.</div>';
    return '<div class="cq-progress">Time\'s up — waiting for the result…</div>';
  }
  // admin
  if (!n) return '<div class="cq-progress">' + (live ? 'Live' : 'Time\'s up') + ' — no attempts yet · ' + nq + ' ' + fmt + ' q · ' + winLabel + '.</div>';
  if (win === 'graded') {
    return '<div class="cq-progress">' + n + ' student' + (n === 1 ? '' : 's') + ' attempted · pick the winner:</div>' + _commGradedChooser(q);
  }
  let lead;
  if (win === 'fastest') {
    lead = entries.filter(e => e.finished || (e.total && e.done >= e.total)).sort((a, b) => (a.elapsedMs == null ? Infinity : a.elapsedMs) - (b.elapsedMs == null ? Infinity : b.elapsedMs))[0];
  } else {
    lead = entries.slice().sort((a, b) => (b.pct || 0) - (a.pct || 0))[0];
  }
  const leadTxt = lead ? (' · leader ' + escapeHtml(lead.name || 'student') + ' ' + (win === 'fastest' ? _fmtDuration(lead.elapsedMs) : Math.round(lead.pct || 0) + '%')) : '';
  const awardBtn = ' <button class="btn btn-outline btn-sm" onclick="commAwardTopScorer(\'' + q._id + '\')">🏆 Award winner</button>';
  return '<div class="cq-progress">' + n + ' student' + (n === 1 ? '' : 's') + ' attempted' + leadTxt + awardBtn + '</div>';
}
function _commGradedChooser(q) {
  const scores = q.scores || {};
  const entries = Object.keys(scores).map(uid => Object.assign({ uid }, scores[uid])).sort((a, b) => (b.pct || 0) - (a.pct || 0));
  if (!entries.length) return '';
  return entries.map(e =>
    '<div class="cq-grade-row"><span>' + escapeHtml(e.name || 'Student') + ' — ' + Math.round(e.pct || 0) + '%' +
    (e.elapsedMs != null ? ' · ' + _fmtDuration(e.elapsedMs) : '') + (e.finished ? ' ✅' : '') + '</span>' +
    '<button class="btn btn-outline btn-sm" onclick="commAwardTo(\'' + q._id + '\',\'' + e.uid + '\')">🏆 Award</button></div>'
  ).join('');
}
function _renderQuestBanners() {
  const area = document.getElementById('commQuestArea'); if (!area) return;
  // Hide dead quests: once a quest ends with no winner there's nothing to act on,
  // so drop it — except keep it for the admin while there are entries left to award.
  const list = _commQuests.filter(q => {
    const isExpired = q.status === 'ended' || new Date(q.endAt).getTime() <= Date.now();
    if (!isExpired) return true;                 // still live
    if (q.winnerUid) return true;                // ended with a winner — celebrate it
    const hasEntries = q.scores && Object.keys(q.scores).length;
    return _isAdmin() && (q.mode === 'score' || q.mode === 'auto') && hasEntries; // admin can still award
  }).sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || ''))).slice(0, 16);
  if (!list.length) { area.innerHTML = ''; return; }
  const student = currentUser && currentUser.role === 'student';
  // Finished quests that already have a winner are just trophies — collapse them
  // into one slim recap card so they don't crowd the board. Everything else
  // (live quests, and ended ones the admin can still award) stays a banner.
  const wonList = list.filter(q => !!q.winnerUid).slice(0, 5);
  const bannerList = list.filter(q => !q.winnerUid).slice(0, 4);
  const bannersHtml = bannerList.map(q => {
    const isScore = q.mode === 'score';
    const isAuto = q.mode === 'auto';
    const left = new Date(q.endAt).getTime() - Date.now();
    const expired = q.status === 'ended' || left <= 0;
    let timer, sub;
    if (expired) {
      timer = '⌛<span>ENDED</span>';
      if (isAuto) {
        sub = _commAutoBannerSub(q, false);
      } else if (isScore) {
        const scores = q.scores || {};
        const n = Object.keys(scores).length;
        const awardBtn = _isAdmin() ? ' <button class="btn btn-outline btn-sm" onclick="commAwardTopScorer(\'' + q._id + '\')">🏆 Award top scorer</button>' : '';
        sub = '<div class="cq-progress">Time\'s up — ' + (n ? n + ' student' + (n === 1 ? '' : 's') + ' attempted. ' + (_isAdmin() ? 'Award the highest %.' : 'Waiting for the result…') : 'no entries this round.') + awardBtn + '</div>';
      } else {
        sub = '<div class="cq-progress">Time\'s up — no winner this round.</div>';
      }
    } else {
      timer = _fmtCountdown(left) + '<span>LEFT</span>';
      if (isAuto) {
        sub = _commAutoBannerSub(q, true);
      } else if (isScore) {
        if (student) {
          const my = (q.scores && q.scores[currentUser.uid]) || null;
          const startBtn = '<button class="btn btn-primary btn-sm" onclick="commStartQuestRun(\'' + q._id + '\')">▶ ' + (my ? 'Improve your score' : 'Start quest') + '</button>';
          sub = '<div class="cq-progress">Answer ' + (q.total || 0) + ' questions — highest % wins.' +
            (my ? ' Your score: <b>' + Math.round(my.pct || 0) + '%</b>' : '') + '</div>' + startBtn;
        } else {
          const scores = q.scores || {};
          const lead = Object.values(scores).sort((a, b) => (b.pct || 0) - (a.pct || 0))[0];
          sub = '<div class="cq-progress">Reward: ' + escapeHtml(q.prize || '$10 voucher') + ' · ' + (q.total || 0) + ' picked questions · highest % wins' +
            (lead ? ' · leader ' + escapeHtml(lead.name || 'student') + ' ' + Math.round(lead.pct || 0) + '%' : '') + '</div>';
        }
      } else {
        const prog = _questProgress(q);
        sub = student
          ? '<div class="cq-progress">Your progress: ' + Math.min(prog, q.count) + ' / ' + q.count + ' questions' + (prog >= q.count ? ' ✅' : '') + '</div>'
          : '<div class="cq-progress">Reward: ' + escapeHtml(q.prize || '$10 voucher') + ' · ' + q.count + ' questions' + (q.topic ? ' · ' + escapeHtml(q.topic) : '') + '</div>';
      }
    }
    const endBtn = _isAdmin() && !expired ? ' <button class="btn btn-outline btn-sm" onclick="commEndQuest(\'' + q._id + '\')">End</button>' : '';
    return '<div class="comm-quest-banner' + (expired ? ' ended' : '') + '">' +
      '<span class="cq-emoji">⚡</span>' +
      '<div class="cq-main"><div class="cq-title">' + escapeHtml(q.title || 'Encounter Quest') + endBtn + '</div>' +
      (q.desc ? '<div class="cq-desc">' + escapeHtml(q.desc) + '</div>' : '') + sub + '</div>' +
      '<div class="cq-timer">' + timer + '</div></div>';
  }).join('');
  area.innerHTML = bannersHtml + _renderQuestWinnersStrip(wonList);
}
// Collapse finished, already-won flash quizzes into one compact recap card.
function _renderQuestWinnersStrip(wonList) {
  if (!wonList || !wonList.length) return '';
  const rows = wonList.map(q => {
    const isAuto = q.mode === 'auto', isScore = q.mode === 'score';
    const how = (isAuto && q.win === 'fastest' && q.winnerTimeMs != null) ? _fmtDuration(q.winnerTimeMs)
      : ((isScore || isAuto) && q.winnerPct != null && !(isAuto && q.win === 'fastest')) ? Math.round(q.winnerPct) + '%' : '';
    const score = how ? '<span class="cqw-score">' + escapeHtml(how) + '</span>' : '';
    const quest = q.title ? ' <span class="cqw-quest">· ' + escapeHtml(q.title) + '</span>' : '';
    return '<div class="cqw-row"><span class="cqw-trophy">🏆</span>' +
      '<div class="cqw-body"><span class="cqw-name">' + escapeHtml(q.winnerName || 'A student') + '</span> won the $10 voucher' + quest + '</div>' +
      score + '</div>';
  }).join('');
  return '<div class="comm-quest-winners"><div class="cqw-head">🏆 Recent Flash Quiz winners</div>' + rows + '</div>';
}
function _commPostHtml(p, moderate) {
  const admin = _isAdmin();
  const isStaff = p.authorRole === 'admin';
  const tag = isStaff
    ? '<span class="comm-tag ' + (p.type || 'update') + '">' + _commTypeLabel(p.type) + '</span>'
    : (p.status === 'pending' ? '<span class="comm-tag pending">Pending</span>' : '');
  const img = p.imageUrl ? '<img class="comm-img" src="' + escapeHtml(p.imageUrl) + '" onclick="window.open(this.src,\'_blank\')" alt="">' : '';
  const ava = escapeHtml(p.authorAvatar || (isStaff ? COMM_ADMIN_AVATAR : '🧑‍🎓'));
  const statusLabel = isStaff ? COMM_ADMIN_STATUS : _commStudentStatus(_commPostCount(p.authorUid));
  const statusPill = '<span class="comm-status' + (isStaff ? ' polymath' : '') + '">' + escapeHtml(statusLabel) + '</span>';
  let actions = '';
  if (p._builtin) actions = '';   // no moderation on the synthetic announcement — there's no doc behind it
  else if (moderate) actions = '<div class="comm-actions"><button class="btn btn-primary" onclick="commApprove(\'' + p._id + '\')">✓ Approve</button><button class="btn btn-outline" onclick="commReject(\'' + p._id + '\')">✕ Reject</button></div>';
  else if (admin) actions = '<div class="comm-actions"><button class="btn btn-outline" onclick="commPin(\'' + p._id + '\',\'' + (p.pinned ? 'false' : 'true') + '\')">' + (p.pinned ? '📌 Unpin' : '📌 Pin') + '</button><button class="btn btn-outline" onclick="commDelete(\'' + p._id + '\')">🗑 Delete</button></div>';
  return '<div class="comm-post' + (p.pinned && !moderate ? ' pinned' : '') + '">' +
    '<div class="comm-ava' + (isStaff ? ' admin' : '') + '">' + ava + '</div>' +
    '<div class="comm-body">' +
    '<div class="comm-meta"><span class="comm-author">' + escapeHtml(p.authorName || 'Anonymous') + '</span>' + statusPill + tag +
    '<span class="comm-time">' + _commTimeAgo(p.createdAt) + '</span>' + (p.pinned && !moderate ? ' 📌' : '') + '</div>' +
    (p.title ? '<div class="comm-title">' + escapeHtml(p.title) + '</div>' : '') +
    (p.text ? '<div class="comm-text">' + escapeHtml(p.text) + '</div>' : '') +
    img + (p._ctaHtml || '') + actions +
    '</div></div>';
}
function _renderCommFeed() {
  const feed = document.getElementById('commFeed'); if (!feed) return;
  const posts = _commPosts.filter(p => p.status === 'approved')
    .sort((a, b) => (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0) || String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
  if (!posts.length) { feed.innerHTML = '<div class="empty-note">No posts yet. ' + (_isAdmin() ? 'Share the first update above!' : 'Check back soon!') + '</div>'; return; }
  feed.innerHTML = posts.map(p => _commPostHtml(p, false)).join('');
}
function _renderCommPending() {
  const wrap = document.getElementById('commPending'), card = document.getElementById('commPendingCard');
  if (!wrap || !card) return;
  if (!_isAdmin()) { card.style.display = 'none'; return; }
  const pend = _commPosts.filter(p => p.status === 'pending').sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
  const cnt = document.getElementById('commPendingCount'); if (cnt) cnt.textContent = pend.length;
  card.style.display = pend.length ? '' : 'none';
  wrap.innerHTML = pend.map(p => _commPostHtml(p, true)).join('');
}
function _commWireTabs() {
  document.querySelectorAll('#commAdminTools .comm-tab').forEach(t => {
    t.onclick = () => {
      document.querySelectorAll('#commAdminTools .comm-tab').forEach(x => x.classList.toggle('active', x === t));
      document.getElementById('commTabPost').classList.toggle('active', t.dataset.commtab === 'post');
      document.getElementById('commTabQuest').classList.toggle('active', t.dataset.commtab === 'quest');
    };
  });
}
// Load the signed-in student's saved animal avatar, then paint the picker.
async function _commLoadMyProfile() {
  if (!(currentUser && currentUser.role === 'student')) return;
  if (!currentUser.avatar && _commCanFirestore()) {
    try {
      const snap = await getDoc(doc(db, PROFILES_COL, currentUser.uid));
      const a = snap.exists() && snap.data().avatar;
      currentUser.avatar = (a && COMM_AVATARS.includes(a)) ? a : COMM_DEFAULT_AVATAR;
    } catch (e) { console.warn('avatar load', e); currentUser.avatar = COMM_DEFAULT_AVATAR; }
  }
  renderCommAvatarPicker();
}
function renderCommAvatarPicker() {
  const row = document.getElementById('commAvatarRow'); if (!row) return;
  if (!(currentUser && currentUser.role === 'student')) return;
  const mine = _commMyAvatar();
  row.innerHTML = COMM_AVATARS.map(a =>
    '<button type="button" class="comm-ava-btn' + (a === mine ? ' selected' : '') +
    '" onclick="commPickAvatar(\'' + a + '\')" aria-label="Pick avatar ' + a + '">' + a + '</button>'
  ).join('');
  const count = _commPostCount(currentUser.uid);
  const st = document.getElementById('commMyStatus');
  if (st) st.textContent = _commStudentStatus(count);
  const hint = document.getElementById('commRankHint');
  if (hint) {
    const next = _commNextTier(count);
    hint.textContent = next
      ? ('You have ' + count + ' approved post' + (count === 1 ? '' : 's') + ' — ' + next.need + ' more to reach ' + next.label + '!')
      : ('You have ' + count + ' approved posts — top rank reached! 🏆');
  }
}
async function commPickAvatar(emoji) {
  if (!(currentUser && currentUser.role === 'student') || !COMM_AVATARS.includes(emoji)) return;
  currentUser.avatar = emoji;
  renderCommAvatarPicker();
  if (_commCanFirestore()) {
    try { await setDoc(doc(db, PROFILES_COL, currentUser.uid), { avatar: emoji }, { merge: true }); showToast('Avatar updated ✓', 'success'); }
    catch (e) { console.warn('avatar save', e); showToast('Could not save avatar', 'error'); }
  }
}
function renderCommunity() {
  const pc = document.getElementById('commPendingCard'); if (pc && !_isAdmin()) pc.style.display = 'none';
  _commWireTabs();
  _commSubscribeFeed();
  commStartGlobalWatch();
  _commLoadMyProfile();
  _renderCommFeed(); _renderCommPending(); _renderQuestBanners();
}

// =====================================================================
// MESSAGING — admin <-> students (top-level `messages` collection, mirrors how
// `flaggedQuestions` is used: authenticated users create docs and query them).
// A message: { fromUid, fromName, fromRole, toUid ('all' = broadcast), text,
// ts, read, kind ('dm'|'flagReply'), flagId?, questionTitle? }.
// =====================================================================
let _messages = [];
function _myUid() { return currentUser && currentUser.uid; }
function _teacherUid() { return (currentUser && currentUser.role === 'admin') ? currentUser.uid : adminUid; }
function _msgTime(m) { try { return m.ts ? (m.ts.toDate ? m.ts.toDate().getTime() : new Date(m.ts).getTime()) : 0; } catch (e) { return 0; } }

async function _fetchMsgs(field, value) {
  try {
    const snap = await getDocs(query(collection(db, MESSAGES_COL), where(field, '==', value)));
    return snap.docs.map(d => ({ ...d.data(), _id: d.id }));
  } catch (e) { console.warn('messages query failed', field, e); return []; }
}
async function loadMessages() {
  const uid = _myUid(); if (!uid) return [];
  const parts = await Promise.all([_fetchMsgs('toUid', uid), _fetchMsgs('fromUid', uid), _fetchMsgs('toUid', 'all')]);
  const map = {};
  parts.flat().forEach(m => { map[m._id] = m; });
  _messages = Object.values(map).sort((a, b) => _msgTime(a) - _msgTime(b));
  return _messages;
}
async function sendMessageDoc(toUid, toName, text, extra) {
  const t = (text || '').trim(); if (!t) return false;
  const u = currentUser; if (!u) return false;
  const data = Object.assign({
    fromUid: u.uid, fromName: u.name || '', fromRole: u.role || 'student',
    toUid: toUid, toName: toName || '', text: t, ts: Timestamp.now(), read: false, kind: 'dm'
  }, extra || {});
  try { await addDoc(collection(db, MESSAGES_COL), data); return true; }
  catch (e) { console.error('sendMessage failed', e); showToast('Message failed: ' + (e && e.message ? e.message : e), 'error'); return false; }
}
function _isIncomingUnread(m) {
  const uid = _myUid();
  return !m.read && m.fromUid !== uid && (m.toUid === uid || (currentUser.role === 'student' && m.toUid === 'all'));
}
function unreadCount() { return _messages.filter(_isIncomingUnread).length; }
function updateMsgBadge() {
  const n = unreadCount();
  ['msgUnreadAdmin', 'msgUnreadStudent'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.textContent = n; el.style.display = n ? '' : 'none'; }
  });
}
async function _markRead(filterFn) {
  const toMark = _messages.filter(m => _isIncomingUnread(m) && filterFn(m));
  await Promise.all(toMark.map(m => updateDoc(doc(db, MESSAGES_COL, m._id), { read: true }).then(() => { m.read = true; }).catch(() => {})));
  updateMsgBadge();
}

function _msgBubble(m, mine) {
  const who = mine ? 'You' : (m.fromName || (m.fromRole === 'admin' ? 'Teacher' : 'Student'));
  const ctx = (m.kind === 'flagReply' && m.questionTitle) ? `<div class="msg-ctx">Re: flagged “${escapeHtml(m.questionTitle)}”</div>` : '';
  const time = _msgTime(m) ? formatDateTimeSGT(new Date(_msgTime(m))) : '';
  return `<div class="msg-row ${mine ? 'mine' : ''}"><div class="msg-bubble ${mine ? 'mine' : ''}">${ctx}<div class="msg-who">${escapeHtml(who)}</div><div class="msg-text">${escapeHtml(m.text || '')}</div><div class="msg-time">${escapeHtml(time)}</div></div></div>`;
}

async function loadMessagesPage() {
  const sub = document.getElementById('messagesSubtitle');
  if (sub) sub.textContent = currentUser && currentUser.role === 'admin'
    ? 'Reply to students, or broadcast an announcement to everyone'
    : 'Message your teacher — replies and announcements appear here';
  await loadMessages();
  if (currentUser && currentUser.role === 'admin') renderAdminMessages(); else renderStudentMessages();
  updateMsgBadge();
}

function renderStudentMessages() {
  const c = document.getElementById('messagesContainer'); if (!c) return;
  const uid = currentUser.uid;
  const msgs = _messages.slice().sort((a, b) => _msgTime(a) - _msgTime(b));
  const bubbles = msgs.length ? msgs.map(m => _msgBubble(m, m.fromUid === uid)).join('') : '<div class="msg-empty">No messages yet. Say hello to your teacher 👋</div>';
  const teacher = _teacherUid();
  c.innerHTML = `<div class="msg-card">
      <div class="msg-card-title">💬 Your teacher</div>
      <div class="msg-thread" id="msgThreadScroll">${bubbles}</div>
      <div class="msg-compose">
        <textarea id="studentMsgInput" class="msg-input" rows="2" placeholder="${teacher ? 'Message your teacher…' : 'Teacher not set up yet'}"${teacher ? '' : ' disabled'}></textarea>
        <button class="btn btn-primary" onclick="sendStudentMsg()"${teacher ? '' : ' disabled'}>Send</button>
      </div>
    </div>`;
  const sc = document.getElementById('msgThreadScroll'); if (sc) sc.scrollTop = sc.scrollHeight;
  _markRead(m => m.toUid === uid || m.toUid === 'all');
}

function renderAdminMessages() {
  const c = document.getElementById('messagesContainer'); if (!c) return;
  const me = currentUser.uid;
  const threads = {};
  _messages.forEach(m => {
    let other, name;
    if (m.toUid === 'all') { other = 'all'; name = '📢 All students'; }
    else if (m.fromUid === me) { other = m.toUid; name = m.toName || m.toUid; }
    else { other = m.fromUid; name = m.fromName || m.fromUid; }
    if (!threads[other]) threads[other] = { uid: other, name, msgs: [] };
    if (name && name !== other) threads[other].name = name;
    threads[other].msgs.push(m);
  });
  const list = Object.values(threads).sort((a, b) => _msgTime(b.msgs[b.msgs.length - 1]) - _msgTime(a.msgs[a.msgs.length - 1]));
  let html = `<div class="msg-card">
      <div class="msg-card-title">📢 Broadcast to all students</div>
      <div class="msg-compose">
        <textarea id="adminBroadcastInput" class="msg-input" rows="2" placeholder="Announcement sent to every student…"></textarea>
        <button class="btn btn-primary" onclick="sendBroadcast()">Send to all</button>
      </div>
    </div>`;
  if (!list.length) html += '<div class="msg-empty">No conversations yet. Student messages and your flag replies will appear here.</div>';
  list.forEach(t => {
    const bubbles = t.msgs.slice().sort((a, b) => _msgTime(a) - _msgTime(b)).map(m => _msgBubble(m, m.fromUid === me)).join('');
    if (t.uid === 'all') {
      html += `<div class="msg-card"><div class="msg-card-title">📢 Broadcast history</div><div class="msg-thread">${bubbles}</div></div>`;
      return;
    }
    const unread = t.msgs.filter(m => !m.read && m.fromUid === t.uid).length;
    html += `<div class="msg-card">
        <div class="msg-card-title">${escapeHtml(t.name)} ${unread ? `<span class="msg-unread-dot">${unread} new</span>` : ''}</div>
        <div class="msg-thread">${bubbles}</div>
        <div class="msg-compose">
          <input id="threadInput_${escapeHtml(t.uid)}" class="msg-input" placeholder="Reply to ${escapeHtml(t.name)}…">
          <button class="btn btn-primary" onclick="sendThreadReply('${escapeHtml(t.uid)}')">Send</button>
        </div>
      </div>`;
  });
  c.innerHTML = html;
  _markRead(m => m.toUid === me);
}

async function sendStudentMsg() {
  const t = _teacherUid();
  if (!t) { showToast('Teacher not available yet', 'error'); return; }
  const el = document.getElementById('studentMsgInput'); const text = el ? el.value.trim() : '';
  if (!text) return;
  if (await sendMessageDoc(t, 'Teacher', text)) { el.value = ''; await loadMessagesPage(); }
}
async function sendBroadcast() {
  const el = document.getElementById('adminBroadcastInput'); const text = el ? el.value.trim() : '';
  if (!text) return;
  if (await sendMessageDoc('all', 'All students', text)) { el.value = ''; showToast('Broadcast sent', 'success'); await loadMessagesPage(); }
}
async function sendThreadReply(uid) {
  const el = document.getElementById('threadInput_' + uid); const text = el ? el.value.trim() : '';
  if (!text) return;
  const ref = _messages.find(m => m.fromUid === uid || m.toUid === uid);
  const name = ref ? (ref.fromUid === uid ? ref.fromName : ref.toName) : '';
  if (await sendMessageDoc(uid, name || '', text)) { el.value = ''; await loadMessagesPage(); }
}

// Reply to a flagged question — sends a message to the student who flagged it.
async function replyToFlag(docId) {
  const f = flaggedQuestions.find(x => x._docId === docId); if (!f) return;
  const input = document.getElementById('flagReply_' + docId);
  const text = input ? input.value.trim() : '';
  if (!text) { showToast('Type a reply first', 'error'); return; }
  if (!f.flaggedByUid) { showToast('No student account on this flag', 'error'); return; }
  const ok = await sendMessageDoc(f.flaggedByUid, f.flaggedBy || '', text, { kind: 'flagReply', flagId: docId, questionTitle: f.questionTitle || '' });
  if (!ok) return;
  try { await updateDoc(doc(db, FLAGS_COL, docId), { reply: text, repliedAt: Timestamp.now() }); } catch (e) {}
  f.reply = text;
  showToast('Reply sent to ' + (f.flaggedBy || 'student'), 'success');
  renderFlaggedQuestions();
}

// =====================================================================
// EXPOSE FUNCTIONS GLOBALLY (required for module scope + onclick handlers)
// =====================================================================
window.loadMessagesPage = loadMessagesPage;
window.sendStudentMsg = sendStudentMsg;
window.sendBroadcast = sendBroadcast;
window.sendThreadReply = sendThreadReply;
window.replyToFlag = replyToFlag;
// =====================================================================
// PAST PAPER ANALYSIS  (2021–2023 PSLE English, fully editable by admins)
// Admins can add/remove questions per year and edit every field, plus
// author recurring concepts, and attach a bank question to each so
// students can practise it.
//   users/{adminUid}/settings/paperData  { questions:[], recurring:[] }
//   users/{adminUid}/settings/paperMap   { map: { questionId: bankQid } }
// Built-in seed below is the default until an admin saves changes.
// =====================================================================
// The past-paper library starts EMPTY: this app is for English and the papers
// are the admin's to add (📄 Past Papers → edit mode). The seed arrays stay so
// a future build can ship a starter set without changing anything else.
const PP_SEED_Q = [];
const PP_SEED_R = [];
const PP_SKILL = { recall:'Knowledge / recall', application:'Application', data:'Text interpretation', experimental:'Language use', open:'Open-ended response' };
const PP_THEME = {
  'Grammar':'language', 'Grammar Cloze':'language', 'Synthesis and Transformation':'language',
  'Editing for Spelling and Grammar':'language', 'Punctuation and Spelling':'language',
  'Vocabulary':'vocabulary', 'Vocabulary Cloze':'vocabulary',
  'Comprehension (Open-ended)':'reading', 'Comprehension Cloze':'reading', 'Visual Text Comprehension':'reading',
  'Comprehension: Inference':'reading', 'Comprehension: Vocabulary in Context':'reading',
  'Continuous Writing':'writing', 'Situational Writing':'writing', 'Picture Composition':'writing',
  'Oral: Reading Aloud':'oral', 'Oral: Stimulus-based Conversation':'oral', 'Listening Comprehension':'oral'
};
const PP_THEME_C = { language:'#2d6ca8', vocabulary:'#0f7a5a', reading:'#a8762c', writing:'#6b4fa0', oral:'#b55a2b' };
const PP_THEME_NAME = { language:'Language Use', vocabulary:'Vocabulary', reading:'Reading', writing:'Writing', oral:'Listening & Speaking' };

let ppData = null;            // { questions:[], recurring:[] } — loaded or seeded
let paperMap = {};            // { questionId: bankQuestionId }
let _ppDataLoaded = false;
let _ppMapLoaded = false;
let ppEditMode = false;
let _ppAssignKey = null;
let _ppQEditId = null;        // id of question being edited (null = new)
let _ppCEditId = null;        // id of concept being edited (null = new)
let _ppCeHits = null;         // Set of question ids while editing a concept
let _ppHoverEl = null;

function ppClone(o){ return JSON.parse(JSON.stringify(o)); }
function ppDefaults(){ return { questions: PP_SEED_Q.map(ppClone), recurring: PP_SEED_R.map(ppClone) }; }
function ppQuestions(){ return (ppData && Array.isArray(ppData.questions)) ? ppData.questions : []; }
function ppRecurring(){ return (ppData && Array.isArray(ppData.recurring)) ? ppData.recurring : []; }
function ppYears(){ return [...new Set(ppQuestions().map(q => String(q.year)))].sort(); }
function ppNextN(year){ const ns = ppQuestions().filter(q => String(q.year) === String(year)).map(q => Number(q.n) || 0); return ns.length ? Math.max.apply(null, ns) + 1 : 1; }
function ppNewId(){ return 'u_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }

function ppKey(q){ return q.id; }
function ppSkillName(t){ return PP_SKILL[t] || t || '—'; }
function ppTheme(topic){ return PP_THEME[topic] || 'diversity'; }
function ppThemeColor(topic){ return PP_THEME_C[ppTheme(topic)]; }
function ppLevel(topic){ try { return getTopicLevel(topic); } catch(_) { return ''; } }
function ppFindQ(id){ return ppQuestions().find(q => q.id === id); }
// The topic used across the analysis (chart, bars, topic worksheets): the
// ATTACHED bank question's topic — the live value the admin edits — when a
// question is attached, otherwise the past-paper record's own topic. This way
// changing a question's topic in the editor immediately re-buckets everything.
function ppTopicOf(q){ if (!q) return ''; const bq = ppBankQ(q.id); return (bq && bq.topic) ? bq.topic : (q.topic || ''); }
function ppIsAdmin(){ return !!(currentUser && currentUser.role === 'admin'); }
function ppOwnerUid(){ return ppIsAdmin() ? (currentUser && currentUser.uid) : adminUid; }
function ppBankQ(id){ const b = paperMap[id]; return b ? questionBank.find(q => q.id === b) : null; }

// ---- Question success rate (correct attempts / total attempts, whole %) ----
// Backed by the shared per-question attempt stats (_qAttemptStats), which are
// written for EVERY marked question on EVERY platform — Quick/Topical/worksheet
// practice and past-paper practice — so this one accessor reflects a student's live accuracy anywhere.
// Returns a whole-number percentage, or null if the question was never attempted.
function questionPercent(qid){
  const r = (typeof _qAttemptStats !== 'undefined' && _qAttemptStats) ? _qAttemptStats[String(qid == null ? '' : qid)] : null;
  if (!r || !r.n) return null;
  return Math.round((r.correct / r.n) * 100);
}
// Full picture for a question id: { attempts, correct, percent }. percent is null
// when there are no attempts yet.
function questionStats(qid){
  const r = (typeof _qAttemptStats !== 'undefined' && _qAttemptStats) ? _qAttemptStats[String(qid == null ? '' : qid)] : null;
  const n = r ? r.n : 0, correct = r ? r.correct : 0;
  return { attempts: n, correct: correct, percent: n ? Math.round((correct / n) * 100) : null };
}

// ---- Past-paper difficulty (admin-set, colour-codes the question chips) ----
// Difficulty lives on each past-paper question as q.diff ∈ 'easy'|'moderate'|'hard'
// and only ever applies inside the Past Papers analysis interface.
function ppDiff(q){ const d = q && q.diff; return (d === 'easy' || d === 'moderate' || d === 'hard') ? d : ''; }
function ppDiffClass(q){ const d = ppDiff(q); return d ? ' pp-diff-' + d : ''; }
// Set (or clear) the difficulty of ONE past-paper question and persist it.
// level: 'easy' | 'moderate' | 'hard'  (anything else clears it).
async function ppSetDifficulty(id, level){
  if (!ppIsAdmin()) { showToast('Only admins can set difficulty', 'error'); return; }
  const q = ppFindQ(id); if (!q) return;
  const lv = (level === 'easy' || level === 'moderate' || level === 'hard') ? level : '';
  if (lv) q.diff = lv; else delete q.diff;
  await savePaperData();
  ppHoverHide();
  ppRenderBody();
}

async function loadPaperData(force){
  if (_ppDataLoaded && !force) return;
  ppData = ppDefaults();
  try {
    const uid = ppOwnerUid();
    if (uid && db) {
      const snap = await getDoc(doc(db, 'users', uid, SETTINGS_COL, 'paperData'));
      if (snap.exists() && snap.data()) {
        const d = snap.data();
        if (Array.isArray(d.questions) && d.questions.length) ppData.questions = d.questions;
        if (Array.isArray(d.recurring)) ppData.recurring = d.recurring;
      }
    }
  } catch (e) { console.warn('paperData load', e); }
  ppMergeSeedContent();   // bring in past-year papers shipped in code that a saved copy predates
  _ppDataLoaded = true;
}
// Specific seed question ids to backfill even into a YEAR the saved data already
// has (we normally only add whole new years). Used when we ship questions that
// were missing from a paper we'd already added — e.g. the 2025 Booklet A Q1–Q3
// placeholders added after the rest of 2025 shipped. Listed explicitly so this
// never resurrects a question the admin deliberately deleted.
const PP_BACKFILL_IDS = new Set([]);
// A saved paperData copy (once an admin edits difficulty/attachments) replaces the
// built-in seed, so a whole new past-year paper added to PP_SEED_Q would never show.
// Merge in every seed question for any YEAR the saved data doesn't have yet (this
// won't resurrect individually-deleted questions inside an existing year), plus any
// explicitly-listed PP_BACKFILL_IDS still missing, and add those new questions'
// recurring-concept links without touching existing years' notes. Also refresh any
// backfill question the admin still has only as an empty placeholder (no answer yet).
function ppMergeSeedContent(){
  try {
    const q = Array.isArray(ppData.questions) ? ppData.questions : (ppData.questions = []);
    const savedYears = new Set(q.map(x => String(x.year)));
    const present = new Set(q.map(x => x.id));
    // A seed question whose id is already saved is NEVER re-added, even if its
    // year label no longer matches — otherwise re-labelling a paper's year in
    // the whole-paper editor would resurrect the entire original paper.
    const addQ = PP_SEED_Q.filter(s => !savedYears.has(String(s.year)) && !present.has(s.id));
    const addIds = new Set(addQ.map(s => s.id));
    const backfill = PP_SEED_Q.filter(s => PP_BACKFILL_IDS.has(s.id) && !present.has(s.id) && !addIds.has(s.id));
    // Upgrade any backfill question the admin still has only as an empty placeholder
    // (blank answer AND blank detail) to the real shipped content — keeps their diff.
    PP_SEED_Q.forEach(s => {
      if (!PP_BACKFILL_IDS.has(s.id)) return;
      const cur = q.find(x => x.id === s.id);
      if (cur && !String(cur.ans || '').trim() && !String(cur.detail || '').trim()) {
        const keepDiff = cur.diff;
        Object.assign(cur, ppClone(s));
        if (keepDiff) cur.diff = keepDiff; else delete cur.diff;
      }
    });
    const toAdd = addQ.concat(backfill);
    if (!toAdd.length) return;
    ppData.questions = q.concat(toAdd.map(ppClone));
    const newIds = new Set(toAdd.map(s => s.id));
    const rec = Array.isArray(ppData.recurring) ? ppData.recurring : (ppData.recurring = []);
    const byId = {}; rec.forEach(r => { if (r && r.id) byId[r.id] = r; });
    PP_SEED_R.forEach(sr => {
      const cur = byId[sr.id];
      if (!cur) { rec.push(ppClone(sr)); return; }
      if (!Array.isArray(sr.hits)) return;
      if (!Array.isArray(cur.hits)) cur.hits = [];
      const have = new Set(cur.hits);
      sr.hits.forEach(h => { if (newIds.has(h) && !have.has(h)) { cur.hits.push(h); have.add(h); } });
    });
  } catch (e) { console.warn('pp seed merge', e); }
}

// =====================================================================
// ANSWER KEY CHECK — cross-check the MCQ (Booklet A) answers stored in the
// past-paper segment against the OFFICIAL answer keys (option numbers) for the
// years we have keys for. Flags mismatches and answers missing an option
// number so an admin can read, edit, or one-click fix them.
// =====================================================================
// Booklet A (MCQ) answer keys, keyed by year then question number.
const PP_ANSWER_KEYS = {};
// Official OPEN-ENDED (Booklet B) answer keys, keyed by year then question
// number. 2022/2023 transcribed cleanly from the answer PDFs; 2014/2015/2017
// are read from the scanned PDFs (may contain minor OCR typos).
const PP_OEQ_OCR_YEARS = new Set([]);
// Official open-ended answer keys, keyed by year then question number.
const PP_OEQ_KEYS = {};

// Pull an option number (1–4) out of a stored answer string, or null if none.
function _arOptionNum(ans){
  const s = String(ans || '');
  let m = s.match(/option\s*([1-4])\b/i);          // "Option 3 — ..."
  if (m) return Number(m[1]);
  m = s.match(/^\s*\(?([1-4])\)/);                  // "(3)" or "3)"
  if (m) return Number(m[1]);
  return null;
}
// Build the check results across every year we have an official key for.
function _arBuildResults(){
  const rows = [];
  Object.keys(PP_ANSWER_KEYS).sort().forEach(yr => {
    const key = PP_ANSWER_KEYS[yr];
    Object.keys(key).map(Number).sort((a,b)=>a-b).forEach(n => {
      const official = key[n];
      const q = ppQuestions().find(x => String(x.year) === yr && Number(x.n) === n && (x.bk || 'A') === 'A');
      if (!q) { rows.push({ yr, n, official, status: 'missing' }); return; }
      const appOpt = _arOptionNum(q.ans);
      let status;
      if (appOpt == null) status = 'nonumber';
      else if (appOpt === official) status = 'ok';
      else status = 'mismatch';
      rows.push({ yr, n, official, appOpt, status, id: q.id, title: q.title, ans: q.ans });
    });
  });
  return rows;
}
function renderAnswerReview(){
  const sumEl = document.getElementById('ansreviewSummary');
  const resEl = document.getElementById('ansreviewResults');
  if (!sumEl || !resEl) return;
  // Make sure paper data is loaded before checking.
  if (!_ppDataLoaded) {
    sumEl.innerHTML = '<div class="ar-note">Loading the past-paper data…</div>';
    resEl.innerHTML = '';
    loadPaperData().then(() => renderAnswerReview());
    return;
  }
  const rows = _arBuildResults();
  const mism = rows.filter(r => r.status === 'mismatch');
  const noNum = rows.filter(r => r.status === 'nonumber');
  const missing = rows.filter(r => r.status === 'missing');
  const ok = rows.filter(r => r.status === 'ok');
  const badge = document.getElementById('ansreviewCount');
  if (badge){ const total = mism.length + noNum.length; if (total){ badge.style.display=''; badge.textContent = total; } else badge.style.display='none'; }

  const yrs = Object.keys(PP_ANSWER_KEYS).sort().join(', ');
  sumEl.innerHTML = `
    <div class="ar-summary">
      <div class="ar-sum-row">
        <div class="ar-stat ok"><b>${ok.length}</b><span>match the key</span></div>
        <div class="ar-stat bad"><b>${mism.length}</b><span>discrepancies</span></div>
        <div class="ar-stat warn"><b>${noNum.length}</b><span>no option number</span></div>
        ${missing.length ? `<div class="ar-stat miss"><b>${missing.length}</b><span>missing in app</span></div>` : ''}
      </div>
      <div class="ar-note">Checked Booklet&nbsp;A (MCQ) answers for <b>${yrs}</b> against the official answer keys. ${mism.length ? 'Red items below disagree with the official answer — read each one and click <b>Fix</b> if the official key is right, or <b>Edit</b> to change it yourself.' : (noNum.length ? 'No disagreements found. The amber items simply have no option number recorded — you can stamp the official one in.' : 'Everything checked matches the official answer keys. ✔')}</div>
    </div>`;

  const rowHtml = (r, kind) => {
    const yq = `${r.yr} Q${r.n}`;
    const officialTxt = `Option ${r.official}`;
    if (kind === 'mismatch') {
      return `<div class="ar-row bad">
        <div class="ar-row-main">
          <div class="ar-row-head"><span class="ar-yq">${escapeHtml(yq)}</span><span class="ar-tag bad">app says Option ${r.appOpt} · key says Option ${r.official}</span></div>
          <div class="ar-row-title">${escapeHtml(r.title || '')}</div>
          <div class="ar-row-ans"><b>App answer:</b> ${escapeHtml(r.ans || '')}</div>
        </div>
        <div class="ar-row-actions">
          <button class="btn btn-primary" onclick="arFixToOfficial('${r.id}',${r.official})">Fix → Option ${r.official}</button>
          <button class="btn btn-outline" onclick="arEditQuestion('${r.id}')">Edit</button>
        </div>
      </div>`;
    }
    if (kind === 'nonumber') {
      return `<div class="ar-row warn">
        <div class="ar-row-main">
          <div class="ar-row-head"><span class="ar-yq">${escapeHtml(yq)}</span><span class="ar-tag warn">official: ${officialTxt}</span></div>
          <div class="ar-row-title">${escapeHtml(r.title || '')}</div>
          <div class="ar-row-ans"><b>App answer:</b> ${escapeHtml(r.ans || '') || '<i>(blank)</i>'}</div>
        </div>
        <div class="ar-row-actions">
          <button class="btn btn-outline" onclick="arStampOption('${r.id}',${r.official})" title="Prepend 'Option ${r.official}' to the recorded answer">Stamp Option ${r.official}</button>
          <button class="btn btn-outline" onclick="arEditQuestion('${r.id}')">Edit</button>
        </div>
      </div>`;
    }
    return `<div class="ar-row miss">
      <div class="ar-row-main">
        <div class="ar-row-head"><span class="ar-yq">${escapeHtml(yq)}</span><span class="ar-tag miss">not in the app — official: ${officialTxt}</span></div>
      </div>
    </div>`;
  };

  let html = '';
  if (mism.length) html += `<h3 class="ar-h">✗ Discrepancies (${mism.length})</h3>` + mism.map(r => rowHtml(r,'mismatch')).join('');
  if (noNum.length) html += `<details class="ar-details"${mism.length ? '' : ' open'}><summary class="ar-h">⚠ No option number recorded (${noNum.length}) — click to review</summary>${noNum.map(r => rowHtml(r,'nonumber')).join('')}</details>`;
  if (missing.length) html += `<details class="ar-details"><summary class="ar-h">Missing in the app (${missing.length})</summary>${missing.map(r => rowHtml(r,'missing')).join('')}</details>`;
  if (!html) html = `<div class="empty-state"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg><h3>All good</h3><p>Every checked answer matches the official keys.</p></div>`;
  resEl.innerHTML = html;
  renderOeqReview();
}
// Correct a mismatched answer to the official option. Keeps the old wording but
// re-stamps the option number and flags the description for review.
async function arFixToOfficial(id, official){
  const q = ppFindQ(id); if (!q) return;
  const rest = String(q.ans || '').replace(/^\s*option\s*[1-4]\s*[—\-:]*\s*/i, '').trim();
  q.ans = `Option ${official}${rest ? ' — ' + rest : ''} (corrected to the official answer key — review the wording)`;
  await savePaperData();
  showToast(`Set ${q.year} Q${q.n} to Option ${official}`, 'success');
  renderAnswerReview();
}
// Stamp the official option number onto a text-only answer (prepend it).
async function arStampOption(id, official){
  const q = ppFindQ(id); if (!q) return;
  const cur = String(q.ans || '').trim();
  q.ans = `Option ${official}${cur ? ' — ' + cur : ''}`;
  await savePaperData();
  showToast(`Stamped Option ${official} onto ${q.year} Q${q.n}`, 'success');
  renderAnswerReview();
}
function arEditQuestion(id){ const q = ppFindQ(id); if (q) ppOpenQEdit(q); }

// ---- Open-ended (Booklet B) answer comparison against the official key ----
const _oeqVerdicts = {};   // key `${year}_${n}` -> { verdict, note }
let _oeqBusyYear = null;
// Pull the answer text out of a bank question's answer-type blocks.
function _oeqBankAnswer(bq){
  if (!bq || !Array.isArray(bq.blocks)) return '';
  const out = [];
  bq.blocks.forEach(b => {
    if (!b || !b.type) return;
    const t = b.type;
    if (t === 'answer') out.push([b.claim, b.evidence, b.reasoning].map(x => stripHtmlToText(x || '')).filter(Boolean).join('; '));
    else if (t === 'answerLine') out.push(((b.label || '') + ' ' + stripHtmlToText(b.answer || '')).trim());
    else if (t === 'answerKey') out.push(stripHtmlToText(b.text || ''));
    else if (t === 'explanation') out.push(stripHtmlToText(b.content || b.text || ''));
    else if (t === 'plainanswer') out.push(stripHtmlToText(b.answer || b.text || b.content || ''));
    else if (t === 'studentAnswer') out.push(stripHtmlToText(b.answer || ''));
  });
  return out.filter(s => s && s.trim()).join(' | ').trim();
}
// The app's answer for an OEQ record: the attached bank question's answer if
// attached, else the record's own answer.
function _oeqAppAnswer(rec){
  const bq = ppBankQ(rec.id);
  if (bq) {
    const a = _oeqBankAnswer(bq);
    return { text: a, source: 'attached: ' + (bq.title || 'bank question') + (a ? '' : ' (no answer text found)'), attached: true };
  }
  return { text: String(rec.ans || ''), source: 'past-paper record answer', attached: false };
}
function _oeqRecord(yr, n){
  return ppQuestions().find(x => String(x.year) === String(yr) && Number(x.n) === Number(n) && (x.bk || 'A') === 'B');
}
const _OEQ_VERDICT_META = {
  equivalent: { cls: 'ok',   label: '✓ matches the key' },
  app_better: { cls: 'ok',   label: '★ better than the key' },
  app_weaker: { cls: 'warn', label: '△ weaker — misses points' },
  app_wrong:  { cls: 'bad',  label: '✗ disagrees with the key' },
  unclear:    { cls: 'miss', label: '? unclear' }
};
function renderOeqReview(){
  const el = document.getElementById('ansreviewOeq');
  if (!el) return;
  let html = '';
  Object.keys(PP_OEQ_KEYS).sort().forEach(yr => {
    const nums = Object.keys(PP_OEQ_KEYS[yr]).map(Number).sort((a,b)=>a-b);
    const ocr = PP_OEQ_OCR_YEARS.has(yr);
    const rows = nums.map(n => {
      const rec = _oeqRecord(yr, n);
      const official = PP_OEQ_KEYS[yr][String(n)];
      const v = _oeqVerdicts[`${yr}_${n}`];
      const meta = v ? (_OEQ_VERDICT_META[v.verdict] || _OEQ_VERDICT_META.unclear) : null;
      const app = rec ? _oeqAppAnswer(rec) : null;
      const appTxt = app ? (app.text || '<i>(no answer recorded)</i>') : '<i>(question not in the app)</i>';
      return `<div class="ar-row ${meta ? meta.cls : ''}">
        <div class="ar-row-main">
          <div class="ar-row-head">
            <span class="ar-yq">${yr} Q${n}</span>
            ${meta ? `<span class="ar-tag ${meta.cls}">${meta.label}</span>` : '<span class="ar-tag miss">not compared yet</span>'}
            ${app ? `<span class="ar-src">${escapeHtml(app.source)}</span>` : ''}
          </div>
          ${v && v.note ? `<div class="ar-row-title">${escapeHtml(v.note)}</div>` : ''}
          <div class="ar-row-ans"><b>Your answer:</b> ${typeof appTxt === 'string' && appTxt.startsWith('<i>') ? appTxt : escapeHtml(String(appTxt).slice(0,300))}</div>
          <details class="ar-off"><summary>Official answer key${ocr ? ' (scanned — may have typos)' : ''}</summary><div class="ar-off-txt">${escapeHtml(official)}</div></details>
        </div>
        <div class="ar-row-actions">${rec ? `<button class="btn btn-outline" onclick="arEditQuestion('${rec.id}')">Edit</button>` : ''}</div>
      </div>`;
    }).join('');
    const flagged = nums.filter(n => { const v=_oeqVerdicts[`${yr}_${n}`]; return v && (v.verdict==='app_wrong'||v.verdict==='app_weaker'); }).length;
    const done = nums.filter(n => _oeqVerdicts[`${yr}_${n}`]).length;
    html += `<div class="ar-oeq-year">
      <div class="ar-oeq-head">
        <div><b>${yr}</b> — ${nums.length} open-ended question${nums.length===1?'':'s'} on file${done?` · ${done} checked${flagged?`, <span style="color:var(--accent-red);font-weight:700;">${flagged} to review</span>`:', all look fine ✔'}`:''}</div>
        <button class="btn btn-primary" onclick="runOeqCompare('${yr}')" ${_oeqBusyYear?'disabled':''}>${_oeqBusyYear===yr?'Comparing…':'Compare '+yr+' with AI'}</button>
      </div>
      ${rows}
    </div>`;
  });
  el.innerHTML = html;
}
async function runOeqCompare(year){
  if (_oeqBusyYear) return;
  if (!geminiModel){ showToast('AI is not ready yet — please wait a moment and try again', 'error'); return; }
  const nums = Object.keys(PP_OEQ_KEYS[year] || {}).map(Number).sort((a,b)=>a-b);
  _oeqBusyYear = year;
  renderOeqReview();
  const ocrNote = PP_OEQ_OCR_YEARS.has(year) ? ' The official answer may contain minor scan/OCR typos — read it charitably.' : '';
  let failed = 0;
  try {
    for (const n of nums){
      const rec = _oeqRecord(year, n);
      const official = PP_OEQ_KEYS[year][String(n)];
      if (!rec){ _oeqVerdicts[`${year}_${n}`] = { verdict:'unclear', note:'This question is not in the app.' }; continue; }
      const app = _oeqAppAnswer(rec);
      if (!app.text || !app.text.trim()){ _oeqVerdicts[`${year}_${n}`] = { verdict:'unclear', note:'No answer is recorded for this question in the app.' }; continue; }
      const question = stripHtmlToText(rec.detail || rec.title || '');
      const prompt = `You are checking a Singapore PSLE primary-school English answer against the official answer key.

Question (PSLE ${year} Q${n}): ${question}

Official answer key: ${official}

The answer stored in the app: ${app.text}

Compare the app's answer to the official answer key for this question.${ocrNote}
Return ONLY JSON, no other text: {"verdict":"<one of: equivalent, app_weaker, app_wrong, app_better, unclear>","note":"<one short sentence explaining>"}
Meanings: equivalent = same key points and correct; app_weaker = correct but misses key points the official has; app_wrong = incorrect or contradicts the official; app_better = more complete or clearer than the official; unclear = cannot tell.`;
      try {
        const raw = await askGemini(prompt, { maxOutputTokens: 400, temperature: 0, json: true });
        const data = _parseAIJson(raw);
        const verdict = ['equivalent','app_weaker','app_wrong','app_better','unclear'].includes(data && data.verdict) ? data.verdict : 'unclear';
        _oeqVerdicts[`${year}_${n}`] = { verdict, note: String((data && data.note) || '').slice(0,240) };
      } catch (e){ failed++; _oeqVerdicts[`${year}_${n}`] = { verdict:'unclear', note:'AI check could not be completed for this one.' }; }
    }
  } finally {
    _oeqBusyYear = null;
    renderOeqReview();
    showToast(`Compared ${year} open-ended answers${failed?` (${failed} could not be read)`:''}`, failed?'info':'success');
  }
}

async function savePaperData(){
  if (!ppIsAdmin() || !db) return;
  try {
    await setDoc(doc(db, 'users', currentUser.uid, SETTINGS_COL, 'paperData'),
      { questions: ppData.questions, recurring: ppData.recurring, updatedAt: new Date().toISOString() }, { merge:false });
  } catch (e) { console.warn('paperData save', e); showToast('Could not save — check your connection', 'error'); }
}

async function loadPaperMap(force){
  if (_ppMapLoaded && !force) return;
  try {
    if (ppIsAdmin()) {
      // Admins load ONLY their own map — savePaperMap writes it back wholesale
      // (merge:false), so merging in the other admin's entries here would copy
      // them into this admin's document on the next save.
      const uid = ppOwnerUid();
      if (uid && db) {
        const snap = await getDoc(doc(db, 'users', uid, SETTINGS_COL, 'paperMap'));
        paperMap = (snap.exists() && snap.data() && snap.data().map && typeof snap.data().map === 'object') ? snap.data().map : {};
      }
    } else if (db) {
      // Students read the UNION of every admin's attachments (primary admin
      // wins on conflicts) — an attachment made from either admin account
      // must be practisable regardless of which admin logged in last.
      paperMap = {};
      for (const uid of await allAdminUids()) {
        try {
          const snap = await getDoc(doc(db, 'users', uid, SETTINGS_COL, 'paperMap'));
          const m = (snap.exists() && snap.data() && snap.data().map && typeof snap.data().map === 'object') ? snap.data().map : {};
          Object.keys(m).forEach(k => { if (!(k in paperMap)) paperMap[k] = m[k]; });
        } catch (e) { console.warn('paperMap load for admin', uid, e); }
      }
    }
  } catch (e) { console.warn('paperMap load', e); if (!paperMap) paperMap = {}; }
  // migrate legacy keys "2021-38" -> stable id "s_2021_38"
  let migrated = false;
  Object.keys(paperMap).forEach(k => {
    if (/^\d{4}-\d+$/.test(k)) { const nk = 's_' + k.replace('-', '_'); if (!paperMap[nk]) paperMap[nk] = paperMap[k]; delete paperMap[k]; migrated = true; }
  });
  if (migrated && ppIsAdmin()) savePaperMap();
  _ppMapLoaded = true;
}
async function savePaperMap(){
  if (!ppIsAdmin() || !db) return;
  try { await setDoc(doc(db, 'users', currentUser.uid, SETTINGS_COL, 'paperMap'), { map: paperMap }, { merge:false }); }
  catch (e) { console.warn('paperMap save', e); showToast('Could not save — check your connection', 'error'); }
}

async function renderPapersPage(){
  const body = document.getElementById('papersBody');
  if (!body) return;
  body.innerHTML = '<div style="padding:48px;text-align:center;color:var(--text-muted);">Loading past-paper analysis…</div>';
  // loadAttemptStats gives each chip the student's live success rate; never let
  // it block the analysis if it errors.
  await Promise.all([ loadPaperData(true), loadPaperMap(true), (typeof loadAttemptStats === 'function' ? loadAttemptStats().catch(()=>{}) : Promise.resolve()) ]);
  ppRenderBody();
  _ppFocusScroll();   // returning from an edit? jump back to that question
}
// Scroll the question we were editing back into view and flash it, so the admin
// lands exactly where they left off in the Past Papers page.
function _ppFocusScroll(){
  if (!_ppReturnFocus) return;
  const id = _ppReturnFocus; _ppReturnFocus = null;
  requestAnimationFrame(() => {
    const sel = '[data-ppid="' + (window.CSS && CSS.escape ? CSS.escape(id) : id) + '"]';
    const el = document.querySelector('#papersBody ' + sel);
    if (!el) return;
    try { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_) { el.scrollIntoView(); }
    const chip = el.classList.contains('pp-chip') ? el : (el.querySelector('.pp-chip') || el);
    chip.style.transition = 'box-shadow .3s ease';
    chip.style.boxShadow = '0 0 0 3px var(--primary,#0b6b4f)';
    setTimeout(() => { chip.style.boxShadow = ''; }, 2200);
  });
}

function ppMarksByTopic(){ const m = {}; ppQuestions().forEach(q => { const t = ppTopicOf(q); m[t] = (m[t] || 0) + (Number(q.marks) || 0); }); return m; }
function ppAssignedCount(){ return ppQuestions().filter(q => ppBankQ(q.id)).length; }
function ppRecurringMarks(c){ return (c.hits || []).reduce((s, id) => { const q = ppFindQ(id); return s + (q ? (Number(q.marks) || 0) : 0); }, 0); }

function ppRenderBody(){
  const body = document.getElementById('papersBody');
  if (!body) return;
  const admin = ppIsAdmin();
  const edit = admin && ppEditMode;
  const qs = ppQuestions();
  const total = qs.length;
  const assigned = ppAssignedCount();
  const totalMarks = qs.reduce((s,q)=>s+(Number(q.marks)||0),0);
  const openMarks = qs.filter(q => q.type === 'open').reduce((s,q)=>s+(Number(q.marks)||0),0);
  const years = ppYears();

  // --- recurring concepts ---
  const rec = ppRecurring().slice().sort((a,b)=> ((b.hits||[]).length - (a.hits||[]).length) || (ppRecurringMarks(b) - ppRecurringMarks(a)));
  [..._ppPrintSel].forEach(id => { if (!rec.some(c => c.id === id)) _ppPrintSel.delete(id); }); // drop deleted concepts
  const recCards = rec.map(c => {
    const hits = (c.hits || []).filter(id => ppFindQ(id));
    const yrs = new Set(hits.map(id => ppFindQ(id).year)).size;
    const span = yrs >= years.length && years.length > 1 ? 'in every year' : (yrs > 1 ? 'in ' + yrs + ' of ' + years.length + ' years' : '');
    const mk = ppRecurringMarks(c);
    const chips = hits.map(id => ppChipByKey(id)).join('') || '<span style="color:var(--text-muted);font-size:0.8rem;">No questions linked yet</span>';
    const attached = hits.filter(id => ppBankQ(id)).length;
    const tools = edit
      ? `<span class="pp-tools"><button class="pp-mini" title="Edit concept" onclick="ppEditConcept('${c.id}')">&#9998; Edit</button><button class="pp-mini del" title="Delete concept" onclick="ppDeleteConcept('${c.id}')">&times; Delete</button></span>`
      : `<span class="pp-tools"><button class="pp-mini" title="Print this concept's ${attached} attached question${attached === 1 ? '' : 's'} as a worksheet — answer key on the last pages" onclick="ppPrintConcept('${c.id}')">🖨 Print</button><label class="pp-print-check" title="Tick to include this concept in “Print selected” at the top"><input type="checkbox" ${_ppPrintSel.has(c.id) ? 'checked' : ''} onchange="ppTogglePrintSel('${c.id}', this.checked)"></label></span>`;
    return `<div class="pp-rec">
      <div class="pp-rec-head"><span class="pp-rec-count">${hits.length}&times;</span><span class="pp-rec-title">${escapeHtml(c.concept || 'Untitled concept')}</span>${tools}</div>
      <div class="pp-rec-topic">${escapeHtml(c.topic || '')}${span ? ' &middot; ' + span : ''}${mk ? ' &middot; ~' + mk + ' marks across the papers' : ''}</div>
      <div class="pp-chip-row">${chips}</div>
      <div class="pp-rec-note">${escapeHtml(c.note || '')}</div>
    </div>`;
  }).join('') || '<div style="color:var(--text-muted);padding:8px;">No recurring concepts yet.</div>';
  const addConcept = edit ? `<button class="pp-add" onclick="ppAddConcept()">+ Add concept</button>` : '';
  const printSelBtn = !edit ? `<button class="pp-add" id="ppPrintSelBtn" ${_ppPrintSel.size ? '' : 'disabled'} title="Print every attached question from the concepts you ticked below as ONE worksheet — questions first, the full answer key on the last pages. Tick concepts with the checkbox at their top-right corner." onclick="ppPrintSelected()">🖨 Print selected${_ppPrintSel.size ? ' (' + _ppPrintSel.size + ')' : ''}</button>` : '';

  // --- question map ---
  const yearGroups = years.map(y => {
    const yq = qs.filter(q => String(q.year) === y).sort((a,b)=> (Number(a.n)||0) - (Number(b.n)||0));
    const yAssigned = yq.filter(q => ppBankQ(q.id)).length;
    const chips = yq.map(q => edit ? ppChipEdit(q) : ppChip(q)).join('') || '<span style="color:var(--text-muted);font-size:0.8rem;">No questions</span>';
    const addBtn = edit ? `<button class="pp-add sm" onclick="ppAddQuestion('${y}')">+ Add question</button>` : '';
    const practiceBtn = (!edit && yAssigned) ? `<button class="pp-mini" title="Practise all ${yAssigned} attached question${yAssigned === 1 ? '' : 's'} from the ${escapeHtml(y)} paper on the system" onclick="ppPracticeYear('${escapeHtml(y)}')">▶ Practice now</button>` : '';
    const printBtn = (!edit && (admin || yAssigned)) ? `<button class="pp-mini" title="Print the whole ${escapeHtml(y)} paper — all ${yAssigned} attached question${yAssigned === 1 ? '' : 's'} in question order, answer key on the last pages" onclick="ppPrintYear('${escapeHtml(y)}')">🖨 Print year</button>` : '';
    // Whole-paper editor: every question in this year on ONE screen, no
    // question-by-question clicking.
    const bulkEditBtn = admin ? `<button class="pp-mini pp-bulkedit" title="Open the whole ${escapeHtml(y)} paper in one editor — change every question's number, marks, topic, skill, difficulty, title, analysis and answer, then save once" onclick="ppOpenPaperEdit('${escapeHtml(y)}')">🗂 Edit whole paper</button>` : '';
    const yearTools = (bulkEditBtn || practiceBtn || printBtn) ? `<span class="pp-tools">${bulkEditBtn}${practiceBtn}${printBtn}</span>` : '';
    return `<div class="pp-year">
      <div class="pp-year-head"><strong>${escapeHtml(y)}</strong> <span class="pp-year-sub">${yq.length} questions &middot; ${yAssigned}/${yq.length} attached</span> ${addBtn}${yearTools}</div>
      <div class="pp-chip-row">${chips}</div>
    </div>`;
  }).join('');
  const addYear = edit ? `<button class="pp-add" onclick="ppAddQuestion('')">+ Add a paper / question in a new year</button>` : '';

  // --- topic breakdown ---
  // Each bar is stacked by year (oldest = lightest tint, newest = full colour).
  // Clicking a year block opens that year's questions; clicking the topic name
  // opens the whole topic as a printable / practisable worksheet.
  const byTopic = ppMarksByTopic();
  const topicRows = Object.keys(byTopic).sort((a,b)=> byTopic[b] - byTopic[a]);
  _ppTopicOrder = topicRows;
  const maxT = topicRows.length ? Math.max.apply(null, topicRows.map(t => byTopic[t])) : 1;
  const bars = topicRows.map((t, ti) => {
    const tq = qs.filter(q => ppTopicOf(q) === t);
    const asg = tq.filter(q => ppBankQ(q.id)).length;
    const cnt = tq.length;
    const tYears = years.filter(y => tq.some(q => String(q.year) === y));
    const segs = tYears.map((y, yi) => {
      const yq = tq.filter(q => String(q.year) === y);
      const mk = yq.reduce((s,q)=>s+(Number(q.marks)||0),0);
      if (!mk) return '';
      const w = mk / maxT * 100;
      const tint = tYears.length > 1 ? (0.42 * (tYears.length - 1 - yi) / (tYears.length - 1)) : 0;
      const label = w >= 8 ? `<span class="pp-seg-lb">${escapeHtml(y)}</span>` : '';
      return `<div class="pp-bar-seg" style="width:${w.toFixed(2)}%;background:linear-gradient(rgba(255,255,255,${tint.toFixed(2)}),rgba(255,255,255,${tint.toFixed(2)})),${ppThemeColor(t)};" title="${escapeHtml(y)}: ${mk} mark${mk === 1 ? '' : 's'} &middot; ${yq.length} question${yq.length === 1 ? '' : 's'} — click to see them" onclick="ppTopicOpen(${ti},'${escapeHtml(y)}')">${label}</div>`;
    }).join('');
    return `<div class="pp-bar-row">
      <div class="pp-bar-name"><span class="pp-dot" style="background:${ppThemeColor(t)}"></span><span class="pp-topic-link" title="Open all ${cnt} question${cnt === 1 ? '' : 's'} in this topic — print them as a worksheet or practise them" onclick="ppTopicOpen(${ti})">${escapeHtml(t)}</span> <span class="pp-lv">${ppLevel(t)}</span></div>
      <div class="pp-bar-track">${segs}</div>
      <div class="pp-bar-val">${byTopic[t]}m &middot; ${asg}/${cnt}</div>
    </div>`;
  }).join('') || '<div style="color:var(--text-muted);">No questions yet.</div>';
  const legend = Object.keys(PP_THEME_NAME).map(k => `<span class="pp-lg"><span class="pp-dot" style="background:${PP_THEME_C[k]}"></span>${PP_THEME_NAME[k]}</span>`).join('');

  // --- practise the papers (all years + each year, on the system or in a game) ---
  const pRows = [{ y: '', avail: ppAttachedBankQs('').length }]
    .concat(years.slice().reverse().map(y => ({ y, avail: ppAttachedBankQs(y).length })));
  const practiceRows = pRows.map(r => `
    <div class="pp-pr-row">
      <div class="pp-pr-info"><div class="pp-pr-title">${r.y ? '📄 PSLE ' + escapeHtml(r.y) : '📚 All years'}</div><div class="pp-pr-sub">${r.avail} question${r.avail === 1 ? '' : 's'} ready to practise</div></div>
      <div class="pp-pr-btns">
        <button class="pp-add" ${r.avail ? '' : 'disabled'} title="Practise ${r.y ? 'the ' + escapeHtml(r.y) + ' paper' : 'every attached past-paper question'} on the system — MCQ and open-ended, marked as usual" onclick="ppPracticeYear('${escapeHtml(r.y)}')">▶ ${r.y ? 'Practice now' : 'Practice all'}</button>
        ${r.y ? `<button class="pp-add" ${r.avail ? '' : 'disabled'} title="Print the whole ${escapeHtml(r.y)} paper as a worksheet — answer key on the last pages" onclick="ppPrintYear('${escapeHtml(r.y)}')">🖨 Print paper</button>` : ''}
      </div>
    </div>`).join('');
  const practiceCard = `
    <div class="pp-card">
      <h3 class="pp-h">Practise the papers</h3>
      <p class="pp-sub">Do the attached questions right here on the system — the whole set or one year's paper — or load them into a mini-game (MCQ and open-ended). <b>Game bonus: every past-paper question answered inside a game counts ×2 on the Questions and PSLE Papers leaderboards.</b></p>
      ${practiceRows}
    </div>`;

  const toggle = admin ? `<button class="pp-editbtn ${edit ? 'on' : ''}" onclick="ppToggleEdit()">${edit ? '✓ Done editing' : '✎ Add / edit questions'}</button>` : '';
  const roleLine = !admin
    ? 'Tap any highlighted question to practise it. Hover to preview. Greyed-out questions have not been added yet. Use “Practise the papers” below to do a whole year in one go — or play it inside a game, where every question counts ×2 on the leaderboards! The 🖨 buttons print a year or a concept as a worksheet, with the answer key on the last pages.'
    : (edit
      ? 'Editing: use <strong>🗂 Edit whole paper</strong> on any year to edit every question in that paper on one screen (and change many at once) — or <strong>+ Add question</strong> to key in a single new past-paper question yourself. <strong>+ Add a paper / question in a new year</strong> starts a new year. Click a question or concept to change its details, or × to remove it. Turn editing off to attach bank questions.'
      : 'Click any question to attach one from your bank — or create a brand-new question for it on the spot — and to set its difficulty (🟢/🟡/🔴, colours the chip on this page only); students can then practise it. Hover a question to preview. Need to fix a whole paper? <strong>🗂 Edit whole paper</strong> on any year opens all of its questions on one screen, with bulk topic / skill / difficulty / marks changes and one Save — no clicking question by question. Use the 🖨 buttons to print a concept or a whole year (answer key on the last pages), and the checkboxes to print several concepts together.');

  body.innerHTML = ppStyles() + `
  <div class="pp-wrap">
    <div class="pp-topbar">
      <div class="pp-tiles">
        <div class="pp-tile"><div class="pp-tile-l">Papers</div><div class="pp-tile-v">${years.length}</div><div class="pp-tile-h">${years.length ? years[0] + '–' + years[years.length-1] : '—'} &middot; ${total} questions</div></div>
        <div class="pp-tile"><div class="pp-tile-l">Attached</div><div class="pp-tile-v">${assigned}<span style="font-size:1rem;color:var(--text-muted);font-weight:500;">/${total}</span></div><div class="pp-tile-h">questions ready to practise</div></div>
        <div class="pp-tile"><div class="pp-tile-l">Open-ended</div><div class="pp-tile-v">${totalMarks ? Math.round(openMarks/totalMarks*100) : 0}%</div><div class="pp-tile-h">of the marks</div></div>
        <div class="pp-tile"><div class="pp-tile-l">Recurring concepts</div><div class="pp-tile-v">${ppRecurring().length}</div><div class="pp-tile-h">patterns across the papers</div></div>
      </div>
      ${toggle}
    </div>

    <div class="pp-note">${roleLine}</div>
    ${practiceCard}
    <div class="pp-card">
      <h3 class="pp-h">The concepts that keep coming back ${addConcept}${printSelBtn}</h3>
      <p class="pp-sub">Patterns that recur across the papers — the highest-yield things to master, ordered by how many questions touched each.</p>
      ${recCards}
    </div>

    <div class="pp-card">
      <h3 class="pp-h">Question map — every question, every year ${addYear}
        <span class="pp-diff-legend"><span><span class="pp-lg-box" style="background:#0f7a5a;"></span>Easy</span><span><span class="pp-lg-box" style="background:#b7791f;"></span>Moderate</span><span><span class="pp-lg-box" style="background:#b23b36;"></span>Difficult</span></span>
      </h3>
      <p class="pp-sub">All ${total} questions, classified into your portal's topics. Chips are colour-coded by difficulty (green / yellow / red). ${edit ? 'Click a question to edit it, use the drop-down to set its difficulty, or × to remove it.' : (admin ? 'A &#10003; marks questions with a bank question attached. ' : 'Highlighted questions are available to practise, with your success rate shown.')}</p>
      ${yearGroups}
    </div>

    <div class="pp-card">
      <h3 class="pp-h">Marks by topic</h3>
      <p class="pp-sub">Where the marks fall across the papers — each bar is split into the years (lighter = older). Click a year block to see that year's questions, or click a topic name to open every question in the topic as a worksheet you can print and practise. The count shows how many of that topic's questions have a bank question attached.</p>
      <div class="pp-legend">${legend}</div>
      ${bars}
    </div>
  </div>`;
  // keep the topic drill-down modal in sync (e.g. after attaching a question from inside it)
  if (_ppTopicSel) ppTopicRender();
}

// A small accuracy badge for students: their live success rate on the attached
// bank question (correct attempts / total attempts). Hidden for admins and when
// the question has never been attempted.
function ppAccBadge(bq){
  if (ppIsAdmin() || !bq) return '';
  const pct = questionPercent(bq.id);
  return (pct == null) ? '' : `<span class="pp-chip-acc" title="Your success rate on this question">${pct}%</span>`;
}
function ppChip(q){
  const bq = ppBankQ(q.id);
  const admin = ppIsAdmin();
  let cls = 'pp-chip';
  if (bq) cls += ' assigned';
  else if (admin) cls += ' open';
  else cls += ' muted';
  cls += ppDiffClass(q);
  const click = admin ? `ppOpenAssign('${q.id}')` : (bq ? `ppPractise('${q.id}')` : '');
  const mark = bq ? ' &#10003;' : '';
  return `<span class="${cls}" data-ppid="${escapeHtml(String(q.id))}" ${click ? `onclick="${click}"` : ''} onmouseenter="ppHoverShow(event,'${q.id}')" onmousemove="ppHoverMove(event)" onmouseleave="ppHoverChipLeave()">Q${escapeHtml(String(q.n))}<span class="pp-chip-yr">${escapeHtml(String(q.year))}</span>${mark}${ppAccBadge(bq)}</span>`;
}
function ppDiffSelect(q){
  const d = ppDiff(q);
  return `<select class="pp-diff-sel" title="Set difficulty (colours this chip — past-paper only)" onchange="ppSetDifficulty('${q.id}', this.value)" onclick="event.stopPropagation()">
    <option value="" ${!d ? 'selected' : ''}>◻ diff</option>
    <option value="easy" ${d === 'easy' ? 'selected' : ''}>🟢 Easy</option>
    <option value="moderate" ${d === 'moderate' ? 'selected' : ''}>🟡 Moderate</option>
    <option value="hard" ${d === 'hard' ? 'selected' : ''}>🔴 Difficult</option>
  </select>`;
}
function ppChipEdit(q){
  const bq = ppBankQ(q.id);
  return `<span class="pp-chip-edit" data-ppid="${escapeHtml(String(q.id))}">
    <span class="pp-chip open ${bq ? 'assigned' : ''}${ppDiffClass(q)}" title="Edit this question" onclick="ppEditQuestion('${q.id}')" onmouseenter="ppHoverShow(event,'${q.id}')" onmousemove="ppHoverMove(event)" onmouseleave="ppHoverChipLeave()">Q${escapeHtml(String(q.n))}<span class="pp-chip-yr">${escapeHtml(String(q.year))}</span>${bq ? ' &#10003;' : ''}</span>
    ${ppDiffSelect(q)}
    <button class="pp-mini del" title="Remove question" onclick="ppDeleteQuestion('${q.id}')">&times;</button>
  </span>`;
}
function ppChipByKey(id){
  const q = ppFindQ(id);
  if (!q) return '';
  const bq = ppBankQ(id);
  const admin = ppIsAdmin();
  let cls = 'pp-chip wide';
  if (bq) cls += ' assigned';
  else if (admin && !ppEditMode) cls += ' open';
  else cls += ' muted';
  cls += ppDiffClass(q);
  const click = (admin && !ppEditMode) ? `ppOpenAssign('${id}')` : (!admin && bq ? `ppPractise('${id}')` : '');
  const mark = bq ? ' &#10003;' : '';
  return `<span class="${cls}" ${click ? `onclick="${click}"` : ''} onmouseenter="ppHoverShow(event,'${id}')" onmousemove="ppHoverMove(event)" onmouseleave="ppHoverChipLeave()">${escapeHtml(String(q.year))} Q${escapeHtml(String(q.n))}${mark}${ppAccBadge(bq)}</span>`;
}

// -------- hover preview --------
function ppHoverEl(){
  if (!_ppHoverEl) {
    _ppHoverEl = document.createElement('div');
    _ppHoverEl.id = 'ppHover';
    // Once the preview is locked open, the cursor can enter it: keep it open
    // while inside, and close shortly after the cursor leaves it.
    _ppHoverEl.addEventListener('mouseenter', () => { clearTimeout(_ppHoverGrace); });
    _ppHoverEl.addEventListener('mouseleave', () => { if (_ppHoverLocked) ppHoverHide(); });
    document.body.appendChild(_ppHoverEl);
  }
  return _ppHoverEl;
}
// "Not in syllabus" ribbon for the past-paper previews — explains why an
// attached question shows here but never appears in practice.
function _ppNisBadge(bq){
  // Same predicate the serving code uses, so a question hidden by the TOPIC
  // rule wears the ribbon too — it used to read the hand-ticked flag only, and
  // a Cell Systems question showed here with nothing explaining why.
  if (!bq || qInSyllabus(bq)) return '';
  return `<div style="margin:6px 0;padding:5px 9px;border-radius:8px;background:#fdf4e3;border:1px solid #e0b768;color:#7a5410;font-size:0.74rem;font-weight:600;">🚫 Not in syllabus — kept here for reference; it is not served in any practice mode.</div>`;
}
function ppHoverHtml(id){
  const q = ppFindQ(id);
  if (!q) return '';
  const bq = ppBankQ(id);
  const diff = ppDiff(q);
  const diffLabel = { easy: '🟢 Easy', moderate: '🟡 Moderate', hard: '🔴 Difficult' }[diff] || '';
  const diffLine = diffLabel ? `<div class="pp-hv-topic" style="font-weight:600;">Difficulty: ${diffLabel}</div>` : '';
  const _topic = ppTopicOf(q);
  const head = `<div class="pp-hv-head"><strong>${escapeHtml(String(q.year))} &middot; Q${escapeHtml(String(q.n))}</strong> &middot; ${escapeHtml(String(q.marks))}m &middot; Booklet ${escapeHtml(String(q.bk||''))}</div>
    <div class="pp-hv-topic"><span class="pp-dot" style="background:${ppThemeColor(_topic)}"></span>${escapeHtml(_topic || '')} &middot; ${ppLevel(_topic)} &middot; ${escapeHtml(ppSkillName(q.type))}</div>${diffLine}`;
  if (bq) {
    // Student's live success rate on the attached question (all platforms).
    const st = questionStats(bq.id);
    const accLine = (st.percent != null) ? `<div class="pp-hv-note" style="color:var(--primary,#0b6b4f);font-style:normal;">Your success rate: <strong>${st.percent}%</strong> (${st.correct}/${st.attempts} correct)</div>` : '';
    // Admins get a direct "Edit question" button in the locked preview — it opens
    // the block editor and, when they finish, brings them back to Past Papers
    // scrolled to this very question, so they don't lose their place.
    const editBtn = ppIsAdmin()
      ? `<div class="pp-hv-actions"><button type="button" class="pp-hv-edit" onclick="ppHoverEditAttached('${escapeHtml(String(id))}','${escapeHtml(String(bq.id))}')">✏️ Edit question</button></div>`
      : '';
    return head + `<div class="pp-hv-assigned">&#10003; Attached: ${escapeHtml(bq.title || 'Untitled')}</div>${_ppNisBadge(bq)}
      <div class="pp-hv-preview">${renderQuestionPreviewHtml(bq.id)}</div>${accLine}${editBtn}
      <div class="pp-hv-note">${ppIsAdmin() ? (ppEditMode ? 'Click the chip to edit this question.' : 'Click the chip to change or remove the attachment.') : 'Click to practise.'}</div>`;
  }
  const b = paperMap[id];
  const missing = b ? '<div class="pp-hv-note" style="color:var(--accent-red,#c0392b);">The attached question is not in the bank — it may be awaiting vetting approval, or it was deleted.</div>' : '';
  return head + `<div class="pp-hv-title">${escapeHtml(q.title || '')}</div>
    <div class="pp-hv-detail">${escapeHtml(q.detail || '')}</div>${missing}
    <div class="pp-hv-note">${ppIsAdmin() ? (ppEditMode ? 'Click to edit this question.' : 'Click to attach a bank question — or create one on the spot.') : 'Not yet available to practise.'}</div>`;
}
let _ppHoverTimer = null;         // fires the "expand to full preview" after a dwell
let _ppHoverLast = null;          // last pointer position, so we can re-anchor on expand
let _ppHoverLocked = false;       // true once expanded: the card is interactive & scrollable
let _ppHoverGrace = null;         // brief delay when leaving a chip, so the cursor can reach the card
const PP_HOVER_EXPAND_MS = 2000;  // dwell time before the preview blooms open
function _ppHoverOpen(html, ev){
  const el = ppHoverEl();
  clearTimeout(_ppHoverGrace);
  _ppHoverLocked = false;
  el.innerHTML = html;
  el.classList.remove('pp-hv-expanded');   // start collapsed every time
  el.style.display = 'block';
  el.scrollTop = 0;
  ppHoverMove(ev);
  // Dwell for a few seconds on the same question → smoothly expand to full view.
  clearTimeout(_ppHoverTimer);
  _ppHoverTimer = setTimeout(ppHoverExpand, PP_HOVER_EXPAND_MS);
}
function ppHoverShow(ev, id){ _ppHoverOpen(ppHoverHtml(id), ev); }
// Same hover preview for a BANK question — used in the "attach a question"
// picker so the teacher can read the full question before selecting it.
function ppBankHoverHtml(qid, note){
  const bq = questionBank.find(q => q.id === qid);
  if (!bq) return '';
  const cat = bq.category ? ' &middot; ' + escapeHtml(normalizeCategoryValue(bq.category)) : '';
  const st = questionStats(bq.id);
  const accLine = (st && st.percent != null) ? `<div class="pp-hv-note" style="color:var(--primary,#0b6b4f);font-style:normal;">Your success rate: <strong>${st.percent}%</strong> (${st.correct}/${st.attempts} correct)</div>` : '';
  return `<div class="pp-hv-head"><strong>${escapeHtml(bq.title || 'Untitled')}</strong></div>
    <div class="pp-hv-topic"><span class="pp-dot" style="background:${ppThemeColor(bq.topic)}"></span>${escapeHtml(bq.topic || '')}${cat}</div>${_ppNisBadge(bq)}
    <div class="pp-hv-preview">${renderQuestionPreviewHtml(bq.id)}</div>${accLine}
    <div class="pp-hv-note">${escapeHtml(note || 'Click to attach this question.')}</div>`;
}
// `note` lets a caller say what clicking actually does here — the same preview
// is used to attach a question (Past Papers), tick one (Learning Objectives)
// and practise one, and a wrong instruction is worse than none.
function ppHoverShowBank(ev, qid, note){ _ppHoverOpen(ppBankHoverHtml(qid, note), ev); }
function ppHoverMove(ev){
  const el = _ppHoverEl; if (!el || el.style.display !== 'block') return;
  _ppHoverLast = { x: ev.clientX, y: ev.clientY };
  // Once expanded the card settles in place — don't chase the cursor any more.
  if (el.classList.contains('pp-hv-expanded')) return;
  const pad = 14, w = el.offsetWidth || 360, h = el.offsetHeight || 240;
  let x = ev.clientX + pad, y = ev.clientY + pad;
  if (x + w > window.innerWidth - 8) x = ev.clientX - w - pad;
  if (y + h > window.innerHeight - 8) y = Math.max(8, window.innerHeight - h - 8);
  el.style.left = Math.max(8, x) + 'px';
  el.style.top = Math.max(8, y) + 'px';
}
// Bloom the partial preview into a full one and re-anchor it so the taller card
// stays fully on-screen (both moves are CSS-transitioned for a premium feel).
function ppHoverExpand(){
  const el = _ppHoverEl; if (!el || el.style.display !== 'block') return;
  el.classList.add('pp-hv-expanded');
  _ppHoverLocked = true;   // now interactive & scrollable — the cursor can move into it
  // A one-time hint that the card can be scrolled, if the content overflows.
  if (!el.querySelector('.pp-hv-scrollhint')) {
    const hint = document.createElement('div');
    hint.className = 'pp-hv-scrollhint';
    hint.textContent = '↕ scroll to read the whole question';
    el.appendChild(hint);
  }
  requestAnimationFrame(() => {
    const hint = el.querySelector('.pp-hv-scrollhint');
    if (hint) hint.style.display = (el.scrollHeight > el.clientHeight + 4) ? 'block' : 'none';
    const p = _ppHoverLast || { x: window.innerWidth / 2, y: window.innerHeight / 2 };
    const pad = 14, w = el.offsetWidth || 400;
    const targetH = Math.min(el.scrollHeight + 4, Math.round(window.innerHeight * 0.86));
    let x = p.x + pad, y = p.y + pad;
    if (x + w > window.innerWidth - 8) x = p.x - w - pad;
    if (y + targetH > window.innerHeight - 8) y = Math.max(8, window.innerHeight - targetH - 8);
    el.style.left = Math.max(8, x) + 'px';
    el.style.top = Math.max(8, y) + 'px';
  });
}
// Admin action from the locked preview: open the block editor for the attached
// question, remembering to return to Past Papers (scrolled to this question)
// when the edit is saved or cancelled — so no place is lost.
function ppHoverEditAttached(ppId, bankId){
  if (!ppIsAdmin()) return;
  ppHoverHide();
  editQuestionFromPapers(bankId, ppId);
}
// A chip's mouse-leave: while the preview is locked open, don't close instantly —
// give the cursor a moment to travel into the card (which cancels the close).
function ppHoverChipLeave(){
  if (_ppHoverLocked) { clearTimeout(_ppHoverGrace); _ppHoverGrace = setTimeout(ppHoverHide, 260); return; }
  ppHoverHide();
}
function ppHoverHide(){
  clearTimeout(_ppHoverTimer);
  clearTimeout(_ppHoverGrace);
  _ppHoverLocked = false;
  if (_ppHoverEl) { _ppHoverEl.style.display = 'none'; _ppHoverEl.classList.remove('pp-hv-expanded'); }
}
// Esc closes a locked preview; a click anywhere outside it does too.
document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && _ppHoverLocked) ppHoverHide(); });
document.addEventListener('pointerdown', function (e) {
  if (_ppHoverLocked && _ppHoverEl && !_ppHoverEl.contains(e.target) && !(e.target.closest && e.target.closest('.pp-chip, .pp-arow'))) ppHoverHide();
}, true);

// -------- edit mode --------
function ppToggleEdit(){ if (!ppIsAdmin()) return; ppEditMode = !ppEditMode; ppHoverHide(); ppRenderBody(); }

// -------- attach modal --------
function ppOpenAssign(id){
  if (!ppIsAdmin() || ppEditMode) return;
  ppHoverHide();
  _ppAssignKey = id;
  const q = ppFindQ(id);
  const t = document.getElementById('ppAssignTitle');
  const info = document.getElementById('ppAssignInfo');
  if (t) t.textContent = `${q.year} Q${q.n} — ${q.topic}`;
  if (info) info.innerHTML = `<div style="font-size:0.82rem;color:var(--text-muted);">${q.marks} mark(s) &middot; Booklet ${escapeHtml(String(q.bk||''))} &middot; ${escapeHtml(ppSkillName(q.type))} &middot; ${ppLevel(q.topic)}</div>
    <div style="margin-top:4px;font-weight:600;">${escapeHtml(q.title || '')}</div>
    <div style="margin-top:4px;font-size:0.85rem;color:var(--text-muted);">${escapeHtml(q.detail || '')}</div>`;
  const s = document.getElementById('ppAssignSearch'); if (s) s.value = '';
  ppRenderAssignDiff();
  ppRenderAssignList();
  const ov = document.getElementById('ppAssignOverlay'); if (ov) ov.classList.add('active');
}
function ppCloseAssign(){ const ov = document.getElementById('ppAssignOverlay'); if (ov) ov.classList.remove('active'); }

// Difficulty picker inside the attach modal — admin clicks a chip, then tags
// the question 🟢/🟡/🔴 here. Stored on the PAST-PAPER record only (q.diff in
// paperData); the attached bank question is never touched.
function ppRenderAssignDiff(){
  const wrap = document.getElementById('ppAssignDiff');
  if (!wrap) return;
  const q = _ppAssignKey ? ppFindQ(_ppAssignKey) : null;
  if (!q || !ppIsAdmin()) { wrap.innerHTML = ''; return; }
  const cur = ppDiff(q);
  const opts = [ ['', '◻ Not set'], ['easy', '🟢 Easy'], ['moderate', '🟡 Moderate'], ['hard', '🔴 Difficult'] ];
  wrap.innerHTML = `<span style="font-size:0.8rem;font-weight:600;color:var(--text-muted);">Difficulty:</span>` +
    opts.map(([v, label]) => `<button type="button" class="pp-diffpick${cur === v ? ' on ' + (v ? 'pp-diff-' + v : '') : ''}" onclick="ppAssignSetDiff('${v}')">${label}</button>`).join('') +
    `<span style="font-size:0.72rem;color:var(--text-muted);">colours this chip — past-paper page only</span>`;
}
async function ppAssignSetDiff(level){
  if (!_ppAssignKey) return;
  await ppSetDifficulty(_ppAssignKey, level);   // saves + re-renders the chips behind the modal
  ppRenderAssignDiff();                          // keep the modal open, refresh the highlight
}
// How recently a bank question was added — its createdAt timestamp, else the
// millisecond stamp baked into its "q_<ms>_…" id, else 0 (treated as oldest).
function _questionRecency(x){
  if (x && x.createdAt) { const t = Date.parse(x.createdAt); if (!isNaN(t)) return t; }
  const m = /^q_(\d{10,})/.exec(String((x && x.id) || ''));
  return m ? Number(m[1]) : 0;
}
function ppRenderAssignList(){
  const id = _ppAssignKey; if (!id) return;
  const q = ppFindQ(id); if (!q) return;
  const term = (document.getElementById('ppAssignSearch')?.value || '').toLowerCase().trim();
  const cur = paperMap[id];
  let list = questionBank.slice();
  if (term) {
    list = list.filter(x => ((x.title || '') + ' ' + (x.topic || '') + ' ' + (x.category || '') + ' ' + getQuestionPreview(x)).toLowerCase().includes(term));
    // While searching, float same-topic matches up, then alphabetical.
    list.sort((a,b)=> ((a.topic === q.topic ? 0 : 1) - (b.topic === q.topic ? 0 : 1)) || String(a.title||'').localeCompare(String(b.title||'')));
  } else {
    // Default view: newest questions first — the one you just created and likely
    // want to attach sits right at the top.
    list.sort((a,b)=> _questionRecency(b) - _questionRecency(a) || String(a.title||'').localeCompare(String(b.title||'')));
  }
  const shown = list.slice(0, 80);
  const rows = shown.map(x => {
    const sel = x.id === cur;
    const same = x.topic === q.topic;
    return `<div class="pp-arow ${sel ? 'sel' : ''}" onclick="ppAssign('${id}','${x.id}')" onmouseenter="ppHoverShowBank(event,'${x.id}')" onmousemove="ppHoverMove(event)" onmouseleave="ppHoverChipLeave()">
      <div style="flex:1;min-width:0;">
        <div class="pp-arow-title">${escapeHtml(x.title || 'Untitled')}${sel ? ' <span style="color:var(--primary);font-weight:700;">&#10003; attached</span>' : ''}</div>
        <div class="pp-arow-sub">${same ? '<span class="pp-match">same topic</span> ' : ''}${escapeHtml(x.topic || '')}${x.category ? ' &middot; ' + escapeHtml(x.category) : ''}</div>
        <div class="pp-arow-prev">${escapeHtml(getQuestionPreview(x))}</div>
      </div>
    </div>`;
  }).join('') || `<div style="color:var(--text-muted);padding:20px;text-align:center;">No matching questions in your bank.${term ? ' Try a different search.' : ''}</div>`;
  document.getElementById('ppAssignList').innerHTML = rows;
  const un = document.getElementById('ppUnassignBtn'); if (un) un.style.display = cur ? '' : 'none';
  const pr = document.getElementById('ppAssignPractiseBtn'); if (pr) pr.style.display = cur ? '' : 'none';
  // Show "Edit this question" only when the attached question is in this bank.
  const ed = document.getElementById('ppEditQBtn'); if (ed) ed.style.display = (cur && questionBank.some(qb => qb.id === cur)) ? '' : 'none';
  const cnt = document.getElementById('ppAssignCount'); if (cnt) cnt.textContent = list.length + ' question' + (list.length === 1 ? '' : 's') + (list.length > shown.length ? ' (showing first ' + shown.length + ')' : '') + (term ? '' : ' · newest first');
}
async function ppAssign(id, qid){ ppHoverHide(); paperMap[id] = qid; await savePaperMap(); ppRenderAssignList(); ppRenderBody(); showToast('Question attached — students can now practise it', 'success'); }
async function ppUnassign(){ const id = _ppAssignKey; if (!id) return; ppHoverHide(); delete paperMap[id]; await savePaperMap(); ppRenderAssignList(); ppRenderBody(); showToast('Attachment removed', 'info'); }
function ppPractise(id){ const bq = ppBankQ(id); if (!bq) { showToast('This question is not available to practise', 'error'); return; } ppHoverHide(); ppCloseAssign(); ppTopicClose(); launchWorksheetPractice([bq]); }
// Edit the attached bank question in the full editor, returning to Past Papers on save.
function ppEditAttachedQuestion(){
  const id = _ppAssignKey; if (!id) return;
  const bq = ppBankQ(id);
  if (!bq) { showToast('The attached question is not in your bank', 'error'); return; }
  ppHoverHide(); ppCloseAssign();
  editQuestionFromPapers(bq.id, id);
}
function ppAssignPractise(){ if (_ppAssignKey) ppPractise(_ppAssignKey); }

// -------- create a NEW bank question for a past-paper question --------
// Opens the Create Question editor prefilled from the past-paper item; when
// the admin saves (Add to Bank / vetting), the new question is attached
// automatically and they land back on the analysis to pick the next one.
let _ppPendingAttach = null;   // past-paper question id awaiting a new bank question

function ppHasPendingAttach(){ return !!_ppPendingAttach; }
function ppCancelPendingAttach(){
  _ppPendingAttach = null;
  const b = document.getElementById('ppAttachBanner');
  if (b) b.style.display = 'none';
}
function ppCreateForAssign(){
  const id = _ppAssignKey; if (!id) return;
  const q = ppFindQ(id); if (!q) return;
  ppCloseAssign(); ppHoverHide();

  // Fresh editor, prefilled from the past-paper question
  blocks = []; selectedBlanks = {}; currentEditingQuestion = null;
  const cs2 = document.getElementById('categorySelect2'); if (cs2) cs2.value = '';
  const ts2 = document.getElementById('topicSelect2'); if (ts2) ts2.value = '';
  if (typeof _setAnswerKeyFields === 'function') _setAnswerKeyFields('', '');
  const titleEl = document.getElementById('questionTitle');
  if (titleEl) titleEl.value = q.title || (q.year + ' Q' + q.n);
  const cat = (q.bk === 'B' || q.type === 'open') ? 'PSLE - OEQ' : 'PSLE - MCQ';
  const catSel = document.getElementById('categorySelect');
  if (catSel) { catSel.value = cat; _lastCategoryValue = cat; }
  const ts = document.getElementById('topicSelect');
  if (ts && q.topic) {
    if (!Array.from(ts.options).some(o => o.value === q.topic)) {
      const opt = document.createElement('option');
      opt.value = q.topic; opt.textContent = q.topic;
      const mg = ts.querySelector('optgroup[label="── Manage ──"]');
      if (mg) ts.insertBefore(opt, mg); else ts.appendChild(opt);
    }
    ts.value = q.topic; _lastTopicValue = q.topic;
  }
  const mgEl = document.getElementById('questionMarkingGuide');
  if (mgEl) mgEl.value = q.ans ? 'Expected answer: ' + q.ans : '';
  const annEl = document.getElementById('questionAnnotation');
  if (annEl) annEl.checked = false;
  const nisEl = document.getElementById('questionNotInSyllabus');
  if (nisEl) nisEl.checked = false;
  // The past-paper record's own topic/skill make a sensible starting tag, so the
  // admin has something to edit rather than an empty box.
  setQuestionTagsField(q.topic ? { tags: [q.topic] } : null);
  renderBlocks();

  _ppPendingAttach = id;
  const b = document.getElementById('ppAttachBanner');
  const bt = document.getElementById('ppAttachBannerText');
  if (bt) bt.innerHTML = `<strong>${escapeHtml(String(q.year))} Q${escapeHtml(String(q.n))}</strong> &middot; ${escapeHtml(q.topic || '')} &middot; ${escapeHtml(String(q.marks))} mark(s)<br>“${escapeHtml(q.title || '')}” — build the question (typing blocks or Build from screenshot both work), then <strong>Add to Bank</strong>. It will be attached to this analysis question automatically.`;
  if (b) b.style.display = 'flex';

  _skipCreateReset = true;
  navigateTo('create');
  showToast('Build the question, then Add to Bank — it will attach to ' + q.year + ' Q' + q.n, 'info');
}
async function ppConsumePendingAttach(bankQ, toVetting){
  const id = _ppPendingAttach; if (!id || !bankQ) return;
  const q = ppFindQ(id);
  const label = q ? q.year + ' Q' + q.n : 'the past-paper question';
  paperMap[id] = bankQ.id;
  ppCancelPendingAttach();
  await savePaperMap();
  if (toVetting) {
    navigateTo('vetting');
    showToast('Attached to ' + label + ' — it becomes practisable once approved into the bank', 'success');
  } else {
    navigateTo('papers');
    showToast('Attached to ' + label + ' ✓ — click the next question to keep going', 'success');
  }
}

// -------- printing: concepts & whole years --------
// Prints the ATTACHED bank questions (questions first, answer key on the
// last pages) via the shared worksheet print pipeline. Past-paper questions
// with nothing attached are skipped and reported.
let _ppPrintSel = new Set();   // concept ids ticked for "Print selected"

function ppCollectPrintable(hitIds){
  const seen = new Map(); const missing = [];
  (hitIds || []).forEach(id => {
    const q = ppFindQ(id); if (!q) return;
    const label = q.year + ' Q' + q.n;
    const bq = ppBankQ(id);
    if (!bq) { missing.push(label); return; }
    if (seen.has(bq.id)) seen.get(bq.id).refs.push(label);   // same bank question attached to several papers — print once
    else seen.set(bq.id, { bq, refs: [label] });
  });
  return { items: [...seen.values()], missing };
}
// Cover sheet for a past-paper print. `coverTitle` is the paper's own name
// ("PSLE 2017 English Paper"); the line under it names the subject.
function _ppCoverHtml(coverTitle) {
  return _wsCoverHtml(coverTitle, 'Primary English', 'Past Year Paper');
}
async function ppDoPrint(items, missing, title, opts){
  if (!items.length) { showToast('Nothing to print — none of these questions have a bank question attached yet', 'error'); return; }
  const selected = items.map(it => Object.assign({}, it.bq, { title: it.refs.join(' / ') + ' — ' + (it.bq.title || 'Untitled') }));
  const output = document.getElementById('printOutput');
  // Preload every image first (progress shown), so measurement is accurate
  // (no questions cut across pages) and the wait is visible, not a dead click.
  _printProgressShow('Preparing worksheet…', 'Starting…');
  const urls = [];
  selected.forEach(q => { if (q.answerKeyImage) urls.push(transformImageUrl(q.answerKeyImage)); (q.blocks || []).forEach(b => { if (b && b.url && (b.type === 'image' || b.type === 'answerKey')) urls.push(transformImageUrl(b.url)); }); });
  await _preloadImageUrls(urls, (done, tot) => _printProgressUpdate('Loading question images…', 0.05 + 0.7 * (done / tot), done + '/' + tot + ' images'));
  _printProgressUpdate('Laying out pages…', 0.8, 'Measuring each question at print size');
  output.innerHTML = buildWorksheetHtml(selected, title, {
    answerKeyExtras: true,
    plainNumbers: true,
    frontHtml: _ppCoverHtml((opts && opts.coverTitle) || title),
  });
  autoscaleAndPrint(output);
  if (missing.length) {
    const list = missing.length > 6 ? missing.slice(0, 6).join(', ') + ' +' + (missing.length - 6) + ' more' : missing.join(', ');
    showToast('Skipped ' + missing.length + ' with no attached question: ' + list, 'info');
  }
}
function ppPrintConcept(id){
  const c = ppRecurring().find(x => x.id === id); if (!c) return;
  const { items, missing } = ppCollectPrintable(c.hits);
  ppDoPrint(items, missing, c.concept || 'Recurring concept');
}
function ppPrintYear(y){
  const hitIds = ppQuestions().filter(q => String(q.year) === String(y))
    .sort((a,b) => (Number(a.n)||0) - (Number(b.n)||0)).map(q => q.id);
  const { items, missing } = ppCollectPrintable(hitIds);
  ppDoPrint(items, missing, 'PSLE English ' + y, { coverTitle: 'PSLE ' + y + ' English Paper' });
}
function ppPrintSelected(){
  const chosen = ppRecurring().filter(c => _ppPrintSel.has(c.id));
  if (!chosen.length) { showToast('Tick the checkbox on the concepts you want, then print', 'info'); return; }
  const allHits = [];
  chosen.forEach(c => (c.hits || []).forEach(h => allHits.push(h)));
  const { items, missing } = ppCollectPrintable(allHits);
  const title = chosen.length === 1 ? (chosen[0].concept || 'Recurring concept') : 'Recurring Concepts — ' + chosen.length + ' concepts';
  ppDoPrint(items, missing, title);
}
function ppTogglePrintSel(id, checked){
  if (checked) _ppPrintSel.add(id); else _ppPrintSel.delete(id);
  const btn = document.getElementById('ppPrintSelBtn');
  if (btn) {
    const n = _ppPrintSel.size;
    btn.textContent = '🖨 Print selected' + (n ? ' (' + n + ')' : '');
    btn.disabled = !n;
  }
}

// -------- topic drill-down (marks-by-topic graph) --------
// Clicking a year block on a bar opens that year's questions for the topic;
// clicking the topic name opens all years. From the modal anyone can print
// the attached questions as a worksheet or practise them all.
let _ppTopicOrder = [];   // topic names in the order the bars render (index-addressed to avoid quoting topic names in onclick)
let _ppTopicSel = null;   // { topic, year } while the modal is open ('' year = all years)

function ppTopicOpen(idx, year){
  const topic = _ppTopicOrder[idx];
  if (!topic) return;
  ppHoverHide();
  _ppTopicSel = { topic: topic, year: year || '' };
  ppTopicRender();
  const ov = document.getElementById('ppTopicOverlay'); if (ov) ov.classList.add('active');
}
function ppTopicQs(){
  if (!_ppTopicSel) return [];
  return ppQuestions()
    .filter(q => ppTopicOf(q) === _ppTopicSel.topic && (!_ppTopicSel.year || String(q.year) === _ppTopicSel.year))
    .sort((a,b)=> String(a.year).localeCompare(String(b.year)) || (Number(a.n)||0) - (Number(b.n)||0));
}
function ppTopicRender(){
  if (!_ppTopicSel) return;
  const t = _ppTopicSel.topic, yr = _ppTopicSel.year;
  const list = ppTopicQs();
  const marks = list.reduce((s,q)=>s+(Number(q.marks)||0),0);
  const attached = list.filter(q => ppBankQ(q.id)).length;
  const title = document.getElementById('ppTopicTitle');
  if (title) title.innerHTML = `<span class="pp-dot" style="background:${ppThemeColor(t)};width:11px;height:11px;"></span>${escapeHtml(t)} <span class="pp-lv" style="font-size:0.72rem;color:var(--text-muted);font-weight:600;">${ppLevel(t)}</span>${yr ? `<span class="pp-topic-yrtag">${escapeHtml(yr)} only</span>` : ''}`;
  const sub = document.getElementById('ppTopicSub');
  if (sub) sub.textContent = `${list.length} question${list.length === 1 ? '' : 's'} · ${marks} mark${marks === 1 ? '' : 's'}${yr ? ` in the ${yr} paper` : ' across the papers'} · ${attached} available to print / practise. ${ppIsAdmin() ? 'Click a question to attach or change its bank question.' : 'Click a highlighted question to practise just that one.'}`;
  const body = document.getElementById('ppTopicBody');
  if (body) {
    const yrs = [...new Set(list.map(q => String(q.year)))];
    body.innerHTML = yrs.map(y => {
      const yq = list.filter(q => String(q.year) === y);
      return `<div class="pp-topic-year"><div class="pp-topic-yhead">${escapeHtml(y)}</div><div class="pp-chip-row">${yq.map(q => ppChip(q)).join('')}</div></div>`;
    }).join('') || '<div style="color:var(--text-muted);padding:12px 0;">No questions here yet.</div>';
  }
  const all = document.getElementById('ppTopicAllBtn'); if (all) all.style.display = yr ? '' : 'none';
  const pr = document.getElementById('ppTopicPrintBtn');
  if (pr) { pr.disabled = !attached; pr.innerHTML = '🖨 Print worksheet' + (attached ? ` (${attached})` : ''); }
  const pl = document.getElementById('ppTopicPractiseBtn');
  if (pl) { pl.disabled = !attached; pl.innerHTML = '▶ Practise all' + (attached ? ` (${attached})` : ''); }
}
function ppTopicShowAll(){ if (_ppTopicSel) { _ppTopicSel.year = ''; ppTopicRender(); } }
function ppTopicClose(){ const ov = document.getElementById('ppTopicOverlay'); if (ov) ov.classList.remove('active'); _ppTopicSel = null; ppHoverHide(); }
function ppTopicPrint(){
  if (!_ppTopicSel) return;
  const { items, missing } = ppCollectPrintable(ppTopicQs().map(q => q.id));
  ppDoPrint(items, missing, _ppTopicSel.topic + (_ppTopicSel.year ? ' — PSLE ' + _ppTopicSel.year : ' — Past-Paper Questions'));
}
function ppTopicPractise(){
  if (!_ppTopicSel) return;
  const seen = new Set(); const bqs = [];
  ppTopicQs().forEach(q => { const bq = ppBankQ(q.id); if (bq && !seen.has(bq.id)) { seen.add(bq.id); bqs.push(bq); } });
  if (!bqs.length) { showToast('None of these questions are available to practise yet', 'error'); return; }
  ppTopicClose();
  launchWorksheetPractice(bqs);
}

// -------- practise the papers --------
// "Practice all" / per-year "Practice now" run the attached bank questions
// through Quick Practice, MCQ and open-ended alike, marked as usual.

// Unique attached bank questions for a year ('' = every year), in paper order.
function ppAttachedBankQs(year){
  const seen = new Set(); const bqs = [];
  ppQuestions()
    .filter(q => !year || String(q.year) === String(year))
    .sort((a,b)=> String(a.year).localeCompare(String(b.year)) || (Number(a.n)||0) - (Number(b.n)||0))
    .forEach(q => { const bq = ppBankQ(q.id); if (bq && !seen.has(bq.id)) { seen.add(bq.id); bqs.push(bq); } });
  return bqs;
}
function ppYearLabel(year){ return year ? 'PSLE ' + year : 'All past papers'; }

// ▶ Practice on the system: run the portion's attached questions (MCQ + OEQ,
// AI-marked as usual) through Quick Practice.
function ppPracticeYear(year){
  const bqs = ppAttachedBankQs(year);
  if (!bqs.length) { showToast('No questions are attached ' + (year ? 'for ' + year : '') + ' yet', 'error'); return; }
  ppHoverHide();
  launchWorksheetPractice(bqs);
}

// Model answer of an open-ended bank question as one HTML snippet (CER answer
// boxes, plain answer boxes and answer-key blocks, in order). '' if none.
function _ppModelAnswerHtml(q){
  const parts = [];
  ((q && q.blocks) || []).forEach(b => {
    if (b.type === 'answer') {
      const seg = [b.claim, b.evidence, b.reasoning].filter(s => stripHtmlToText(s || '').trim());
      if (seg.length) parts.push(seg.join(' '));
    } else if (b.type === 'plainanswer') {
      if (stripHtmlToText(b.content || '').trim()) parts.push(b.content);
    } else if (b.type === 'answerKey') {
      if (stripHtmlToText(b.text || '').trim()) parts.push(b.text);
    }
  });
  return parts.length ? parts.join('<br>') : '';
}

// -------- question editor --------
function ppAddQuestion(year){
  const y = year || (ppYears().slice(-1)[0] || String(new Date().getFullYear()));
  ppOpenQEdit({ id: null, year: y, n: ppNextN(y), bk: 'A', marks: 2, topic: (currentTopics()[0] || 'Electrical Systems'), type: 'recall', title: '', detail: '', ans: '' });
}
function ppEditQuestion(id){ const q = ppFindQ(id); if (q) ppOpenQEdit(q); }
function ppOpenQEdit(q){
  _ppQEditId = q.id;   // null when new
  ppHoverHide();
  const set = (elId, v) => { const el = document.getElementById(elId); if (el) el.value = v; };
  document.getElementById('ppQEditTitle').textContent = q.id ? 'Edit question' : 'Add question';
  set('ppQeYear', q.year); set('ppQeN', q.n); set('ppQeBk', q.bk || 'A'); set('ppQeMarks', q.marks);
  // topic dropdown from the portal's live topic list (+ current value if custom)
  const ts = document.getElementById('ppQeTopic');
  if (ts) {
    const topics = currentTopics().slice();
    if (q.topic && topics.indexOf(q.topic) < 0) topics.unshift(q.topic);
    ts.innerHTML = topics.map(t => `<option ${t === q.topic ? 'selected' : ''}>${escapeHtml(t)}</option>`).join('');
  }
  const sk = document.getElementById('ppQeType');
  if (sk) sk.innerHTML = Object.keys(PP_SKILL).map(k => `<option value="${k}" ${k === q.type ? 'selected' : ''}>${escapeHtml(PP_SKILL[k])}</option>`).join('');
  set('ppQeTitle', q.title || ''); set('ppQeDetail', q.detail || ''); set('ppQeAns', q.ans || '');
  set('ppQeDiff', ppDiff(q));
  const del = document.getElementById('ppQeDeleteBtn'); if (del) del.style.display = q.id ? '' : 'none';
  const eb = document.getElementById('ppQeEditBankBtn');
  if (eb) { const bq = q.id ? ppBankQ(q.id) : null; eb.style.display = bq ? '' : 'none'; }
  const ov = document.getElementById('ppQEditOverlay'); if (ov) ov.classList.add('active');
}
// From the past-paper metadata editor, jump into the full editor for the
// attached bank question (returns to Past Papers on save).
function ppEditAttachedFromQEdit(){
  const id = _ppQEditId; if (!id) return;
  const bq = ppBankQ(id);
  if (!bq) { showToast('No bank question is attached to this one', 'info'); return; }
  ppCloseQEdit();
  editQuestionFromPapers(bq.id, id);
}
function ppCloseQEdit(){ const ov = document.getElementById('ppQEditOverlay'); if (ov) ov.classList.remove('active'); _ppQEditId = null; }
async function ppSaveQuestionEditor(){
  const val = (elId) => (document.getElementById(elId)?.value || '').trim();
  const year = val('ppQeYear');
  const n = val('ppQeN');
  if (!year || !n) { showToast('Year and question number are required', 'error'); return; }
  const rec = {
    year: year,
    n: (Number(n) || n),
    bk: document.getElementById('ppQeBk')?.value || 'A',
    marks: Math.max(1, Number(val('ppQeMarks')) || 1),
    topic: document.getElementById('ppQeTopic')?.value || '',
    type: document.getElementById('ppQeType')?.value || 'recall',
    title: val('ppQeTitle'),
    detail: val('ppQeDetail'),
    ans: val('ppQeAns')
  };
  const diff = document.getElementById('ppQeDiff')?.value || '';
  if (diff === 'easy' || diff === 'moderate' || diff === 'hard') rec.diff = diff;
  if (_ppQEditId) {
    const q = ppFindQ(_ppQEditId); if (q) { if (!rec.diff) delete q.diff; Object.assign(q, rec); }
  } else {
    rec.id = ppNewId(); ppData.questions.push(rec);
  }
  await savePaperData();
  ppCloseQEdit();
  ppRenderBody();
  // If the Answer Key Check page is the one open, refresh it too.
  const arPage = document.getElementById('page-ansreview');
  if (arPage && arPage.classList.contains('active')) renderAnswerReview();
  showToast('Saved', 'success');
}
async function ppDeleteQuestion(id){
  const q = ppFindQ(id); if (!q) return;
  if (!confirm(`Remove ${q.year} Q${q.n}? This also removes it from any concept and clears its attachment.`)) return;
  ppData.questions = ppData.questions.filter(x => x.id !== id);
  ppData.recurring.forEach(c => { if (Array.isArray(c.hits)) c.hits = c.hits.filter(h => h !== id); });
  if (paperMap[id]) { delete paperMap[id]; savePaperMap(); }
  await savePaperData();
  ppRenderBody();
  showToast('Question removed', 'info');
}
function ppDeleteQuestionFromEditor(){ const id = _ppQEditId; if (!id) return; ppCloseQEdit(); ppDeleteQuestion(id); }

// =====================================================================
// WHOLE-PAPER EDITOR — edit an entire past year paper on ONE screen
// instead of opening each question's dialog one at a time.
//
// Everything is edited on a DRAFT copy of the year's questions, so Cancel
// throws the lot away and Save writes the whole paper back in a single
// savePaperData() call. Rows can be added, deleted, re-numbered and bulk-
// stamped (topic / skill / difficulty / booklet / marks) across every ticked
// question at once.
// =====================================================================
let _ppPeYear = null;        // the year currently open in the whole-paper editor
let _ppPeYearDraft = '';     // the year as typed (kept in state: the bulk bar re-renders)
let _ppPeRows = null;        // draft rows: clones of the year's questions (+ new ones)
let _ppPeSel = new Set();    // row keys ticked for the bulk actions
let _ppPeDeleted = [];       // ids of EXISTING questions removed in this session
let _ppPeDirty = false;      // has anything been touched since opening?
let _ppPeKeySeq = 0;         // draft-local row keys (a new row has no id yet)

function ppPeNewKey(){ return 'k' + (++_ppPeKeySeq); }
function ppPeFind(k){ return (_ppPeRows || []).find(r => r._k === k); }
function ppPeMarkDirty(){ _ppPeDirty = true; ppPeRenderStatus(); }

function ppOpenPaperEdit(year){
  if (!ppIsAdmin()) { showToast('Only admins can edit the papers', 'error'); return; }
  const y = String(year || '');
  ppHoverHide();
  _ppPeYear = y;
  _ppPeYearDraft = y;
  _ppPeSel = new Set();
  _ppPeDeleted = [];
  _ppPeDirty = false;
  _ppPePrevCache = {};
  _ppPeRows = ppQuestions()
    .filter(q => String(q.year) === y)
    .sort((a,b) => (Number(a.n)||0) - (Number(b.n)||0))
    .map(q => Object.assign(ppClone(q), { _k: ppPeNewKey() }));
  const t = document.getElementById('ppPaperEditTitle');
  if (t) t.textContent = `🗂 PSLE ${y} — the whole paper`;
  ppPeRender();
  const ov = document.getElementById('ppPaperEditOverlay'); if (ov) ov.classList.add('active');
}

function ppClosePaperEdit(){
  if (_ppPeDirty && !confirm('Discard every change you made to this paper?')) return;
  const ov = document.getElementById('ppPaperEditOverlay'); if (ov) ov.classList.remove('active');
  _ppPeYear = null; _ppPeYearDraft = ''; _ppPeRows = null; _ppPeSel = new Set(); _ppPeDeleted = []; _ppPeDirty = false; _ppPePrevCache = {};
}
function ppPeSetYear(v){ _ppPeYearDraft = v; ppPeMarkDirty(); }

// ---- draft mutations (typing never re-renders, so the caret is never lost) ----
function ppPeSet(k, field, value){
  const r = ppPeFind(k); if (!r) return;
  r[field] = value;
  // Typing still never re-renders — but the row's own heading now repeats the
  // number, marks, booklet and topic, so those four are patched in place.
  // Without this the header would sit there contradicting the field the user
  // is editing until something else forced a full render.
  if (field === 'n' || field === 'marks' || field === 'bk' || field === 'topic') {
    const row = document.getElementById('ppPeRow_' + k);
    if (row) {
      const qno = row.querySelector('.pp-pe-qno');
      if (qno) qno.textContent = 'Q' + String(r.n == null ? '' : r.n);
      const meta = row.querySelector('.pp-pe-headmeta');
      if (meta) meta.innerHTML = `${escapeHtml(String(r.marks || 0))} mark${Number(r.marks) === 1 ? '' : 's'} &middot; Booklet ${escapeHtml(String(r.bk || 'A'))}${r.topic ? ' &middot; ' + escapeHtml(String(r.topic)) : ''}`;
    }
  }
  ppPeMarkDirty();
}
function ppPeToggleSel(k, on){ if (on) _ppPeSel.add(k); else _ppPeSel.delete(k); ppPeRenderBulk(); ppPeRenderStatus(); ppPeSyncRowClasses(); }
function ppPeSelectAll(on){
  _ppPeSel = on ? new Set((_ppPeRows || []).map(r => r._k)) : new Set();
  (_ppPeRows || []).forEach(r => { const cb = document.getElementById('ppPeCb_' + r._k); if (cb) cb.checked = on; });
  ppPeRenderBulk(); ppPeRenderStatus(); ppPeSyncRowClasses();
}
function ppPeSyncRowClasses(){
  (_ppPeRows || []).forEach(r => {
    const el = document.getElementById('ppPeRow_' + r._k);
    if (el) el.classList.toggle('sel', _ppPeSel.has(r._k));
  });
}
function ppPeAddRow(){
  if (!_ppPeRows) return;
  const used = _ppPeRows.map(r => Number(r.n) || 0);
  const next = used.length ? Math.max.apply(null, used) + 1 : 1;
  _ppPeRows.push({
    _k: ppPeNewKey(), id: null, year: _ppPeYear, n: next, bk: 'A', marks: 2,
    topic: (currentTopics()[0] || 'Electrical Systems'), type: 'recall', title: '', detail: '', ans: ''
  });
  ppPeMarkDirty();
  ppPeRender();
  requestAnimationFrame(() => {
    const el = document.getElementById('ppPeRow_' + _ppPeRows[_ppPeRows.length - 1]._k);
    if (el) { try { el.scrollIntoView({ behavior:'smooth', block:'center' }); } catch(_) { el.scrollIntoView(); } }
  });
}
function ppPeDeleteRow(k){
  const r = ppPeFind(k); if (!r) return;
  const label = `Q${r.n}`;
  if (r.id && !confirm(`Remove ${_ppPeYear} ${label} from this paper? It is only deleted when you save.`)) return;
  if (r.id) _ppPeDeleted.push(r.id);
  _ppPeRows = _ppPeRows.filter(x => x._k !== k);
  _ppPeSel.delete(k);
  ppPeMarkDirty();
  ppPeRender();
}
// Re-number every question 1..n in the order they are listed — the usual fix
// after inserting a question the paper was missing.
function ppPeRenumber(){
  if (!_ppPeRows || !_ppPeRows.length) return;
  if (!confirm('Renumber every question in this paper 1, 2, 3… in the order shown?')) return;
  _ppPeRows.forEach((r, i) => { r.n = i + 1; });
  ppPeMarkDirty();
  ppPeRender();
}
function ppPeSort(){
  if (!_ppPeRows) return;
  _ppPeRows.sort((a,b) => ((a.bk || 'A') > (b.bk || 'A') ? 1 : (a.bk || 'A') < (b.bk || 'A') ? -1 : 0) || (Number(a.n)||0) - (Number(b.n)||0));
  ppPeRender();
}
// Stamp one field onto every ticked row at once.
function ppPeBulk(field, value, selEl){
  if (selEl) selEl.value = '';
  if (!_ppPeSel.size) { showToast('Tick the questions you want to change first', 'info'); return; }
  if (value === '' || value == null) return;
  let v = value;
  if (field === 'marks') v = Math.max(1, Number(value) || 1);
  if (field === 'diff' && v === 'none') v = '';   // "Clear difficulty"
  _ppPeSel.forEach(k => {
    const r = ppPeFind(k); if (!r) return;
    if (field === 'diff' && !v) delete r.diff; else r[field] = v;
  });
  ppPeMarkDirty();
  ppPeRender();
  showToast(`Applied to ${_ppPeSel.size} question${_ppPeSel.size === 1 ? '' : 's'}`, 'success');
}
function ppPeBulkMarks(){
  const el = document.getElementById('ppPeBulkMarks');
  const v = el ? el.value : '';
  if (!String(v).trim()) { showToast('Type the number of marks first', 'info'); return; }
  ppPeBulk('marks', v);
  if (el) el.value = '';
}

// ---- rendering ----
function ppPeTopicOptions(cur){
  const topics = currentTopics().slice();
  if (cur && topics.indexOf(cur) < 0) topics.unshift(cur);
  return topics.map(t => `<option ${t === cur ? 'selected' : ''}>${escapeHtml(t)}</option>`).join('');
}
function ppPeSkillOptions(cur){
  return Object.keys(PP_SKILL).map(k => `<option value="${k}" ${k === cur ? 'selected' : ''}>${escapeHtml(PP_SKILL[k])}</option>`).join('');
}
function ppPeDiffOptions(cur){
  const d = (cur === 'easy' || cur === 'moderate' || cur === 'hard') ? cur : '';
  return `<option value="" ${!d ? 'selected' : ''}>◻ No difficulty</option>
    <option value="easy" ${d === 'easy' ? 'selected' : ''}>🟢 Easy</option>
    <option value="moderate" ${d === 'moderate' ? 'selected' : ''}>🟡 Moderate</option>
    <option value="hard" ${d === 'hard' ? 'selected' : ''}>🔴 Difficult</option>`;
}
function ppPeRender(){
  ppPeRenderBulk();
  const body = document.getElementById('ppPaperEditBody');
  if (body) {
    // Replacing the body wholesale loses the scroll position. That barely
    // mattered when a row was six small fields; now that a row is a whole
    // question, a bulk topic stamp halfway down a forty-question paper would
    // throw you back to the top and lose your place.
    const keepTop = body.scrollTop;
    const rows = _ppPeRows || [];
    body.innerHTML = rows.length
      ? rows.map(r => ppPeRowHtml(r)).join('') + `<button type="button" class="pp-add pp-pe-addrow" onclick="ppPeAddRow()">＋ Add another question to this paper</button>`
      : `<div class="pp-pe-empty">This paper has no questions yet.<br><button type="button" class="pp-add" style="margin-top:14px;" onclick="ppPeAddRow()">＋ Add the first question</button></div>`;
    ppPeFillPreviews();   // the containers must exist before buildOpenBody fills them
    if (keepTop) body.scrollTop = keepTop;
  }
  ppPeRenderStatus();
}
function ppPeRowHtml(r){
  const k = r._k;
  const bq = r.id ? ppBankQ(r.id) : null;
  const sel = _ppPeSel.has(k);
  const badges = [
    r.id ? '' : '<span class="pp-pe-badge new">NEW</span>',
    bq ? `<span class="pp-pe-badge ok" title="A bank question is attached — students can practise it">✓ attached</span>` : '<span class="pp-pe-badge muted" title="No bank question attached yet — students cannot practise this one">not attached</span>'
  ].join('');
  // The question exactly as a student is served it, then its answer key, then
  // the paper's own bookkeeping folded away. Checking a paper means reading the
  // question and the answer — not filling in a grid of tiny boxes — so those
  // come first and the metadata is one click away.
  return `<div class="pp-pe-row${sel ? ' sel' : ''}" id="ppPeRow_${k}">
    <div class="pp-pe-rowhead">
      <label class="pp-pe-tick" title="Tick to include this question in the bulk actions above">
        <input type="checkbox" id="ppPeCb_${k}" ${sel ? 'checked' : ''} onchange="ppPeToggleSel('${k}', this.checked)">
      </label>
      <span class="pp-pe-qno">Q${escapeHtml(String(r.n))}</span>
      ${badges}
      <span class="pp-pe-headmeta">${escapeHtml(String(r.marks || 0))} mark${Number(r.marks) === 1 ? '' : 's'} &middot; Booklet ${escapeHtml(String(r.bk || 'A'))}${r.topic ? ' &middot; ' + escapeHtml(String(r.topic)) : ''}</span>
      <div class="pp-pe-rowtools">
        ${bq ? `<button type="button" class="pp-mini" title="Open the attached quiz question in the full block editor" onclick="ppPeEditBank('${k}')">✏️ Edit the question</button>` : ''}
        <button type="button" class="pp-mini del" title="Remove this question from the paper" onclick="ppPeDeleteRow('${k}')">&times; Remove</button>
      </div>
    </div>

    <div class="pp-pe-title-line">
      <input class="form-input pp-pe-titleinput" type="text" placeholder="Short description of the question"
             value="${escapeHtml(String(r.title || ''))}" oninput="ppPeSet('${k}','title',this.value)">
    </div>

    <div class="pp-pe-preview" id="ppPePrev_${k}">${bq
      ? `<div class="pp-pe-prevwait">Loading the question…</div>`
      : `<div class="pp-pe-noq">No quiz question is attached to this one yet, so there is nothing to show a student. Build it from the paper list, then it appears here.</div>`}</div>

    <div class="pp-pe-key">
      <div class="pp-pe-key-h">✅ Answer key<span> — the paper's own mark scheme. Edit it here.</span></div>
      <textarea class="form-input pp-pe-keytext" rows="3" placeholder="Model answer / key"
                oninput="ppPeSet('${k}','ans',this.value)">${escapeHtml(String(r.ans || ''))}</textarea>
      <div class="pp-pe-model" id="ppPeModel_${k}"></div>
    </div>

    <details class="pp-pe-meta">
      <summary>Paper details — number, booklet, marks, topic, skill, difficulty, analysis</summary>
    <div class="pp-pe-grid">
      <label class="pp-pe-f"><span>Q no.</span><input class="form-input" type="number" min="1" value="${escapeHtml(String(r.n == null ? '' : r.n))}" oninput="ppPeSet('${k}','n',this.value)"></label>
      <label class="pp-pe-f"><span>Booklet</span><select class="form-select" onchange="ppPeSet('${k}','bk',this.value)"><option ${((r.bk||'A') === 'A') ? 'selected' : ''}>A</option><option ${((r.bk||'A') === 'B') ? 'selected' : ''}>B</option></select></label>
      <label class="pp-pe-f"><span>Marks</span><input class="form-input" type="number" min="1" value="${escapeHtml(String(r.marks == null ? '' : r.marks))}" oninput="ppPeSet('${k}','marks',this.value)"></label>
      <label class="pp-pe-f"><span>Topic</span><select class="form-select" onchange="ppPeSet('${k}','topic',this.value)">${ppPeTopicOptions(r.topic || '')}</select></label>
      <label class="pp-pe-f"><span>Skill tested</span><select class="form-select" onchange="ppPeSet('${k}','type',this.value)">${ppPeSkillOptions(r.type || 'recall')}</select></label>
      <label class="pp-pe-f"><span>Difficulty</span><select class="form-select" onchange="ppPeSet('${k}','diff',this.value)">${ppPeDiffOptions(r.diff)}</select></label>
    </div>
    <label class="pp-pe-f full"><span>What it tests / analysis</span><textarea class="form-input" rows="2" placeholder="How the question works and what to watch for" oninput="ppPeSet('${k}','detail',this.value)">${escapeHtml(String(r.detail || ''))}</textarea></label>
    </details>
  </div>`;
}
// The student's view of the attached question, plus the bank's own model
// answer, dropped into each row AFTER the list is in the DOM.
//
// buildOpenBody is the single renderer every student-facing surface uses, so
// this is the real thing rather than a lookalike that would drift from it. It
// keys its answer stores by container selector, which is why each row gets its
// own id — the same pattern the worksheet preview uses. The result is made
// inert with CSS (.pp-pe-preview): this screen is for READING the question, so
// the answer boxes are shown but not typed in, and the hint / check buttons
// that would mark them are hidden.
// Built HTML per row key. ppPeRender() replaces the whole body — a bulk topic
// stamp, a renumber, a sort, adding a row — and rebuilding forty question
// previews each time (images, tables, option lists) is the one thing that
// would make this screen slow. The bank question cannot change while the modal
// is open (editing one closes it), so the built markup is reusable.
let _ppPePrevCache = {};
function ppPeFillPreviews(){
  (_ppPeRows || []).forEach(r => {
    const k = r._k;
    const host = document.getElementById('ppPePrev_' + k);
    const bq = r.id ? ppBankQ(r.id) : null;
    if (host && bq) {
      try {
        if (_ppPePrevCache[k] == null) {
          _ppPePrevCache[k] = buildOpenBody(bq, '#ppPePrev_' + k, { scoreElId: 'ppPeScore_' + k, scorePrefix: '', mode: 'preview' });
        }
        host.innerHTML = _ppPePrevCache[k];
      } catch (e) {
        console.warn('paper preview', r.id, e);
        host.innerHTML = `<div class="pp-pe-noq">This question could not be previewed — open it in the block editor to check it.</div>`;
      }
    }
    const mh = document.getElementById('ppPeModel_' + k);
    if (mh) {
      let bits = '';
      if (bq) {
        const model = _deriveModelAnswer(bq);
        if (model) bits += `<div class="pp-pe-model-h">From the attached question</div>`
          + `<div class="pp-pe-model-b">${escapeHtml(model).replace(/\n/g, '<br>')}</div>`;
        const ex = (bq.blocks || []).filter(b => b.type === 'explanation' && stripHtml(b.content || '').trim());
        if (ex.length) bits += `<div class="pp-pe-model-h">Explanation</div>`
          + `<div class="pp-pe-model-b">${ex.map(b => sanitizeAnswerKeyHtml(b.content)).join('<br>')}</div>`;
      }
      mh.innerHTML = bits;
    }
  });
}
// Jump from a row straight into the attached bank question's block editor.
// Anything typed in the paper editor is saved first so it is never lost.
async function ppPeEditBank(k){
  const r = ppPeFind(k); if (!r || !r.id) return;
  const bq = ppBankQ(r.id);
  if (!bq) { showToast('No bank question is attached to this one', 'info'); return; }
  if (_ppPeDirty) { const ok = await ppSavePaperEdit(true); if (!ok) return; }
  ppClosePaperEdit();
  editQuestionFromPapers(bq.id, r.id);
}
function ppPeRenderBulk(){
  const el = document.getElementById('ppPaperEditBulk');
  if (!el) return;
  const rows = _ppPeRows || [];
  const n = _ppPeSel.size;
  const allOn = rows.length > 0 && n === rows.length;
  const dis = n ? '' : 'disabled';
  el.innerHTML = `
    <div class="pp-pe-bulkline">
      <label class="pp-pe-f sm"><span>Paper year</span><input class="form-input" id="ppPeYearInput" type="text" value="${escapeHtml(String(_ppPeYearDraft || ''))}" oninput="ppPeSetYear(this.value)" title="Applies to every question in this paper when you save"></label>
      <label class="pp-pe-selall" title="Tick every question in this paper"><input type="checkbox" ${allOn ? 'checked' : ''} onchange="ppPeSelectAll(this.checked)"> Select all</label>
      <span class="pp-pe-selcount">${n ? n + ' selected' : 'none selected'}</span>
      <span class="pp-pe-spacer"></span>
      <button type="button" class="pp-mini" title="Number the questions 1, 2, 3… in the order they are listed" onclick="ppPeRenumber()">1·2·3 Renumber</button>
      <button type="button" class="pp-mini" title="Sort the list by booklet, then question number" onclick="ppPeSort()">⇅ Sort</button>
      <button type="button" class="pp-add" onclick="ppPeAddRow()">＋ Add question</button>
    </div>
    <div class="pp-pe-bulkline">
      <span class="pp-pe-bulklabel">Change all ticked questions:</span>
      <select class="form-select sm" ${dis} onchange="ppPeBulk('topic', this.value, this)"><option value="">Set topic…</option>${ppPeTopicOptions('')}</select>
      <select class="form-select sm" ${dis} onchange="ppPeBulk('type', this.value, this)"><option value="">Set skill…</option>${ppPeSkillOptions('')}</select>
      <select class="form-select sm" ${dis} onchange="ppPeBulk('diff', this.value, this)"><option value="">Set difficulty…</option><option value="easy">🟢 Easy</option><option value="moderate">🟡 Moderate</option><option value="hard">🔴 Difficult</option><option value="none">◻ Clear difficulty</option></select>
      <select class="form-select sm" ${dis} onchange="ppPeBulk('bk', this.value, this)"><option value="">Set booklet…</option><option value="A">Booklet A</option><option value="B">Booklet B</option></select>
      <span class="pp-pe-marksbox"><input class="form-input sm" id="ppPeBulkMarks" type="number" min="1" placeholder="Marks" ${dis}><button type="button" class="pp-mini" ${dis} onclick="ppPeBulkMarks()">Set marks</button></span>
    </div>`;
}
function ppPeRenderStatus(){
  const rows = _ppPeRows || [];
  const sub = document.getElementById('ppPaperEditSub');
  if (sub) sub.textContent = `Every question exactly as a student is served it, with its answer key underneath — scroll from the top, check each one, edit the key in place. Paper details fold open under each question; tick questions to change several at once. Save the lot in one go.`;
  const st = document.getElementById('ppPaperEditStatus');
  if (!st) return;
  const marks = rows.reduce((s,r) => s + (Number(r.marks) || 0), 0);
  const added = rows.filter(r => !r.id).length;
  const bits = [`${rows.length} question${rows.length === 1 ? '' : 's'}`, `${marks} mark${marks === 1 ? '' : 's'}`];
  if (added) bits.push(`${added} new`);
  if (_ppPeDeleted.length) bits.push(`${_ppPeDeleted.length} to delete`);
  st.innerHTML = `<span>${bits.join(' &middot; ')}</span>` + (_ppPeDirty ? `<span class="pp-pe-unsaved">● Unsaved changes</span>` : '');
}

// Write the whole draft back: deletions, edits and new questions in ONE save.
// Returns true when it saved, false when validation stopped it.
async function ppSavePaperEdit(quiet){
  if (!ppIsAdmin()) { showToast('Only admins can edit the papers', 'error'); return false; }
  const rows = _ppPeRows || [];
  const yr = String(_ppPeYearDraft || '').trim();   // kept in sync by ppPeSetYear on every keystroke
  if (!yr) { showToast('The paper needs a year', 'error'); return false; }
  if (rows.some(r => !String(r.n == null ? '' : r.n).trim())) { showToast('Every question needs a question number', 'error'); return false; }
  const nums = rows.map(r => (r.bk || 'A') + '-' + String(r.n).trim());
  const dupe = nums.find((v, i) => nums.indexOf(v) !== i);
  if (dupe && !confirm(`Two questions share the same booklet and number (${dupe.replace('-', ' Q')}). Save anyway?`)) return false;

  // 1) deletions — also unlink them from concepts and from any attachment
  if (_ppPeDeleted.length) {
    const del = new Set(_ppPeDeleted);
    ppData.questions = ppData.questions.filter(q => !del.has(q.id));
    ppData.recurring.forEach(c => { if (Array.isArray(c.hits)) c.hits = c.hits.filter(h => !del.has(h)); });
    let mapChanged = false;
    del.forEach(id => { if (paperMap[id]) { delete paperMap[id]; mapChanged = true; } });
    if (mapChanged) await savePaperMap();
  }
  // 2) edits + new questions
  let created = 0;
  rows.forEach(r => {
    const rec = {
      year: yr,
      n: (Number(r.n) || String(r.n).trim()),
      bk: r.bk || 'A',
      marks: Math.max(1, Number(r.marks) || 1),
      topic: r.topic || '',
      type: r.type || 'recall',
      title: String(r.title || '').trim(),
      detail: String(r.detail || '').trim(),
      ans: String(r.ans || '').trim()
    };
    const d = (r.diff === 'easy' || r.diff === 'moderate' || r.diff === 'hard') ? r.diff : '';
    if (d) rec.diff = d;
    const cur = r.id ? ppFindQ(r.id) : null;
    if (cur) { if (!rec.diff) delete cur.diff; Object.assign(cur, rec); }
    else { rec.id = r.id || ppNewId(); ppData.questions.push(rec); if (!r.id) { r.id = rec.id; created++; } }
  });
  await savePaperData();
  _ppPeDeleted = [];
  _ppPeYear = yr;
  _ppPeYearDraft = yr;
  _ppPeDirty = false;
  _ppPeRows = rows.map(r => Object.assign(r, { year: yr }));
  ppPeRender();
  ppRenderBody();
  const arPage = document.getElementById('page-ansreview');
  if (arPage && arPage.classList.contains('active')) renderAnswerReview();
  if (!quiet) {
    showToast(`Saved the ${yr} paper — ${rows.length} question${rows.length === 1 ? '' : 's'}${created ? `, ${created} new` : ''}`, 'success');
    ppClosePaperEdit();
  }
  return true;
}

// -------- concept editor --------
function ppAddConcept(){ ppOpenCEdit({ id: null, concept: '', topic: '', note: '', hits: [] }); }
function ppEditConcept(id){ const c = ppRecurring().find(x => x.id === id); if (c) ppOpenCEdit(c); }
function ppOpenCEdit(c){
  _ppCEditId = c.id;
  _ppCeHits = new Set((c.hits || []).filter(h => ppFindQ(h)));
  document.getElementById('ppCEditTitle').textContent = c.id ? 'Edit concept' : 'Add concept';
  const set = (elId, v) => { const el = document.getElementById(elId); if (el) el.value = v; };
  set('ppCeName', c.concept || ''); set('ppCeTopic', c.topic || ''); set('ppCeNote', c.note || '');
  const s = document.getElementById('ppCeSearch'); if (s) s.value = '';
  ppRenderConceptPicker();
  const del = document.getElementById('ppCeDeleteBtn'); if (del) del.style.display = c.id ? '' : 'none';
  const ov = document.getElementById('ppCEditOverlay'); if (ov) ov.classList.add('active');
}
function ppCloseCEdit(){ const ov = document.getElementById('ppCEditOverlay'); if (ov) ov.classList.remove('active'); _ppCEditId = null; _ppCeHits = null; }
function ppRenderConceptPicker(){
  if (!_ppCeHits) return;
  const term = (document.getElementById('ppCeSearch')?.value || '').toLowerCase().trim();
  const selWrap = document.getElementById('ppCeSelected');
  if (selWrap) {
    const chips = [..._ppCeHits].map(id => { const q = ppFindQ(id); return q ? `<span class="pp-chip assigned" onclick="ppCeToggleHit('${id}')">${escapeHtml(String(q.year))} Q${escapeHtml(String(q.n))} &times;</span>` : ''; }).join('');
    selWrap.innerHTML = chips || '<span style="color:var(--text-muted);font-size:0.8rem;">No questions selected yet — pick some below.</span>';
  }
  let list = ppQuestions().slice();
  if (term) list = list.filter(q => (String(q.year) + ' q' + q.n + ' ' + (q.topic||'') + ' ' + (q.title||'')).toLowerCase().includes(term));
  const rows = ppYears().map(y => {
    const yq = list.filter(q => String(q.year) === y).sort((a,b)=> (Number(a.n)||0)-(Number(b.n)||0));
    if (!yq.length) return '';
    return `<div style="margin-bottom:8px;"><div style="font-size:0.72rem;color:var(--text-muted);font-weight:700;margin:2px 0 5px;">${escapeHtml(y)}</div><div class="pp-chip-row">` +
      yq.map(q => { const on = _ppCeHits.has(q.id); return `<span class="pp-chip ${on ? 'assigned' : 'open'}" onclick="ppCeToggleHit('${q.id}')">Q${escapeHtml(String(q.n))}${on ? ' &#10003;' : ''}</span>`; }).join('') + `</div></div>`;
  }).join('');
  const picker = document.getElementById('ppCePicker');
  if (picker) picker.innerHTML = rows || '<div style="color:var(--text-muted);padding:10px;">No matching questions.</div>';
}
function ppCeToggleHit(id){ if (!_ppCeHits) return; if (_ppCeHits.has(id)) _ppCeHits.delete(id); else _ppCeHits.add(id); ppRenderConceptPicker(); }
async function ppSaveConceptEditor(){
  const val = (elId) => (document.getElementById(elId)?.value || '').trim();
  const name = val('ppCeName');
  if (!name) { showToast('Give the concept a name', 'error'); return; }
  // hits ordered by year then question number
  const hits = [...(_ppCeHits || new Set())].map(id => ppFindQ(id)).filter(Boolean)
    .sort((a,b)=> String(a.year).localeCompare(String(b.year)) || (Number(a.n)||0)-(Number(b.n)||0)).map(q => q.id);
  const rec = { concept: name, topic: val('ppCeTopic'), note: val('ppCeNote'), hits: hits };
  if (_ppCEditId) { const c = ppRecurring().find(x => x.id === _ppCEditId); if (c) Object.assign(c, rec); }
  else { rec.id = ppNewId(); ppData.recurring.push(rec); }
  await savePaperData();
  ppCloseCEdit();
  ppRenderBody();
  showToast('Saved', 'success');
}
async function ppDeleteConcept(id){
  const c = ppRecurring().find(x => x.id === id); if (!c) return;
  if (!confirm(`Delete the concept "${c.concept}"? (The questions themselves are not deleted.)`)) return;
  ppData.recurring = ppData.recurring.filter(x => x.id !== id);
  await savePaperData();
  ppRenderBody();
  showToast('Concept deleted', 'info');
}
function ppDeleteConceptFromEditor(){ const id = _ppCEditId; if (!id) return; ppCloseCEdit(); ppDeleteConcept(id); }

function ppStyles(){
  return `<style>
  #page-papers .page-body { padding-bottom:60px; }
  .pp-wrap { max-width:960px; margin:0 auto; }
  .pp-topbar { display:flex; align-items:flex-start; gap:14px; flex-wrap:wrap; margin-bottom:18px; }
  .pp-tiles { display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:14px; flex:1; min-width:280px; }
  .pp-tile { background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:16px 18px; }
  .pp-tile-l { font-size:0.8rem; color:var(--text-muted); margin-bottom:4px; }
  .pp-tile-v { font-size:1.9rem; font-weight:700; line-height:1.1; color:var(--primary); }
  .pp-tile-h { font-size:0.75rem; color:var(--text-muted); margin-top:4px; }
  .pp-editbtn { border:1px solid var(--border); background:var(--surface); color:var(--text); border-radius:10px; padding:10px 16px; font:inherit; font-weight:600; cursor:pointer; white-space:nowrap; }
  .pp-editbtn.on { background:var(--primary); border-color:var(--primary); color:#fff; }
  .pp-note { font-size:0.9rem; color:var(--text-muted); background:var(--surface-alt,#fafbfa); border:1px solid var(--border); border-radius:12px; padding:12px 16px; margin-bottom:18px; }
  .pp-card { background:var(--surface); border:1px solid var(--border); border-radius:16px; padding:22px 24px; margin-bottom:20px; }
  .pp-h { margin:0 0 4px; font-size:1.05rem; display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
  .pp-sub { margin:0 0 16px; font-size:0.88rem; color:var(--text-muted); }
  .pp-add { border:1px dashed var(--primary,#0b6b4f); background:var(--primary-light,#eaf3ef); color:var(--primary-dark,#064834); border-radius:9px; padding:6px 12px; font:inherit; font-size:0.82rem; font-weight:600; cursor:pointer; }
  .pp-add.sm { padding:4px 10px; font-size:0.76rem; margin-left:6px; }
  .pp-add:hover { filter:brightness(0.97); }
  .pp-chip-row { display:flex; flex-wrap:wrap; gap:7px; align-items:center; }
  .pp-chip { display:inline-flex; align-items:center; gap:5px; font-size:0.8rem; font-weight:600; padding:5px 10px; border-radius:9px; border:1px solid var(--border); background:var(--surface-alt,#fafbfa); color:var(--text,#333); cursor:default; user-select:none; }
  .pp-chip .pp-chip-yr { font-size:0.64rem; color:var(--text-muted); font-weight:600; }
  .pp-chip.assigned { background:var(--primary-light,#e4f1ec); border-color:var(--primary,#0b6b4f); color:var(--primary-dark,#064834); cursor:pointer; }
  .pp-chip.open { border-style:dashed; cursor:pointer; }
  .pp-chip.open:hover, .pp-chip.assigned:hover { filter:brightness(0.97); box-shadow:0 1px 4px rgba(0,0,0,0.08); }
  .pp-chip.muted { opacity:0.55; }
  /* Difficulty colour-coding (admin-set, past-paper only). Placed after the
     assigned/open/muted rules so it wins for the same specificity. */
  .pp-chip.pp-diff-easy { background:#e4f1ec; border-color:#0f7a5a; color:#0b5b43; }
  .pp-chip.pp-diff-moderate { background:#fdf4e3; border-color:#b7791f; color:#7a5410; }
  .pp-chip.pp-diff-hard { background:#fbeceb; border-color:#b23b36; color:#8f2f2b; }
  .pp-chip.pp-diff-easy, .pp-chip.pp-diff-moderate, .pp-chip.pp-diff-hard { border-style:solid; }
  .pp-chip.pp-diff-easy .pp-chip-yr, .pp-chip.pp-diff-moderate .pp-chip-yr, .pp-chip.pp-diff-hard .pp-chip-yr { color:inherit; opacity:0.7; }
  .pp-diff-legend { display:inline-flex; gap:12px; flex-wrap:wrap; margin-left:auto; font-size:0.76rem; color:var(--text-muted); align-items:center; }
  .pp-diff-legend .pp-lg-box { display:inline-block; width:12px; height:12px; border-radius:4px; margin-right:5px; vertical-align:-1px; border:1px solid rgba(0,0,0,0.12); }
  .pp-diff-sel { font:inherit; font-size:0.72rem; border:1px solid var(--border); border-left:none; border-radius:0; background:var(--surface); color:var(--text); padding:0 4px; cursor:pointer; }
  .pp-diffpick { font:inherit; font-size:0.78rem; font-weight:600; border:1px solid var(--border); background:var(--surface); color:var(--text-muted); border-radius:999px; padding:5px 12px; cursor:pointer; }
  .pp-diffpick:hover { border-color:var(--primary,#0b6b4f); color:var(--text); }
  .pp-diffpick.on { border-color:var(--primary,#0b6b4f); background:var(--primary-light,#eaf3ef); color:var(--primary-dark,#064834); box-shadow:inset 0 0 0 1px var(--primary,#0b6b4f); }
  .pp-diffpick.on.pp-diff-easy { background:#e4f1ec; border-color:#0f7a5a; color:#0b5b43; box-shadow:inset 0 0 0 1px #0f7a5a; }
  .pp-diffpick.on.pp-diff-moderate { background:#fdf4e3; border-color:#b7791f; color:#7a5410; box-shadow:inset 0 0 0 1px #b7791f; }
  .pp-diffpick.on.pp-diff-hard { background:#fbeceb; border-color:#b23b36; color:#8f2f2b; box-shadow:inset 0 0 0 1px #b23b36; }
  .pp-chip-acc { font-size:0.6rem; font-weight:700; padding:1px 5px; border-radius:6px; background:rgba(0,0,0,0.06); color:var(--text-muted); }
  .pp-chip-edit { display:inline-flex; align-items:stretch; border-radius:9px; }
  .pp-chip-edit .pp-chip { border-top-right-radius:0; border-bottom-right-radius:0; }
  .pp-mini { border:1px solid var(--border); background:var(--surface); color:var(--text-muted); font:inherit; font-size:0.78rem; cursor:pointer; padding:0 8px; border-radius:0 9px 9px 0; border-left:none; }
  .pp-mini:hover { color:var(--text); }
  .pp-mini.del:hover { color:#fff; background:var(--accent-red,#b23b36); border-color:var(--accent-red,#b23b36); }
  .pp-tools { margin-left:auto; display:flex; gap:6px; align-items:center; }
  .pp-tools .pp-mini { border-radius:8px; border-left:1px solid var(--border); padding:3px 9px; }
  .pp-print-check { display:inline-flex; align-items:center; justify-content:center; padding:3px 6px; border:1px solid var(--border); border-radius:8px; background:var(--surface); cursor:pointer; }
  .pp-print-check:hover { border-color:var(--primary,#0b6b4f); }
  .pp-print-check input { width:15px; height:15px; margin:0; accent-color:var(--primary,#0b6b4f); cursor:pointer; }
  .pp-add:disabled { opacity:0.5; cursor:not-allowed; }
  .pp-pr-row { display:flex; align-items:center; gap:16px; flex-wrap:wrap; padding:13px 2px; }
  .pp-pr-row + .pp-pr-row { border-top:1px solid var(--border); }
  .pp-pr-info { flex:1; min-width:150px; }
  .pp-pr-title { font-size:0.95rem; font-weight:700; }
  .pp-pr-sub { font-size:0.76rem; color:var(--text-muted); margin-top:3px; }
  .pp-pr-btns { display:flex; gap:9px; flex-wrap:wrap; align-items:center; }
  .pp-pr-btns .pp-add { padding:8px 14px; }
  .pp-gamebtn { border-style:solid; background:#fdf4e3; border-color:#c08a2e; color:#7a5410; }
  .pp-year-head .pp-tools { margin-left:auto; }
  .pp-year { padding:12px 0; }
  .pp-year + .pp-year { border-top:1px solid var(--border); }
  .pp-year-head { margin-bottom:9px; font-size:0.95rem; display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
  .pp-year-sub { font-size:0.78rem; color:var(--text-muted); font-weight:500; }
  .pp-rec { border:1px solid var(--border); border-radius:12px; padding:14px 16px; margin-bottom:12px; }
  .pp-rec-head { display:flex; align-items:center; gap:9px; flex-wrap:wrap; }
  .pp-rec-count { font-size:0.72rem; font-weight:700; color:#fff; background:var(--primary,#0b6b4f); border-radius:999px; padding:2px 9px; }
  .pp-rec-title { font-size:0.98rem; font-weight:700; }
  .pp-rec-topic { font-size:0.76rem; color:var(--text-muted); margin:4px 0 8px; }
  .pp-rec-note { font-size:0.84rem; color:var(--text-muted); margin-top:9px; }
  .pp-legend { display:flex; flex-wrap:wrap; gap:12px; margin-bottom:12px; font-size:0.76rem; color:var(--text-muted); }
  .pp-lg { display:inline-flex; align-items:center; gap:5px; }
  .pp-dot { width:9px; height:9px; border-radius:3px; display:inline-block; flex:none; }
  .pp-bar-row { display:flex; align-items:center; gap:12px; padding:5px 0; }
  .pp-bar-name { width:210px; flex:none; font-size:0.82rem; display:flex; align-items:center; gap:7px; }
  .pp-bar-name .pp-lv { font-size:0.66rem; color:var(--text-muted); font-weight:600; }
  .pp-bar-track { flex:1; height:18px; border-radius:5px; background:var(--surface-alt,#eef1ef); overflow:hidden; display:flex; }
  .pp-bar-seg { height:100%; min-width:4px; cursor:pointer; display:flex; align-items:center; justify-content:center; overflow:hidden; border-right:2px solid var(--surface,#fff); transition:filter 0.15s; }
  .pp-bar-seg:last-child { border-right:none; }
  .pp-bar-seg:hover { filter:brightness(1.1) saturate(1.15); }
  .pp-seg-lb { font-size:0.6rem; font-weight:700; color:#fff; text-shadow:0 1px 2px rgba(0,0,0,0.4); white-space:nowrap; pointer-events:none; }
  .pp-topic-link { cursor:pointer; }
  .pp-topic-link:hover { color:var(--primary,#0b6b4f); text-decoration:underline; text-underline-offset:3px; }
  .pp-topic-yrtag { font-size:0.68rem; font-weight:700; color:var(--primary-dark,#064834); background:var(--primary-light,#eaf3ef); border:1px solid var(--primary,#0b6b4f); border-radius:999px; padding:2px 10px; }
  .pp-topic-year { padding:11px 0; }
  .pp-topic-year + .pp-topic-year { border-top:1px solid var(--border); }
  .pp-topic-yhead { font-size:0.74rem; font-weight:700; color:var(--text-muted); margin-bottom:7px; }
  .pp-bar-val { width:74px; flex:none; text-align:right; font-size:0.76rem; color:var(--text-muted); }
  .pp-arow { display:flex; gap:10px; align-items:flex-start; padding:11px 12px; border:1px solid var(--border); border-radius:10px; margin-bottom:8px; cursor:pointer; }
  .pp-arow:hover { border-color:var(--primary,#0b6b4f); background:var(--primary-light,#eaf3ef); }
  .pp-arow.sel { border-color:var(--primary,#0b6b4f); background:var(--primary-light,#eaf3ef); }
  .pp-arow-title { font-size:0.9rem; font-weight:600; }
  .pp-arow-sub { font-size:0.76rem; color:var(--text-muted); margin:2px 0; }
  .pp-arow-prev { font-size:0.78rem; color:var(--text-muted); overflow:hidden; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; }
  .pp-match { color:var(--primary,#0b6b4f); font-weight:700; }
  .pp-form-grid { display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px 12px; margin-bottom:6px; }
  .pp-form-grid .full { grid-column:1 / -1; }
  .pp-mini.pp-bulkedit { background:var(--primary-light,#eaf3ef); border-color:var(--primary,#0b6b4f); color:var(--primary-dark,#064834); font-weight:600; }
  .pp-mini.pp-bulkedit:hover { background:var(--primary,#0b6b4f); color:#fff; }
  /* ---- whole-paper editor ---- */
  .pp-pe-dialog { max-width:1040px; width:min(1040px, 96vw); text-align:left; max-height:92vh; display:flex; flex-direction:column; padding:0; overflow:hidden; }
  .pp-pe-head { display:flex; align-items:flex-start; gap:18px; padding:24px 28px 18px; border-bottom:1px solid var(--border); }
  .pp-pe-headtext { flex:1; min-width:0; }
  .pp-pe-head h3 { margin:0 0 8px; font-size:1.15rem; }
  .pp-pe-sub { margin:0; font-size:0.86rem; color:var(--text-muted); line-height:1.6; }
  .pp-pe-x { flex:none; border:none; background:none; font-size:1.7rem; line-height:1; color:var(--text-muted); cursor:pointer; padding:0 4px; border-radius:8px; }
  .pp-pe-x:hover { color:var(--text); }
  .pp-pe-bulk { padding:16px 28px; background:var(--surface-alt,#fafbfa); border-bottom:1px solid var(--border); display:flex; flex-direction:column; gap:12px; }
  .pp-pe-bulkline { display:flex; align-items:flex-end; gap:12px; flex-wrap:wrap; }
  .pp-pe-bulklabel { font-size:0.8rem; font-weight:700; color:var(--text-muted); padding-bottom:9px; }
  .pp-pe-spacer { flex:1; min-width:0; }
  .pp-pe-selall { display:inline-flex; align-items:center; gap:7px; font-size:0.84rem; font-weight:600; cursor:pointer; padding-bottom:9px; }
  .pp-pe-selall input { width:16px; height:16px; margin:0; accent-color:var(--primary,#0b6b4f); cursor:pointer; }
  .pp-pe-selcount { font-size:0.78rem; color:var(--text-muted); padding-bottom:10px; }
  .pp-pe-bulk .form-select.sm, .pp-pe-bulk .form-input.sm { font-size:0.82rem; padding:7px 10px; width:auto; min-width:126px; margin:0; }
  .pp-pe-bulk .form-input.sm { min-width:92px; }
  .pp-pe-marksbox { display:inline-flex; align-items:stretch; gap:6px; }
  .pp-pe-marksbox .pp-mini { border-radius:9px; border-left:1px solid var(--border); padding:0 12px; }
  .pp-pe-bulk .pp-mini { padding:8px 12px; border-radius:9px; border-left:1px solid var(--border); }
  .pp-pe-body { flex:1; overflow-y:auto; padding:22px 28px; display:flex; flex-direction:column; gap:14px; }
  .pp-pe-row { border:1px solid var(--border); border-radius:14px; padding:15px 18px 17px; background:var(--surface); display:flex; flex-direction:column; gap:11px; }
  .pp-pe-row.sel { border-color:var(--primary,#0b6b4f); box-shadow:inset 0 0 0 1px var(--primary,#0b6b4f); background:var(--primary-light,#eff6f3); }
  .pp-pe-rowhead { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
  .pp-pe-tick { display:inline-flex; align-items:center; cursor:pointer; }
  .pp-pe-tick input { width:17px; height:17px; margin:0; accent-color:var(--primary,#0b6b4f); cursor:pointer; }
  .pp-pe-qno { font-size:1rem; font-weight:700; color:var(--primary-dark,#064834); }
  .pp-pe-badge { font-size:0.68rem; font-weight:700; border-radius:999px; padding:3px 10px; border:1px solid var(--border); color:var(--text-muted); background:var(--surface-alt,#fafbfa); }
  .pp-pe-badge.ok { color:var(--primary-dark,#064834); background:var(--primary-light,#e4f1ec); border-color:var(--primary,#0b6b4f); }
  .pp-pe-badge.new { color:#7a5410; background:#fdf4e3; border-color:#c08a2e; }
  .pp-pe-rowtools { margin-left:auto; display:flex; gap:8px; align-items:center; }
  .pp-pe-rowtools .pp-mini { border-radius:9px; border-left:1px solid var(--border); padding:5px 11px; }
  .pp-pe-headmeta { font-size:0.78rem; color:var(--text-muted); }
  .pp-pe-title-line .pp-pe-titleinput { width:100%; font-size:1rem; font-weight:600; padding:9px 12px; }
  /* The question exactly as a student is served it — but for READING, not
     answering. Pointer events off makes the whole thing inert, and the
     hint / check / mic controls that only make sense mid-practice are hidden
     so the card shows the question and its answer spaces, nothing else. */
  .pp-pe-preview { border:1px solid var(--border); border-radius:12px; padding:18px 20px; background:var(--surface-alt,#fafbfa); }
  .pp-pe-preview .qp-part { background:var(--surface,#fff); }
  .pp-pe-preview .open-answer, .pp-pe-preview .fb-input, .pp-pe-preview input[type=radio] { pointer-events:none; }
  .pp-pe-preview .part-actions, .pp-pe-preview .part-hint-box, .pp-pe-preview .mcq-feedback,
  .pp-pe-preview .open-feedback, .pp-pe-preview .admin-ans-tool, .pp-pe-preview .mic-btn,
  .pp-pe-preview .fb-actions, .pp-pe-preview .open-photo-bar,
  .pp-pe-preview .dgn-toolbar, .pp-pe-preview .dgn-actions { display:none !important; }
  .pp-pe-preview { pointer-events:none; }
  .pp-pe-preview img { pointer-events:auto; }   /* still clickable to enlarge */
  .pp-pe-preview .open-answer { min-height:52px; background:#fff; }
  .pp-pe-prevwait, .pp-pe-noq { font-size:0.85rem; color:var(--text-muted); line-height:1.65; }
  /* The answer key sits directly under the question — the thing being checked,
     next to the thing it answers. */
  .pp-pe-key { border:1px solid var(--primary,#0b6b4f); border-radius:12px; padding:14px 16px 15px; background:var(--primary-light,#f2f8f5); }
  .pp-pe-key-h { font-size:0.8rem; font-weight:700; color:var(--primary-dark,#064834); margin-bottom:9px; }
  .pp-pe-key-h span { font-weight:400; color:var(--text-muted); }
  .pp-pe-keytext { width:100%; margin:0; resize:vertical; line-height:1.6; background:#fff; }
  .pp-pe-model { margin-top:10px; }
  .pp-pe-model-h { font-size:0.7rem; font-weight:700; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted); margin:8px 0 3px; }
  .pp-pe-model-b { font-size:0.85rem; line-height:1.65; color:var(--on-surface,#14161a); }
  .pp-pe-meta > summary { cursor:pointer; font-size:0.8rem; font-weight:600; color:var(--text-muted); padding:6px 0; list-style:revert; }
  .pp-pe-meta[open] > summary { margin-bottom:11px; }
  .pp-pe-meta { border-top:1px solid var(--border); padding-top:4px; }
  /* Q no / booklet / marks / topic / skill / difficulty all on ONE line, so a
     whole paper's rows read like a table you can scan and scroll. */
  .pp-pe-grid { display:grid; grid-template-columns:84px 96px 84px 1fr 1fr 1fr; gap:12px 14px; }
  .pp-pe-f { display:flex; flex-direction:column; gap:5px; min-width:0; }
  .pp-pe-f > span { font-size:0.74rem; font-weight:700; color:var(--text-muted); }
  .pp-pe-f .form-input, .pp-pe-f .form-select, .pp-pe-f textarea { margin:0; width:100%; }
  .pp-pe-f textarea { resize:vertical; }
  .pp-pe-two { display:grid; grid-template-columns:1fr 1fr; gap:12px 14px; }
  .pp-pe-addrow { align-self:flex-start; padding:10px 16px; font-size:0.86rem; }
  .pp-pe-empty { text-align:center; color:var(--text-muted); padding:44px 20px; font-size:0.9rem; line-height:1.7; }
  .pp-pe-foot { display:flex; align-items:center; gap:16px; flex-wrap:wrap; padding:18px 28px; border-top:1px solid var(--border); background:var(--surface-alt,#fafbfa); }
  .pp-pe-status { flex:1; min-width:150px; font-size:0.8rem; color:var(--text-muted); display:flex; gap:14px; align-items:center; flex-wrap:wrap; }
  .pp-pe-unsaved { color:#7a5410; font-weight:700; }
  .pp-pe-actions { display:flex; gap:10px; flex-wrap:wrap; }
  @media (max-width:860px){
    .pp-pe-grid { grid-template-columns:repeat(2, 1fr); }
    .pp-pe-two { grid-template-columns:1fr; }
    .pp-pe-head, .pp-pe-bulk, .pp-pe-body, .pp-pe-foot { padding-left:18px; padding-right:18px; }
  }
  /* On a phone the bulk bar would eat the screen — let it scroll on its own. */
  @media (max-width:560px){ .pp-pe-bulk { max-height:34vh; overflow-y:auto; } .pp-pe-body { padding-top:16px; } }
  @media (max-width:560px){ .pp-card { padding:18px; } .pp-bar-name { width:130px; font-size:0.74rem; } .pp-bar-val { width:56px; } .pp-form-grid { grid-template-columns:1fr 1fr; } }
  </style>`;
}

